	@RequestMapping(value = "/procedimento/atto/redazioneScheda.htm", method = RequestMethod.POST, params = { "cancellaSchedaACasellario" })
	public String nuovaRedazioneSchedaDettaglioCancella(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap ) throws Exception {
		attoForm = recuperaAtto();
		modelMap.addAttribute("isReadOnly", true);
		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		ComunicazioneForm comunicazioneForm = attoForm.getComunicazioneForm();
		String descUtente = (recuperaIdCodiceUtente().toString());
		if (comunicazioneForm.getFlagStatoInvioComunicazione().equals(Constants.ComunicazioniCasellario.STATO_COMUNICAZIONE_INVIATA)) {
			// Se la comunicazione è in stato inviata devo invocare anche la chiamata al servizio del casellario
			TUtente tUtente = (TUtente)request.getSession().getAttribute(Constants.ID_UTENTE);
			DATIRISPOSTATRASFERIMENTO response = casellarioService.cancellaProvvedimento(descUtente, tUtente, idUffOwn, attoForm, comunicazioneForm, procedimento);
			if (response.getArrayEsito().getESITO().get(0).getCODICE().equals("000")) {
				// Se è ok modifico lo stato della comunicazione ad annullata
				attoService.cancellaCasellario(idUffOwn,  comunicazioneForm.getIdComunicazione(), descUtente);
				super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);
				modelMap.addAttribute("isInviata", true);
				modelMap.addAttribute("isCancellata", true);
			} else
				utilityService.addMessageErrorCasellario(response);
			super.updateProcedimentoIntoSession(procedimento.getIdProcedimento());
			attoForm.setIdAtto(comunicazioneForm.getIdAtto());
			return visualizzaRedazioneSchedaDettaglio( attoForm,  result,  request,  modelMap) ;
		} else {
			//Se la comunicazione non è stata inviata eseguo la cancellazione fisica dell'atto e ritorno al pagina precedente
			KeyMessageDto ritornoDb = attoService.cancellaAtto(idUffOwn, comunicazioneForm.getIdAtto(), descUtente, super.printMethodName());
			if (ritornoDb.isError()) {
				super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
				result.reject(Constants.MESSAGE);
			} else {
				super.setMessage(Constants.SUCCESS_MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
				modelMap.addAttribute("isInviata", true);
				modelMap.addAttribute("isCancellata", true);
				modelMap.addAttribute("isCancellataFisicamente",true);
			}
			super.updateProcedimentoIntoSession(procedimento.getIdProcedimento());
			attoForm.setIdAtto(comunicazioneForm.getIdAtto());
			String backPage = ((String)request.getSession().getAttribute("returnTo"));
			if (backPage.indexOf("elencoAttiOrdineCronologico.htm")>0)
				return elencoAttiOrdineCronologico(attoForm, request, modelMap);
			else if (backPage.indexOf("elenco.htm")>0)
				//elencoAtto(request, null);
				return "redirect:" + backPage;
			else
				return backPage.replaceAll(".htm","");
		}
	}

