	@RequestMapping(value = { "/procedimento/atto/scaricaPDFOmonimo" }, method = RequestMethod.POST)
	public File redazioneSchedaDownloadPDFOmonimo(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap map, HttpServletResponse response) throws Exception {
		String idNSC = request.getParameter("idNSCDownload");
		attoForm = recuperaAtto();
		TComunicazione tComunicazione = attoService.getTComunicazioneById(attoForm.getComunicazioneForm().getIdComunicazione());
		DATIRISPOSTATRASFERIMENTO risposta =  casellarioService.unmarhallerRispostaTrasferimento(tComunicazione.getFileEstrattoCertif());
		byte[] file = null;
		for (OMONIMO omonimo : risposta .getArrayOmonimi().getOMONIMO())
			if (omonimo.getDATIANAGRAFICI().getPROGANAGRAFICA().toString().equals(idNSC)) {
				file = omonimo.getCERTIFICATOCONTROLLO();
				break;
			}
		OutputStream out = response.getOutputStream();
		response.setContentType("application/pdf");
		response.setHeader("Content-Disposition", "attachment;filename=Omonimo.pdf");
		out.write(file);
		out.flush();
		return null;
	}

	@RequestMapping(value = "/procedimento/atto/redazioneScheda.htm", method = RequestMethod.POST, params = { "inviaSchedaACasellario" })
	public String nuovaRedazioneSchedaDettaglioInvioScheda(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap ) throws Exception {
		attoForm = recuperaAtto();
		modelMap.addAttribute("isReadOnly", true);
		ProcedimentoForm procedimento = recuperaProcedimento();
		//Recupero le info dell'utente connesso
		TUtente tUtente = (TUtente)request.getSession().getAttribute(Constants.ID_UTENTE);
		int idUffOwn = recuperaIdUfficioUtente();
		ComunicazioneForm comunicazioneForm = attoForm.getComunicazioneForm();
		attoForm.setIdAtto(comunicazioneForm.getIdAtto());
		String codUtente = recuperaIdCodiceUtente();
		String idNSC = request.getParameter("idNSC");
		if (idNSC==null ||(idNSC!=null && idNSC.equals("")) && request.getParameter("hasOmonimi")!=null && request.getParameter("hasOmonimi").equalsIgnoreCase("true")) {
			// Se ci sono gli omonimi ma non ho selezionato nessuno
			super.setMessage(Constants.MESSAGE, "redazioneScheda.errore.selezionareOmonimo", null, false);
			return visualizzaRedazioneSchedaDettaglio( attoForm,  result,  request,  modelMap) ;
		}

		DATIRISPOSTATRASFERIMENTO datiRisposta = casellarioService.inviaProvvedimento(codUtente,tUtente, idUffOwn,  attoForm, comunicazioneForm,procedimento,idNSC);
		if (datiRisposta.getArrayEsito().getESITO().get(0).getCODICE().equals("000")) {
			// Se l'esito è ok
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);
			modelMap.addAttribute("isInviata", true);
		} else if (datiRisposta.getArrayEsito().getESITO().get(0).getCODICE().equals("999"))
			super.setMessage(Constants.MESSAGE, "redazioneScheda.errore.selezionareOmonimo", null, false);
		else
			utilityService.addMessageErrorCasellario(datiRisposta);
		return visualizzaRedazioneSchedaDettaglio( attoForm,  result,  request,  modelMap) ;
	}

