	@RequestMapping(value = { "/procedimento/atto/nuovoVersionamentoSoggetto.htm" }, method = RequestMethod.POST, params = { "Versionamento" })
	private ModelAndView nuovoVersionamentoSoggetto(AttoForm attoForm,BindingResult result, HttpServletRequest request, HttpServletResponse response, ModelMap modelMap,String provenienza) {

		SoggettoForm soggetto = new SoggettoForm();

		if(attoForm.getTipoSoggetto() != null){
			soggetto.setIdSoggetto(attoForm.getIdentificativoSoggetto());
			soggetto.setIdVersione(attoForm.getVersioneSoggetto());
			soggetto.setTipoSoggetto(attoForm.getTipoSoggetto());
		}

		if(provenienza == null || !provenienza.equalsIgnoreCase("confermaVersionamentoSoggetto")){
			soggettoValidation.validateGestioneSoggetto(soggetto, result, request);
			if (result.hasErrors()) {
				attoForm.getTipoAtto().setId(Constants.TIPO_ATTO_VERSIONAMENTO);
				attoForm.getCategoriaAtto().setId(Constants.ATTO_VERSIONAMENTO_SOGGETTO);
				return controllaSelezioneCategoriaAtto(attoForm,result,request,response,modelMap);
			}
		}

		soggetto.setIdUfficio((Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE));
		soggetto.setIdProcedimento(((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento());

		String lPaginaReturn = null;
		ComboForm comuneTmp = new ComboForm();
		if(Constants.SOGGETTO_FISICO.equalsIgnoreCase(attoForm.getTipoSoggetto())){
			soggetto = procedimentoService.caricaValoriDettaglioSoggettoFisicoVersionamento(soggetto);
			lPaginaReturn = "/procedimento/atto/versionamentoSoggettoFisico";
			if(soggetto.getStatoNascita() != null && !"1".equalsIgnoreCase(soggetto.getStatoNascita().getId())){
				comuneTmp.setDescrizione(soggetto.getDescrizioneComuneEsteroNascita());
				soggetto.setComuneNascita(comuneTmp);
			}
		}else{
			soggetto = procedimentoService.caricaValoriDettaglioSoggettoGiuridicoVersionamento(soggetto);
			lPaginaReturn = "/procedimento/atto/versionamentoSoggettoGiuridico";
			if(soggetto.getStatoSedeLegale() != null && !"1".equalsIgnoreCase(soggetto.getStatoSedeLegale().getId())){
				comuneTmp.setDescrizione(soggetto.getDescrizioneComuneEsteroSedeLegale());
				soggetto.setComuneSedeLegale(comuneTmp);
			}
		}

		addBreadcrumbs();

		attoForm.setSoggetto(soggetto);
		ModelAndView mnv = new ModelAndView(lPaginaReturn, "attoForm", attoForm);

		List<ComboForm> magistrati = commonService.listaPmAssegnatari(soggetto.getIdUfficio());

		mnv.addObject("magistrati", magistrati);


		return mnv;
	}


	@RequestMapping(value = "/procedimento/atto/versionamentoSoggettoGiuridico.htm", method = RequestMethod.POST, params = { "verificaPI" })
	private ModelAndView controllaCFSoggettoGiuridico(AttoForm attoForm, BindingResult result, HttpServletRequest request, HttpServletResponse response, ModelMap modelMap) {
		SoggettoForm soggettoForm = attoForm.getSoggetto();

		String msgErrore = "";

		if ( "".equals(soggettoForm.getRagioneSociale()) || soggettoForm.getRagioneSociale()==null )
			msgErrore = "errors.campi.controllo.pi.ragionesociale";
		else {
			//Invoco il WS
			EsitoControlloCFePIWrapper  esito = agenziaEntrateService.controllaDatiAnagraficiPI(soggettoForm);
			if (esito.isInvocazioneFallita())
				super.setMessage(Constants.MESSAGE, "errors.campi.controllo.pi", esito.getErrore(), false);
			else if (soggettoForm.getPartitaIva()!=null && !soggettoForm.getPartitaIva().equals("")) {
				// Compara CF
				if (soggettoForm.getPartitaIva().equals(esito.getPartitaIva()))
					super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.pi.corretta", " ", true);
				else
					super.setMessage(Constants.MESSAGE, "errors.campi.controllo.pi.diverso", esito.getPartitaIva(), false);
			} else
				soggettoForm.setPartitaIva(esito.getPartitaIva());
		}

		if (!msgErrore.equals(""))
			super.setMessage(Constants.MESSAGE, msgErrore, null, false);
		attoForm = new AttoForm();
		attoForm.setTipoSoggetto(Constants.SOGGETTO_GIURIDICO);
		attoForm.setIdentificativoSoggetto(soggettoForm.getIdSoggetto());
		attoForm.setVersioneSoggetto(soggettoForm.getIdVersione());
		return nuovoVersionamentoSoggetto(attoForm,result, request, response, modelMap,"confermaVersionamentoSoggetto");
	}

	@RequestMapping(value = "/procedimento/atto/versionamentoSoggettoFisico.htm", method = RequestMethod.POST, params = { "verificaCF" })
	private ModelAndView controllaCFSoggettoFisico(AttoForm attoForm, BindingResult result, HttpServletRequest request, HttpServletResponse response, ModelMap modelMap) {
		SoggettoForm soggettoForm = attoForm.getSoggetto();

		String msgErrore = "";

		if ( "".equals(soggettoForm.getNome()) || soggettoForm.getNome()==null || "".equals(soggettoForm.getCognome()) || soggettoForm.getCognome()==null )
			msgErrore = "errors.campi.controllo.codicefiscale.nomeocognome";
		else {
			//Invoco il WS
			EsitoControlloCFePIWrapper  esito = agenziaEntrateService.controllaDatiAnagraficiPF(soggettoForm);
			if (esito.isInvocazioneFallita())
				super.setMessage(Constants.MESSAGE, "errors.campi.controllo.codicefiscale", esito.getErrore(), false);
			else if (soggettoForm.getCodiceFiscale()!=null && !soggettoForm.getCodiceFiscale().equals("")) {
				// Compara CF
				if (soggettoForm.getCodiceFiscale().equals(esito.getCodiceFiscale()))
					super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.codicefiscale.corretto", " ", true);
				else
					super.setMessage(Constants.MESSAGE, "errors.campi.controllo.codicefiscale.diverso", esito.getCodiceFiscale(), false);
			} else
				soggettoForm.setCodiceFiscale(esito.getCodiceFiscale());
		}

		if (!msgErrore.equals(""))
			super.setMessage(Constants.MESSAGE, msgErrore, null, false);
		attoForm = new AttoForm();
		attoForm.setTipoSoggetto(Constants.SOGGETTO_FISICO);
		attoForm.setIdentificativoSoggetto(soggettoForm.getIdSoggetto());
		attoForm.setVersioneSoggetto(soggettoForm.getIdVersione());
		return nuovoVersionamentoSoggetto(attoForm,result, request, response, modelMap,"confermaVersionamentoSoggetto");
	}


	/**
	 * metodo che versiona il soggetto fisico
	 * @param soggettoForm
	 * @param result
	 * @param request
	 * @param response
	 * @param modelMap
	 * @return ModelAndView
	 */
	@RequestMapping(value = { "/procedimento/atto/versionamentoSoggettoFisico.htm" }, method = RequestMethod.POST, params = { "Conferma" })
	private ModelAndView confermaVersionamentoSoggettoFisico(AttoForm attoForm, BindingResult result, HttpServletRequest request, HttpServletResponse response, ModelMap modelMap) {

		SoggettoForm soggettoForm = attoForm.getSoggetto();

		soggettoValidation.validateNuovoSoggettoFisicoObblVer(soggettoForm, result);

		if (result.hasErrors()) {
			super.setMessage(Constants.MESSAGE, "errors.campi.controllo", null, false);

			attoForm = new AttoForm();
			attoForm.setTipoSoggetto(Constants.SOGGETTO_FISICO);

			attoForm.setIdentificativoSoggetto(soggettoForm.getIdSoggetto());
			attoForm.setVersioneSoggetto(soggettoForm.getIdVersione());

			return nuovoVersionamentoSoggetto(attoForm,result, request, response, modelMap,"confermaVersionamentoSoggetto");
		}

		boolean flgVersiona = true;

		ProcedimentoForm currentProcedimento = recuperaProcedimento();
		Integer idUfficio = (Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE);
		soggettoForm.setIdUfficio(idUfficio);
		soggettoForm.setIdProcedimento(currentProcedimento.getIdProcedimento());
		SoggettoForm tmpSogg = soggettoForm;
		SoggettoForm soggettoOld = procedimentoService.caricaValoriDettaglioSoggettoFisicoVersionamento(soggettoForm);

		flgVersiona = soggettiUtilService.controlloSoggFisVer(tmpSogg,soggettoOld);

		if(flgVersiona){

			ComboForm tmp = new ComboForm();
			tmp.setId(Constants.TIPO_ATTO_VERSIONAMENTO);
			attoForm.setTipoAtto(tmp);

			tmp = new ComboForm();
			tmp.setId(Constants.ATTO_VERSIONAMENTO_SOGGETTO);
			attoForm.setCategoriaAtto(tmp);

			inizializzaDocumento(attoForm, request);

			long idAtto =  attoService.inserisciAttoVerSoggetto(idUfficio.longValue(), currentProcedimento.getIdProcedimento(),recuperaIdCodiceUtente(), attoForm, Long.valueOf(soggettoForm.getMagistrato().getId()), soggettoForm);

			//INIZIO INVIO DATI MPS - 8.5
			if(soggettoForm.getTipoSoggetto()!=null && soggettoForm.getTipoSoggetto().equalsIgnoreCase("F")){
				String descUtente = recuperaIdCodiceUtente();
				String tipoProcedimento = null;
				if(currentProcedimento.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE) || currentProcedimento.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE_E_PATRIMONIALE))
					tipoProcedimento = Constants.TIPOPROC_PERSONALE;
				else if(currentProcedimento.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PATRIMONIALE))
					tipoProcedimento = Constants.TIPOPROC_PATRIMONIALE;
				List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(Integer.valueOf(currentProcedimento.getProcedente().getId()), idUfficio, currentProcedimento.getIdProcedimento(), tipoProcedimento);
				for(int i=0; i<uffDestinatariList.size(); i++)
				{
					Long tipoPrev = new Long(0);
					if(currentProcedimento.getTipologiaPrevenzione()!=null)
						tipoPrev = new Long(currentProcedimento.getTipologiaPrevenzione().getId());
					Long idSoggetto = soggettoForm.getIdSoggetto();
					TRelProcSogint relProc = procedimentoDao.getTrelProcSogintByIdsoggIdProcIdUff(currentProcedimento.getIdProcedimento(), idSoggetto, idUfficio, tipoPrev);
					int idVersioneNew = relProc.getTRelProcSogintVer().getId().getCodiKIdVer();
					int idVersioneOld = soggettoForm.getIdVersione().intValue();
					VariazioneAnagraficheSoggettiInteressatiRequest variazioneAna = poliziaService.createVariazioneAnagraficheSoggettiInteressatiRequest(currentProcedimento.getIdProcedimento().longValue(), idSoggetto.longValue(), idVersioneOld, idVersioneNew, idUfficio.intValue(), uffDestinatariList.get(i));
					/*long idMsg = */poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_VARIAZIONE_ANAGRAFICA_SOGGETTI_INTERESSATI, currentProcedimento.getIdProcedimento(), idAtto, variazioneAna, Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUfficio.intValue(), uffDestinatariList.get(i), descUtente);
				}
			}
			//FINE INVIO DATI MPS - 8.5

			addBreadcrumbs("GET", "/procedimento/atti/elencoAttiOrdineCronologico.htm", null);
			addBreadcrumbs("GET", "procedimento/atti/nuovo.htm", null);

			List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(idAtto, idUfficio);
			modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);

			attoForm.setCodAtto(idAtto);
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);

			String pagina = attoUtilService.copertinaAttoVersionamento(attoForm, result, request, modelMap, idUfficio);

			ModelAndView mnv = new ModelAndView(pagina, "attoForm", attoForm);
			return mnv;

		}

		super.setMessage(Constants.MESSAGE, "errors.campi.versionamento", null, false);

		attoForm = new AttoForm();
		attoForm.setTipoSoggetto(Constants.SOGGETTO_FISICO);

		attoForm.setIdentificativoSoggetto(soggettoForm.getIdSoggetto());
		attoForm.setVersioneSoggetto(soggettoForm.getIdVersione());

		addBreadcrumbs();
		return nuovoVersionamentoSoggetto(attoForm,result, request, response, modelMap,"confermaVersionamentoSoggetto");

	}


	/**
	 * metodo che versiona il soggetto giuridico
	 * @param soggettoForm
	 * @param result
	 * @param request
	 * @param response
	 * @param modelMap
	 * @return ModelAndView
	 */
	@RequestMapping(value = { "/procedimento/atto/versionamentoSoggettoGiuridico.htm" }, method = RequestMethod.POST, params = { "Conferma" })
	private ModelAndView confermaVersionamentoSoggettoGiuridico(AttoForm attoForm, BindingResult result, HttpServletRequest request, HttpServletResponse response, ModelMap modelMap) {

		SoggettoForm soggettoForm = attoForm.getSoggetto();

		if (soggettoForm.getStatoSedeLegale().getId().equalsIgnoreCase(Constants.NO_ITEM_SELECTED) )
			result.rejectValue("soggetto.statoSedeLegale.id", "NotNull");
		if (soggettoForm.getDescrizioneComuneSedeLegaleItalianoEstero() == null )
			result.rejectValue("soggetto.comuneSedeLegale.descrizione", "NotNull");

		soggettoValidation.validateNuovoSoggettoGiuridicoVer(soggettoForm, result);

		if (result.hasErrors()) {
			super.setMessage(Constants.MESSAGE, "errors.campi.controllo", null, false);

			attoForm = new AttoForm();
			attoForm.setTipoSoggetto(Constants.SOGGETTO_GIURIDICO);

			attoForm.setIdentificativoSoggetto(soggettoForm.getIdSoggetto());
			attoForm.setVersioneSoggetto(soggettoForm.getIdVersione());

			return nuovoVersionamentoSoggetto(attoForm,result, request, response, modelMap,"confermaVersionamentoSoggetto");
		}

		boolean flgVersiona = true;

		ProcedimentoForm currentProcedimento = recuperaProcedimento();

		Integer idUfficio = (Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE);
		soggettoForm.setIdUfficio(idUfficio);
		soggettoForm.setIdProcedimento(currentProcedimento.getIdProcedimento());
		SoggettoForm tmpSogg = soggettoForm;
		SoggettoForm soggettoOld = procedimentoService.caricaValoriDettaglioSoggettoGiuridicoVersionamento(soggettoForm);

		flgVersiona = soggettiUtilService.controlloSoggGiuVer(tmpSogg,soggettoOld);

		if(flgVersiona){

			ComboForm tmp = new ComboForm();
			tmp.setId(Constants.TIPO_ATTO_VERSIONAMENTO);
			attoForm.setTipoAtto(tmp);

			tmp = new ComboForm();
			tmp.setId(Constants.ATTO_VERSIONAMENTO_SOGGETTO);
			attoForm.setCategoriaAtto(tmp);


			inizializzaDocumento(attoForm, request);

			long idAtto =   attoService.inserisciAttoVerSoggetto(idUfficio.longValue(), currentProcedimento.getIdProcedimento(),recuperaIdCodiceUtente(), attoForm, Long.valueOf(soggettoForm.getMagistrato().getId()), soggettoForm);

			addBreadcrumbs("GET", "/procedimento/atti/elencoAttiOrdineCronologico.htm", null);
			addBreadcrumbs("GET", "procedimento/atti/nuovo.htm", null);

			attoForm.setCodAtto(idAtto);

			List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(idAtto, idUfficio);
			modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);

			super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);

			String pagina = attoUtilService.copertinaAttoVersionamento(attoForm, result, request, modelMap, idUfficio);

			ModelAndView mnv = new ModelAndView(pagina, "attoForm", attoForm);
			return mnv;

		}
		super.setMessage(Constants.MESSAGE, "errors.campi.versionamento", null, false);

		attoForm = new AttoForm();
		attoForm.setTipoSoggetto(Constants.SOGGETTO_GIURIDICO);

		attoForm.setIdentificativoSoggetto(soggettoForm.getIdSoggetto());
		attoForm.setVersioneSoggetto(soggettoForm.getIdVersione());

		addBreadcrumbs();
		return nuovoVersionamentoSoggetto(attoForm,result, request, response, modelMap,"confermaVersionamentoSoggetto");
	}

	/***
	 * Creazione della lista dei soggetti per il versionamento
	 *
	 * @param attoForm
	 * @param result
	 * @param request
	 * @param modelMap
	 * @return String
	 */
	public String inserisciDecretoDecisorioIGrado(AttoForm attoForm, HttpServletRequest request, ModelMap modelMap, BindingResult result) {

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = procedimentoForm.getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;

		String catAtto=Constants.DECRETO_DECISORIO_I_GRADO;
		long idTipoAtto = 9l;

		if (procedimentoForm.getTipoProcedimento() != null) {
			String idTipoProc = procedimentoForm.getTipoProcedimento().getId();
			if (idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PERSONALE_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM)||
				idTipoProc.equals(""+Constants.TIPOPROC_PERMESSI_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_CAUZIONI_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM))
			   {
			catAtto=Constants.DECRETO_DECISORIO_I_GRADO_CAMERE;
			idTipoAtto = Long.parseLong(Constants.TIPO_ATTO_ISTANZA_CAM);
			}

			if (Constants.TIPOPROC_RIESAME_PROVV_QUESTURA.equals(idTipoProc))
				idTipoAtto = Long.parseLong(Constants.TIPO_ATTO_ISTANZA);
		}

		// verifica che esista un UNICO atto decisorio di I Grado
		List<AttoForm> attoDecisorioIGrado = attoService.getAttiByProcedimento(idProcedimento, 3l, catAtto);

		if (attoDecisorioIGrado.size() > 0) {
			// request.setAttribute(MESSAGE, "error.atto.unico");
			super.setMessage(Constants.MESSAGE, "error.atto.unico", "Decisorio I Grado", true);
			attoForm.getTipoAtto().setId(Constants.NO_ITEM_SELECTED);
			return "procedimento/atto/nuovoAtto";
		}
		 // setto l'idTipoAtto a 9 (PROPOSTA)
		// se il tipo procedimento non è specificato o non è di nessuno
		// dei tipi specifici controllati nella seguente if allora l'atto è una
		// PROPOSTA

		AttoForm attoOrigine = (attoService.getAttiByProcedimento(idProcedimento, idTipoAtto, null)).get(0);
		long IdAtto = attoService.salvaAttoDecretoDecisorio(idUffOwn, idProcedimento, codiceUtente, attoForm, idStatoAtto, attoOrigine.getCodAtto());

		utilityService.gestioneMagistratiAssociati(idUffOwn, IdAtto, idProcedimento, codiceUtente);

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, IdAtto, codiceUtente, idProcedimento, request, attoForm);
		attoForm.setIdProcedimento(idProcedimento);
		
		// P.Q. MEV 2020/48 Inizio
		amministratoreService.copiaAmministratori(idUffOwn, idProcedimento, IdAtto, codiceUtente, super.printMethodName());		
		// P.Q. MEV 2020/48 Fine				
		
		String url = copertinaAtto(attoForm, result, request, modelMap);
		modelMap.addAttribute("attoForm", attoForm);
		return url;
	}

	public String inserisciDecretoDecisorioIIGrado(AttoForm attoForm, HttpServletRequest request, ModelMap modelMap, BindingResult result) {

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = procedimentoForm.getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		int idTipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");

		String catAtto=Constants.DECRETO_DECISORIO_II_GRADO;
		long idTipoAtto=Long.valueOf(Constants.TIPO_ATTO_DECRETO_II_GRADO);
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();
		if (procedimentoForm.getTipoProcedimento() != null)
			if (idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PERSONALE_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_PERMESSI_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_CAUZIONI_CAM))
				catAtto=Constants.DECRETO_DECISORIO_II_GRADO_CAM;

		// verifica che esista un UNICO atto decisorio di II Grado
		List<AttoForm> attoDecisorioIIGrado = attoService.getAttiByProcedimento(idProcedimento, idTipoAtto,
				catAtto);
		if (attoDecisorioIIGrado.size() > 0) {
			super.setMessage(Constants.MESSAGE, "error.atto.unico", "Decisorio II Grado", true);
			attoForm.getTipoAtto().setId(Constants.NO_ITEM_SELECTED);
			return "procedimento/atto/nuovoAtto";
		}

		long idAtto = attoService.salvaAttoDecretoDecisorio(idUffOwn, idProcedimento, codiceUtente, attoForm, Constants.STATOATTO_IN_LAVORAZIONE, 0l);

		//nel caso di Liquidazione amministratore
		//copia la t_rel_atto_ist_gen di primo grado per quella di secodno grado
		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {
			//caricare la decisione su t_rel_atto_ist_gen di un qualiasi atto di ricorso
			List attiRicorso = attoService.getAttiByProcedimento(idProcedimento, 4l, Constants.RICORSO_IN_APPELLO);
			AttoForm attoRicorsoGen = (AttoForm)attiRicorso.get(0);

			TRelAttoIstGenId id = new TRelAttoIstGenId();
			id.setCodiKIdAtto(attoRicorsoGen.getCodAtto());
			id.setCodiKIdProc(idProcedimento);
			id.setCodiKIdUffOwner(idUffOwn);
			TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);

			if(relAttoIstGen!=null) {
				beneService.salvaDecisorioBeniIstGen(idAtto, idProcedimento, codiceUtente, idUffOwn, idTipoUfficio, "DECISORIO", relAttoIstGen.getTTpEsitoByCodiFkIdEsito1().getCodiKIdEsito(), relAttoIstGen);
			}

		}
		utilityService.gestioneMagistratiAssociati(idUffOwn, idAtto, idProcedimento, codiceUtente);

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, idProcedimento, request, attoForm);

		////////////////////////////////////////////////////////////////////////////////////////////////
		// J.C MEV 2020/48 Inizio SITMP 294
		amministratoreService.copiaAmministratoriIIGrado(idUffOwn, idProcedimento, idAtto, codiceUtente, super.printMethodName());
		// J.C MEV 2020/48 Fine SITMP 294
		////////////////////////////////////////////////////////////////////////////////////////////////
		String url = copertinaAtto(attoForm, result, request, modelMap);

		modelMap.addAttribute("attoForm", attoForm);
		return url;
	}


	/**
	 * inserisciDecretoDecisorioIIIGrado
	 * @param attoForm
	 * @param request
	 * @param modelMap
	 * @param result
	 * @return String
	 */
	public String inserisciDecretoDecisorioIIIGrado(AttoForm attoForm, HttpServletRequest request, ModelMap modelMap, BindingResult result) {

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = procedimentoForm.getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		int idTipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();

		String catAtto=Constants.SENTENZA_SU_RICORSO_II_GRADO;
		long idTipoAtto=Long.valueOf(Constants.TIPO_ATTO_SENTENZA_CASSAZIONE_DA_CDA);

		if (String.valueOf(request.getSession().getAttribute("idTipoUfficio")).equals(Constants.TIPO_UFFICIO_TRIBUNALE)) {

				idTipoAtto=Long.valueOf(Constants.TIPO_ATTO_SENTENZA_CASSAZIONE);
				catAtto=Constants.SENTENZA_SU_RICORSO_II_GRADO_DA_TRIB;
			}

		// verifica che esista un UNICO atto decisorio di II Grado
		List<AttoForm> attoDecisorioIIIGrado = attoService.getAttiByProcedimento(idProcedimento, idTipoAtto,
				catAtto);
		if (attoDecisorioIIIGrado.size() > 0) {
			super.setMessage(Constants.MESSAGE, "error.atto.unico", "Sentenza di Cassazione", true);
			attoForm.getTipoAtto().setId(Constants.NO_ITEM_SELECTED);
			return "procedimento/atto/nuovoAtto";
		}

		long idAtto = attoService.salvaAttoDecretoDecisorio(idUffOwn, idProcedimento, codiceUtente, attoForm, Constants.STATOATTO_IN_LAVORAZIONE, 0l);

		//nel caso di Liquidazione amministratore
		//copia la t_rel_atto_ist_gen di primo grado per quella di secodno grado
		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM )) {
			//caricare la decisione su t_rel_atto_ist_gen di un qualiasi atto di ricorso
			String catAttoRicerca = Constants.RICORSO_IN_CASSAZIONE;
			long tipoAttoRicerca = 19l;
			if(catAtto.equals(Constants.SENTENZA_SU_RICORSO_II_GRADO_DA_TRIB)) {
				catAttoRicerca = Constants.RICORSO_IN_CASSAZIONE_DA_TRIB;
				 tipoAttoRicerca = 4l;
			}
			List attiRicorso = attoService.getAttiByProcedimento(idProcedimento, tipoAttoRicerca, catAttoRicerca);
			AttoForm attoRicorsoGen = (AttoForm)attiRicorso.get(0);

			TRelAttoIstGenId id = new TRelAttoIstGenId();
			id.setCodiKIdAtto(attoRicorsoGen.getCodAtto());
			id.setCodiKIdProc(idProcedimento);
			id.setCodiKIdUffOwner(idUffOwn);
			TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
			if(relAttoIstGen!=null) {
				beneService.salvaDecisorioBeniIstGen(idAtto, idProcedimento, codiceUtente, idUffOwn, idTipoUfficio, "DECISORIO", relAttoIstGen.getTTpEsitoByCodiFkIdEsito1().getCodiKIdEsito(), relAttoIstGen);
				if(catAtto.equals(Constants.SENTENZA_SU_RICORSO_II_GRADO)) {
					beneService.salvaDecisorioBeniIstGen(idAtto, idProcedimento, codiceUtente, idUffOwn, idTipoUfficio, "DECISORIO_II", relAttoIstGen.getTTpEsitoByCodiFkIdEsito2().getCodiKIdEsito(), relAttoIstGen);
				}
			}

		}
		utilityService.gestioneMagistratiAssociati(idUffOwn, idAtto, idProcedimento, codiceUtente);


		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, idProcedimento, request, attoForm);

		String url = copertinaAtto(attoForm, result, request, modelMap);

		modelMap.addAttribute("attoForm", attoForm);
		return url;
	}


	public String inserisciDecretoProvvIstanza(AttoForm attoForm, HttpServletRequest request, ModelMap modelMap, BindingResult result) {

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = procedimentoForm.getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();

		String catAtto=Constants.DECRETO_DECISORIO_PROVV_ISTANZA;
		long idTipoAtto=Long.valueOf(Constants.TIPO_ATTO_DECRETO_II_GRADO);

		// verifica che esista un UNICO atto decisorio di II Grado
		List<AttoForm> attoDecisorioIIGrado = attoService.getAttiByProcedimento(idProcedimento, idTipoAtto,
				catAtto);
		if (attoDecisorioIIGrado.size() > 0) {
			super.setMessage(Constants.MESSAGE, "error.atto.unico", "Decisorio II Grado", true);
			attoForm.getTipoAtto().setId(Constants.NO_ITEM_SELECTED);
			return "procedimento/atto/nuovoAtto";
		}

		long idAtto = attoService.salvaAttoDecretoDecisorio(idUffOwn, idProcedimento, codiceUtente, attoForm, Constants.STATOATTO_IN_LAVORAZIONE, 0l);
		utilityService.gestioneMagistratiAssociati(idUffOwn, idAtto, idProcedimento, codiceUtente);



		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, idProcedimento, request, attoForm);

		String url = copertinaAtto(attoForm, result, request, modelMap);

		modelMap.addAttribute("attoForm", attoForm);
		return url;
	}


	@RequestMapping(value = "/procedimento/atto/nuovoDecretoIncompetenza.htm", method = RequestMethod.POST)
	public ModelAndView nuovoDecretoIncompetenza(AttoForm attoForm, HttpServletRequest request, BindingResult result, ModelMap modelMap) {

		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		// verifica che esista un UNICO decreto di incompetenza e restituzione
		// atti alla procura
		List<AttoForm> decreti = attoService.getAttiByProcedimento(idProcedimento, 3l, Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA);
		if (decreti.size() > 0) {
			// request.setAttribute(MESSAGE, "error.atto.unico");
			super.setMessage(Constants.MESSAGE, "error.atto.unico", "Decreto di incompetenza e restituzione atti alla Procura", false);
			return new ModelAndView("/procedimento/atto/nuovoAtto", "atto", attoForm);
		}

		String url = this.decretoUtilService.apriDecretoIncompetenza(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA, attoForm, request, result, modelMap);
		if (!result.hasErrors()) {

			// imposta il tipo di atto a 3 (Decreto)
			attoForm.setTipoAtto(new ComboForm(Constants.TIPO_ATTO_DECRETO, null));
			// imposta la categoria dell'atto corrente a 308 (Decreto di
			// incompetenza)
			attoForm.setCategoriaAtto(new ComboForm(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA, null));

			// aggiunto il salvataggio prima di modificare i dati nella pagina
			// di dettaglio
			// come per gli altri atti
			int idUfficio = recuperaIdUfficioUtente();
			String codiceUtente = recuperaIdCodiceUtente();
			long idAtto = this.decretoUtilService.salvaModificaDecretoIncompetenza(attoForm, idUfficio, codiceUtente, idProcedimento, request);
			attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);
		}

		ModelAndView mnv = new ModelAndView(url);
		modelMap.addAttribute("attoForm", attoForm);
		return mnv;
	}

