	@RequestMapping(value = { "/procedimento/atto/nuovoDecretoIncompetenza.htm", "/procedimento/atto/nuovoDecretoIncompetenzaProcura.htm" }, method = RequestMethod.POST, params = { "SalvaModifica" })
	public String salvaModificaDecretoIncompetenza(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result,
			HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		attoValidation.validateFormDecretoIncompetenza(attoForm, result, request, modelMap, false);

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		if (result.hasErrors())
			return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		this.decretoUtilService.salvaModificaDecretoIncompetenza(attoForm, idUfficio, codiceUtente, idProcedimento, request);

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);
		// FINE GESTIONE DOCUMENTALE
		return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
	}

	@RequestMapping(value = { "/procedimento/atto/nuovoDecretoIncompetenza.htm", "/procedimento/atto/nuovoDecretoIncompetenzaProcura.htm" }, method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaDecretoIncompetenza(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		attoForm.setIdProcedimento(idProcedimento);

		attoValidation.validateFormDecretoIncompetenza(attoForm, result, request, modelMap, true);
		if (result.hasErrors())
			return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);

		// MODIFICA 01/2014
		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore)
			return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
		// MODIFICA 01/2014

		long idUfficio = recuperaIdUfficioUtente();

		String codiceUtente = recuperaIdCodiceUtente();
		long categoriaAtto = Long.parseLong(attoForm.getCategoriaAtto().getId());

		attoForm.setDataRegistrazione(Calendar.getInstance().getTime());

		long idAtto = this.decretoUtilService.salvaModificaDecretoIncompetenza(attoForm, idUfficio, codiceUtente, idProcedimento, request);
		long idDestinatario1 = 0;
		long idDestinatario2 = 0;
		long idDestinatario3 = 0;
		long idDestinatarioProposta = 0;

		if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA)
				|| attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_TRASF_ALTRO_TRIBUNALE)) {

			procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);
			List<ComboForm> uffDestinatari = (List<ComboForm>) modelMap.get("ufficiList");

			if (uffDestinatari.size() >= 1)
				idDestinatario1 = Long.valueOf(uffDestinatari.get(0).getId());
			if (uffDestinatari.size() >= 2)
				idDestinatario2 = Long.valueOf(uffDestinatari.get(1).getId());
			if (uffDestinatari.size() >= 3)
				idDestinatario3 = Long.valueOf(uffDestinatari.get(2).getId());

			this.attoService.inviaDecretoIncompetenza(idProcedimento, idAtto, idUfficio, idDestinatario1, idDestinatario2,
					idDestinatario3, codiceUtente, idUfficio, categoriaAtto, super.printMethodName());
			super.setMessage(Constants.SUCCESS_MESSAGE, "succes.invio.generic", null, false);
		} else if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_PROCURA)) {

			List<ComboForm> uffDestinatari = ufficioUtilService.getUfficiDestinatariIncompetenzaProcura(request);

			if (uffDestinatari.size() >= 1)
				idDestinatarioProposta = Long.valueOf(uffDestinatari.get(0).getId());
			if (uffDestinatari.size() >= 2)
				idDestinatario2 = Long.valueOf(uffDestinatari.get(1).getId());
			if (uffDestinatari.size() >= 3)
				idDestinatario3 = Long.valueOf(uffDestinatari.get(2).getId());

			attoService.inviaDecretoIncompetenzaProcura(idProcedimento, idAtto, idUfficio, idDestinatarioProposta, idDestinatario2, idDestinatario3,
					codiceUtente, idUfficio, categoriaAtto, super.printMethodName());
			super.setMessage(Constants.SUCCESS_MESSAGE, "succes.invio.generic", null, false);
		}

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);
		// FINE GESTIONE DOCUMENTALE

		super.updateProcedimentoIntoSession(idProcedimento);
		// invoca metodo per l'esecuzione dell'invio
		return copertinaAtto(attoForm, result, request, modelMap);
		// return "redirect:/procedimento/atti/elenco.htm";
	}

	@RequestMapping(value = { "/procedimento/atto/nuovoDecretoIncompetenza.htm", "/procedimento/atto/nuovoDecretoIncompetenzaProcura.htm" }, method = RequestMethod.POST, params = { "Conferma" })
	public String salvaDecretoIncompetenza(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = recuperaIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = recuperaAtto().getCodAtto();
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());
		// INIZIA GESTIONE DOCUMENTALE
		if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)){
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
			}
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateAttoDateSalva(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
		}

		attoForm.setCodAtto(idAtto);

		inizializzaDocumento(attoForm, request);

		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;

		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		attoForm.setDataRegistrazione(null);

		attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		return this.decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);

	}


	@RequestMapping(value = "/procedimento/atto/nuovoDecretoIncompetenza.htm", method = RequestMethod.POST, params = { "Definitivita" })
	public String apriFormDefinitivita(@ModelAttribute("attoForm") AttoForm attoForm, HttpServletRequest request, ModelMap modelMap) {

		String tipoDecreto = attoForm.getCategoriaAtto().getId();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		AttoForm atto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
		long idAtto = atto.getCodAtto();
		recuperaIdCodiceUtente();

		List<BeneSoggettoForm> misurePatr = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(idProcedimento, idAtto, idUffOwn);
		List<BeneSoggettoForm> misurePers = procedimentoService.listaSoggettiMisuraPersonaleAssociatiAdAttoEProcedimento(idProcedimento, idAtto,
				idUffOwn);

		// se presente, la data di definitività è uguale per tutte le misure
		// presenti, quindi prendo la prima
		// data definitività di una misura personale o patrimoniale
		Date dataDefinitivita = null;

		// controllo disabilitazione definitività
		boolean disableDefinitivita = false;
		if (misurePatr != null && misurePatr.size() > 0) {
			BeneSoggettoForm beneSogg = misurePatr.get(0);
			if (beneSogg != null) {
				List<SoggettoForm> soggetti = beneSogg.getSoggetti();
				if (soggetti != null && soggetti.size() > 0) {
					SoggettoForm sogg = soggetti.get(0);
					dataDefinitivita = sogg.getMisura().getDataDefinitivita();
				}
			}
		}

		if (misurePers != null && misurePers.size() > 0) {
			BeneSoggettoForm beneSogg = misurePers.get(0);
			if (beneSogg != null) {
				List<MisuraForm> misure = beneSogg.getMisure();
				if (misure != null && misure.size() > 0) {
					MisuraForm mis = misure.get(0);
					dataDefinitivita = mis.getDataDefinitivita();
				}
			}
		}
		//
		if (dataDefinitivita != null) {
			attoForm.setDataDefinitivita(dataDefinitivita);
			disableDefinitivita = true;
		}
		if (attoForm.getIdProcEmiss()!=0 && !(attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento))
			disableDefinitivita = true;

		modelMap.addAttribute("disableDefinitivita", disableDefinitivita);

		List<ComboForm> ufficiList = new ArrayList<ComboForm>();
		long idTipoPrev = Long.valueOf(recuperaProcedimento().getCalcoloTipologiaPrevenzione());
		if (tipoDecreto.equals(Constants.DECRETO_INCOMPETENZA_TRASF_ALTRO_TRIBUNALE) && !disableDefinitivita) {
			//ricerco i tribunali legati alla procura proponente
			//escludendo l'ufficio tribunale connesso
			ComboForm procProp = commonService.getProcuraProponente(idProcedimento);
			ufficiList = commonService.getRelProcTrib(Long.valueOf(procProp.getId()), Constants.TIPO_UFFICIO_PROCURA, idTipoPrev, null, null);
			for(int i=0;i<ufficiList.size();i++) {
				ComboForm uffTrib = ufficiList.get(i);
				if(Integer.valueOf(uffTrib.getId()).intValue() == idUffOwn)
					ufficiList.remove(i);
			}
			modelMap.put("ufficiDestinatari", ufficiList);
		}
		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		return "/procedimento/atto/definitivita";
	}

	@RequestMapping(value = "/procedimento/atto/nuovoDecretoIncompetenza.htm", method = RequestMethod.POST, params = { "ConfermaDefinitivita" })
	public String confermaDefinitivita(@ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		attoValidation.validateConfermaDefinitivita(attoForm, result, request, modelMap);
		if (result.hasErrors())
			return this.apriFormDefinitivita(attoForm, request, modelMap);
		ProcedimentoForm procedimento = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		long idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		String tipoDecreto = attoForm.getCategoriaAtto().getId();
		ComboForm idUffProcProp = commonService.getProcuraProponente(procedimento.getIdProcedimento());
		long idProcProp = 0l;
		if (idUffProcProp != null)
			idProcProp = Long.parseLong(idUffProcProp.getId());
		if (tipoDecreto.equals(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA))
			attoService.inviaDefinitivita(attoForm, codiceUtente, idUfficio, procedimento, idProcProp, null);
		else if (tipoDecreto.equals(Constants.DECRETO_INCOMPETENZA_TRASF_ALTRO_TRIBUNALE)) {
			long idDestinatario = Long.parseLong(attoForm.getDestinatario2().getId());
			attoService.inviaDefinitivita(attoForm, codiceUtente, idUfficio, procedimento, new Long(idUffProcProp.getId()), idDestinatario);
		}
		// cambia stato al procedimento
		super.updateProcedimentoIntoSession(procedimento.getIdProcedimento());
		super.setMessage(Constants.SUCCESS_MESSAGE, "succes.invio.generic", null, false);
		return copertinaAtto(attoForm, result, request, modelMap);
	}


