	public ModelAndView inserisciDecretoSequestro(AttoForm attoForm, HttpServletRequest request, ModelMap modelMap, BindingResult result) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;
		long IdAtto = attoService.salvaAttoDecretoConMagistrato(idUffOwn, idProcedimento, codiceUtente, attoForm, idStatoAtto);

		utilityService.gestioneMagistratiAssociati(idUffOwn, IdAtto, idProcedimento, codiceUtente);

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, IdAtto, codiceUtente, idProcedimento, request, attoForm);
		String url = copertinaAtto(attoForm, result, request, modelMap);
		ModelAndView mnv = new ModelAndView(url, "attoForm", attoForm);
		return mnv;
	}

