	@RequestMapping(value = { "/procedimento/atto/beneAssociatoADecretoOpposizioneDissequestro.htm",
			"/procedimento/atto/beneAssociatoADecretoRevocaOpposizioneDissequestro.htm", "/procedimento/atto/beneAssociatoARevocazioneConfisca.htm"
			, "/procedimento/atto/beneAssociatoADecretoProrogaSequestro.htm"},
			method = RequestMethod.POST, params = { "Modifica" })
	private String beneAssociatoADecreto(BeneForm beneForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		beneValidation.validateListaBeni(beneForm, request, result);
		if (result.hasErrors())
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		Integer idUfficioUtente = (Integer) request.getSession().getAttribute("idUffOwner");
		BeneForm beneScelto = beneService.beneById(idUfficioUtente, beneForm.getIdBene(), idProcedimento);
		request.getSession().setAttribute("beneScelto", beneScelto);
		// se provengo dalla maschera dell'atto decreto di sequestro
		long idAtto = 0l;
		if (request.getSession().getAttribute(Constants.ATTO) != null
				&& ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto() > idAtto)
			idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		List<BeneSoggettoForm> beniSoggetti = beneService.listaSoggettiBeniProc(idProcedimento, idUfficioUtente, beneForm.getIdBene(), idAtto);
		modelMap.addAttribute("soggettiDelBene", beniSoggetti);
		request.getSession().setAttribute("beneDaImpostare", beneScelto);
		modelMap.addAttribute("beneForm", beneScelto);
		modelMap.addAttribute("soggettiDelProcedimento", procedimentoService.soggettiDirettiInteressatiDelProcedimento(idProcedimento));
		addBreadcrumbs();
		return "/procedimento/bene/titoliDiInteresse";
	}

