	@SuppressWarnings("unused")
	@RequestMapping(value = "/procedimento/atto/beneAssociatoADecretoSequestro.htm", method = RequestMethod.POST, params = { "Elimina" })
	private String eliminaBeneAssociatoADecretoSequestro(BeneForm beneForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		beneValidation.validateListaBeni(beneForm, request, result);
		if (result.hasErrors())
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		Integer idUfficioUtente = recuperaIdUfficioUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		String codUtente = recuperaIdCodiceUtente();
		AttoForm attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		List<BeneSoggettoForm> beniSoggetti = beneService.listaSoggettiBeniProc(idProcedimento, idUfficioUtente, beneForm.getIdBene(), idAtto);

		for (Iterator iterator = beniSoggetti.iterator(); iterator.hasNext();) {
			BeneSoggettoForm beneSoggettoSelezionato = (BeneSoggettoForm) iterator.next();

			Boolean daProposta = true;
//			double quotaSequestroTotale = 0;
//			int quotaFrazioneNumeratoreSeqTotale = 0;
//			int quotaFrazioneDenominatoreSeqTotale = 0;
			if (attoForm != null && !(attoForm.getTipoAtto().getId().equalsIgnoreCase((Constants.TipoAtto.TIPO_ATTO) + "")))
				daProposta = false;

			// Carico le percentuali o frazioni per T_REL_PROC_BENE_TIT
			double quotaSequestro = 0;
			double numeratoreFrazioneSequestro = 0;
			double denominatoreFrazioneSequestro = 0;

			if (beneSoggettoSelezionato.getQuotaInteresse() != null)
				quotaSequestro = beneSoggettoSelezionato.getQuotaInteresse().doubleValue();
			if (beneSoggettoSelezionato.getNumeratoreFrazioneQuota() != null)
				numeratoreFrazioneSequestro = beneSoggettoSelezionato.getNumeratoreFrazioneQuota().doubleValue();
			if (beneSoggettoSelezionato.getDenominatoreFrazioneQuota() != null)
				denominatoreFrazioneSequestro = beneSoggettoSelezionato.getDenominatoreFrazioneQuota().doubleValue();
			beneService.modificaRelBeneTit(beneSoggettoSelezionato, idProcedimento, idAtto, idUfficioUtente, codUtente, daProposta, quotaSequestro,
					numeratoreFrazioneSequestro, denominatoreFrazioneSequestro, Constants.TipiOperazioneCRUD.DELETE, super.printMethodName());
		}
		attoService.eliminaMisBeneAtto(idProcedimento, idAtto, beneForm.getIdBene(), idUfficioUtente, 0l, 0l);

		return copertinaAtto(new AttoForm(), result, request, modelMap);
	}

