	@RequestMapping(value = "/procedimento/atto/remissioneSuRuolo.htm", method = RequestMethod.POST, params = { "Salva" })
	public String salvaDecretoRemissioneSuRuolo(@Valid UdienzaForm udienzaForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		AttoForm attoForm = new AttoForm();
		if (request.getSession().getAttribute(Constants.ATTO) != null)
			attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		long idUdienzaPrec = udienzaForm.getUdienzaPrecedente().getCodUdienza();
		UdienzaForm udienzaPrec = attoService.getUdienzaById(idUdienzaPrec, idUfficio);
		attoValidation.validateInserisciUdienzaDecreto(udienzaForm, result, request, modelMap);

		if (!result.hasErrors())
			salvaUdienzaDecretoRiemissioneSuRuolo(udienzaForm, attoForm, idUfficio, codiceUtente, idProcedimento, request);
		udienzaPrec.setEsito(new ComboForm("10", "RISERVA"));
		udienzaForm.setUdienzaPrecedente(udienzaPrec);
		procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
		modelMap.addAttribute("udienzaForm", udienzaForm);
		return "/procedimento/atto/copertinaDecretoRemissioneRuolo";
	}

	private void salvaUdienzaDecretoRiemissioneSuRuolo(UdienzaForm udienzaForm, AttoForm attoForm, long idUfficio, String codiceUtente,
			long idProcedimento, HttpServletRequest request) {

		if (udienzaForm.getCodUdienza() == 0) {
			// salvataggio di una nuova udienza
			if (udienzaForm.getAllegato().getFileData() != null && udienzaForm.getAllegato().getFileData().getSize() > 0) {
				udienzaForm.getAllegato().setFileName(udienzaForm.getAllegato().getFileData().getOriginalFilename());
				udienzaForm.getAllegato().setContentType(udienzaForm.getAllegato().getFileData().getContentType());
			}
			// Chiamo la SP per il salvataggio dei dati dell'udienza e
			// dell'allegato
			Map<String, Long> resultMap = attoService.salvaUdienzaDecretoRiemissioneSuRuolo(idUfficio, codiceUtente, idProcedimento,
					attoForm.getCodAtto(), udienzaForm);
			udienzaForm.setCodUdienza(resultMap.get("ID_UDIENZA"));
			udienzaForm.setCodAtto(attoForm.getCodAtto());
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "INSERIMENTO", false);
		} else {
			// modifica di un'udienza già presente in base dati
			this.inizializzaDocumento(udienzaForm, request);
			udienzaForm.setCodAtto(attoForm.getCodAtto());
			attoService.modificaUdienza(idUfficio, udienzaForm);
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);
		}
	}

	@RequestMapping(value = "/procedimento/atto/remissioneSuRuolo.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaDecretoRemissioneSuRuolo(@Valid UdienzaForm udienzaForm, BindingResult result, ModelMap map, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();

		long idUdienzaPrec = udienzaForm.getUdienzaPrecedente().getCodUdienza();
		UdienzaForm udienzaPrecedente = attoService.getUdienzaById(idUdienzaPrec, idUffOwn);
		udienzaPrecedente.setEsito(new ComboForm("10", "RISERVA"));
		udienzaForm.setUdienzaPrecedente(udienzaPrecedente);
		attoValidation.validateAttoDate(udienzaForm, result, request);
		if (result.hasErrors()) {
			procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(map);
			updateViewAndMenu(procedimento, request);
			MenuController.caricaMenu("15", request);
			map.addAttribute("udienzaForm", udienzaForm);
			if (!CollectionUtils.isEmpty(result.getFieldErrors())) {
				super.setMessage(Constants.MESSAGE, "errors.campi.controllo", null, false);
			}
			return "/procedimento/atto/copertinaDecretoRemissioneRuolo";
		} else {
			// MODIFICA 01/2014
			// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
			boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
			if (errore) {
				procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(map);
				updateViewAndMenu(procedimento, request);
				MenuController.caricaMenu("15", request);
				map.addAttribute("udienzaForm", udienzaForm);
				return "/procedimento/atto/copertinaDecretoRemissioneRuolo";
			}
			// MODIFICA 01/2014

			AttoForm attoForm = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
			attoForm.setDataRegistrazione(new Date());
			attoForm.setDataEmissione(udienzaForm.getDataEmissione());
			attoForm.setDataDeposito(udienzaForm.getDataDeposito());
			ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(procedimento.getIdProcedimento());
			long idStatoAtto = Constants.STATOATTO_REGISTRATO;
			long idProcUdi = 0l;
			if (procInUdienza != null)
				idProcUdi = Long.parseLong(procInUdienza.getId());
			udienzaForm.setCodAtto(attoForm.getCodAtto());
			// Chiamo la SP per il salvataggio dei dati dell'udienza e
			// dell'allegato
			salvaUdienzaDecretoRiemissioneSuRuolo(udienzaForm, attoForm, idUffOwn, codiceUtente, procedimento.getIdProcedimento(), request);
			attoService.inviaAttoDecretoRemissioneSuRuolo(attoForm, idStatoAtto, idUffOwn, procedimento.getIdProcedimento(),
					codiceUtente, idProcUdi, udienzaForm.getUdienzaPrecedente().getCodUdienza(), udienzaForm.getCodUdienza());
			super.setMessage(SUCCESS_MESSAGE, "success.invioAtto", null, false);
			return copertinaAtto(attoForm, result, request, map);
		}
	}

