	@RequestMapping(value = {"/procedimento/atto/visualizzaDirettiInteressati.htm","/procedimento/atto/visualizzaDirettiInteressatiSentenzaCassazioneCDA.htm"}, method = RequestMethod.POST, params = { "DecisioneOpposizioneDivietiQuestore" })
	public String apriDecisiorioOpposizioneDivietiQuestore(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap map) {
		ProcedimentoForm procedimento = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		long idProcedimento = procedimento.getIdProcedimento();
		AttoForm atto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
		long idAtto = atto.getCodAtto();
		int idUffOwn = recuperaIdUfficioUtente();
		String codiceUtente = (String) request.getSession().getAttribute(Constants.ID_CODICE_UTENTE);

		List<ComboForm> esiti = procedimentoService.getEsiti("EM", Long.parseLong(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE), 0);
		map.addAttribute("esitiDecisione", esiti);

		String[] decisioni = procedimentoServiceCam.getEsitoDecisione(idProcedimento, idAtto, idUffOwn, codiceUtente);

		SoggettoForm soggetto = new SoggettoForm();
		soggetto.setDecisioneSuDecreto(decisioni[0]);

		List<TRelAttoMisPers> relAttoMisPersList = attoService.getTRelAttoMisPers(idProcedimento,idAtto,idUffOwn);
		if(relAttoMisPersList != null && relAttoMisPersList.size() > 0)
		{
			TRelAttoMisPers relAttoMisPers = (TRelAttoMisPers)relAttoMisPersList.get(0);
			ComboForm decisioneSentenza = new ComboForm();
			if(relAttoMisPers.getTTpEsitoByCodiFkIdEsito3() != null)
				decisioneSentenza.setId(relAttoMisPers.getTTpEsitoByCodiFkIdEsito3().getCodiKIdEsito()+"");

			soggetto.setDecisioneErroreMaterialeIIIGrado(decisioneSentenza);
			TAtto attoDB = attoService.getTAttoById(idAtto, idUffOwn);
			soggetto.setDataRicezioneSentenza(attoDB.getDataRicezione());
			TDecreto decreto = attoService.getTDecreto(idAtto,  idUffOwn);
			soggetto.setNumeAnnoSentenza(decreto.getNumeAnnoAtto().toString());
			soggetto.setNumeSentenza(decreto.getNumeAtto().toString());

		}

		/***ROB***/
		/*Leggere in T_DEF_PERS.data_definitivita ed inserirla quando è registrato*/

		List<ComboForm> esiti3 = procedimentoService.getEsiti("X", Long.parseLong(Constants.SENTENZA_SU_RICORSO_II_GRADO_DA_TRIB), 0);

		map.addAttribute("esitiDecisione3", esiti3);
		map.addAttribute("soggettoForm", soggetto);

		String readOnlyDecisione3Grado = null;

		if(atto != null && atto.getStatoAtto() != null && "3".equalsIgnoreCase(atto.getStatoAtto().getId()))
		{
			 readOnlyDecisione3Grado = "true";
		}
		else
		{
			if(atto.getCategoriaAtto() != null && Constants.SENTENZA_SU_RICORSO_II_GRADO_DA_TRIB.equalsIgnoreCase(atto.getCategoriaAtto().getId()))
				 readOnlyDecisione3Grado = "false";

		}

		map.addAttribute("readOnlyDecisione3Grado", readOnlyDecisione3Grado);

		return "procedimento/atto/decisioneOpposizioneDivietiQuestore";
	}


	@RequestMapping(value = { "/procedimento/atto/visualizzaDirettiInteressati.htm", "/procedimento/atto/sentenzaOpposizioneDissequestro.htm",
			"/procedimento/atto/nuovoDecretoIncompetenza.htm" }, method = RequestMethod.POST, params = { "DecisioneBeni" })
	public String apriDecisiorioBeni(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap map) {

		ProfiloForm profilo = (ProfiloForm) request.getSession().getAttribute("profilo");
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();

		AttoForm attoForm = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
		Long idProcedimentoCda=beneSoggettoForm.getIdProcedimentoCda();

		 if (idProcedimentoCda== null) {
			 idProcedimentoCda=beneSoggettoForm.getIdProcedimentoCda();
		 }

		ProcedimentoForm procedimento = recuperaProcedimento();
		if (idProcedimentoCda != null && idProcedimentoCda > 0){
			int idUffOwn1=Integer.parseInt(commonService.getUfficiCompetenza(procedimento.getIdProcedimento(),19L).get(0).getId());

			beneSoggettoForm.setIdUfficio(idUffOwn1);
			beneSoggettoForm.setIdProcedimento(idProcedimentoCda);
			idProcedimento=idProcedimentoCda;
			idUffOwn=idUffOwn1;
			beneSoggettoForm.setIdProcedimentoCda(idProcedimentoCda);
		   }
		else {

			beneSoggettoForm.setIdUfficio((Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE));
			beneSoggettoForm.setIdProcedimento(((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento());
		}

		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {

			//caricare la decisione su t_rel_atto_ist_gen
			TRelAttoIstGenId id = new TRelAttoIstGenId();
			id.setCodiKIdAtto(idCurrentAtto);
			id.setCodiKIdProc(idProcedimento);
			id.setCodiKIdUffOwner(idUffOwn);
			TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
			if(relAttoIstGen!=null) {
				if(relAttoIstGen.getTTpEsitoByCodiFkIdEsito1()!=null) {
					ComboForm cb = new ComboForm();
					cb.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito1().getCodiKIdEsito());
					beneSoggettoForm.setDecisioneBeni(cb);
					beneSoggettoForm.setMotivazione1(relAttoIstGen.getDescAltro1());
					beneSoggettoForm.setImporto1(relAttoIstGen.getImpo1());
				}
			}
			List<AttoForm> idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 5l, Constants.ISTANZA_LIQUIDAZIONE_AMM);
			if(idsAttoIstanza!=null && !idsAttoIstanza.isEmpty()) {
				AttoForm af = idsAttoIstanza.get(0);
				AmministratoreForm amministratore = procedimentoService.getAmministratoreByIstanza(idProcedimento, af.getCodAtto(), idUffOwn);
				List<BeneForm>beniInAmministrazione = beneService.listaBeniInAmministrazione(idUffOwn, idProcedimento, af.getCodAtto(), amministratore.getId());
				map.addAttribute("beniInAmministrazione", beniInAmministrazione);
			}

			int idUffOwnRic = (Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE);
			long idProcRic = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
			long tipoAttoRic = new Long(Constants.TIPO_ATTO_ISTANZA_CAM);
			long catAttoRic = new Long(Constants.ISTANZA_LIQUIDAZIONE_AMM);
			List<AttoForm> istanze = attoService.getricercaIstanza(idUffOwnRic, idProcRic, tipoAttoRic, catAttoRic);
			AttoForm istanza = new AttoForm();
			if (istanze != null && !istanze.isEmpty()) {
				istanza = istanze.get(0);
				SoggettoForm soggettoForm = new SoggettoForm();
				soggettoForm.setDescRichiesta(istanza.getNote());
				attoForm.setSoggetto(soggettoForm);
				map.addAttribute("attoForm", attoForm);
			}

		} else {
			List<BeneSoggettoForm> beni = procedimentoService.listaBeniAttoDecisorio(idProcedimento, idCurrentAtto, idUffOwn, 0, 0, 0, 0, 0);
			map.addAttribute("risultatoRicerca", beni);
		}
		map.addAttribute("beneSoggetto", beneSoggettoForm);
		String esitoReadOnly = "false";
		String categoriaAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId();
		Long catAttoSearch;
		if (((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) && idProcedimentoCda==null)
			catAttoSearch = Long.parseLong(Constants.DECRETO_DECISORIO_II_GRADO);
		else
			catAttoSearch = Long.parseLong(Constants.DECRETO_DECISORIO_I_GRADO);
		if (categoriaAtto != null && categoriaAtto.equals(Constants.SENTENZA_OPPOSIZIONE_AL_DISSEQUESTRO)) {
			catAttoSearch = Long.parseLong(Constants.SENTENZA_OPPOSIZIONE_AL_DISSEQUESTRO);

			if (attoForm.getDataRegistrazione() != null) {
				List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
				map.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
			} else
				map.addAttribute("ufficiList", ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca());
		} else if (categoriaAtto != null && categoriaAtto.equals(Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA)) {
			catAttoSearch = Long.parseLong(Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA);
			if (attoForm.getDataRegistrazione() != null) {
				List<ComboForm> listaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
				map.addAttribute("ufficiListFromFlussiOut", listaUfficiDestinatari);
			} else {
				// carica elenco soggetti diretti interessati x Tasto Spese processuali Marzo 2020 mev
				List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(
						procedimento.getIdProcedimento(), Constants.RUOLO_DIRETTO, Constants.Flag.S);
				map.addAttribute("soggetti", soggetti);
				map.addAttribute("ufficiList", ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca());
			}
		} else if (categoriaAtto != null
				&& (categoriaAtto.equals(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA)
						|| categoriaAtto.equals(Constants.DECRETO_INCOMPETENZA_TRASF_ALTRO_TRIBUNALE)
						|| categoriaAtto.equals(Constants.DECRETO_INCOMPETENZA_PROCURA)))
			esitoReadOnly = "true";
		map.addAttribute("esitoReadOnly", esitoReadOnly);

		AttoForm af = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		if (af != null && (af.getNumeAnnoAtto() != null && af.getNumeAnnoAtto().length() > 0)
				&& (af.getNumeAtto() != null && af.getNumeAtto().length() > 0))
			map.addAttribute("esitoReadOnly", "true");

		String carEsito = "T";
		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM) ||
					idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM) ||
					idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM)) {

			if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) carEsito = "LA";
			if(idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM)) carEsito = "T";
			if(idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) carEsito = "EM";

			catAttoSearch = new Long(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE);
		}

		long idUffRic = profilo.getIdTipoUfficio();
		if(carEsito.equals("LA")) idUffRic = 0;

		List<ComboForm> esiti = procedimentoService.getEsiti(carEsito, catAttoSearch, idUffRic);
//		Segnalazione EMS-142
		if(idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM) || idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM))
			esiti.remove(new ComboForm("234","ACCOGLIE PARZIALMENTE L'ISTANZA"));

		map.addAttribute("esitiDecisioneBeni", esiti);
		map.addAttribute("attoForm", attoForm);

		// se è il decreto decisorio di II grado visualizzo una pagina diversa
		if (categoriaAtto.equals(Constants.DECRETO_DECISORIO_II_GRADO) || categoriaAtto.equals(Constants.DECRETO_DECISORIO_II_GRADO_CAM) )
			return "procedimento/atto/decisorioBeniIIGrado";
		else
			return "procedimento/atto/decisorioBeni";
	}

	// mev marzo 2020 gestione tasto spese processuali
	@RequestMapping(value = { "/procedimento/atto/visualizzaDirettiInteressati.htm" , "/procedimento/atto/visualizzaDirettiInteressatiIIGrado.htm" }, method = RequestMethod.POST, params = { "CondannaSpese" })
	public String apriSpeseProcessuali(SpeseSoggettoForm speseSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap map) {

		ProfiloForm profilo = (ProfiloForm) request.getSession().getAttribute("profilo");
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();

		speseSoggettoForm.setIdUfficio((Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE));
		speseSoggettoForm.setIdProcedimento(((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento());

		String categoriaAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId();
		List<ComboForm> listaSpeseProcessuali = commonService.listaSpeseProcessuali();
		map.addAttribute("listaSpeseProcessuali", listaSpeseProcessuali);
		// map.addAttribute("listaSpeseProcessualinew", listaSpeseProcessuali);

		List<SoggettoForm> soggetti = new ArrayList<SoggettoForm>();
//		List<SoggettoForm> soggettiT = new ArrayList<SoggettoForm>();
		List<SoggettoForm> soggettiI = new ArrayList<SoggettoForm>();

		if (categoriaAtto.equals(Constants.DECRETO_DECISORIO_II_GRADO) || categoriaAtto.equals(Constants.DECRETO_DECISORIO_II_GRADO_CAM) ){
			//soggetti = attoService.getRicercaSoggettoAttoSpeseProc(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S, listaSpeseProcessuali);
			//soggettiT = attoService.getRicercaSoggettoAttoSpeseProc(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_TERZO, Constants.Flag.S, listaSpeseProcessuali);
			soggettiI = attoService.getRicercaSoggettoAttoSpeseProc(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_INTERVENIENTE, Constants.Flag.S, listaSpeseProcessuali);
			//soggetti.addAll(soggettiT);
			soggetti.addAll(soggettiI);
		} else {
			soggetti = attoService.getRicercaSoggettoAttoSpeseProc(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S, listaSpeseProcessuali);
		}

		map.addAttribute("risultatoRicerca", soggetti);
		request.getSession().setAttribute("soggettiSpese", soggetti);
		map.addAttribute("listaSoggetti", soggetti);
		// speseSoggettoForm.setSoggetti(soggetti);
		// ComboForm sp = new ComboForm();
		// sp.setId(""+"1");
		// sp.setDescrizione("");
		// speseSoggettoForm.setSpeseProcessuali(sp);
		speseSoggettoForm.setListaSpeseProcessuali(listaSpeseProcessuali);

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();

		AttoForm attoForm = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
		Long idProcedimentoCda=speseSoggettoForm.getIdProcedimentoCda();
		if (idProcedimentoCda == null) {
			 idProcedimentoCda = speseSoggettoForm.getIdProcedimentoCda();
		}

		ProcedimentoForm procedimento = recuperaProcedimento();
		if (idProcedimentoCda != null && idProcedimentoCda > 0) {
			int idUffOwn1 = Integer.parseInt(commonService.getUfficiCompetenza(procedimento.getIdProcedimento(),19L).get(0).getId());
			speseSoggettoForm.setIdUfficio(idUffOwn1);
			speseSoggettoForm.setIdProcedimento(idProcedimentoCda);
			idProcedimento = idProcedimentoCda;
			idUffOwn = idUffOwn1;
			speseSoggettoForm.setIdProcedimentoCda(idProcedimentoCda);
		   }
		else {

			speseSoggettoForm.setIdUfficio((Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE));
			speseSoggettoForm.setIdProcedimento(((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento());
		}

		map.addAttribute("speseSoggetto", speseSoggettoForm);
		String esitoReadOnly = "false";

		Long catAttoSearch;
		if (((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) && idProcedimentoCda==null)
			catAttoSearch = Long.parseLong(Constants.DECRETO_DECISORIO_II_GRADO);
		else
			catAttoSearch = Long.parseLong(Constants.DECRETO_DECISORIO_I_GRADO);
		if (categoriaAtto != null && categoriaAtto.equals(Constants.SENTENZA_OPPOSIZIONE_AL_DISSEQUESTRO)) {
			catAttoSearch = Long.parseLong(Constants.SENTENZA_OPPOSIZIONE_AL_DISSEQUESTRO);
			if (attoForm.getDataRegistrazione() != null) {
				List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
				map.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
			} else
				map.addAttribute("ufficiList", ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca());
		} else if (categoriaAtto != null && categoriaAtto.equals(Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA)) {
			catAttoSearch = Long.parseLong(Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA);
			if (attoForm.getDataRegistrazione() != null) {
				List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
				map.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
			} else
				map.addAttribute("ufficiList", ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca());
		} else if (categoriaAtto != null
				&& (categoriaAtto.equals(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA)
						|| categoriaAtto.equals(Constants.DECRETO_INCOMPETENZA_TRASF_ALTRO_TRIBUNALE)
						|| categoriaAtto.equals(Constants.DECRETO_INCOMPETENZA_PROCURA)))
			esitoReadOnly = "true";
		map.addAttribute("esitoReadOnly", esitoReadOnly);

		if ((attoForm.getNumeAnnoAtto() != null && attoForm.getNumeAnnoAtto().length() > 0)
				&& (attoForm.getNumeAtto() != null && attoForm.getNumeAtto().length() > 0)) {
			map.addAttribute("esitoReadOnly", "true");
		}

		String carEsito = "T";
		if (idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)
				|| idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM)
				|| idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)
				|| idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM)) {
			if (idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM))
				carEsito = "LA";
			if (idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM))
				carEsito = "T";
			if (idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM))
				carEsito = "EM";
			catAttoSearch = new Long(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE);
		}

		long idUffRic = profilo.getIdTipoUfficio();
		if (carEsito.equals("LA"))
			idUffRic = 0;

		List<ComboForm> esiti = procedimentoService.getEsiti(carEsito, catAttoSearch, idUffRic);
		// Segnalazione EMS-142
		if (idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM)
				|| idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM))
			esiti.remove(new ComboForm("234","ACCOGLIE PARZIALMENTE L'ISTANZA"));

		map.addAttribute("esitiDecisioneBeni", esiti);
		map.addAttribute("attoForm", attoForm);

		// se è il decreto decisorio di II grado visualizzo una pagina diversa
		if (categoriaAtto.equals(Constants.DECRETO_DECISORIO_II_GRADO) || categoriaAtto.equals(Constants.DECRETO_DECISORIO_II_GRADO_CAM) )
			return "procedimento/atto/speseProcessuali";
		else
			return "procedimento/atto/speseProcessuali";
	}

	@RequestMapping(value = { "/procedimento/atto/visualizzaDirettiInteressati.htm" }, method = RequestMethod.POST, params = { "SalvaSpese" })
	public String salvaSpeseProcessuali(@ModelAttribute("speseSoggetto") SpeseSoggettoForm speseSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

//		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
//		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();
		List<SoggettoForm> sogg = (List<SoggettoForm>)  request.getSession().getAttribute("soggettiSpese");
		speseSoggettoForm.setSoggetti(sogg);
		String idCodiceUtente = (String) request.getSession().getAttribute(Constants.ID_CODICE_UTENTE);
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
//		String catAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = (Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE);
		int idTipoUfficio = (Integer)request.getSession().getAttribute("idTipoUfficio");
		if(speseSoggettoForm.isCheckTutti() ){
			  // salv per tutti i soggetti il valore selezionato dalla combo spese processuali
			 String applicaTutti = speseSoggettoForm.getSpeseProcessuali().getId();
			 // speseService.salvaSpeseProcessuali(speseSoggettoForm, idCurrentAtto, idProcedimento, idCodiceUtente, idUffOwn, idTipoUfficio, applicaTutti);
			 soggettoService.salvaSpeseProcessuali(speseSoggettoForm, idCurrentAtto, idProcedimento, idCodiceUtente, idUffOwn, idTipoUfficio, applicaTutti);
		} else {
			// salva le occorrenze modificate
			//speseService.salvaSpeseProcessuali(speseSoggettoForm,  idCurrentAtto, idProcedimento, idCodiceUtente, idUffOwn, idTipoUfficio);
			soggettoService.salvaSpeseProcessuali(speseSoggettoForm,  idCurrentAtto, idProcedimento, idCodiceUtente, idUffOwn, idTipoUfficio);
		}

		super.setMessage(Constants.SUCCESS_MESSAGE, "success", null, true);
		modelMap.addAttribute("speseSoggettoForm" , new SpeseSoggettoForm());
		addBreadcrumbs("POST", "/procedimento/atto/visualizzaDirettiInteressati.htm", "CondannaSpese" );
		return apriSpeseProcessuali(speseSoggettoForm, result, request, modelMap);
	}

