	@RequestMapping(value = { "/procedimento/atto/visualizzaDirettiInteressati.htm", "/procedimento/atto/visualizzaDirettiInteressatiIIGrado.htm"}, method = RequestMethod.POST, params = { "SubmitImpugnazione" })
	public String apriImpugnazioneLiquidazioneAmm(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap map) {

		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);

		//caricare la decisione su t_rel_atto_ist_gen
		TRelAttoIstGenId id = new TRelAttoIstGenId();
		id.setCodiKIdAtto(idCurrentAtto);
		id.setCodiKIdProc(idProcedimento);
		id.setCodiKIdUffOwner(idUffOwn);
		TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
		if(relAttoIstGen!=null) {

			if(idCatAtto == Long.valueOf(Constants.DECRETO_DECISORIO_PROVV_ISTANZA)) {

				if(relAttoIstGen.getTTpEsitoByCodiFkIdEsito2()!=null) {
					ComboForm cb = new ComboForm();
					cb.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito2().getCodiKIdEsito());
					beneSoggettoForm.setDecisioneBeni(cb);
					beneSoggettoForm.setMotivazione1(relAttoIstGen.getDescAltro1());
					beneSoggettoForm.setImporto1(relAttoIstGen.getImpo1());

					beneSoggettoForm.setDataPresentazioneCda(relAttoIstGen.getDataPresent2());
					beneSoggettoForm.setDataDepositoCda(relAttoIstGen.getDataDeposito2());
					beneSoggettoForm.setMotivazione2(relAttoIstGen.getDescAltro2());
					beneSoggettoForm.setImporto2(relAttoIstGen.getImpo2());
					beneSoggettoForm.setDataDefinitivitaCda(relAttoIstGen.getDataDef2());

					beneSoggettoForm.setDataPresentazioneCass(relAttoIstGen.getDataPresent3());
					beneSoggettoForm.setDataDepositoCass(relAttoIstGen.getDataDeposito3());
					beneSoggettoForm.setMotivazione3(relAttoIstGen.getDescAltro3());
					beneSoggettoForm.setImporto3(relAttoIstGen.getImpo3());
					beneSoggettoForm.setDataDefinitivitaCass(relAttoIstGen.getDataDef3());
				}

			} else {

				if(relAttoIstGen.getTTpEsitoByCodiFkIdEsito1()!=null) {
					ComboForm cb = new ComboForm();
					cb.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito1().getCodiKIdEsito());
					beneSoggettoForm.setDecisioneBeni(cb);
					beneSoggettoForm.setMotivazione1(relAttoIstGen.getDescAltro1());
					beneSoggettoForm.setImporto1(relAttoIstGen.getImpo1());

					beneSoggettoForm.setDataPresentazioneCda(relAttoIstGen.getDataPresent2());
					beneSoggettoForm.setDataDepositoCda(relAttoIstGen.getDataDeposito2());
					beneSoggettoForm.setMotivazione2(relAttoIstGen.getDescAltro2());
					beneSoggettoForm.setImporto2(relAttoIstGen.getImpo2());
					beneSoggettoForm.setDataDefinitivitaCda(relAttoIstGen.getDataDef2());

					beneSoggettoForm.setDataPresentazioneCass(relAttoIstGen.getDataPresent3());
					beneSoggettoForm.setDataDepositoCass(relAttoIstGen.getDataDeposito3());
					beneSoggettoForm.setMotivazione3(relAttoIstGen.getDescAltro3());
					beneSoggettoForm.setImporto3(relAttoIstGen.getImpo3());
					beneSoggettoForm.setDataDefinitivitaCass(relAttoIstGen.getDataDef3());
					beneSoggettoForm.setDataDecisione(relAttoIstGen.getDataDecisione2());
					beneSoggettoForm.setDataDepositoDecisione(relAttoIstGen.getDataDepDecis2());
					beneSoggettoForm.setDataSentenza(relAttoIstGen.getDataDecisione3());
					beneSoggettoForm.setDataDepositoSentenza(relAttoIstGen.getDataDepDecis3());
				}

			}

		}

		List<AttoForm> idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 5l, Constants.ISTANZA_LIQUIDAZIONE_AMM);
		if(idsAttoIstanza!=null && !idsAttoIstanza.isEmpty()) {
			AttoForm af = idsAttoIstanza.get(0);
			AmministratoreForm amministratore = procedimentoService.getAmministratoreByIstanza(idProcedimento, af.getCodAtto(), idUffOwn);
			List<BeneForm>beniInAmministrazione = beneService.listaBeniInAmministrazione(idUffOwn, idProcedimento, af.getCodAtto(), amministratore.getId());
			map.addAttribute("beniInAmministrazione", beniInAmministrazione);
		}

		map.addAttribute("beneSoggetto", beneSoggettoForm);

		String carEsito = "LA";
		Long catAttoSearch = new Long(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE);
		long idUffRic = 0;

		List<ComboForm> esiti = procedimentoService.getEsiti(carEsito, catAttoSearch, idUffRic);
		map.addAttribute("esitiDecisioneBeni", esiti);

		AttoForm attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		if (map.get("attoForm") == null)
			map.addAttribute("attoForm", attoForm);

		int idTipoUfficio = recuperaIdTipoUfficio();
		String disabilita = "false";
		if(idTipoUfficio == Constants.TIPO_UFFICIO_PROCURA_L.intValue() || idTipoUfficio == Constants.TIPO_UFFICIO_PROCURA_GENERALE){
			disabilita = "true";
		}

		map.addAttribute("disabilita", disabilita);

		return "procedimento/atto/impugnazioneLiquidazioneAmm";
	}

	@RequestMapping(value = {"/procedimento/atto/impugnazioneLiquidazioneAmm.htm"}, method = RequestMethod.POST, params = { "SalvaImpugnazione" })
	public String salvaImpugnazioneLiquidazioneAmm(@ModelAttribute("beneSoggetto") BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		String idCodiceUtente = (String) request.getSession().getAttribute(Constants.ID_CODICE_UTENTE);
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = (Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE);
		int idTipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");

		if (!result.hasErrors()) {

			if (beneSoggettoForm.getDataDefinitivitaCda() != null && beneSoggettoForm.getDataDefinitivitaCass() != null) {
				super.setMessage(Constants.MESSAGE, "error.liquidazioneamm.definitivita", null, false);
			} else if (beneSoggettoForm.getDataDefinitivitaCda() != null && (beneSoggettoForm.getMotivazione2() == null || beneSoggettoForm.getDataPresentazioneCda() == null || beneSoggettoForm.getDataDepositoCda() == null)) {
				super.setMessage(Constants.MESSAGE, "error.liquidazioneamm.impugnazione", null, false);
			} else if (beneSoggettoForm.getDataDefinitivitaCass() != null && (beneSoggettoForm.getMotivazione3() == null)) {
				super.setMessage(Constants.MESSAGE, "error.liquidazioneamm.impugnazione", null, false);
			} else if (beneSoggettoForm.getDataDefinitivitaCass() != null && (beneSoggettoForm.getMotivazione3() == null)) {
				super.setMessage(Constants.MESSAGE, "error.liquidazioneamm.impugnazione", null, false);
			} else {

				// ALTRE VALIDAZIONI
				/*
				 * La data di deposito non può essere precedente alla data di
				 * presentazione
				 *
				 * La data di deposito non può essere precedente alla data di
				 * iscrizione
				 *
				 * La data di presentazione non può essere precedente alla data
				 * di iscrizione
				 *
				 */

				// cda
				Date dataDepositoCda = beneSoggettoForm.getDataDepositoCda();
				Date dataPresentazioneCda = beneSoggettoForm.getDataPresentazioneCda();
				Date dataDefinitivitaCda = beneSoggettoForm.getDataDefinitivitaCda();
				List<Message> messaggi = new ArrayList<Message>();
				boolean containErrors = false;
				if (dataDepositoCda != null && dataPresentazioneCda != null) {
					if (dataDepositoCda.before(dataPresentazioneCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.cda.datadeposito.before.datapresentazione", null);
						containErrors = true;
					}
				}

				if (dataDepositoCda != null && dataDefinitivitaCda != null) {
//					Segnalazione EMS-07
//					if (dataDepositoCda.before(dataDefinitivitaCda)) {
					if (dataDefinitivitaCda.before(dataDepositoCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.cda.datadeposito.before.dataiscrizione", null);
						containErrors = true;
					}
				}

				if (dataPresentazioneCda != null && dataDefinitivitaCda != null) {
//					Segnalazione EMS-07
//					if (dataPresentazioneCda.before(dataDefinitivitaCda)) {
					if (dataDefinitivitaCda.before(dataPresentazioneCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.cda.datapresentazione.before.dataiscrizione", null);
						containErrors = true;
					}
				}

				// cassazione
				Date dataDepositoCassazione = beneSoggettoForm.getDataDepositoCass();
				Date dataPresentazioneCassazione = beneSoggettoForm.getDataPresentazioneCass();
				Date dataIscrizioneCassazione = beneSoggettoForm.getDataDefinitivitaCass();

				if (dataDepositoCassazione != null && dataPresentazioneCassazione != null) {
					if (dataDepositoCassazione.before(dataPresentazioneCassazione)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.cassazione.datadeposito.before.datapresentazione", null);
						containErrors = true;
					}
				}

				if (dataDepositoCassazione != null && dataIscrizioneCassazione != null) {
					if (dataDepositoCassazione.before(dataIscrizioneCassazione)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.cassazione.datadeposito.before.dataiscrizione", null);
						containErrors = true;
					}
				}

				if (dataPresentazioneCassazione != null && dataIscrizioneCassazione != null) {
					if (dataPresentazioneCassazione.before(dataIscrizioneCassazione)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.cassazione.datapresentazione.before.dataiscrizione", null);
						containErrors = true;
					}
				}


				Date dataDecisione = beneSoggettoForm.getDataDecisione();
				Date dataDepositoDecisione = beneSoggettoForm.getDataDepositoDecisione();
				Date dataSentenza = beneSoggettoForm.getDataSentenza();
				Date dataDepositoSentenza = beneSoggettoForm.getDataDepositoSentenza();

				if (dataDecisione != null) {
					if (dataPresentazioneCda == null || dataDepositoCda == null) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadecisione.valorizzata", null);
						containErrors = true;
					}
					if (DateUtils.isBefore(dataDecisione, dataPresentazioneCda) || DateUtils.isBefore(dataDecisione, dataDepositoCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadecisione.before.altredate", null);
						containErrors = true;
					}
				}

				if (dataDepositoDecisione != null) {
					if (dataPresentazioneCda == null || dataDepositoCda == null) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadepositodecisione.valorizzata", null);
						containErrors = true;
					}
					if (DateUtils.isBefore(dataDepositoDecisione, dataPresentazioneCda) || DateUtils.isBefore(dataDepositoDecisione, dataDepositoCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadepositodecisione.before.altredate", null);
						containErrors = true;
					}
				}

				if (dataSentenza != null) {
					if (dataPresentazioneCda == null || dataDepositoCda == null) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datasentenza.valorizzata", null);
						containErrors = true;
					}
					if (DateUtils.isBefore(dataSentenza, dataPresentazioneCda) || DateUtils.isBefore(dataSentenza, dataDepositoCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datasentenza.before.altredate", null);
						containErrors = true;
					}
				}

				if (dataDepositoSentenza != null) {
					if (dataPresentazioneCda == null || dataDepositoCda == null) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadepositosentenza.valorizzata", null);
						containErrors = true;
					}
					if (DateUtils.isBefore(dataDepositoSentenza, dataPresentazioneCda) || DateUtils.isBefore(dataDepositoSentenza, dataDepositoCda)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadepositosentenza.before.altredate", null);
						containErrors = true;
					}
				}

//				La data deposito decisione non può essere precedente alla data della decisione (Segnalazione EMS-06)
				if(dataDecisione!=null && dataDepositoDecisione!=null){
					if (DateUtils.isBefore(dataDepositoDecisione, dataDecisione)) {
						super.addMessageIntoList(messaggi, Constants.MESSAGE, "impugnazione.datadepositodecisione.before.altredate", null);
						containErrors = true;
					}
				}


				if (containErrors) {
					super.setMessages(messaggi, false);
					return apriImpugnazioneLiquidazioneAmm(beneSoggettoForm, result, request, modelMap);
				}

				TRelAttoIstGenId id = new TRelAttoIstGenId();
				id.setCodiKIdAtto(idCurrentAtto);
				id.setCodiKIdProc(idProcedimento);
				id.setCodiKIdUffOwner(idUffOwn);
				TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
				if (relAttoIstGen == null) {
					relAttoIstGen = new TRelAttoIstGen();
					relAttoIstGen.setId(id);
				}

				relAttoIstGen.setDataPresent2(beneSoggettoForm.getDataPresentazioneCda());
				relAttoIstGen.setDataDeposito2(beneSoggettoForm.getDataDepositoCda());
				relAttoIstGen.setDescAltro2(beneSoggettoForm.getMotivazione2());
				relAttoIstGen.setImpo2(beneSoggettoForm.getImporto2());
				relAttoIstGen.setDataDef2(beneSoggettoForm.getDataDefinitivitaCda());

				relAttoIstGen.setDataPresent3(beneSoggettoForm.getDataPresentazioneCass());
				relAttoIstGen.setDataDeposito3(beneSoggettoForm.getDataDepositoCass());
				relAttoIstGen.setDescAltro3(beneSoggettoForm.getMotivazione3());
				relAttoIstGen.setImpo3(beneSoggettoForm.getImporto3());
				relAttoIstGen.setDataDef3(beneSoggettoForm.getDataDefinitivitaCass());

				relAttoIstGen.setDataDecisione2(dataDecisione);
				relAttoIstGen.setDataDepDecis2(dataDepositoDecisione);
				relAttoIstGen.setDataDecisione3(dataSentenza);
				relAttoIstGen.setDataDepDecis3(dataDepositoSentenza);

				beneService.salvaDecisorioBeniIstGen(idCurrentAtto, idProcedimento, idCodiceUtente, idUffOwn, idTipoUfficio, "DECISORIO", new Integer(beneSoggettoForm.getDecisioneBeni().getId()), relAttoIstGen);

				if (beneSoggettoForm.getDataDefinitivitaCda() != null || beneSoggettoForm.getDataDefinitivitaCass() != null) {
					updateProcedimentoIntoSession(idProcedimento);
				}
			}
		}

		return apriImpugnazioneLiquidazioneAmm(beneSoggettoForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/sentenzaOpposizioneDissequestro.htm", method = RequestMethod.POST, params = { "Salva" })
	public String aggiornaSentenzaOpposizioneDissequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap, String tipo) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();

		if ((proced != null && proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_OPPOSIZIONE_ALLA_RESTITUZIONE)) && attoInSessione != null && attoInSessione.getCategoriaAtto() != null
				&& attoInSessione.getCategoriaAtto().getId().equals(Constants.CategoriaAtto.DECRETO_OPPOSIZIONE_DISSEQUESTRO)) {
			attoValidation.validateSalvaSentenzaOpposizioneDissequestroIIGrado(attoForm, result, request, modelMap);
		} else {
			// (Marco 15/01/2016) Inserito in else altrimenti non consentiva il mai l'invio dal secondo grado
			attoValidation.validateSalvaSentenzaOpposizioneDissequestro(attoForm, result, request, modelMap);

		}
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
		} else {
			// INIZIA GESTIONE DOCUMENTALE
			allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
			// FINE GESTIONE DOCUMENTALE
			if (tipo != null && tipo.equals("ConfermaInvia"))
				attoValidation.validateAttoDate(attoForm, result, request);

			if (result.hasErrors())
				return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
			else {

				attoForm.setCodAtto(attoInSessione.getCodAtto());
				if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
					attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
					attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
					attoForm.setDataRicezione(Calendar.getInstance().getTime());
				}
				List<ComboForm> ufficiCompetenza = ufficioUtilService.caricaUfficiSentenzaOpposizioneDissequestro();
				long idUff1 = 0l;
				long idUff2 = 0l;
				long idUff3 = 0l;
				for (int i = 0; ufficiCompetenza != null && i < ufficiCompetenza.size(); i++) {
					ComboForm uff = ufficiCompetenza.get(i);
					if (i == 0)
						idUff1 = Long.parseLong(uff.getId());
					if (i == 1)
						idUff2 = Long.parseLong(uff.getId());
					if (i == 2)
						idUff3 = Long.parseLong(uff.getId());
				}

				if (tipo != null && tipo.equals("ConfermaInvia"))
					attoForm.setDataRegistrazione(new Date());

				attoService.aggiornaSentenzaOpposizioneDissequestro(idUffOwn, idUff1, idUff2, idUff3, proced.getIdProcedimento(),
						attoForm, codUtente);
				super.updateProcedimentoIntoSession(proced.getIdProcedimento());
				// INIZIA GESTIONE DOCUMENTALE
				gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
				// FINE GESTIONE DOCUMENTALE
				if (tipo != null && tipo.equals("ConfermaInvia"))
					super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
				else
					super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

				//INIZIO INVIO DATI MPS - 8.7
				if((proced.getTipoFascicolo()!=null && proced.getTipoFascicolo().getId().equals("5"))
					&&	(proced.getStatoProcedimento()!= null && proced.getStatoProcedimento().getId().equals(Constants.STATOPROC_TRATTAZIONE_OPPOSIZIONE))
					&& (attoInSessione!=null && attoInSessione.getCategoriaAtto()!=null && attoInSessione.getCategoriaAtto().getId().equals("23"))
					)
				{
					int idTipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");
					if(idTipoUfficio == 6)
					{
						String tipoProcedimento = "9";
						List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(Integer.valueOf(proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(), tipoProcedimento);
						for(int i=0; i<uffDestinatariList.size(); i++)
						{
							DecretiSospensioneRestituzioneBeniRequest decretiSospBeni = poliziaService.createDecretiSospensioneRestituzioneBeniRequest(proced.getIdProcedimento(), attoForm.getCodAtto(), idUffOwn, uffDestinatariList.get(i));
							/*long idMsg = */poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_DECRETI_SOSPENSIONE_REST_BENI, proced.getIdProcedimento(), attoForm.getCodAtto(), decretiSospBeni, Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUffOwn, uffDestinatariList.get(i), codUtente);
						}
					}
				}
				//FINE   INVIO DATI MPS - 8.7

				return copertinaAtto(attoForm, result, request, modelMap);
			}

		}
	}

	@RequestMapping(value = "/procedimento/atto/sentenzaOpposizioneDissequestro.htm", method = RequestMethod.POST, params = { "Invia" })
	public String inviaSentenzaOpposizioneDissequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		return aggiornaSentenzaOpposizioneDissequestro(attoForm, result, request, modelMap, "ConfermaInvia");
	}

	@RequestMapping(value = "/procedimento/atto/sentenzaOpposizioneDissequestro.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String confermaSentenzaOpposizioneDissequestro(AttoForm attoForm, BindingResult result,
			HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = recuperaIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = recuperaAtto().getCodAtto();
		ProcedimentoForm proced = recuperaProcedimento();
		AttoForm recuperaAtto = recuperaAtto();

		if ((proced != null
				&& proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_OPPOSIZIONE_ALLA_RESTITUZIONE))
				&& recuperaAtto != null
				&& recuperaAtto.getCategoriaAtto() != null
				&& recuperaAtto.getCategoriaAtto().getId().equals(Constants.CategoriaAtto.DECRETO_OPPOSIZIONE_DISSEQUESTRO)) {
			attoValidation.validateSalvaSentenzaOpposizioneDissequestroIIGrado(attoForm, result, request, modelMap);
			if (result.hasErrors()) {
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
			}
		}

		// ---
		// INIZIA GESTIONE DOCUMENTALE
		if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
		}
		// FINE GESTIONE DOCUMENTALE

		attoValidation.validateAttoDateSalva(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
		}

		attoForm.setCodAtto(idAtto);

		inizializzaDocumento(attoForm, request);

		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;

		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		attoForm.setDataRegistrazione(null);

		attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto,
				categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);

	}

