	@RequestMapping(value = "/procedimento/atto/associaBeneADecretoSequestro.htm", method = RequestMethod.POST)
	public String postDecretoSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		String warning = attoForm.getWarning();
		int idUffOwn = recuperaIdUfficioUtente();
		ProcedimentoForm proc = recuperaProcedimento();

		BeneForm beneForm = new BeneForm();
		beneForm.setWarning(warning);
		beniDecretoUtilService.beniDecretoSequestro(attoForm, request, modelMap, result, false, super.printMethodName());
		modelMap.addAttribute("beneForm", beneForm);
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		if (attoService.esisteDecretoConvalidaSequesto(attoForm.getCodAtto(), idUffOwn))
			modelMap.addAttribute("convalidato", true);
		updateViewAndMenu(proc, request);
		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoSequestro";
	}

	@SuppressWarnings("unused")
	@RequestMapping(value = "/procedimento/atto/associaBeneADecretoSequestro.htm", method = RequestMethod.POST, params = { "Associa" })
	private String associaBeneADecretoSequestro(BeneForm beneForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

//		List<BeneForm> listaBeniSuperioriCento = new ArrayList<BeneForm>();
		beneValidation.validateSceltaListaBeni(beneForm.getListaIdCheckbox(), result, request);
		if (result.hasErrors())
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		// verifica se ci sono titoli di diritto per il bene selezionato con la
		// proposta
		Iterator itx = beneForm.getListaIdCheckbox().iterator();
		Iterator it = beneForm.getListaIdCheckbox().iterator();
		while (itx.hasNext()) {
			long idBene = (Long) itx.next();
			List<BeneSoggettoForm> beniSoggetti = beneService.listaSoggettiBeniProcTuttiAtti(idProcedimento, idUffOwn, idBene);
			beneForm = beneService.beneById(idUffOwn, idBene, idProcedimento);

			if (beniSoggetti == null || beniSoggetti.isEmpty()) {
				// se non ci sono titoli di diritto per il bene selezionato con
				// la
				// proposta
				// verifico se ce ne sono con l'atto in sessione
				beniSoggetti = new ArrayList<BeneSoggettoForm>();
				beniSoggetti = beneService.listaSoggettiBeniProc(idProcedimento, idUffOwn, idBene, idAtto);
				// se non trovo nulla invio l'errore non associato a titolo
				beneValidation.validateBeneNonAssociatoTitoliDiritto(beniSoggetti, request, result);
				if (result.hasErrors())
					return redirectSuCopertinaAtto(result, request, modelMap, idUffOwn, idProcedimento, idBene, true);
			}
		}
		while (it.hasNext()) {
			long idBene = (Long) it.next();
			// passo come idAttoSequestro 0L poichè sulla procedura si aspetta
			// quel valore >0 solo in caso
			// di revoca sequestro
			attoService.copiaMisBeneAtto(idProcedimento, idAtto, idBene, idUffOwn, codiceUtente, Constants.TipiFlagDecretoRevoca.DECRETO,
					super.printMethodName());
		}
		return copertinaAtto(new AttoForm(), result, request, modelMap);
	}

