	private String redirectSuCopertinaAtto(BindingResult result, HttpServletRequest request, ModelMap modelMap, int idUffOwn, long idProcedimento,
			long idBene, boolean checkTitoliDiritto) {

		if (checkTitoliDiritto) {
			BeneForm temp = beneService.beneById(idUffOwn, idBene, idProcedimento);
			List<BeneForm> listaBeniNoTitDir = new ArrayList<BeneForm>();
			listaBeniNoTitDir.add(temp);
			modelMap.addAttribute("listaBeniNoTitDir", listaBeniNoTitDir);
		}
		return copertinaAtto(new AttoForm(), result, request, modelMap);
	}

	@SuppressWarnings("unused")
	@RequestMapping(value = "/procedimento/atto/associaBeneADecretoSequestro.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String confermaInviaDecretoSequestro(BeneForm beneForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

		attoValidation.validateBeniAssociatiAtto(idProcedimento, idAtto, idUffOwn, result);
		if (result.hasErrors())
			return copertinaAtto(new AttoForm(), result, request, modelMap);

		List<BeneForm> listaBeniNoTitDir = attoValidation.validateListaBeniNoTitDir(idUffOwn, idProcedimento, 0l, result, request);
		if (result.hasErrors()) {
			modelMap.addAttribute("listaBeniNoTitDir", listaBeniNoTitDir);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}
		List<BeneForm> listaBeniNoMisPatr = attoValidation.validateListaBeniNoMisPatr(idUffOwn, idProcedimento, idAtto, result, request);
		if (result.hasErrors()) {
			modelMap.addAttribute("listaBeniNoMisPatr", listaBeniNoMisPatr);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}
		List<BeneForm> listaBeneQuotaZero = attoValidation.validateListaBeniTitDirUgualiAZero(idUffOwn, idProcedimento, idAtto, result);
		if (result.hasErrors()) {
			modelMap.addAttribute("listaBeneQuotaZero", listaBeneQuotaZero);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}

		// MODIFICA 01/2014
		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore)
		 return copertinaAtto(new AttoForm(), result, request, modelMap);

		AttoForm attoForm = attoService.getAttoById(idAtto, idUffOwn);

		// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		List<MagistratoForm> magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUffOwn, idAtto, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
		List<MagistratoForm> magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUffOwn, idProcedimento, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
	// se non C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO vuol dire che sto registrando il primo sequestro, mando il messaggio Giudice Delegato obbligatorio.
		if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
			&& (magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))){
			modelMap.addAttribute("attoForm", attoForm);
			super.setMessage(Constants.MESSAGE,"magistrato.error.giudiceDelegato.registrazioneAtto",null,false);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}

	// *** INIZIO GESTIONE AMMINISTRATORI *** J.C. SITMP 295
			if(beneForm.getWarning() == null) {
				boolean beniSenzaAmministratori = attoService.controllaBeniAmministratoriSenzaAmministratore(idUffOwn, idProcedimento, idAtto);
				String primaSubmitEffettuata = request.getParameter("primaSubmitEffettuata");
				 if (beniSenzaAmministratori && primaSubmitEffettuata==null) {
					 super.setMessage(Constants.MESSAGE,"amministratore.senza.beni.sequestro",null,false);
					 attoForm.setWarning("WARNING");
					 request.setAttribute("primaSubmitEffettuata", Boolean.TRUE);
					 return copertinaAtto(attoForm, result, request, modelMap);
				 }
			} else {
				beneForm.setWarning(null);
				attoForm.setWarning(null);
			}
		// *** FINE GESTIONE AMMINISTRATORI *** J.C. SITMP 295

//---
//--- recupero il flag AllegatoObbligatorio
//---
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);

		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
		 logger.debug("--- fine confermaInviaDecretoSequestro -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

			return this.confermaInviaUtilService.includeConfermaInviaDecretoSequestro(attoForm, result, request, modelMap);
	}

