	@RequestMapping(value = "/procedimento/atto/associaBeneADecretoRevocaSequestro.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String confermaInviaDecretoRevocaSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		attoValidation.validateBeniAssociatiAtto(idProcedimento, idAtto, idUffOwn, result);
		if (result.hasErrors())
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		List<BeneForm> listaBeniNoTitDir = attoValidation.validateListaBeniNoTitDir(idUffOwn, idProcedimento, 0l, result, request);
		if (result.hasErrors()) {
			modelMap.addAttribute("listaBeniNoTitDir", listaBeniNoTitDir);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}
		List<BeneForm> listaBeniNoMisPatr = attoValidation.validateListaBeniNoMisPatr(idUffOwn, idProcedimento, idAtto, result, request);
		if (result.hasErrors()) {
			modelMap.addAttribute("listaBeniNoMisPatr", listaBeniNoMisPatr);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}
		List<BeneForm> listaBeneQuotaZero = attoValidation.validateListaBeniTitDirUgualiAZero(idUffOwn, idProcedimento, idAtto, result);
		if (result.hasErrors()) {
			modelMap.addAttribute("listaBeneQuotaZero", listaBeneQuotaZero);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}

		// MODIFICA 01/2014
		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore)
		 return copertinaAtto(new AttoForm(), result, request, modelMap);

		attoForm = attoService.getAttoById(idAtto, idUffOwn);

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		return confermaInviaUtilService.includeConfermaInviaDecretoRevocaSequestro(attoForm, result, request, modelMap);
	}

