	@RequestMapping(value = "/procedimento/atto/confermaInviaAtto.htm", method = RequestMethod.POST, params = { "Invia" })
	public String inviaDecreto(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		String nomeMetodo = super.printMethodName();
		long idProcedimento = recuperaIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = recuperaAtto().getCodAtto();
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
		 logger.debug("--- inizio inviaDecreto -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		if (result.hasErrors()) {
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/confermaInviaAtti";
		}
		attoValidation.validateAttoDate(attoForm, result, request);

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/confermaInviaAtti";
		}

		// MODIFICA 01/2014
		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore)
			return "/procedimento/atto/confermaInviaAtti";
		// MODIFICA 01/2014

		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		String categoriaAttoString = attoTmp.getCategoriaAtto().getId();
		GestioneUdienzaDto gestUdienza = new GestioneUdienzaDto();
		if (ComparatorUtil.containsValue(categoriaAttoString,
				Constants.DECRETO_SEQUESTRO_URGENTE,
				Constants.DECRETO_SEQUESTRO_ANTICIPATO,
				Constants.DECRETO_SEQUESTRO_ORDINARIO,
				Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO,
				Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO,
				Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO)) {
			// *** INIZIO GESTIONE UDIENZA DEL DECRETO ***
			gestUdienza = udienzaUtilService.gestioneUdienzaPerInvioDecreto(attoForm, modelMap, idUffOwn, idUfficio, idProcedimento, attoTmp);
			if (gestUdienza != null && gestUdienza.getUrlRitorno() != null && gestUdienza.getUrlRitorno().trim().length() > 0)
			 return gestUdienza.getUrlRitorno();
		}
	// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		String giudiceDelegato = null;
		MagistratoForm magistratoForm = null;
		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE) || categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_BENI)
				) {

			List<MagistratoForm> magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUffOwn, idAtto, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
			List<MagistratoForm> magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUffOwn, idProcedimento, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
		// se NON C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO mando il messaggio Giudice Delegato obbligatorio.
			if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
				&& (magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))){
				modelMap.addAttribute("attoForm", attoForm);
				super.setMessage(Constants.MESSAGE,"magistrato.error.giudiceDelegato.registrazioneAtto",null,false);
				return copertinaAtto(new AttoForm(), result, request, modelMap);
			}
		// se C'è nella REL_MAG_ATTO e NON C'è nella REL_MAG_PROC vuol dire che sto registrando il primo sequestro:
		// quindi devo inserire nella REL_MAG_PROC e associare il Giudice delegato al procedimento.
			if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
				&& (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() > 0)){
				magistratoForm = magistratiAssociatiAtto.get(0);
				giudiceDelegato = "PROC";
			}
			if(magistratoForm == null) {
				magistratoForm = new MagistratoForm();
				magistratoForm.setId(Long.valueOf(0));
			} else
				magistratoForm.setId(magistratoForm.getId());
		}
			// *** FINE GESTIONE GIUDICE DELEGATO ***

		attoForm.setDataRegistrazione(new Date());

		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE) || categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO)
				|| categoriaAttoString.equals(Constants.DECRETO_SOSPENSIONE_TEMP_CDA)
				)
			attoService.inviaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi,
					idProcProp, attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(), gestUdienza.getCodUdienzaInFaseDiRip(),
					gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(), magistratoForm.getId(), giudiceDelegato);
		else if (ComparatorUtil.containsValue(categoriaAttoString,
				Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO,
				Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO))
			attoService.inviaAttoDecretoRigettoTotaleSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto,
					idStatoAtto, idProcUdi, idProcProp, attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(),
					gestUdienza.getCodUdienzaInFaseDiRip(), gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(), nomeMetodo);

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		super.setMessage(SUCCESS_MESSAGE, "success.invioAtto", null, false);

		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE) || categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO)
				)
			return confermaInviaUtilService.includeConfermaInviaDecretoSequestro(attoForm, result, request, modelMap);
		else if (ComparatorUtil.containsValue(categoriaAttoString,
				Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO,
				Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO))
			return confermaInviaUtilService.includeConfermaInviaDecretoRigettoTotaleSequestro(attoForm, result, request, modelMap);

		return "/procedimento/atto/confermaInviaAtti";
	}

	@RequestMapping(value = "/procedimento/atto/decretoConvalidaSequestro.htm", method = RequestMethod.POST, params = { "Invia" })
	public String inviaDecretoConvalidaSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

//---
//--- recupero il flag AllegatoObbligatorio
//---
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());
//---

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE
		attoValidation.validateAttoDate(attoForm, result, request);
		beniDecretoUtilService.beniDecretoSequestro(attoForm, request, modelMap, result, true, super.printMethodName());

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/confermaInviaDecretoConvalidaSequestro";
		}
		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		long idProcUdi = 0l;
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		// *** INIZIO GESTIONE UDIENZA DEL DECRETO ***
		GestioneUdienzaDto gestUdienza = udienzaUtilService.gestioneUdienzaPerInvioDecreto(attoForm, modelMap, idUffOwn, idUfficio, idProcedimento, attoTmp);
		if (gestUdienza != null && gestUdienza.getUrlRitorno() != null && gestUdienza.getUrlRitorno().trim().length() > 0)
		 return gestUdienza.getUrlRitorno();

		// *** MODIFICA DEL 19/10/2012 --> L'Atto di Convalida del Sequestro non
		// viene inviato alla Procura Proponente (Commentato il flusso relativo)
		attoForm.setDataRegistrazione(new Date());
		attoService.inviaAttoDecretoConvalidaSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
				idProcUdi, idProcProp, attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(), gestUdienza.getCodUdienzaInFaseDiRip(),
				gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(), super.printMethodName());

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE
		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
		ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);

		if(anbscService.verificaInvioDecretoConvalidaAnbsc(idProcedimento, idAtto)) {

			/* Mev 2020/22
			if(anbscMsgService.invioDecretoConvalidaSequestro(idProcedimento, idAtto, idUffOwn, codiceUtente,attoTmp.getCategoriaAtto().getId()) == false)
				super.setMessage(Constants.MESSAGE, "anbsc.invio.error", null, false);
			Mev 2020/22 */

			// Mev 2020/22 Inizio
			EsitoFromResponse esitoFromResponse = anbscMsgService.invioDecretoConvalidaSequestro(idProcedimento, idAtto, idUffOwn, codiceUtente,attoTmp.getCategoriaAtto().getId());

			switch (esitoFromResponse.getEsito()) {
			case 'C':
				super.setMessage(Constants.SUCCESS_MESSAGE, esitoFromResponse.getMessaggio(), null, false);
				break;

			default:
				super.setMessage(Constants.MESSAGE, esitoFromResponse.getMessaggio(), null, false);
				break;

			}
			// Mev 2020/22 fine
		}

		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/confermaInviaDecretoConvalidaSequestro";
	}

