	@RequestMapping(value = "/procedimento/atto/decretoRevocaSequestro.htm", method = RequestMethod.POST, params = { "Invia" })
	public String inviaDecretoRevocaSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		List<Message> customMessageListSuccess = new ArrayList<Message>();
		List<Message> customMessageListError = new ArrayList<Message>();

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE
		attoValidation.validateAttoDate(attoForm, result, request);
		beniDecretoUtilService.beniDecretoSequestro(attoForm, request, modelMap, result, false, super.printMethodName());

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			modelMap.addAttribute("attoForm", attoForm);
//			return "/procedimento/atto/confermaInviaDecretoRevocaSequestro";
			return this.confermaInviaUtilService.includeConfermaInviaDecretoRevocaSequestro(attoForm, result, request, modelMap);
		}
		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		long idProcUdi = 0l;
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		// *** INIZIO GESTIONE UDIENZA DEL DECRETO ***
		GestioneUdienzaDto gestUdienza = udienzaUtilService.gestioneUdienzaPerInvioDecreto(attoForm, modelMap, idUffOwn, idUfficio, idProcedimento, attoTmp);
		if (gestUdienza != null && gestUdienza.getUrlRitorno() != null && gestUdienza.getUrlRitorno().trim().length() > 0)
		 return gestUdienza.getUrlRitorno();

		attoForm.setDataRegistrazione(new Date());
		attoService.inviaAttoDecretoRevocaSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
				idProcUdi, idProcProp, attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(), gestUdienza.getCodUdienzaInFaseDiRip(),
				gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(), super.printMethodName());

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE
		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);
		super.addMessageIntoList(customMessageListSuccess, Constants.SUCCESS_MESSAGE, "success.invioAtto", null);

		ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
		ProcedimentoForm procedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO)));

		// Invio Revoca Sequestro a Anbsc
		// Mev 2020/22 Inizio
		//confermaInviaUtilService.inviaRevocaSequestroAnbsc(procedimento, attoForm, idProcedimento, idAtto, idUffOwn, codiceUtente);

		int grado = 1;
		if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO)
			grado = 2;

		EsitoFromResponse esitoFromResponse = confermaInviaUtilService.inviaRevocaSequestroAnbsc(procedimento, attoForm, idProcedimento, idAtto, idUffOwn, codiceUtente, grado);
		if (esitoFromResponse == null) esitoFromResponse = anbscMsgService.getEsitoInCoda();

		switch (esitoFromResponse.getEsito()) {
		case 'C':
			super.addMessageIntoList(customMessageListSuccess, Constants.SUCCESS_MESSAGE, esitoFromResponse.getMessaggio(), null);
			break;

		default:
			super.addMessageIntoList(customMessageListError, Constants.MESSAGE, esitoFromResponse.getMessaggio(), null);
			break;

		}
		// Mev 2020/22 Fine

		//POLIZIA 8.6 revoca sequestro

		if(procedimento!=null && procedimento.getProcedente()!=null && procedimento.getProcedente().getDescrizione()!=null)
		{
			List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(Integer.valueOf(procedimento.getProcedente().getId()), idUffOwn, procedimento.getIdProcedimento(), Constants.TIPOPROC_PATRIMONIALE);
			for(int i=0; i<uffDestinatariList.size(); i++)
			{
				if(poliziaMsgService.invioRevocaSequestroPolizia(idProcedimento, idAtto, idUffOwn, codiceUtente, ""+uffDestinatariList.get(i)) == false)
					super.setMessage(Constants.MESSAGE, "polizia.invio.error", null, false);
			}
		}

		super.setMessaggiErrori(customMessageListError, true);
		super.setMessagesSuccess(customMessageListSuccess, true);

		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/confermaInviaRevocaSequestro";
	}

