	@RequestMapping(value = "/procedimento/atto/salvaUdienzaDecretoSeqConv.htm", method = RequestMethod.POST, params = { "SalvaUdienzaSeqConv" })
	public String inserisciModificaUdienzaDecretoSequestroConvalida(@Valid @ModelAttribute("udienzaForm") UdienzaForm udienzaForm,
			BindingResult result, HttpServletRequest request, HttpServletResponse response, ModelMap modelMap) throws IOException, SQLException {

		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		AttoForm attoForm = new AttoForm();
		if (request.getSession().getAttribute(Constants.ATTO) != null)
			attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		attoValidation.validateInserisciUdienzaDecreto(udienzaForm, result, request, modelMap);
		if (result.hasErrors())
			return udienzaDecretoSequestroConvalida(udienzaForm, result, request, response, modelMap);
		else {
			// Controllo se è già presente per il procedimento un'udienza in
			// stato FISSATA
			boolean udienzaFissataErrData = false;
			String dataUdienzaFissStr = null;
			String dataUdienzaStr = null;
			String oraUdienzaFissStr = null;
			String oraUdienzaStr = null;
			long codUdienzaFiss = 0L;
			long codUdienzaVerbRis = 0L;
			List<UdienzaForm> udienzaFiss = udienzaService.listaUdienzePerProcedimentoEStatoUdienza(idProcedimento, idUfficio,
					String.valueOf(UdienzaController.STATO_UDIENZA_FISSATA));
			if (udienzaFiss.size() > 0) {
				dataUdienzaFissStr = Utility.convertDateToString(udienzaFiss.get(0).getDataUdienza());
				dataUdienzaStr = Utility.convertDateToString(udienzaForm.getDataUdienza());
				oraUdienzaFissStr = udienzaFiss.get(0).getOraInizioUdienzaStr();
				oraUdienzaStr = udienzaForm.getOraInizioUdienza().getId() + ":" + udienzaForm.getMinutiInizioUdienza().getId();
				codUdienzaFiss = udienzaFiss.get(0).getCodUdienza();
				// Verifico che la data della nuova udienza sia diversa dalla
				// data dell'udienza fissata presente
				if (dataUdienzaStr.equalsIgnoreCase(dataUdienzaFissStr))
					if (oraUdienzaStr.equalsIgnoreCase(oraUdienzaFissStr))
						udienzaFissataErrData = true;
			} else {
				// Controllo che ci sia un'Udienza VERBALIZZATA con RISERVA
				List<UdienzaForm> udienzaVerbRiserva = new ArrayList<UdienzaForm>();
				udienzaVerbRiserva = udienzaService.listaUdienzePerProcedimentoEStatoUdienza(idProcedimento, idUfficio,
						String.valueOf(UdienzaController.STATO_UDIENZA_VERBALIZZATA));
				if (udienzaVerbRiserva.size() > 0) {
					// E' presente l'esito dell'Udienza Verbalizzata
					String esito = udienzaVerbRiserva.get(0).getEsito().getId();
					if (esito.equals("10"))
						codUdienzaVerbRis = udienzaVerbRiserva.get(0).getCodUdienza();
				}
			}
			if (udienzaFissataErrData)
				super.setMessage(Constants.MESSAGE, "udienza.sequestro.presente.fissata.data.error", null, false);
			else
				udienzaUtilService.salvaModificaUdienzaDecretoSeqConv(udienzaForm, attoForm, idUfficio, codiceUtente, idProcedimento, codUdienzaFiss, codUdienzaVerbRis,
						request);
			return udienzaDecretoSequestroConvalida(udienzaForm, result, request, response, modelMap);
		}
	}

