	@RequestMapping(value = "/procedimento/atto/inserimentoUdienza.htm", method = RequestMethod.POST, params = { "CaricaUdienza" })
	public String caricaUdienza(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();
		procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);

		long idProcedimento = procedimento.getIdProcedimento();


		if (attoForm != null && attoForm.getIdProcedimentoCdatrib() != null && attoForm.getIdProcedimentoCdatrib() > 0){
			TProcedimento procedi= procedimentoService.getProcedimentoById(attoForm.getIdProcedimentoCdatrib());
			idUffOwn=procedi.getTAnUfficioByCodiFkIdUffOwner().getCodiKIdUfficio();
			idProcedimento=attoForm.getIdProcedimentoCdatrib();
			AttoForm attoForm1 = attoService.dettaglioAtto(idUffOwn, attoForm.getCodAtto(), idProcedimento, codiceUtente);
			if (attoForm1!= null && attoForm1.getCategoriaAtto() != null  && attoForm1.getCategoriaAtto().getId() != null){
				attoForm = attoForm1;
				attoForm.setIdProcedimentoCdatrib(idProcedimento);
			}

		}

		AttoForm atto = null;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			atto = this.attoService.dettaglioAtto(idUffOwn, attoForm.getCodAtto(), idProcedimento, codiceUtente);
		else
			atto = (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		//Segnalazione EMS-24
		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(atto.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		request.getSession().setAttribute(Constants.ATTO,atto);

		UdienzaForm udienzaForm = attoService.getUdienzaById(atto.getFkUdienzaDecreto(), idUffOwn);
		udienzaForm.setStatoAtto(atto.getStatoAtto());
		udienzaForm.setDataRegistrazione(atto.getDataRegistrazione());
		udienzaForm.setDataEmissione(atto.getDataEmissione());
		udienzaForm.setDataDeposito(atto.getDataDeposito());
		udienzaForm.setCodAtto(attoForm.getCodAtto());
		if (atto.getAllegato().getFileName() != null) {
			udienzaForm.getAllegato().setFileName(atto.getAllegato().getFileName());
			udienzaForm.getAllegato().setContentType(atto.getAllegato().getContentType());
			udienzaForm.getAllegato().setDocumentoFirmato(atto.getAllegato().getDocumentoFirmato());
			udienzaForm.getAllegato().setFirmaRemota(atto.getAllegato().getFirmaRemota());
		}
		modelMap.addAttribute("udienzaForm", udienzaForm);

		if (attoForm.getIdProcedimentoCdatrib() == null || attoForm.getIdProcedimentoCdatrib() == 0){
			updateViewAndMenu(procedimento, request);
			MenuController.caricaMenu("15", request);
		}

		return "/procedimento/atto/nuovaUdienza";
	}

	public String caricaDecretoAnticipazioneRinvioUdienza(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {


		String codiceUtente = recuperaIdCodiceUtente();

		int idUffOwn = recuperaIdUfficioUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);


		if (attoForm != null && attoForm.getIdProcedimentoCdatrib() != null && attoForm.getIdProcedimentoCdatrib() > 0){
			TProcedimento procedi= procedimentoService.getProcedimentoById(attoForm.getIdProcedimentoCdatrib());
			idUffOwn=procedi.getTAnUfficioByCodiFkIdUffOwner().getCodiKIdUfficio();
			long idProcedimento=attoForm.getIdProcedimentoCdatrib();
			AttoForm attoForm1 = attoService.dettaglioAtto(idUffOwn, attoForm.getCodAtto(), idProcedimento, codiceUtente);
			if (attoForm1!= null && attoForm1.getCategoriaAtto() != null  && attoForm1.getCategoriaAtto().getId() != null){
				attoForm = attoForm1;
				attoForm.setIdProcedimentoCdatrib(idProcedimento);
			}

		}

		UdienzaForm udienzaForm = attoService.getUdienzaById(attoForm.getFkUdienzaDecreto(), idUffOwn);
		udienzaForm.setStatoAtto(attoForm.getStatoAtto());
		udienzaForm.setDataRegistrazione(attoForm.getDataRegistrazione());
		udienzaForm.setDataEmissione(attoForm.getDataEmissione());
		udienzaForm.setDataDeposito(attoForm.getDataDeposito());
		udienzaForm.setCodAtto(attoForm.getCodAtto());
		if (attoForm.getAllegato().getFileName() != null) {
			udienzaForm.getAllegato().setFileName(attoForm.getAllegato().getFileName());
			udienzaForm.getAllegato().setContentType(attoForm.getAllegato().getContentType());
		}

		// mi carico i dati dell'udienza che sto anticipando e li salvo nel mio
		// udienzaForm
		UdienzaForm udienzaDaAnticipare = new UdienzaForm();
		long idUdienzaDaAnticipare = udienzaService.getUdienzaPrecedente(udienzaForm.getCodUdienza(), idUffOwn);
		udienzaDaAnticipare = attoService.getUdienzaById(idUdienzaDaAnticipare, idUffOwn);
		udienzaForm.setUdienzaPrecedente(udienzaDaAnticipare);
		modelMap.addAttribute("udienzaForm", udienzaForm);

		if (attoForm.getIdProcedimentoCdatrib() == null || attoForm.getIdProcedimentoCdatrib() == 0){
			updateViewAndMenu(procedimento, request);
			MenuController.caricaMenu("15", request);
		}


		if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA)
				|| attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA_II_GRADO))
			return "/procedimento/atto/copertinaDecretoAnticipazioneUdienza";
		else
			return "/procedimento/atto/copertinaDecretoRinvioUdienza";
	}

	@RequestMapping(value = "/procedimento/atto/inserimentoUdienza.htm", method = RequestMethod.POST, params = { "SalvaModifica" })
	public ModelAndView inserisciUdienza(@Valid UdienzaForm udienzaForm, BindingResult result,
			HttpServletRequest request, HttpServletResponse response, ModelMap modelMap) throws IOException, SQLException {

		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		List<SoggettoForm> soggettiInteressatiConNessunDifensore = procedimentoService.getSogIntSenzaDifensore(idProcedimento, idUfficio);

		// INIZIA GESTIONE DOCUMENTALE
		allegatoFirmaUtilService.validaAllegatoEFirma(udienzaForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		attoValidation.validateInserisciUdienza(udienzaForm, false, soggettiInteressatiConNessunDifensore, result, request, modelMap);
		if (result.hasErrors()){
			super.setMessage(Constants.MESSAGE, "errors.campi.controllo", null, false);
			return nuovaUdienza(udienzaForm, result, request, response, modelMap);
		}

		ModelAndView mnv = new ModelAndView("/procedimento/atto/nuovaUdienza");
		// recupero delle informazioni presenti in sessione e
		// salvataggio/modifica

		udienzaUtilService.salvaModificaUdienza(udienzaForm, idUfficio, codiceUtente, idProcedimento, request);
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(udienzaForm, request, idUfficio, result);
		// FINE GESTIONE DOCUMENTALE
		procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
		return mnv;
	}


	@RequestMapping(value = "/procedimento/atto/inserimentoUdienza.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String apriFormInviaUdienza(@Valid @ModelAttribute("udienzaForm") UdienzaForm udienzaForm, BindingResult result,
			HttpServletRequest request, ModelMap modelMap) {

		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		List<SoggettoForm> soggettiInteressatiConNessunDifensore = procedimentoService.getSogIntSenzaDifensore(idProcedimento, idUfficio);
		modelMap.addAttribute("udienzaForm", udienzaForm);
		boolean errore = false;
		// *** INVIO DECRETO FISSAZIONE UDIENZA ***
		// Consentito solo se non ci sono udienze oppure lo stato dell'ultima
		// udienza è "Assegnata nuovo ruolo"
		List<UdienzaForm> udienze = new ArrayList<UdienzaForm>();
		String idStatoUdi = "1,2,3,4,5,6,7,8,10,11,12";// Tutti gli stati tranne
														// "ASSEGNATA NUOVO RUOLO"(9)
		// Controllo che non ci sia già un'Udienza qualsiasi per il decreto che
		// non sia "ASSEGNATA NUOVO RUOLO"
		udienze = udienzaService.listaUdienzePerProcedimentoEStatoUdienza(idProcedimento, idUfficio, idStatoUdi);

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(udienzaForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(udienzaForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		if (udienze.size() > 0) {
			super.setMessage(Constants.MESSAGE, "udienza.presente.fissazione.error", null, false);
			errore = true;
		}
		attoValidation.validateInserisciUdienza(udienzaForm, true, soggettiInteressatiConNessunDifensore, result, request, modelMap);
		if (result.hasErrors())
			errore = true;

		//gennaroeventualmente
		boolean errore1 = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore1)
			errore=true;

		//finegennaroeventualmente
		if (errore) {
			udienzaForm.setDataRegistrazione(null);
			procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
			return "/procedimento/atto/nuovaUdienza";
		} else {
			// INIZIA GESTIONE DOCUMENTALE
			gestionePiattaformaDocumentale(udienzaForm, request, idUfficio, result);
			// FINE GESTIONE DOCUMENTALE
			// la data di resgistrazione è quella odierna
			udienzaForm.setDataRegistrazione(new Date());
			udienzaUtilService.salvaModificaUdienza(udienzaForm, idUfficio, codiceUtente, idProcedimento, request);
			return confermaInviaUdienza(udienzaForm, result, request, modelMap);
		}
	}

	@RequestMapping(value = "/procedimento/atto/inserimentoUdienza.htm", method = RequestMethod.POST, params = { "Invia" })
	public String confermaInviaUdienza(@Valid @ModelAttribute("udienzaForm") UdienzaForm udienzaForm, BindingResult result,
			HttpServletRequest request, ModelMap modelMap) {

		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		AttoForm tmp = attoService.getAttoById(udienzaForm.getCodAtto(), idUfficio);
		if (tmp.getAllegato().getFileName() != null) {
			// udienzaForm.setDocumento(Hibernate.createBlob(tmp.getAllegato().getAttach()));
			udienzaForm.getAllegato().setDocumento(tmp.getAllegato().getDocumento());
			udienzaForm.getAllegato().setFileName(tmp.getAllegato().getFileName());
			udienzaForm.getAllegato().setContentType(tmp.getAllegato().getContentType());
		}
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);

		long idProcUdi = 0l;

		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());

		//Commentato perchè sembra più ragionevole che l'udienza vada sempre alla PU!!
		if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO){
			attoService.inviaUdienza(idUfficio, codiceUtente, idProcedimento, Long.parseLong(Constants.TIPO_ATTO_DECRETO_II_GRADO),
					Long.parseLong(Constants.DECRETO_FISSAZIONE_UDIENZA_II_GRADO), udienzaForm, idProcUdi);
		}else{
			attoService.inviaUdienza(idUfficio, codiceUtente, idProcedimento, Long.parseLong(Constants.TIPO_ATTO_DECRETO),
					Long.parseLong(Constants.DECRETO_FISSAZIONE_UDIENZA), udienzaForm, idProcUdi);
		}
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
		return copertinaAtto(tmp, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/udienza/visualizzaUdienzeDecretoSequestroConvalida.htm", method = RequestMethod.GET)
	public String udienzeDecretoSequestroConvalida(@ModelAttribute("atto") AttoForm atto, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap) {

		AttoForm attoForm = new AttoForm();
		if (request.getSession().getAttribute(Constants.ATTO) != null)
			attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		Integer idUfficioUtente = recuperaIdUfficioUtente();

		boolean udienzaFissata = false;
		boolean attoInLavDatiUdienza = false;
		String dataUdienzaFiss = null;
		TTpCatAtto catAtto = new TTpCatAtto();
		List<UdienzaForm> udienzaFiss = new ArrayList<UdienzaForm>();
		List<UdienzaForm> udienzaInLav = new ArrayList<UdienzaForm>();

		// Se tipo utente SMP_GIU
		if (request.getSession().getAttribute(Constants.TIPO_UTENTE).equals(Constants.TIPO_UTENTE_SMP_GIU)) {
			// Controllo sui direttiInteressatiSenzaDifensore
			List<SoggettoForm> soggettiInteressatiConNessunDifensore = procedimentoService.getSogIntSenzaDifensore(idProcedimento, idUfficioUtente);
			if (soggettiInteressatiConNessunDifensore.size() > 0) {
				super.setMessage(Constants.MESSAGE, "table.udienza.sogint.nodifensore", null, false);
				modelMap.addAttribute("direttiInteressatiSenzaDifensore", soggettiInteressatiConNessunDifensore);
				return copertinaAtto(attoForm, result, request, modelMap);
			}
			// Controllo se lo stato dell'ultima udienza è "Fissata" (1)
			udienzaFiss = udienzaService.listaUdienzePerProcedimentoEStatoUdienza(idProcedimento, idUfficioUtente,
					String.valueOf(UdienzaController.STATO_UDIENZA_FISSATA));
			if (udienzaFiss.size() > 0) {
				dataUdienzaFiss = Utility.convertDateToString(udienzaFiss.get(0).getDataUdienza());
				udienzaFiss.get(0).getCodUdienza();
				udienzaFissata = true;
			} else {
				// Controllo se lo stato dell'ultima udienza è "In fase di ..."
				// (4-6-8-10-12)
				String idStatoUdi = "4,6,8,10,12";
				udienzaInLav = udienzaService.listaUdienzePerProcedimentoEStatoUdienza(idProcedimento, idUfficioUtente, idStatoUdi);
				if (udienzaInLav.size() > 0) {
					udienzaInLav.get(0).getCodUdienza();
					// Recupero i dati dell'atto in lavorazione che sta fissando
					// l'udienza
					catAtto = new TTpCatAtto();
					String exist = udienzaService.esisteAttoInLavorazioneConDatiUdienza(idProcedimento, idUfficioUtente.longValue(),
							attoForm.getCodAtto());
					if (exist != null) {
						catAtto = attoService.getCatAttoById(Integer.valueOf(exist));
						attoInLavDatiUdienza = true;
					}
				}
			}
			// GESTIONE ERRORI E PAGINE DI RITORNO
			String statoAtto = attoForm.getStatoAtto().getId();
			UdienzaForm datiUdienza = new UdienzaForm();
			UdienzaForm udienzaDecreto = udienzaService.caricaUdienzaDecretoSeqConv(attoForm.getCodAtto(), idUfficioUtente.longValue());
			// Se esiste un'Udienza per l'Atto, carico e visualizzo i suoi dati
			// (Al di là dello stato dell'Atto)
			if (udienzaDecreto != null)
				datiUdienza = udienzaDecreto;
			// Controllo sullo stato dell'Atto
			if (!statoAtto.equals("1")) {
				// Se l'atto non è "In Lavorazione" e quindi è "Registrato"
				// La pagina dell'Udienza è in sola visualizzazione
				if (udienzaDecreto != null) {
					// Se esiste l'Udienza visualizzo la pagina in sola lettura
					datiUdienza.setReadOnly(true);
					return udienzaDecretoSequestroConvalida(datiUdienza, result, request, response, modelMap);
				} else {
					// Se non esiste l'Udienza, mando il messaggio di errore
					// relativo
					super.setMessage(Constants.MESSAGE, "udienza.sequestroconvalida.nonpresente.atto.error", null, false);
					return copertinaAtto(attoForm, result, request, modelMap);
				}
			} else // Se l'atto è "In Lavorazione"
			if (attoInLavDatiUdienza) {
				String descCatAtto = catAtto.getDescCatAtto();
				String descCatAtto1[] = descCatAtto.split("-");
				super.setMessage(Constants.MESSAGE, "udienza.sequestroconvalida.presente.atto.error", descCatAtto1[0], false);
				return copertinaAtto(attoForm, result, request, modelMap);
			} else {
				// Se lo stato dell'ultima udienza è "Fissata" (1), comunico
				// che l'udienza verrà ripianificata
				if (udienzaFissata)
					super.setMessage(Constants.MESSAGE, "udienza.sequestroconvalida.presente.fissata.error", dataUdienzaFiss, false);
				// Se lo stato dell'ultima udienza è "Assegnata nuovo ruolo"
				// (9) oppure Verbalizzata (3) con esito Riserva (10)
				// Consento l'inserimento dei dati per la nuova Udienza
				// senza alcun messaggio di avviso
				return udienzaDecretoSequestroConvalida(datiUdienza, result, request, response, modelMap);
			}
		}
		// Se tipo utente SMP
		else if (request.getSession().getAttribute(Constants.TIPO_UTENTE).equals(Constants.TIPO_UTENTE_SMP)) {
			UdienzaForm datiUdienza = new UdienzaForm();
			UdienzaForm udienzaDecreto = udienzaService.caricaUdienzaDecretoSeqConv(attoForm.getCodAtto(), idUfficioUtente.longValue());
			// Se esiste un'Udienza per l'Atto, carico e visualizzo i suoi dati
			// (Al di là dello stato dell'Atto)
			if (udienzaDecreto != null) {
				datiUdienza = udienzaDecreto;
				// La pagina dell'Udienza è in sola visualizzazione
				datiUdienza.setReadOnly(true);
				return udienzaDecretoSequestroConvalida(datiUdienza, result, request, response, modelMap);
			} else {
				super.setMessage(Constants.MESSAGE, "udienza.sequestroconvalida.nonpresente.atto.error", null, false);
				return copertinaAtto(attoForm, result, request, modelMap);
			}
		}
		return null;
	}

	@RequestMapping(value = { "/procedimento/atto/inserimentoUdienza.htm", "/procedimento/atto/anticipazioneRinvioUdienza.htm",
			"/procedimento/atto/assegnazioneNuovoRuolo.htm", "/procedimento/atto/remissioneSuRuolo.htm" }, method = RequestMethod.POST, params = { "Cancella" })
	public ModelAndView rimuoviDocumentoFromUdienza(@Valid @ModelAttribute("udienza") UdienzaForm udienza, BindingResult result,
			HttpServletRequest request, HttpServletResponse response, ModelMap map) throws IOException, SQLException {

		cancellaDocumento(udienza, request);
		ModelAndView mnv = null;
		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		if (attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA_II_GRADO)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_RINVIO_UDIENZA)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_RINVIO_UDIENZA_II_GRADO)) {
			mnv = new ModelAndView(aggiornaDecretoAnticipazioneRinvioUdienza(udienza, result, request, map));
			return mnv;
		} else if (attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_REMISSIONE_SU_RUOLO)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_REMISSIONE_SU_RUOLO_II_GRADO)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ASSEGNAZIONE_NUOVO_RUOLO)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ASSEGNAZIONE_NUOVO_RUOLO_II_GRADO)) {
			if (attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_REMISSIONE_SU_RUOLO)
					|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_REMISSIONE_SU_RUOLO_II_GRADO))
				udienza.setFkUdienzaDecreto(udienza.getCodUdienza());
			mnv = new ModelAndView(decretoUtilService.caricaDecretoAssNuovoRuoloRemSuRuolo(udienza, attoInSessione.getCategoriaAtto().getId(), result, request, map));
			return mnv;
		} else
			return nuovaUdienza(udienza, result, request, response, map);
	}

