	@RequestMapping(value = { "/procedimento/atto/inserimentoFonte.htm" }, method = RequestMethod.POST, params = { "CaricaFonte" })
	public ModelAndView caricaFonte(@ModelAttribute("atto") AttoForm atto, HttpServletRequest request, ModelMap modelMap) {
		ModelAndView mnv = new ModelAndView("/procedimento/atto/nuovaFonte");
		Integer idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		// caricamento fonte
		atto = this.attoService.dettaglioAtto(idUfficio, atto.getCodAtto(), idProcedimento, codiceUtente);
		atto.setDataInformativa(atto.getDataEmissione());
		if (atto.getAllegato().getFileData() != null) {
			atto.getAllegato().getFileData().getContentType();
			atto.getAllegato().setFileName(atto.getAllegato().getFileData().getOriginalFilename());
			atto.getAllegato().setContentType(atto.getAllegato().getFileData().getContentType());
			// atto.getAllegato().setAllegatoRimosso(isAllRim);
		}
		modelMap.addAttribute("atto", atto);
		modelMap.addAttribute("soggettiDelProcedimentoNonAssociati",
				procedimentoService.getSoggettiInteressatiNonAssociati(idUfficio, idProcedimento));
		if (atto.getCodAtto() > 0)
			modelMap.addAttribute("soggettiDelProcedimentoAssociati",
					procedimentoService.getSoggettiInteressatiAssociati(idUfficio, idProcedimento, atto.getCodAtto()));
		caricaCombo(atto, modelMap, request);
		return mnv;
	}

	@RequestMapping(value = "/procedimento/atto/nuovaFonte.htm", method = RequestMethod.POST)
	public ModelAndView nuovaFonte(@ModelAttribute("atto") AttoForm atto, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ModelAndView mnv = new ModelAndView("/procedimento/atto/nuovaFonte", "attoForm", atto);
		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		if (procedimentoService.getSoggettiInteressatiNonAssociati(idUfficio, idProcedimento).size() > 0 || result.hasErrors()) {
			mnv.addObject("soggettiDelProcedimentoNonAssociati", procedimentoService.getSoggettiInteressatiNonAssociati(idUfficio, idProcedimento));
			if (atto.getCodAtto() > 0)
				mnv.addObject("soggettiDelProcedimentoAssociati",
						procedimentoService.getSoggettiInteressatiAssociati(idUfficio, idProcedimento, atto.getCodAtto()));
			caricaCombo(atto, modelMap, request);

			modelMap.addAttribute("AllegatoObbligatorio", "S");

			return mnv;
		} else {
			super.setMessage(Constants.MESSAGE, "atto.nuovafonte.noSoggetiAssociabili", null, false);
			return nuovoAtto(atto, result, request, null);
		}
	}

