	@RequestMapping(value = "/procedimento/atto/proposta.htm", method = RequestMethod.POST)
	public ModelAndView proposta(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {
		ModelAndView mv = new ModelAndView("/procedimento/atto/proposta");
		int idUffOwn = recuperaIdUfficioUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		//cambio i valori della tipologia di prevenzione in sessione
		updateProcedimentoIntoSession(procedimento.getIdProcedimento());
		procedimento = recuperaProcedimento();

		long idProcedimento = procedimento.getIdProcedimento();
		recuperaProfilo();

		Long idProcedimentoCda=attoForm.getIdProcedimentoCda();

		if (attoForm.getIdProcedimentoCda() != null && attoForm.getIdProcedimentoCda() > 0){
			idUffOwn=Integer.parseInt(commonService.getUfficiCompetenza(idProcedimento,19L).get(0).getId());
			idProcedimento=attoForm.getIdProcedimentoCda();
		   }

		if (procedimento.getTipoProcedimento() != null)
			Long.valueOf(procedimento.getTipoProcedimento().getId());
		if (attoForm.getCodAtto() == 0)
			attoForm = procedimentoService.dettaglioPropostaAtto(idUffOwn, idProcedimento, attoForm.getCodAtto(), false);
		boolean aggravamento = false;
		List<SoggettoForm> soggetti = null;
		int idTipoFascicolo = getIdTipoFascicolo(false);
		int idTipoUff = (Integer) request.getSession().getAttribute(Constants.ID_TIPO_UFFICIO);
		if (idTipoFascicolo == Constants.TIPO_FASCICOLO_AGGRAVAMENTO ) {
			soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(idProcedimento, null, Constants.Flag.S);
			modelMap.addAttribute("soggettiInteressati", soggetti);
			aggravamento = true;
		} else if (attoForm.getStatoAtto().getId().equals(Constants.STATOATTO_IN_LAVORAZIONE_S) == true)
			soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(idProcedimento, Constants.RUOLO_DIRETTO, Constants.Flag.S);
		else
			soggetti = attoService.getRicercaSoggettoAtto(idProcedimento, attoForm.getCodAtto(),
					idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
		modelMap.addAttribute("soggettiInteressati", soggetti);

		attoForm.setAttoPerAggravamento(aggravamento);
		List<BeneForm> listaBeniNoTitDir = null;
		List<BeneForm> listaBeniNoMisPatr = null;
		List<SoggettoForm> listaTerziNoTitDir = null;
		if (!aggravamento)
			if (attoForm.getDataRegistrazione() == null
					&& (attoForm.getStatoAtto() != null && attoForm.getStatoAtto().getId() != null && !attoForm.getStatoAtto().getId()
							.equals(String.valueOf(Constants.STATOATTO_REGISTRATO)))) {
				listaBeniNoTitDir = attoService.listaBeniNoTitDir(idUffOwn, procedimento.getIdProcedimento(), attoForm.getCodAtto());
				listaBeniNoMisPatr = attoService.listaBeniNoMisPatr(idUffOwn, procedimento.getIdProcedimento(), attoForm.getCodAtto());
				listaTerziNoTitDir = attoService.listaTerziNoTitDir(idUffOwn, procedimento.getIdProcedimento(), attoForm.getCodAtto());
				modelMap.addAttribute("listaBeniNoTitDir", listaBeniNoTitDir);
				modelMap.addAttribute("listaBeniNoMisPatr", listaBeniNoMisPatr);
				modelMap.addAttribute("listaTerziNoTitDir", listaTerziNoTitDir);
			}

		List<ComboForm> ufficiList = new ArrayList<ComboForm>();

		long idTipoPrev =0l;
		if(procedimento.getCalcoloTipologiaPrevenzione() != null)
			 idTipoPrev = Long.valueOf(procedimento.getCalcoloTipologiaPrevenzione());


		if (attoForm != null && attoForm.getDataRegistrazione() == null)
			if (request.getSession().getAttribute(Constants.TIPO_UTENTE).equals(Constants.TIPO_UTENTE_SMP)) {
				if (aggravamento) {
					Long idProcPadre = procedimentoService.getIdPadreAggravamento(idProcedimento);
					ufficiList = commonService.getUfficoCompetenzaAggravamento(idProcPadre);
					modelMap.addAttribute("isAggravamento", aggravamento);
				} else
					ufficiList = commonService.getRelProcTrib(idUffOwn, Constants.TIPO_UFFICIO_PROCURA, idTipoPrev, null, null);
			} else if (request.getSession().getAttribute(Constants.TIPO_UTENTE).equals(Constants.TIPO_UTENTE_SMP_GIU))
				if (idTipoUff == Integer.parseInt(Constants.TIPO_UFFICIO_TRIBUNALE) && idTipoFascicolo == Constants.TIPO_FASCICOLO_AGGRAVAMENTO) {

					 modelMap.addAttribute("isAggravamento", aggravamento);

				}else if (idTipoUff == Constants.TIPO_UFFICIO_CORTE_D_APPELLO && idTipoFascicolo == Constants.TIPO_FASCICOLO_AGGRAVAMENTO) {
					ComboForm procGenerale = commonService.getProcuraGenerale(idUffOwn);
					if (procGenerale != null)
						ufficiList.add(procGenerale);

				} else if (procedimento.isAntimafia())
					ufficiList = commonService.getRelProcTrib(idUffOwn, Constants.TIPO_UFFICIO_TRIBUNALE, idTipoPrev, "S", null);
				//antiterrorismo e ordinaria
				else {
					ComboForm procInUdienza = null;
					procInUdienza = commonService.getProcuraInUdienza(idUffOwn);
					if (procInUdienza != null)
						ufficiList.add(procInUdienza);

					if (attoForm.getStatoAtto() != null && Constants.STATOATTO_ACQUISITO != new Long(attoForm.getStatoAtto().getId())) {
						List<ComboForm> uffici2List = null;
						uffici2List = commonService.getRelProcTrib(idUffOwn, Constants.TIPO_UFFICIO_TRIBUNALE, idTipoPrev, null, Long.valueOf(procInUdienza.getId()));
						modelMap.addAttribute("ufficiDestinatario2", uffici2List);
					}
				}

		modelMap.addAttribute("ufficiDestinatario", ufficiList);
		if(ufficiList.size()>1)
			request.getSession().setAttribute("listaUffici", ufficiList);

		if (attoForm != null && attoForm.getDataRegistrazione() != null
				&& !attoForm.getStatoAtto().getId().equals(Constants.STATOATTO_IN_LAVORAZIONE_S))

			attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, attoForm.getCodAtto(), recuperaIdCodiceUtente(), idProcedimento, request, attoForm);

		if (idProcedimentoCda != null && idProcedimentoCda > 0)
			attoForm.setIdProcedimentoCda(idProcedimentoCda);

		attoValidation.validateProposta(attoForm, procedimento, listaBeniNoTitDir, listaBeniNoMisPatr, listaTerziNoTitDir, soggetti, result, aggravamento, request,
				modelMap, idUffOwn);
		modelMap.addAttribute("attoForm", attoForm);

		attoForm.setAttoPerAggravamento(aggravamento);
		// per il Conferma Invia
		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);

		inizializzaDocumento(attoForm, request);
		modelMap.addAttribute("attoForm", attoForm);
		
		//F.C errore idStatoAtto nullPointer compilazione Misure Patrimoniali
		if (request.getSession().getAttribute(Constants.ATTO) == null)
		{
			impostaAtto(attoForm);
		}
						
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;

		if (idCatAtto <= 0)	{
			AttoForm tmp = procedimentoService.dettaglioPropostaAtto(idUffOwn, idProcedimento, attoForm.getCodAtto(), false);
			idCatAtto = tmp.getCategoriaAtto() != null ? Long.valueOf(tmp.getCategoriaAtto().getId()).longValue() : 0;
		}

		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
		 logger.debug("--- fine Proposta -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		return mv;
	}

