	@RequestMapping(value = "/procedimento/atto/confermaInviaAtto.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String aggiornaDecretoSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = recuperaIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = recuperaAtto().getCodAtto();

		if (result.hasErrors()) {
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/confermaInviaAtti";
		}

//---
//--- recupero il flag AllegatoObbligatorio
//---
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
			logger.debug("--- inizio aggiornaDecretoSequestro -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");
//---
		// INIZIA GESTIONE DOCUMENTALE
		if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)){
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return "/procedimento/atto/confermaInviaAtti";
			}
		// FINE GESTIONE DOCUMENTALE*/


		attoValidation.validateAttoDateSalva(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return "/procedimento/atto/confermaInviaAtti";
		}

		attoForm.setCodAtto(idAtto);

		inizializzaDocumento(attoForm, request);

		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;

		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		String categoriaAttoString = attoTmp.getCategoriaAtto().getId();

		attoForm.setDataRegistrazione(null);

		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE) || categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO)
				|| categoriaAttoString.equals(Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO)
				|| categoriaAttoString.equals(Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO)
				)
			attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		if (logger.isDebugEnabled())
			logger.debug("--- fine aggiornaDecretoSequestro -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		return "/procedimento/atto/confermaInviaAtti";
	}

	@RequestMapping(value = "/procedimento/atto/proposta.htm", method = RequestMethod.POST, params = { "Conferma" })
	public ModelAndView aggiornaProposta(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, ModelMap modelMap,
			HttpServletRequest request) {

		if (logger.isDebugEnabled())
			logger.debug("---aggiornaProposta -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");


		// INIZIA GESTIONE DOCUMENTALE
			if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)){
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return proposta(attoForm, result, request, modelMap);
			}
		// FINE GESTIONE DOCUMENTALE*/

		ProcedimentoForm procedimento = recuperaProcedimento();
		int idTipoUff = (Integer) request.getSession().getAttribute("idTipoUfficio");

		Long idTipoProcedimento = null;
		if (procedimento.getTipoProcedimento() != null)
			idTipoProcedimento = Long.valueOf(procedimento.getTipoProcedimento().getId());
		if (idTipoProcedimento != null && idTipoProcedimento.longValue() == Constants.ID_TIPO_PROCEDIMENTO_AGGRAVAMENTO) {
			Long idProcPadre = procedimentoService.getIdPadreAggravamento(procedimento.getIdProcedimento());

			if (idTipoUff == Integer.parseInt(Constants.TIPO_UFFICIO_TRIBUNALE)){

				//List<ComboForm> uffDestAggr =  commonService.getUfficiCompetenza(idProcPadre, Long.parseLong(Constants.TIPO_UFFICIO_PROCURA));
				//if(uffDestAggr!=null && uffDestAggr.size() > 0)
				//	attoForm.setDestinatario(uffDestAggr.get(0));

				ProcedimentoForm procedimentoPadre=procedimentoService.getDettaglioProcedimento(idProcPadre);
				int  ufficioPu=procedimentoPadre.getUfficioPU();
				attoForm.setDestinatario(new ComboForm(""+ufficioPu,""));

			}else if (idTipoUff == Integer.parseInt(Constants.TIPO_UFFICIO_PROCURA)){


				List<ComboForm> uffDestAggr = commonService.getUfficoCompetenzaAggravamento(idProcPadre);
				if(uffDestAggr!=null && uffDestAggr.size() > 0)
					attoForm.setDestinatario(uffDestAggr.get(0));
			}
		}

		attoValidation.validateSalvaProposta(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return proposta(attoForm, result, request, modelMap);
		}
		long idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
		}
		
		//P.Q. 21/06/2021 Mev 9 Inizio
		long idDestinatario = 0;
		if(attoForm.getDestinatario() != null && attoForm.getDestinatario().getId() != null) {
			  idDestinatario = new Long(attoForm.getDestinatario().getId());			
		}
		//P.Q. 21/06/2021 Mev 9 Inizio	
		long idDestinatario2 = 0;
		if (attoForm.getDestinatario2() != null)
			idDestinatario2 = new Long(attoForm.getDestinatario2().getId());

		//P.Q. 18/06/2021 Mev 9 Inizio 
		// se attoForm non contiene il file allegato (nel caso di salvataggio prima del conferma invia ad esempio)
		if (attoForm.getAllegato() == null || (attoForm.getAllegato() != null && attoForm.getAllegato().getFileData() == null)) {
			TAtto atto = attoService.getTAttoById(attoForm.getCodAtto(), idUffOwn);
			if (atto != null && atto.getFileDocumento() != null) { 
				attoForm.getAllegato().setDocumento(atto.getFileDocumento());
				attoForm.getAllegato().setFileName(atto.getDescNomeDocumento());
				attoForm.getAllegato().setContentType(atto.getDescTipoDocumento());
			}
		}
		//P.Q. 18/06/2021 Mev 9 Fine 		
		
		attoForm.setCodAtto(procedimentoService.aggiornaPropostaAtto(idUffOwn, idDestinatario, idDestinatario2, idProcedimento, attoForm, codUtente));
		if (attoForm.getDataRegistrazione() != null)
			super.updateProcedimentoIntoSession(idProcedimento);

		// INIZIA GESTIONE DOCUMENTALE

		// commento per nuova gestione del documentale


		//gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);

		// FINE GESTIONE DOCUMENTALE

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;

		if (idCatAtto <= 0)	{
			AttoForm tmp = procedimentoService.dettaglioPropostaAtto(idUffOwn, idProcedimento, attoForm.getCodAtto(), false);
			idCatAtto = tmp.getCategoriaAtto() != null ? Long.valueOf(tmp.getCategoriaAtto().getId()).longValue() : 0;
		}

		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
		 logger.debug("--- fine aggiornaProposta -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		return proposta(attoForm, result, request, modelMap);
	}

