	@RequestMapping(value = "/procedimento/atto/archiviazione.htm", method = RequestMethod.POST)
	public ModelAndView archiviazione(AttoForm atto, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		String idStatoProc = "0";
		String idTipoProc = "0";

		ProcedimentoForm currentProcedimento = recuperaProcedimento();
		long idUfficio = recuperaIdUfficioUtente();
		if (procedimentoService.hasAttiInLavorazioni(currentProcedimento.getIdProcedimento(),idUfficio)) {
			// Se esistono atti in lavorazione diversi dalla proposta blocco l'utente con un messaggio
			super.setMessage(Constants.MESSAGE, "archiviazione.errore.presenzaattiinlavorazione", null, false);
			return new ModelAndView("/procedimento/atto/nuovoAtto", "atto", atto);
		}

		int idTipoUfficio = recuperaIdTipoUfficio();
		if (currentProcedimento.getStatoProcedimento() != null)
			idStatoProc = currentProcedimento.getStatoProcedimento().getId();
		if (currentProcedimento.getTipoProcedimento() != null)
			idTipoProc = currentProcedimento.getTipoProcedimento().getId();

		long idProcedimento = 0l;
		if(currentProcedimento.getIdProcedimento() != null)
			idProcedimento = currentProcedimento.getIdProcedimento().intValue();

		ModelAndView mnv = new ModelAndView("/procedimento/atto/archiviazione", "attoForm", atto);
		String tipoAtto = atto.getTipoAtto().getId();
		// carica combo categoria atto archiviazione
		if (tipoAtto != null && !tipoAtto.isEmpty()) {
			this.categoria = commonService.getCategoriaAttoAbilitate(idProcedimento,idTipoUfficio, Integer.parseInt(idTipoProc), Integer.parseInt(idStatoProc),Integer.parseInt(tipoAtto));
			mnv.addObject("categoria", this.categoria);
		}
		return mnv;
	}

	@RequestMapping(value = "/procedimento/atto/inserimentoarchiviazione.htm", method = RequestMethod.POST, params = { "ConfermaInserimento" })
	public ModelAndView inserisciArchiviazione(@Valid @ModelAttribute("atto") AttoForm atto, BindingResult result, HttpServletRequest request,ModelMap modelMap) throws IOException, SQLException {

		attoValidation.validateInserisciArchiviazione(atto, result, request);
		long idCatAtto = Long.valueOf(atto.getCategoriaAtto().getId()).longValue();
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		allegatoValidation.validateAllegatoEFirma(atto.getAllegato(), result, request, tTpCatAtto);
		attoValidation.validateDataRicezione(atto, result, request);
		if (result.hasErrors()) {
			List<Message> customMessageList = new ArrayList<Message>();
			if (request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST) != null)
				customMessageList = ((List<Message>) request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST));
			super.addMessageIntoList(customMessageList, Constants.MESSAGE, "errors.campi.controllo", null);
			super.setMessages(customMessageList, true);
			return archiviazione(atto, result, request, modelMap);
		}

		ProcedimentoForm procedimento = recuperaProcedimento();
		long idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = procedimento.getIdProcedimento();
		long idStatoProcedimento = Long.parseLong(procedimento.getStatoProcedimento().getId());
		if (atto.getAllegato().getFileData().getSize() > 0) {
			atto.getAllegato().setFileName(atto.getAllegato().getFileData().getOriginalFilename());
			atto.getAllegato().setContentType(atto.getAllegato().getFileData().getContentType());
		}
		long idAtto = this.procedimentoService.inserisciArchivizione(idUfficio, codiceUtente, idProcedimento, idStatoProcedimento, atto);
		atto.setCodAtto(idAtto);

		gestionePiattaformaDocumentale(atto, request, idUfficio, result);

		// Recupero i messaggi settati nel gestionePiattaformaDocumentale, se
		// presenti
		List<Message> customMessageList = new ArrayList<Message>();
		if (request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST) != null)
			customMessageList = ((List<Message>) request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST));

		//DG Mev Marzo-Giugno Prog 20 - MEV AMM - atti in archivio dopo il salvataggio e il ricaricamento
		request.getSession().setAttribute("statoProcedimento", "24");
		// ricarica il procedimento per visualizzare l'eventuale cambiamento di
		// stato
		super.updateProcedimentoIntoSession(idProcedimento);
		super.addMessageIntoList(customMessageList, Constants.SUCCESS_MESSAGE, "success.operation", "INSERIMENTO");
		super.setMessagesSuccess(customMessageList, true);

		ModelAndView mvn = new ModelAndView(elencoAttiOrdineCronologico(atto, request, modelMap), "attoForm", new AttoForm());
		return mvn;
	}

	@RequestMapping(value = "/procedimento/atto/aggiornaIstanzaSoggettoDiffidato.htm", method = RequestMethod.POST, params = { "Conferma" })
	public ModelAndView aggiornaIstanzaSoggettoDiffidato(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		long idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();
		attoValidation.validateSalvaIstanzaSoggDiffidato(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
			return new ModelAndView("/procedimento/atto/istanzaSoggettoDiffidato", "attoForm", attoForm);
		}
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
			attoForm.setDataRicezione(Calendar.getInstance().getTime());
		}
		attoForm.setDataRegistrazione(null);
		attoForm.setCodAtto(attoService.aggiornaIstanzaSoggettoDiffidato(idUffOwn, idProcedimento, attoForm, codUtente));
		super.updateProcedimentoIntoSession(idProcedimento);

		procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);

		return new ModelAndView("/procedimento/atto/istanzaSoggettoDiffidato", "attoForm", attoForm);
	}

	@RequestMapping(value = "/procedimento/atto/proposta.htm", method = RequestMethod.POST, params = { "Invia" })
	public ModelAndView inviaProposta(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, ModelMap modelMap,
			HttpServletRequest request) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		boolean aggravamento = false;
		Long idTipoProcedimento = null;
		int idTipoUff = (Integer) request.getSession().getAttribute(Constants.ID_TIPO_UFFICIO);


		List<ComboForm> ufficiList = (List<ComboForm>)request.getSession().getAttribute("listaUffici");

		if (procedimento.getTipoProcedimento() != null)
			idTipoProcedimento = Long.valueOf(procedimento.getTipoProcedimento().getId());
		if (idTipoProcedimento != null && idTipoProcedimento.longValue() == Constants.ID_TIPO_PROCEDIMENTO_AGGRAVAMENTO) {
			aggravamento = true;
			Long idProcPadre = procedimentoService.getIdPadreAggravamento(procedimento.getIdProcedimento());
			if (idTipoUff == Integer.parseInt(Constants.TIPO_UFFICIO_TRIBUNALE)){

			//	List<ComboForm> uffDestAggr =  commonService.getUfficiCompetenza(idProcPadre, Long.parseLong(Constants.TIPO_UFFICIO_PROCURA));
			//	if(uffDestAggr!=null && uffDestAggr.size() > 0)
			//		attoForm.setDestinatario(uffDestAggr.get(0));
			ProcedimentoForm procedimentoPadre=procedimentoService.getDettaglioProcedimento(idProcPadre);
			int  ufficioPu=procedimentoPadre.getUfficioPU();
			attoForm.setDestinatario(new ComboForm(""+ufficioPu,""));

			}else if (idTipoUff == Integer.parseInt(Constants.TIPO_UFFICIO_PROCURA)){

				List<ComboForm> uffDestAggr = commonService.getUfficoCompetenzaAggravamento(idProcPadre);
				if(uffDestAggr!=null && uffDestAggr.size() > 0)
					attoForm.setDestinatario(uffDestAggr.get(0));
			}
		}
		List<BeneForm> listaBeniNoTitDir = null;
		List<BeneForm> listaBeniNoMisPatr = null;
		List<SoggettoForm>listaTerziNoTitDir = null;
		if (!aggravamento)
			if (attoForm.getDataRegistrazione() == null
					&& (attoForm.getStatoAtto() != null && !attoForm.getStatoAtto().getId().equals(String.valueOf(Constants.STATOATTO_REGISTRATO)))) {
				listaBeniNoTitDir = attoService.listaBeniNoTitDir(idUffOwn, procedimento.getIdProcedimento(), attoForm.getCodAtto());
				listaBeniNoMisPatr = attoService.listaBeniNoMisPatr(idUffOwn, procedimento.getIdProcedimento(), attoForm.getCodAtto());
				listaTerziNoTitDir = attoService.listaTerziNoTitDir(idUffOwn, procedimento.getIdProcedimento(), attoForm.getCodAtto());
				modelMap.addAttribute("listaBeniNoTitDir", listaBeniNoTitDir);
				modelMap.addAttribute("listaBeniNoMisPatr", listaBeniNoMisPatr);
				modelMap.addAttribute("listaTerziNoTitDir", listaTerziNoTitDir);
			}
		List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(procedimento.getIdProcedimento(),
				Constants.RUOLO_DIRETTO, Constants.Flag.S);

		// /INIZIA GESTIONE DOCUMENTALE
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateProposta(attoForm, procedimento, listaBeniNoTitDir, listaBeniNoMisPatr, listaTerziNoTitDir, soggetti, result, aggravamento, request,
				modelMap, idUffOwn);
		attoValidation.validateSalvaProposta(attoForm, result, request);
		if (procedimento.getStatoProcedimento() != null
				&& Constants.STATOPROC_DEFINITO_IN_I_GRADO_PER_INCOMPETENZA_CON_RESTITUZIONE_ATTI_ALLA_PROCURA.equalsIgnoreCase(procedimento
						.getStatoProcedimento().getId())) {
			attoForm.setIdProcedimento(procedimento.getIdProcedimento());
			attoValidation.validateInviaProposta(attoForm, aggravamento, result, true);
		} else
			attoValidation.validateInviaProposta(attoForm, aggravamento, result, false);
		String ufficioInvio = "";
		if (attoForm.getDestinatario() != null) {
			if (ufficiList != null) {
				for (int i = 0; i < ufficiList.size(); i++) {
					if (ufficiList.get(i).getId().equals(attoForm.getDestinatario().getId())) {
						ufficioInvio = ufficiList.get(i).getDescrizione();
					}
				}
			}
		}

		if (result.hasErrors() || (((List) request.getAttribute(Constants.MESSAGELIST)).size() > 0)) {
			return this.proposta(attoForm, result, request, modelMap);
		} else { 
			
			// P.Q. 18/06/2021 Mev 9 Inizio 
			//doppia conferma gestita con messaggio popup 
			
			/*
			if (request.getSession().getAttribute("pulsantiConfermaDest") == null && ufficiList != null) {

			new ModelAndView("/procedimento/atto/proposta");
			super.setMessage(Constants.MESSAGE, "success.conferma.destin", ufficioInvio, false);
			result.reject(Constants.MESSAGE);
			request.getSession().setAttribute("pulsantiConfermaDest", "si");
			gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
			return this.proposta(attoForm, result, request, modelMap);
		} else {
		*/
			// P.Q. 18/06/2021 Mev 9 Inizio
			
			attoForm.setDataRegistrazione(Calendar.getInstance().getTime());
			if (ufficioInvio != null && !ufficioInvio.isEmpty()) {
				super.setMessage(Constants.SUCCESS_MESSAGE, "success.conferma.destin", ufficioInvio, false);
			} else {
				super.setMessage(Constants.SUCCESS_MESSAGE, "success.invio.proposta", null, false);
			}

			//P.Q. 21/06/2021 Mev 9 Inizio 
			// se attoForm non contiene il file allegato (nel caso di salvataggio prima del conferma invia ad esempio)
			if (attoForm.getAllegato() == null || (attoForm.getAllegato() != null && attoForm.getAllegato().getFileData() == null)) {
				TAtto atto = attoService.getTAttoById(attoForm.getCodAtto(), idUffOwn);
				if (atto != null && atto.getFileDocumento() != null) { 
					attoForm.getAllegato().setDocumento(atto.getFileDocumento());
					attoForm.getAllegato().setFileName(atto.getDescNomeDocumento());
					attoForm.getAllegato().setContentType(atto.getDescTipoDocumento());
				}
			}
			//P.Q. 18/06/2021 Mev 9 Fine			
			
			// INIZIA GESTIONE DOCUMENTALE
			gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
			// FINE GESTIONE DOCUMENTALE

			//INIZIO INVIO DATI MPS - 8.17
			if(procedimento.getTipoProcedimento().getId().equals(Constants.TIPOPROC_AGGRAVAMENTO_PERSONALE) &&
					procedimento.getStatoProcedimento().getId().equals(Constants.STATOPROC_IN_ACQUISIZ_PROPOSTA)){

				Map<String, Object> mapProcedimentoPadre = procedimentoService.getDettaglioProcedimentoById(procedimento.getIdPadre());
				TAnProcedente procedentePadre = (TAnProcedente) mapProcedimentoPadre.get("procedente");
				String descrProcedentePadre = procedentePadre!=null ? procedentePadre.getDescProced().trim().toUpperCase() : "";
				int idUfficioProcPadre = 0;
				if(StringUtils.contains(descrProcedentePadre, "QUESTORE")){
					int idProcedente = procedentePadre.getCodiKIdProced();
					idUfficioProcPadre = poliziaDao.getIdUfficioDestByIdProcedente(new Integer(idProcedente).intValue()).intValue();
				} else if(StringUtils.contains(descrProcedentePadre, "PROCURATORE")) {
					idUfficioProcPadre = new Long(idUffOwn).intValue();
				} else{
					idUfficioProcPadre = poliziaDao.getIdUfficioDest(new Long(idUffOwn)).intValue();
				}
				List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(procedentePadre.getCodiKIdProced(), new Long(idUffOwn).intValue(), procedimento.getIdProcedimento(), Constants.TIPOPROC_PERSONALE);
				for(int i=0; i<uffDestinatariList.size(); i++)
				{
					RichiestaAggravamentoMisuraPersonaleRequest richiestaAgg = poliziaService.createRichiestaAggravamentoMisuraPersonale(procedimento.getIdProcedimento().longValue(), attoForm.getCodAtto(), new Long(idUffOwn).intValue(), uffDestinatariList.get(i), procedimento.getIdPadre().longValue(), idUfficioProcPadre);
					/*long idMsg = */poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_RICHIESTA_AGGRAVAMENTO_MISURE_PERSONALI, procedimento.getIdProcedimento().longValue(), attoForm.getCodAtto(), richiestaAgg, Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUffOwn, uffDestinatariList.get(i), recuperaIdCodiceUtente());
				}
			}
			//FINE   INVIO DATI MPS - 8.17

			attoForm.getStatoAtto().setId(Constants.STATOATTO_INOLTRATO + "");
			request.getSession().removeAttribute("listaUffici");
			return this.aggiornaProposta(attoForm, result, modelMap, request);

		}
	}

	@RequestMapping(value = "/procedimento/atto/aggiornaIstanzaSoggettoDiffidato.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaIstanzaSoggettoDiffidato(@Valid AttoForm attoForm, BindingResult result, ModelMap modelMap, HttpServletRequest request) {

		attoValidation.validateConfermaInviaIstanzaSoggDiffidato(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
			return "/procedimento/atto/istanzaSoggettoDiffidato";
		}
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
			attoForm.setDataRicezione(Calendar.getInstance().getTime());
		}
		Date dataRegistrazione = Calendar.getInstance().getTime();
		attoForm.setDataRegistrazione(dataRegistrazione);

		long idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();

		attoForm.setCodAtto(attoService.aggiornaIstanzaSoggettoDiffidato(idUffOwn, idProcedimento, attoForm, codUtente));
		super.updateProcedimentoIntoSession(idProcedimento);
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.registra.istanza", null, false);
		return copertinaAtto(attoForm, result, request, modelMap);

	}

	@RequestMapping(value = "/procedimento/atto/inserimentoFonte.htm", method = RequestMethod.POST, params = { "ConfermaInserimento" })
	public ModelAndView inserisciFonte(@Valid @ModelAttribute("atto") AttoForm atto, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) throws IOException, SQLException {

		attoValidation.validateInserisciFonte(atto, result, request);

		long idCatAtto = Long.valueOf(atto.getTipoAtto().getId()).longValue();

		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		allegatoValidation.validateAllegatoEFirma(atto.getAllegato(), result, request, tTpCatAtto);
		attoValidation.validateDataRicezione(atto, result, request);

		if (result.hasErrors()) {
			List<Message> customMessageList = new ArrayList<Message>();
			if (request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST) != null)
				customMessageList = ((List<Message>) request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST));
			super.addMessageIntoList(customMessageList, Constants.MESSAGE, "errors.campi.controllo", null);
			super.setMessages(customMessageList, true);
			return nuovaFonte(atto, result, request, modelMap);
		}
		ProcedimentoForm procedimento = recuperaProcedimento();
		long idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = procedimento.getIdProcedimento();
		long idStatoProcedimento = Long.parseLong(procedimento.getStatoProcedimento().getId());
//		Segnalazione TMC-0717
		if(atto.getCodAtto() == 0)
		{
			long idAtto = procedimentoService.inserisciFonte(idUfficio, codiceUtente, idProcedimento, idStatoProcedimento, atto);
			atto.setCodAtto(idAtto);
		}
		else
			procedimentoService.modificaFonte(idUfficio, idProcedimento, atto, codiceUtente);


		gestionePiattaformaDocumentale(atto, request, idUfficio, result);

		// Recupero i messaggi settati nel gestionePiattaformaDocumentale, se
		// presenti
		List<Message> customMessageList = new ArrayList<Message>();
		if (request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST) != null)
			customMessageList = ((List<Message>) request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST));

		// ricarica il procedimento per visualizzare l'eventuale cambiamento di
		// stato
		super.updateProcedimentoIntoSession(idProcedimento);
		super.addMessageIntoList(customMessageList, Constants.SUCCESS_MESSAGE, "success.operation", "INSERIMENTO");
		super.setMessagesSuccess(customMessageList, true);

		ModelAndView mvn = new ModelAndView(elencoAttiOrdineCronologico(atto, request, modelMap), "attoForm", new AttoForm());
		return mvn;
	}

	@RequestMapping(value = "/procedimento/atto/decretoOpposizioneDissequestro.htm", method = RequestMethod.POST, params = { "SelezionaDecreto" })
	public String inserisciDecretoOpposizioneDissequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return decretoUtilService.nuovoDecretoOpposizioneDissequestro(attoForm, result, request, modelMap);
		}

		long idAtto = attoService.inserisciAttoDecretoOpposizioneDissequestro(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(
				procedimento.getIdProcedimento(), idAtto, idUffOwn);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);
		List<BeneForm> beni = beneService.listaBeniPerProcedimentoNoAttoPerOpposizione(idAtto, procedimento.getIdProcedimento(), codUtente, idUffOwn,
				super.printMethodName(), 0, 0, 0, 0, 0);
		modelMap.addAttribute("beni", beni);

		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoOpposizioneDissequestro";
	}

