	@RequestMapping(value = "/procedimento/atto/revocazioneConfisca.htm", method = RequestMethod.POST, params = { "SelezionaDecreto" })
	public String inserisciRevocazioneConfisca(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return decretoUtilService.nuovaRevocazioneConfisca(attoForm, result, request, modelMap);
		}
		//vado a controllare che per l'atto selezionato ci siano beni che
		//soddisfano la revocazione della confisca
		List<BeneForm> listBeneForm = beneService.controlloPresenzaBeniPerRevocaConfisca(idAttoOrigine, idProcedimento, codUtente, idUffOwn,
				super.printMethodName());

		if (listBeneForm==null || listBeneForm.size()==0){
			super.setMessage(Constants.MESSAGE,"error.controllo.beni.revoca",null,false);
			result.reject(Constants.MESSAGE);
			return decretoUtilService.nuovaRevocazioneConfisca(attoForm, result, request, modelMap);


		}

		long idAtto = attoService.inserisciAttoRevocazioneConfisca(idUffOwn, idProcedimento, codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, idProcedimento, request, attoForm);

		if (!attoForm.isVisualizzaFiltro()) {
			attoForm.setSoggettiDiretti(null);
			attoForm.setSoggettiTitolari(null);
			attoForm.setTipologiaBene(null);
			attoForm.setCategoriaBene(null);
			attoForm.setSottoCategoriaBene(null);
		}

		long idSoggettoDiretto = attoForm.getIdSoggettoDiretto();
		long idSoggettoTitolare = attoForm.getIdSoggettoTitolare();
		long idTipologia = attoForm.getIdTipologia();
		long idCategoria = attoForm.getIdCategoria();
		long idSottocategoria = attoForm.getIdSottocategoria();

		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(
				idProcedimento, idAtto, idUffOwn);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);
		List<BeneForm> beni = beneService.listaBeniPerProcedimentoNoAttoPerRevocazione(idAtto, idProcedimento, codUtente, idUffOwn,
				super.printMethodName(), idSoggettoDiretto, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
		modelMap.addAttribute("beni", beni);

		modelMap.addAttribute("categorie", getCategorieBene(attoForm));
		modelMap.addAttribute("sottocategorie", getSottoCategorieBene(attoForm));
		if (attoForm.isVisualizzaFiltro()) {
			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDiretti = attoService.getRicercaSoggettoAtto(idProcedimento, idAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDiretti != null )
				modelMap.addAttribute("soggettiDiretti", utility.creaComboSoggetti(soggettiDiretti));
			List<SoggettoForm> soggettiTitolari = attoService.getRicercaSoggettoAtto(idProcedimento, idAtto, idUffOwn, Constants.ID_RUOLO_TITOLARI, Constants.Flag.S);
			if (soggettiTitolari != null )
				modelMap.addAttribute("soggettiTitolari", utility.creaComboSoggetti(soggettiTitolari));
		}


		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaRevocazioneConfisca";
	}

	@RequestMapping(value = "/procedimento/atto/inserimentoFonte.htm", method = RequestMethod.POST, params = { "ConfermaModifica" })
	public ModelAndView modificaFonte(@Valid @ModelAttribute("atto") AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) throws IOException, SQLException {

		attoValidation.validateInserisciFonte(attoForm, result, request);

		long idCatAtto = Long.valueOf(attoForm.getTipoAtto().getId()).longValue();
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		allegatoValidation.validateAllegatoEFirma(attoForm.getAllegato(), result, request, tTpCatAtto);
		attoValidation.validateDataRicezione(attoForm, result, request);

		if (result.hasErrors()) {
			List<Message> customMessageList = new ArrayList<Message>();
			if (request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST) != null)
				customMessageList = ((List<Message>) request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST));
			super.addMessageIntoList(customMessageList, Constants.MESSAGE, "errors.campi.controllo", null);
			super.setMessages(customMessageList, true);
			return nuovaFonte(attoForm, result, request, modelMap);
		}
		ProcedimentoForm procedimento = recuperaProcedimento();
		long idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = procedimento.getIdProcedimento();
		this.inizializzaDocumento(attoForm, request);

		this.procedimentoService.modificaFonte(idUfficio, idProcedimento, attoForm, codiceUtente);

		gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);

		// Recupero i messaggi settati nel gestionePiattaformaDocumentale, se
		// presenti
		List<Message> customMessageList = new ArrayList<Message>();
		if (request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST) != null)
			customMessageList = ((List<Message>) request.getSession().getAttribute(Constants.SUCCESS_MESSAGE_LIST));

		super.addMessageIntoList(customMessageList, Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA");

		super.setMessagesSuccess(customMessageList, true);

		ModelAndView mvn = new ModelAndView(elencoAttiOrdineCronologico(attoForm, request, modelMap), "attoForm", new AttoForm());
		return mvn;
	}

	// Utilizzato per la cancellazione del file dal documentale.
	// Su tutte le pagine dove è presente la possibilità di cancellare il
	// documento è presente
	// un id sul form così indicato: id="id_formConfermaInvia".
	// Questa pagina non esiste fisicamente ma viene valorizzata da
	// firmaRemota.js quando viene
	// invocata l'eliminazione del documento
	@RequestMapping(value = { "/procedimento/atto/rimuoviAllegatoDaMemoriaDocumentale.htm" }, method = RequestMethod.POST, params = { "rimuoviAllegatoDaMemoriaDocumentale" })
	public ModelAndView rimuoviAllegatoDaMemoriaDocumentale(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap map)
			throws IOException, SQLException {

		String url = copertinaAtto(attoForm, result, request, map);
		if (map.get("udienzaForm") != null) {
			UdienzaForm udienzaForm = (UdienzaForm) map.get("udienzaForm");

			udienzaForm.getAllegato().setAllegatoRimosso(true);
			udienzaForm.getAllegato().setDocumentoFirmato("N");

			if (udienzaForm.getAllegato().getFirmaRemota() != null)
				udienzaForm.getAllegato().getFirmaRemota().setFirmaImmediata(false);

			udienzaForm.getAllegato().setFileName(null);

			if(udienzaForm.getAllegato().isAllegatoRimosso()){
				cancellaDocumento(udienzaForm, request);
				udienzaForm.getAllegato().setAllegatoRimosso(false);
			}

			return new ModelAndView(url, "udienzaForm", udienzaForm);
		} else if (map.get("attoForm") != null
				&& (attoForm.getTipoAtto() != null && !attoForm.getTipoAtto().getId().equalsIgnoreCase(Constants.TIPO_ATTO_FONTE))) {
			attoForm = (AttoForm) map.get("attoForm");

			attoForm.getAllegato().setAllegatoRimosso(true);
			attoForm.getAllegato().setDocumentoFirmato("N");
			attoForm.getAllegato().getFirmaRemota().setFirmaImmediata(false);
			attoForm.getAllegato().setFileName(null);

			if(attoForm.getAllegato().isAllegatoRimosso()){
				cancellaDocumento(attoForm, request);
				attoForm.getAllegato().setAllegatoRimosso(false);
			}

			return new ModelAndView(url, "attoForm", attoForm);
		} else if (map.get("atto") != null) {
			attoForm = (AttoForm) map.get("atto");

			attoForm.getAllegato().setAllegatoRimosso(true);
			attoForm.getAllegato().setDocumentoFirmato("N");
			attoForm.getAllegato().getFirmaRemota().setFirmaImmediata(false);
			attoForm.getAllegato().setFileName(null);

			if (attoForm.getAllegato().isAllegatoRimosso()){
				cancellaDocumento(attoForm, request);
				attoForm.getAllegato().setAllegatoRimosso(false);
			}

			/*
			 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
			 * Numero MEV : 006
			 * Autore    : Gioggi
			 * Data      : 20 apr 2020
			 * Branch    : MEV_006
			 */
			attoUtilService.caricaDatiDaAttoInSessione(attoForm, map);
			AttoForm attoFormTmp = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
			if (attoFormTmp.getAllegato() != null
					&& attoFormTmp.getAllegato().getFileName() != null) {
				if (request.getSession().getAttribute(Constants.ATTO) != null)
					request.getSession().removeAttribute(Constants.ATTO);
				if (attoFormTmp.getCategoriaAtto() != null && attoForm.getCategoriaAtto() == null)
					attoForm.setCategoriaAtto(attoFormTmp.getCategoriaAtto());
				if (attoFormTmp.getCodAtto() > 0 && attoForm.getCodAtto() == 0)
					attoForm.setCodAtto(attoFormTmp.getCodAtto());
				if (attoFormTmp.getTipoAtto() != null && attoForm.getTipoAtto() == null)
					attoForm.setTipoAtto(attoFormTmp.getTipoAtto());
				if (attoFormTmp.getStatoAtto() != null && attoForm.getStatoAtto() == null)
					attoForm.setStatoAtto(attoFormTmp.getStatoAtto());
				request.getSession().setAttribute(Constants.ATTO, attoForm);
			}
			//***** FINE INTERVENTO MEV_006 *****//

			return new ModelAndView(url, "attoForm", attoForm);
		}
		return new ModelAndView(url, "attoForm", attoForm);
	}

