	// Utilizzato per la firma posticipata del documento
	// Su tutte le pagine dove è presente la possibilità di scaricare il
	// documento è presente
	// un id sul form così indicato: id="id_formConfermaInvia".
	// Questa pagina non esiste fisicamente ma viene valorizzata da
	// firmaRemota.js quando viene
	// invocata la firma del documento
	@RequestMapping(value = { "/procedimento/atto/firmaPosticipataDocumentale.htm" }, method = RequestMethod.POST, params = { "firmaPosticipataDocumentale" })
	public String firmaPosticipataDocumentale(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap map,
			HttpServletResponse response) throws IOException, SQLException {
		String url = copertinaAtto(attoForm, result, request, map);

		Integer idUfficio = recuperaIdUfficioUtente();
		BigInteger idAttoDocumentale = new BigInteger("-1");

		// INIZIA GESTIONE DOCUMENTALE
		allegatoFirmaUtilService.validaAllegatoFirmaPosticipata(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		if (attoForm != null && attoForm.getCodAtto() > 0) {
			TAtto tAtto = attoService.getTAttoById(attoForm.getCodAtto(), idUfficio);
			if (tAtto.getNumeDocumentoPdoc() != null)
				idAttoDocumentale = Utility.longToBigInteger(tAtto.getNumeDocumentoPdoc());
		}
		// INIZIA GESTIONE DOCUMENTALE
		gestioneFirmaRemotaDocumento(attoForm, idUfficio, result, idAttoDocumentale);
		// FINE GESTIONE DOCUMENTALE

		url = copertinaAtto(attoForm, result, request, map);

		return url;
	}

