	@RequestMapping(value = { "/procedimento/atti/elenco.htm" }, method = {RequestMethod.GET,RequestMethod.POST})
	public ModelAndView elencoAtto(HttpServletRequest request, HttpServletResponse response) {

		// rimuovo dalla sessione un eventuale atto che avevo caricato in
		// precedenza
		// poichè potrebbe incasinare il caricamento di alcuni atti - F.Ronchi
		// 26/09/2012
		request.getSession().removeAttribute(Constants.ATTO);
		request.getSession().setAttribute(Constants.ATTO, new AttoForm());
		request.getSession().setAttribute("fromMenuAtti", "elenco");
		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento();
		ProfiloForm profiloUtente = (ProfiloForm) request.getSession().getAttribute("profilo");
		List<TreeNode> albero = null;
		Long idTipofasc = null;
		Long idTipoproc = null;
		if (procedimento.getTipoProcedimento() != null) {
			idTipofasc = Long.valueOf(procedimento.getTipoFascicolo().getId());
			idTipoproc = Long.valueOf(procedimento.getTipoProcedimento().getId());
			albero = procedimentoService.getAlberaturaAtti(idProcedimento, profiloUtente.getIdTipoUfficio(), idTipofasc, idTipoproc);
		} else
			albero = procedimentoService.getAlberaturaAtti(idProcedimento, profiloUtente.getIdTipoUfficio());
		this.updateViewAndMenu(procedimento, request);

		request.getSession().setAttribute("returnTo", "/procedimento/atti/elenco.htm?mappingUrl=%2Fmenu.htm");

		// Giacomo 10/07/2013 Aggiungo la breadcrumb
		addBreadcrumbs();

		return (new ModelAndView("/procedimento/atto/alberaturaAtti", "albero", albero)).addObject("udienza", new UdienzaForm());
	}

	@RequestMapping(value = { "/procedimento/atti/elenco.htm" }, method = RequestMethod.POST, params = "EliminaAtto")
	public ModelAndView eliminaAttoDaElencoAtto(AttoForm attoForm, BindingResult errors, HttpServletRequest request, HttpServletResponse response,
			ModelMap modelMap) {

		if ((attoForm.getCodAtto() == 0)) {
			super.setMessage(Constants.MESSAGE, "table.item.selection", null, false);
			return elencoAtto(request, response);
		}
		Integer idUffOwn = recuperaIdUfficioUtente();
		String descUtente = (recuperaIdCodiceUtente().toString());
		long codAtto = attoForm.getCodAtto();
		long idProcedimento = recuperaIdProcedimento();

		KeyMessageDto ritornoDb = attoService.cancellaAtto(idUffOwn, codAtto, descUtente, super.printMethodName());
		if (ritornoDb.isError()) {
			super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
			errors.reject(Constants.MESSAGE);
		} else {
			super.setMessage(Constants.SUCCESS_MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
			errors.reject(Constants.MESSAGE);
		}

		// aggiorno l'intestazione del procedimento perchè nel caso di fonte
		// passa da ISCRITTO a IN LAVORAZIONE
		super.updateProcedimentoIntoSession(idProcedimento);

		return elencoAtto(request, response);
	}

