	private void caricaCombo(AttoForm atto, ModelMap map, HttpServletRequest request) {
		List<ComboForm> organi = null;
		List<ComboForm> province = null;
		List<ComboForm> indirizziSede = null;
		List<ComboForm> comuni = null;
		if (fonti != null && atto.getFonte() != null && !atto.getFonte().getId().equals(Constants.NO_ITEM_SELECTED)
				&& !atto.getFonte().getId().equals(Constants.FONTE_ALTRO)) {
			String tipo = null;
			if (atto.getFonte().getId().equals("9"))
				tipo = Constants.ORGANO_POLIZIA_GIUDIZIARIA;
			if (atto.getFonte().getId().equals("10"))
				tipo = Constants.ORGANO_AUTORITA_GIUDIZIARIA;
			organi = procedimentoService.getOrgani(tipo);
		} else {
			organi = null;
			atto.setOrgano(null);
		}
		if (organi != null && atto.getOrgano() != null && !atto.getOrgano().getId().equals(Constants.NO_ITEM_SELECTED)) {
			if (!String.valueOf(request.getSession().getAttribute("idTipoUfficio")).equals(Constants.TIPO_UFFICIO_PROCURA))
				province = StaticListLoader.getProvince();
			else
				province = StaticListLoader.getProvince(Long.valueOf(atto.getOrgano().getId()));
		} else {
			province = null;
			atto.setProvinciaOrgano(null);
		}
		if (province != null && atto.getProvinciaOrgano() != null && !atto.getProvinciaOrgano().getId().equalsIgnoreCase(Constants.NO_ITEM_SELECTED))
			comuni = commonService.getAllComuniByOrganoAndProvincia(atto.getProvinciaOrgano().getId(), Long.parseLong(atto.getOrgano().getId()));
		else {
			comuni = null;
			atto.setComuneOrgano(null);
		}
		if (comuni != null && atto.getComuneOrgano() != null && !atto.getComuneOrgano().getId().equals(Constants.NO_ITEM_SELECTED))
			indirizziSede = procedimentoService.getIndirizzoByOrganoAndComune(atto.getComuneOrgano().getId(),
					Long.parseLong(atto.getOrgano().getId()));
		else {
			atto.setIndirizzoOrgano(null);
			indirizziSede = null;
		}

		map.addAttribute("organi", organi);
		map.addAttribute("province", province);
		map.addAttribute("indirizziSede", indirizziSede);
		map.addAttribute("comuni", comuni);
	}

	private void caricaComboPerAttoGenerico(AttoForm atto, ModelMap map, List<ComboForm> fontiAttoGenerico) {
		List<ComboForm> organi = null;
		List<ComboForm> province = null;
		List<ComboForm> indirizziSede = null;
		List<ComboForm> comuni = null;
		if (fontiAttoGenerico != null && atto.getFonteAttoGenerico() != null
				&& !atto.getFonteAttoGenerico().getId().equals(Constants.NO_ITEM_SELECTED)
				&& !atto.getFonteAttoGenerico().getId().equals(Constants.FONTE_ALTRO)) {
			String tipo = null;
			if (atto.getFonteAttoGenerico().getId().equals("9"))
				tipo = Constants.ORGANO_POLIZIA_GIUDIZIARIA;
			if (atto.getFonteAttoGenerico().getId().equals("10"))
				tipo = Constants.ORGANO_AUTORITA_GIUDIZIARIA;
			organi = procedimentoService.getOrgani(tipo);

		} else {
			organi = null;
			atto.setOrgano(null);
		}
		if (organi != null && atto.getOrgano() != null && !Constants.NO_ITEM_SELECTED.equals(atto.getOrgano().getId())) {
			province = StaticListLoader.getProvince(Long.valueOf(atto.getOrgano().getId()));
		} else {
			province = null;
			atto.setProvinciaOrgano(null);
		}
		if (province != null && atto.getProvinciaOrgano() != null && !atto.getProvinciaOrgano().getId().equalsIgnoreCase(Constants.NO_ITEM_SELECTED))
			comuni = commonService.getAllComuniByOrganoAndProvincia(atto.getProvinciaOrgano().getId(), Long.parseLong(atto.getOrgano().getId()));
		else {
			comuni = null;
			atto.setComuneOrgano(null);
		}
		if (comuni != null && atto.getComuneOrgano() != null && !atto.getComuneOrgano().getId().equals(Constants.NO_ITEM_SELECTED))
			indirizziSede = procedimentoService.getIndirizzoByOrganoAndComune(atto.getComuneOrgano().getId(),
					Long.parseLong(atto.getOrgano().getId()));
		else if (fontiAttoGenerico != null && atto.getFonteAttoGenerico() != null
				&& !atto.getFonteAttoGenerico().getId().equals(Constants.NO_ITEM_SELECTED)
				&& !atto.getFonteAttoGenerico().getId().equals(Constants.FONTE_ALTRO)) {
			ComboForm cbo = new ComboForm();
			cbo.setId(Constants.NO_ITEM_SELECTED);
			cbo.setDescrizione(Constants.NO_ITEM_SELECTED);
			atto.setIndirizzoOrgano(cbo);
		} else {
			atto.setIndirizzoOrgano(null);
			indirizziSede = null;
		}

		map.addAttribute("organi", organi);
		map.addAttribute("province", province);
		map.addAttribute("indirizziSede", indirizziSede);
		map.addAttribute("comuni", comuni);

		// carico le descrizione delle combo
		if (atto.getFonteAttoGenerico() != null && atto.getFonteAttoGenerico().getId().trim().length() > 0) {
			TTpCatAtto tipoCatAtto = attoService.getCatAttoById(Integer.parseInt(atto.getFonteAttoGenerico().getId()));
			atto.getFonteAttoGenerico().setDescrizione(tipoCatAtto.getDescCatAtto());
		}
		if (atto.getFlagSpedRic() != null && atto.getFlagSpedRic().getId() != null && atto.getFlagSpedRic().getId().trim().length() > 0)
			if (atto.getFlagSpedRic().getId().equalsIgnoreCase(Constants.NO_ITEM_SELECTED))
				atto.getFlagSpedRic().setDescrizione("");
			else if (atto.getFlagSpedRic().getId().equalsIgnoreCase(Constants.Flag.RICEVUTO))
				atto.getFlagSpedRic().setDescrizione(Constants.Flag.RICEVUTO_LABEL);
			else if (atto.getFlagSpedRic().getId().equalsIgnoreCase(Constants.Flag.SPEDITO))
				atto.getFlagSpedRic().setDescrizione(Constants.Flag.SPEDITO_LABEL);

	}

