	@RequestMapping(value = "/procedimento/atti/elencoAttiOrdineCronologico.htm", method = RequestMethod.GET)
	public String elencoAttiOrdineCronologico(AttoForm attoForm, HttpServletRequest request, ModelMap modelMap) {

		request.getSession().removeAttribute(Constants.ATTO);
		request.getSession().setAttribute(Constants.ATTO, new AttoForm());

		if (attoForm.getFlgNascondiRicevute()!=null) {
			request.getSession().setAttribute("flgNascondiRicevute", attoForm.getFlgNascondiRicevute());
		} else {
			if (request.getSession().getAttribute("flgNascondiRicevute")!=null) {
				attoForm.setFlgNascondiRicevute((Boolean)request.getSession().getAttribute("flgNascondiRicevute"));
			} else {
				request.getSession().setAttribute("flgNascondiRicevute", false);
			}
		}

		request.getSession().setAttribute("fromMenuAtti", "ordine");
		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento();
		List<AttoForm> listaAtti = attoService.getAttiOrdineCronologico(idProcedimento, recuperaIdCodiceUtente(), super.printMethodName(),(Boolean)request.getSession().getAttribute("flgNascondiRicevute"));
		modelMap.addAttribute("listaAtti", listaAtti);
		int idTipoFascicolo = getIdTipoFascicolo(false);


		if (idTipoFascicolo==Constants.TIPO_FASCICOLO_AGGRAVAMENTO ||
				idTipoFascicolo==Constants.TIPO_FASCICOLO_CAMERA_DI_CONSIGLIO	) {
//				if(procedimento!=null && procedimento.getTipoProcedimento()!=null && (procedimento.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)))
//					modelMap.addAttribute("TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM", true);
				Long idPadre = procedimentoService.getIdPadreAggravamento(procedimento.getIdProcedimento());
				if(idPadre != null){
					ProcedimentoForm padre = procedimentoService.getDettaglioProcedimento(idPadre);
					procedimento.setAnnoPadre(padre.getAnno());
					procedimento.setNumeroPadre(padre.getNumero());
					NumeroRegistroForm formPadre = procedimentoService.getNumeroRegistroPadre(procedimento.getIdProcedimento());
					if(formPadre!=null) 	procedimento.setUfficioPadre(formPadre.getUfficio());
				}
		}

		this.updateViewAndMenu(procedimento, request);
		// Imposto il campo returnTo per gestire il ritorno alla cronologia degli atti
		request.getSession().setAttribute("returnTo", "/procedimento/atti/elencoAttiOrdineCronologico.htm");

		// Giacomo 10/07/2013 Aggiunto la breadcrums
		addBreadcrumbs("GET", "/procedimento/atti/elencoAttiOrdineCronologico.htm", null);
		return "/procedimento/atto/elencoAttiOrdineCronologico";
	}



