	@RequestMapping(value = "/procedimento/atti/elencoAttiOrdineCronologico.htm", method = RequestMethod.POST, params = { "EliminaAtto" })
	public String eliminaAttoDaElencoAttiOrdineCronologico(AttoForm attoForm, BindingResult errors, HttpServletRequest request, ModelMap modelMap) {

		if ((attoForm.getCodAtto() == 0)) {
			super.setMessage(Constants.MESSAGE, "table.item.selection", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		ProfiloForm profiloUtente = (ProfiloForm) request.getSession().getAttribute("profilo");

		Integer idUffOwn = recuperaIdUfficioUtente();
		long codAtto = attoForm.getCodAtto();
		String descUtente = (recuperaIdCodiceUtente().toString());
		long idProcedimento = recuperaIdProcedimento();
		String tipoAtto = "";
		String statoAtto = "";
		String categoriaAtto = "";
		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto: aggiunto recupero variabili
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 21 apr 2020
		 * Branch    : MEV_006
		 */
		String numeAnnoAtto = "", numeAtto = "";
		//***** FINE INTERVENTO MEV_006 *****//

		List<AttoForm> listaAtti = attoService.getAttiOrdineCronologico(idProcedimento, recuperaIdCodiceUtente(), super.printMethodName(),(Boolean)request.getSession().getAttribute("flgNascondiRicevute"));
		for (int i = 0; i < listaAtti.size(); i++) {
			if (listaAtti.get(i).getCodAtto() == codAtto) {
				tipoAtto = listaAtti.get(i).getTipoAtto().getId();
				statoAtto = listaAtti.get(i).getStatoAtto().getId();
				categoriaAtto = listaAtti.get(i).getCategoriaAtto().getId();
				/*
				 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
				 * Numero MEV : 006
				 * Autore    : Gioggi
				 * Data      : 21 apr 2020
				 * Branch    : MEV_006
				 */
				numeAnnoAtto = listaAtti.get(i).getNumeAnnoAtto();
				numeAtto = listaAtti.get(i).getNumeAtto();
				//***** FINE INTERVENTO MEV_006 *****//
			}
		}
		if ((!tipoAtto.equals("") && (tipoAtto.equals(Constants.TIPO_ATTO_PROPOSTA))) ||
			((!categoriaAtto.equals("")&& (categoriaAtto.equals(Constants.ISTANZA_MODIFICA_PATRIMONIALE)
									|| categoriaAtto.equals(Constants.ISTANZA_MODIFICA_PERSONALE))))) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!tipoAtto.equals("") && categoriaAtto.equals(Constants.CORREZIONE_ERRORE_MATERIALE)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!tipoAtto.equals("") && categoriaAtto.equals(Constants.ISTANZA_CAUZIONE)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!tipoAtto.equals("") && categoriaAtto.equals(Constants.ISTANZA_PERMESSI)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!tipoAtto.equals("") && categoriaAtto.equals(Constants.ISTANZA_TERZO_INTERVENIENTE)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!tipoAtto.equals("") && categoriaAtto.equals(Constants.ISTANZA_LIQUIDAZIONE_AMM)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!tipoAtto.equals("") && categoriaAtto.equals(Constants.ISTANZA_DIFFIDA_SOGGETTO)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!statoAtto.equals("") && statoAtto.equals(Constants.STATOATTO_ARCHIVIATO)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!statoAtto.equals("") && !statoAtto.equals("1")) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		if (!statoAtto.equals("") && !tipoAtto.equals("") && statoAtto.equals("1") && tipoAtto.equals(Constants.TIPO_ATTO_ACCERTAMENTO)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}

		String tipoUfficio = "" + profiloUtente.getIdTipoUfficio();
		if (tipoUfficio.equals(Constants.TIPO_UFFICIO_TRIBUNALE)
				&& (categoriaAtto.equals(Constants.RICORSO_IN_APPELLO) || categoriaAtto.equals(Constants.RICORSO_SUCCESSIVO) || categoriaAtto
						.equals(Constants.RICORSO_TARDIVO))) {
			ImpugnazioneForm impugnazione = attoService.getImpugnazioneByIdAttoUfficioOwner(codAtto, idUffOwn);
			if (impugnazione.getDescTipoProp() != null && !impugnazione.getDescTipoProp().equals("")) {
				super.setMessage(Constants.MESSAGE, "atto.cancella.ricorso.ko", null, false);
				return elencoAttiOrdineCronologico(attoForm, request, modelMap);
			}
		}

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 21 apr 2020
		 * Branch    : MEV_006
		 */
		if (!"".equals(statoAtto) && statoAtto.equals("1")
				&& (numeAnnoAtto != null && numeAnnoAtto.length() > 0)
				&& (numeAtto != null && numeAtto.length() > 0)) {
			super.setMessage(Constants.MESSAGE, "atto.cancella.ko.numatto.generato", null, false);
			return elencoAttiOrdineCronologico(attoForm, request, modelMap);
		}
		//***** FINE INTERVENTO MEV_006 *****//

		KeyMessageDto ritornoDb = attoService.cancellaAtto(idUffOwn, codAtto, descUtente, super.printMethodName());
		if (ritornoDb.isError()) {
			super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
			errors.reject(Constants.MESSAGE);
		} else {
			super.setMessage(Constants.SUCCESS_MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
			errors.reject(Constants.MESSAGE);
		}

		// aggiorno l'intestazione del procedimento perchè nel caso di fonte
		// passa da ISCRITTO a IN LAVORAZIONE
		super.updateProcedimentoIntoSession(idProcedimento);

		return elencoAttiOrdineCronologico(attoForm, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/decisioneRiesame.htm", method = RequestMethod.POST, params = { "DecisioneRiesame" })
	public String aggiornaEsitoMisuraOpposizione(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap,
			String tipo) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		long idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		if (tipo != null && tipo.equals("ConfermaInvia"))
			attoForm.setDataRegistrazione(new Date());

		attoValidation.validateSalvaDecisorioIGradoOpposizione(attoForm, result, request);
		if (result.hasErrors()) {
			AttoForm attoFormSession = recuperaAtto();
			attoForm.setIdProcEmiss(attoFormSession.getIdProcEmiss());
			attoForm.setDataRegistrazione(null);
			return decretoUtilService.dettaglioDecisorioIGradoRiesame(attoForm, modelMap, result, request);
		}
		attoForm.setCodAtto(attoInSessione.getCodAtto());
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
			attoForm.setDataRicezione(Calendar.getInstance().getTime());
		}
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(proced.getIdProcedimento());
		long idProcUdi = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		attoService.aggiornaDecisorioIGradoSoggettoDiffidato(idUffOwn, idProcUdi, 0, proced.getIdProcedimento(), attoForm, codUtente);
		super.updateProcedimentoIntoSession(proced.getIdProcedimento());
		return copertinaAtto(attoForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/decisioneRiesame.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaDecisorioOpposizione(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {
		if(attoForm.getAllegato().getFileData() !=null &&
			(attoForm.getAllegato().getFileData().getFileItem().getName() == null
				|| "".equals(attoForm.getAllegato().getFileData().getFileItem().getName()))) {
			result.rejectValue("allegato.fileData", "NotNull");
		}
		return aggiornaEsitoMisuraOpposizione(attoForm, result, request, modelMap, "ConfermaInvia");
	}

	@RequestMapping(value = "/procedimento/atto/decisioneRiesame.htm", method = RequestMethod.POST, params = { "DefinitivitaDecisorioIGradoRiesame" })
	public String inviaDefinitivaDecisorioIGradoOpposizione(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		long idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		attoInSessione.setDataDefinitivita(attoForm.getDataDefinitivita());
		attoValidation.validateInviaDefinitivitaDecisorioIGradoOpposizione(attoInSessione, result, request);
		if (result.hasErrors())
			return decretoUtilService.dettaglioDecisorioIGradoRiesame(attoInSessione, modelMap, result, request);

		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(proced.getIdProcedimento());
		long idProcUdi = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		attoService.inviaDefinitivitaDecisorioIGradoRiesame(attoInSessione, codUtente, idUffOwn, proced, idProcUdi, 0);
		super.updateProcedimentoIntoSession(proced.getIdProcedimento());
		return copertinaAtto(attoForm, result, request, modelMap);
	}

	// Il metodo è utilizzato per il decisorio di I e di II grado.
	@RequestMapping(value = "/procedimento/atto/decisorioIGrado.htm", method = RequestMethod.POST, params = { "Salva" })
	public String aggiornaDecisorio(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap, String tipo) {

		List<Message> customMessageListSuccess = new ArrayList<Message>();
		List<Message> customMessageListError = new ArrayList<Message>();

		AttoForm attoInSessione = recuperaAtto(); // (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		ProcedimentoForm proced = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return copertinaAtto(attoForm, result, request, modelMap);
		}

		beniDecretoUtilService.controlloSuiBeni(proced.getIdProcedimento(), attoForm.getCodAtto(), idUffOwn, request, result, false);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			// F.C. 05/04/2022 - Modifica del msg
			customMessageListError = (List<Message>)getSession().getAttribute(Constants.MESSAGELIST);
			super.addMessageIntoList(customMessageListError, Constants.MESSAGE, "error.beni.no.definiti.categoria", null);
			super.setMessages(customMessageListError, true);
			super.setMessaggiErrori(customMessageListError, true);
			// F.C: Fine mod 05/04
			return copertinaAtto(attoForm, result, request, modelMap);
		}

		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());
		if (logger.isDebugEnabled())
		 logger.debug("--- inizio aggiornaDecisorio -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		if (tipo != null && tipo.equals("ConfermaInvia")) {
		   if (proced != null && proced.getTipoFascicolo() != null
				   && !String.valueOf(Constants.TIPO_FASCICOLO_AGGRAVAMENTO).equalsIgnoreCase(proced.getTipoFascicolo().getId())) {
			   boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
			if (errore)
				return copertinaAtto(new AttoForm(), result, request, modelMap);
		   }
		}

		if (tipo == null || !tipo.equals("ConfermaInvia")) {
			if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)) {
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return copertinaAtto(attoForm, result, request, modelMap);
			}
		}

		if (tipo == null || !tipo.equals("ConfermaInvia")) {
			attoValidation.validateAttoDateSalva(attoForm, result, request);
			if (result.hasErrors()) {
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return copertinaAtto(attoForm, result, request, modelMap);
			}
		}

		if (tipo != null && tipo.equals("ConfermaInvia"))
			allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);

		String funzione = "I_GRADO";
		if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO)
			funzione = "II_GRADO";

		if (tipo != null && tipo.equals("ConfermaInvia")) {
			boolean err = false;
			attoValidation.validateAttoDate(attoForm, result, request);
			if (proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)
					|| proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) {
				//caricare la decisione su t_rel_atto_ist_gen
				TRelAttoIstGenId id = new TRelAttoIstGenId();
				id.setCodiKIdAtto(attoInSessione.getCodAtto());
				id.setCodiKIdProc(proced.getIdProcedimento());
				id.setCodiKIdUffOwner(idUffOwn);
				TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
				if ((!(idCatAtto == Long.valueOf(Constants.DECRETO_DECISORIO_PROVV_ISTANZA))
						&& (relAttoIstGen == null || relAttoIstGen.getTTpEsitoByCodiFkIdEsito1() == null))
						|| ((idCatAtto == Long.valueOf(Constants.DECRETO_DECISORIO_PROVV_ISTANZA))
								&& (relAttoIstGen == null || relAttoIstGen.getTTpEsitoByCodiFkIdEsito2() == null))) {
					if (proced.getTipoProcedimento().getId().equals("" + Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) {
						List<AttoForm> istanze = attoService.getricercaIstanza(idUffOwn, proced.getIdProcedimento(),
								new Long(Constants.TIPO_ATTO_ISTANZA_CAM), new Long(Constants.ISTANZA_CORREZIONE_ERRORI_MATERIALI));
						AttoForm istanza = new AttoForm();
						if (istanze != null && !istanze.isEmpty()) {
							istanza = istanze.get(0);
							SoggettoForm soggettoForm = new SoggettoForm();
							soggettoForm.setDescRichiesta(istanza.getNote());
							modelMap.addAttribute("soggettoForm",soggettoForm);
						}
						super.setMessage(Constants.MESSAGE, "errore.materiale.decisorioIGrado.soggSenzaDecisioni.error", null, false);
					} else {
					  super.setMessage(Constants.MESSAGE, "atto.decreto.decisorioIGrado.beniSenzaDecisioni.error", null, false);
					}
					err = true;
				}
			} else
				attoValidation.validateConfermaInviaDecisorio(funzione,proced.getIdProcedimento(), idUffOwn,
						attoForm, proced.getStatoProcedimento().getId(), result, request, modelMap);
			if (result.hasErrors() || err) {
				attoForm.setDataRegistrazione(null);
				if (proced.getTipoProcedimento().getId().equals("" + Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)
						|| proced.getTipoProcedimento().getId().equals("" + Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) {
					List<IntestatarioDto> listaIntestatari = procedimentoServiceCam.getIntestatari(
							idUffOwn, proced.getIdProcedimento());
					modelMap.addAttribute("listaIntestatari", listaIntestatari);
					modelMap.addAttribute("soggettoForm", new SoggettoForm());
				} else {
					List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(
							proced.getIdProcedimento(), Constants.RUOLO_DIRETTO, Constants.Flag.S);
					modelMap.addAttribute("soggettoForm", new SoggettoForm());
					modelMap.addAttribute("soggetti", soggetti);
				}
				procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);
				if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
					if (Constants.SENTENZA_DI_CASSAZIONE_DA_CDA.equals(attoInSessione.getTipoAtto().getId()))
						return "/procedimento/atto/copertinaSentenzaRicorsoIIGrado";
					else
						return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
				} else
					return "/procedimento/atto/copertinaDecretoDecisorioIGrado";
			}

			if (!proced.getTipoProcedimento().getId().equals("" + Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)
					&& !proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) {
				KeyMessageDto ritornoDb = attoService.controllaRegistrazioneDecisorio(proced.getIdProcedimento(),
						attoInSessione.getCodAtto(), idUffOwn, codUtente, funzione, super.printMethodName());
				if (ritornoDb.isError()) {
					super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
					result.reject(Constants.MESSAGE);
					attoForm.setDataRegistrazione(null);
					List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(
							proced.getIdProcedimento(),Constants.RUOLO_DIRETTO, Constants.Flag.S);
					modelMap.addAttribute("soggettoForm", new SoggettoForm());
					modelMap.addAttribute("soggetti", soggetti);
					procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);
					if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
						if (Constants.SENTENZA_DI_CASSAZIONE_DA_CDA.equals(attoInSessione.getTipoAtto().getId()))
							return "/procedimento/atto/copertinaSentenzaRicorsoIIGrado";
						else
							return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
					} else
						return "/procedimento/atto/copertinaDecretoDecisorioIGrado";
				}

				// *** INIZIO GESTIONE AMMINISTRATORI ***
				// P.Q. MEV 2020/48 Inizio
				/*
				boolean controlloAmministratori = true;
				Calendar c = Calendar.getInstance();
				c.set(2012, Calendar.MARCH, 15, 0, 0, 0);
				Date dataANBSC = c.getTime();
				Date maxProposta = attoService.getMaxDataEmissioneProposta(idUffOwn, proced.getIdProcedimento());
				if (maxProposta != null && (maxProposta.after(dataANBSC)
						|| maxProposta.equals(dataANBSC)))
					controlloAmministratori = true;
				*/
				
				boolean amministratoriPresenti = false;
	    		List<AmministratoreForm> amministratoriAssociati = beneService.getAmministratori(idUffOwn, proced.getIdProcedimento(), null, null, false);
	    		if(amministratoriAssociati != null && amministratoriAssociati.size() > 0) {
	    			amministratoriPresenti = true;
	    		}
	    		
	    		int grado = 0;
	    		if (proced.getTipoFascicolo().getId().equals("1") && funzione.equalsIgnoreCase("I_GRADO")) {
	    			grado = 1;
	    		} else {
	    			grado = 2;
	    		}
				
				// P.Q. MEV 2020/48 Fine

				// J.C. SITMP 294 Inizio
				 if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
						if (attoForm.getWarning() == null
								 && attoInSessione.getCategoriaAtto() != null && attoInSessione.getCategoriaAtto().getId() != null
								 && !attoInSessione.getCategoriaAtto().getId().equals("" + Constants.DECRETO_DECISORIO_I_GRADO_CAMERE)
								 && !attoInSessione.getCategoriaAtto().getId().equals("" + Constants.DECRETO_DECISORIO_II_GRADO_CAM )) {

						//fascicolo gestione
						long idFascioloGestione = 0;
						HashMap fascGestione = commonService.getFascicoloGestione(proced.getIdProcedimento(), idUffOwn, codUtente);
						if(fascGestione!=null) {
							Long idProcGest = (Long) fascGestione.get("idProcGest");
							Long idUffRic = (Long) fascGestione.get("idUffRic");
							if(idProcGest!=null && idUffRic!=null && idProcGest>0 && idUffRic>0) {
								idFascioloGestione = idProcGest.longValue();
							}
						}
						//fascicolo gestione
							
						boolean controlloAmm = attoService.controllaAmministratoriSenzaBeniDecisorioSecondGrado(new Integer(String.valueOf(idUffOwn)), proced.getIdProcedimento(), attoInSessione.getCodAtto(), idFascioloGestione);

						attoForm.setWarning("WARNING");
						attoForm.setDataRegistrazione(null);
						List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(proced.getIdProcedimento(),Constants.RUOLO_DIRETTO, Constants.Flag.S);
						modelMap.addAttribute("soggettoForm", new SoggettoForm());
						modelMap.addAttribute("soggetti", soggetti);
						procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);

						if (controlloAmm) {
							super.setMessage(Constants.MESSAGE,"amministratore.senza.beni.decisorio",null,false);
							modelMap.addAttribute("attoForm", attoForm);
							return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
						} else {
							if(amministratoriPresenti == true && amministratoreService.visualizzaMessaggioAmministratoriPresenti(idUffOwn, proced.getIdProcedimento(), attoInSessione.getCodAtto(), grado) == true ) {
								super.setMessage(Constants.MESSAGE,"amministratore.esistono.beni.associati",null,false);
								modelMap.addAttribute("attoForm", attoForm);
								return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
							}
						}
					} else
						attoForm.setWarning(null);
						modelMap.addAttribute("attoForm", attoForm);
					}
				// J.C. 294 Fine


			    // Il messaggio di presenza amministratori deve essere visualizzato se :
				// * Tutti gli amministratori presenti nel decisorio sono gli stessi che ho copiato dai decreti (l'utente quindi non e' intervernuto per modificarli)
				if ((Integer) request.getSession().getAttribute("idTipoUfficio") != Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
					if (attoForm.getWarning() == null
							 && attoInSessione.getCategoriaAtto() != null && attoInSessione.getCategoriaAtto().getId() != null
							 && !attoInSessione.getCategoriaAtto().getId().equals("" + Constants.DECRETO_DECISORIO_I_GRADO_CAMERE)
							 && !attoInSessione.getCategoriaAtto().getId().equals("" + Constants.DECRETO_DECISORIO_II_GRADO_CAM )) {
						boolean controlloAmm = attoService.controllaAmministratoriSenzaBeniDecisorio(new Integer(String.valueOf(idUffOwn)), proced.getIdProcedimento(), attoInSessione.getCodAtto());

					// P.Q. MEV 2020/48 Inizio
							attoForm.setWarning("WARNING");
							attoForm.setDataRegistrazione(null);
							List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(proced.getIdProcedimento(),Constants.RUOLO_DIRETTO, Constants.Flag.S);
							modelMap.addAttribute("soggettoForm", new SoggettoForm());
							modelMap.addAttribute("soggetti", soggetti);
							procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);
					// P.Q. MEV 2020/48 Fine					
					if(amministratoriPresenti == true && amministratoreService.visualizzaMessaggioAmministratoriPresenti(idUffOwn, proced.getIdProcedimento(), attoInSessione.getCodAtto(), grado) == true ) {
						super.setMessage(Constants.MESSAGE,"amministratore.esistono.beni.associati",null,false);
							return "/procedimento/atto/copertinaDecretoDecisorioIGrado";
					} else {
						if(controlloAmm) {
							super.setMessage(Constants.MESSAGE,"amministratore.senza.beni.decisorio",null,false);
							return "/procedimento/atto/copertinaDecretoDecisorioIGrado";
						}
						}
					} else
						attoForm.setWarning(null);
				}
			}
		}

		if (tipo != null && tipo.equals("ConfermaInvia"))
			allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);

		// GESTIONE GIUDICE DELEGATO
		// se NON C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO devo inserire il giudice delegato
		List<MagistratoForm> magistratiAssociatiAtto = null;
		List<MagistratoForm> magistratiAssociatiProc = null;
		boolean esitoFinApplica = false;
		if (proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE_E_PATRIMONIALE)
				|| proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PATRIMONIALE)) {
			int idUffOwnInt = recuperaIdUfficioUtente();
			// Controllo che ci sia almeno una decisione sui Beni con esito applica
			// in tal caso il giudice delegato è obbligatorio
			KeyMessageDto messaggioRitorno = attoService.controllaEsitoFinale(idUffOwnInt, proced.getIdProcedimento(), attoForm.getCodAtto(),
					funzione ==  "I_GRADO" ? Integer.parseInt(Constants.DECRETO_DECISORIO_I_GRADO): Integer.parseInt(Constants.DECRETO_DECISORIO_II_GRADO));
			if (!messaggioRitorno.getStatus().equals("KO") && messaggioRitorno.getStatus() != "KO")
				esitoFinApplica = true;
			magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUffOwnInt , attoForm.getCodAtto(), Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
			magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUffOwnInt, proced.getIdProcedimento().longValue(), Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
			// Nuova gestione GIUDICE DELEGATO
			if (esitoFinApplica
					&& (Integer) request.getSession().getAttribute("idTipoUfficio") != Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
				 if (magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0)) {
					modelMap.addAttribute("attoForm", attoForm);
					super.setMessage(Constants.MESSAGE,"magistrato.error.giudiceDelegato.registrazioneAtto",null,false);
					if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
						if (attoInSessione.getTipoAtto().getId().equals(Constants.SENTENZA_DI_CASSAZIONE_DA_CDA))
							return copertinaAtto(attoForm, result, request, modelMap);
						else
							return copertinaAtto(attoForm, result, request, modelMap);
					} else
						return copertinaAtto(attoForm, result, request, modelMap);
				 }
			}
		}

		if (tipo == null || !tipo.equals("ConfermaInvia")) {
			attoValidation.validateSalvaDecisorioPrevenzione(attoForm, result, request, modelMap);
			if (result.hasErrors()) {
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return copertinaAtto(attoForm, result, request, modelMap);
			}
		}

		if (tipo != null && tipo.equals("ConfermaInvia")) {
			attoValidation.validateSalvaDecisorioPrevenzione(attoForm, result, request, modelMap);
			if (result.hasErrors()) {
				attoForm.setDataRegistrazione(null);
				if (proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)
						|| proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) {
					List<IntestatarioDto> listaIntestatari = procedimentoServiceCam.getIntestatari(idUffOwn, proced.getIdProcedimento());
					modelMap.addAttribute("listaIntestatari", listaIntestatari);
				} else {
					List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(proced.getIdProcedimento(),
							Constants.RUOLO_DIRETTO, Constants.Flag.S);
					modelMap.addAttribute("soggettoForm", new SoggettoForm());
					modelMap.addAttribute("soggetti", soggetti);
				}

				procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);

				if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
					if (attoInSessione.getTipoAtto().getId().equals(Constants.SENTENZA_DI_CASSAZIONE_DA_CDA))
						return "/procedimento/atto/copertinaSentenzaRicorsoIIGrado";
					else
						return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
				} else
					return "/procedimento/atto/copertinaDecretoDecisorioIGrado";
			}
		}

		// INIZIO Spese processuali Marzo 2020 mev
		if (tipo != null && tipo.equals("ConfermaInvia")) {
			List<ComboForm> listaSpeseProcessuali = commonService.listaSpeseProcessuali();
			List<SoggettoForm> soggetti = attoService.getRicercaSoggettoAttoSpeseProc(proced.getIdProcedimento(),
					attoForm.getCodAtto(), idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S, listaSpeseProcessuali);
			if (soggetti != null && !soggetti.isEmpty()) {
				for (int i = 0; i < soggetti.size(); i++) {
					SoggettoForm sf = soggetti.get(i);
					if (sf.getSpeseProcessuali() != null && sf.getSpeseProcessuali().getId() != null) {
						int idSpesaP = Integer.parseInt(sf.getSpeseProcessuali().getId());
						TTpSpeseProcessuali ricercaSpesa = commonService.ricercaSpeseProcessuali(idSpesaP);
						if (ricercaSpesa != null && ricercaSpesa.getDataFineValidita() != null
								&& DateUtils.isBefore(ricercaSpesa.getDataFineValidita(), new Date())) {
							String params = DateUtils.formatDate(new Date(), DateUtils.FORMAT_STANDARD) + ";"
								+ DateUtils.formatDate(ricercaSpesa.getDataFineValidita(), DateUtils.FORMAT_STANDARD) + ";"
								+ Utility.getImporto(ricercaSpesa.getImportoSpese());
							super.setMessage(Constants.MESSAGE, "error.importi.non.validi", params, false);
							result.reject(Constants.MESSAGE);
							attoForm.setDataRegistrazione(null);
							List<SoggettoForm> s = procedimentoService.soggettiDirettiInteressatiDelProcedimento(
									proced.getIdProcedimento(),Constants.RUOLO_DIRETTO, Constants.Flag.S);
							modelMap.addAttribute("soggettoForm", new SoggettoForm());
							modelMap.addAttribute("soggetti", s);
							procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);
							if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
								if (Constants.SENTENZA_DI_CASSAZIONE_DA_CDA.equals(attoInSessione.getTipoAtto().getId()))
									return "/procedimento/atto/copertinaSentenzaRicorsoIIGrado";
								else
									return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
							} else
								return "/procedimento/atto/copertinaDecretoDecisorioIGrado";
						}
					}
				}
			}
		}
		// FINE Spese processuali Marzo 2020 mev

		attoForm.setCodAtto(attoInSessione.getCodAtto());
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
			attoForm.setDataRicezione(Calendar.getInstance().getTime());
		}
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(proced.getIdProcedimento());
		ComboForm procGenerale = commonService.getProcuraGenerale(idUffOwn);
		ComboForm procProponente = commonService.getProcuraProponente(proced.getIdProcedimento());
		long idProcUdi = 0l;
		long idProcGen = 0l;
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procGenerale != null)
			idProcGen = Long.parseLong(procGenerale.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());
		// se la procura in udienza è uguale dalla proponente, la proponente non
		// la prendo in considerazione (perciò la rimetto a 0)
		if (idProcUdi == idProcProp)
			idProcProp = 0l;
		if (tipo != null && tipo.equals("ConfermaInvia"))
			attoForm.setDataRegistrazione(new Date());
		else
			attoForm.setDataRegistrazione(null);

		// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		String giudiceDelegato = null;
		MagistratoForm magistratoForm = null;
		if (esitoFinApplica) {
			if (tipo != null && tipo.equals("ConfermaInvia"))
				// se C'è nella REL_MAG_ATTO e NON C'è nella REL_MAG_PROC vuol dire che sto registrando il primo sequestro:
				// quindi devo inserire nella REL_MAG_PROC e associare il Giudice delegato al procedimento.
				if ((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
					&& (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() > 0)) {
					magistratoForm = magistratiAssociatiAtto.get(0);
					giudiceDelegato = "PROC";
				}
			// se C'è nella REL_MAG_PROC e NON C'è nella REL_MAG_ATTO inserisco nella REL_MAG_ATTO)
			if ((magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))
					&& (magistratiAssociatiProc != null && magistratiAssociatiProc.size() > 0)) {
				magistratoForm = magistratiAssociatiProc.get(0);
				giudiceDelegato = "ATTO";
			}
		} else if(magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() > 0){
			magistratoForm = magistratiAssociatiAtto.get(0);
			giudiceDelegato = "CANC";
		}
		if (magistratoForm == null) {
			magistratoForm = new MagistratoForm();
			magistratoForm.setId(Long.valueOf(0));
		} else
			magistratoForm.setId(magistratoForm.getId());

		int tipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");
		long idAtto = attoService.aggiornaDecisorioPrevenzione(idUffOwn, idProcUdi, idProcGen, idProcProp, proced.getIdProcedimento(), attoForm,
				codUtente, tipoUfficio, magistratoForm.getId(), giudiceDelegato);
		super.updateProcedimentoIntoSession(proced.getIdProcedimento());
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		//INIZIO INVIO DATI MPS - 8.9 - 8.11 - 8.18 - 8.21
		if (tipo != null && tipo.equals("ConfermaInvia")) {
			if (proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE_E_PATRIMONIALE)
					|| proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE)
					|| (proced.getTipoFascicolo() != null
					&& proced.getTipoFascicolo().getId().equals(Constants.TIPO_FASCICOLO_AGGRAVAMENTO_S))
					|| proced.getTipoProcedimento().getId().equals(String.valueOf(Constants.TIPOPROC_MODIFICA_PERSONALE_CAM)) ) {
				if (proced.getTipoFascicolo().getId().equals(Constants.TIPO_FASCICOLO_MERITO_S)
						&& funzione.equalsIgnoreCase("I_GRADO")) {
					List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(Integer.valueOf(
							proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(), Constants.TIPOPROC_PERSONALE);
					for (int i = 0; i < uffDestinatariList.size(); i++) {
						DecretiDecisoriIGradoPersonaliRequest decretiIgrado =
								poliziaService.createDecretiDecisoriIGradoPersonaliRequest(
										proced.getIdProcedimento().longValue(), idAtto, idUffOwn, uffDestinatariList.get(i));
						poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_DECRETI_DECISORI_I_GRADO_PERS,
								proced.getIdProcedimento().longValue(), idAtto, decretiIgrado,
								Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUffOwn, uffDestinatariList.get(i), codUtente);
					}
				}
				if (proced.getTipoFascicolo().getId().equals(Constants.TIPO_FASCICOLO_MERITO_S)
						&& funzione.equalsIgnoreCase("II_GRADO")) {
					List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(
							Integer.valueOf(proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(),
							Constants.TIPOPROC_PERSONALE);
					for (int i = 0; i < uffDestinatariList.size(); i++) {
						DecretiDecisoriIIGradoPersonaliRequest decretiIIgrado = poliziaService.
								createDecretiDecisoriIIGradoPersonaliRequest(proced.getIdProcedimento().longValue(),
										idAtto, idUffOwn, uffDestinatariList.get(i));
						poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_DECRETI_DECISORI_II_GRADO_PERS,
								proced.getIdProcedimento().longValue(), idAtto, decretiIIgrado,
								Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUffOwn, uffDestinatariList.get(i), codUtente);
					}
				}
				if (proced.getTipoFascicolo().getId().equals(Constants.TIPO_FASCICOLO_AGGRAVAMENTO_S)) {
					List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(
							Integer.valueOf(proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(),
							Constants.TIPOPROC_PERSONALE);
					for(int i=0; i<uffDestinatariList.size(); i++) {
						DecisorioAggravamentoMisuraPersonaleRequest decisorioAggravam =
								poliziaService.createDecisorioAggravamentoMisuraPersonaleRequest(
										proced.getIdProcedimento().longValue(), idAtto, idUffOwn, uffDestinatariList.get(i));
						poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_DECISORIO_AGGRAVAMENTO_MISURE_PERSONALI,
								proced.getIdProcedimento().longValue(), idAtto, decisorioAggravam,
								Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUffOwn, uffDestinatariList.get(i), codUtente);
					}
				}
				if (proced.getTipoProcedimento() != null && proced.getTipoProcedimento().getId() != null
						&& proced.getTipoProcedimento().getId().equals(String.valueOf(Constants.TIPOPROC_MODIFICA_PERSONALE_CAM))) {
					List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(
							Integer.valueOf(proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(),
							Constants.TIPOPROC_PERSONALE);
					for (int i = 0; i < uffDestinatariList.size(); i++) {
						DecisorioRevocaModificaMisuraPersonaleRequest decisorioRevMod =
								poliziaService.createDecisorioRevocaModificaMisuraPersonaleRequest(
										proced.getIdProcedimento().longValue(), idAtto, idUffOwn, uffDestinatariList.get(i));
						poliziaService.insertPoliziaMsgDatabase(Constants.POLIZIA_DECISORIO_MODIFICA_REVOCA_PATRIMONIALE_PERSONALE,
								proced.getIdProcedimento().longValue(), idAtto, decisorioRevMod,
								Constants.POLIZIA_STATO_SERVIZIO_INSERITO, idUffOwn, uffDestinatariList.get(i), codUtente);
					}
				}
			}
		}
		//FINE INVIO DATI MPS - 8.9 - 8.11 - 8.12 - 8.18 - 8.21

		// P.Q. MEV 2020/48 Inizio
		// Aggiornamento degli amministratori :
		// Premessa : con la MEV 2020/48, all'atto della creazione del Decisorio di I grado, tutti gli amministratori inseriti negli altri decreti di sequestro vengono copiati nel Decisorio di I grado
		//Nel Decisorio di I gli amministratori possono essere rimossi , rimossi e aggiunti di nuovo, oppure inseriti ex novo
		// 1) Cancellazione di un amministratore copiato da un decreto di sequestro :
		//		-> al "Conferma e Invia" devo aggiornare le date di fine incarico (con la data deposito) di tutti i record con la coppia amministratore/bene per quel determinato procedimento
		//      -> Se tutti i beni amministrati hanno data fine incario devo mettere la data di fine incarico su T_REL_PROC_ATTO_AMM
		// 2) Cancellazione di un amministratore copiato da un decreto di sequestro e re-inserimento della stessa coppia amministratore/bene
		//		-> al "Conferma e Invia" devo aggiornare la data di inizio incarico del record con la data di inizio incarico della coppia amministratore/bene del decisorio
		// 3) Inserimento di un nuovo record amministratore/bene
		//		-> al "Conferma e Invia" devo aggiornare la data di inizio incarico con la data deposito

		//
		// In caso di decisione diversa da 118, 119, 123 devo valorizzare le date di fine incarico con la data deposito
		//
		// Se tutti i beni amministrati da un amministratore hanno la data di fine incarico valorizzata , devo mettere la data di fine incarico su T_REL_PROC_ATTO_AMM
		//
		if (tipo != null && tipo.equals("ConfermaInvia")) {

			if(proced.getTipoFascicolo().getId().equals("1") && funzione.equalsIgnoreCase("I_GRADO")) {
				amministratoreService.sistemaDate(idUffOwn, proced.getIdProcedimento().longValue(), idAtto, attoForm.getDataDeposito(), Constants.PRIMO_GRADO);
			} else {
				//amministratoreService.sistemaDate(idUffOwn, proced.getIdProcedimento().longValue(), idAtto, attoForm.getDataDeposito(), Constants.SECONDO_GRADO);	
				// GC 11/03/2021 - Mev 2020/048: Cambiato il metodo chiamato
				amministratoreService.sistemaDateIIGrado(idUffOwn, proced.getIdProcedimento().longValue(), idAtto, attoForm.getDataDeposito(), Constants.SECONDO_GRADO);	
			}
		}
		// P.Q. MEV 2020/48 Fine

		if (tipo != null && tipo.equals("ConfermaInvia")) {
			if (proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE_E_PATRIMONIALE) ||
					proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PATRIMONIALE))
			{
				if(proced.getTipoFascicolo().getId().equals("1") && funzione.equalsIgnoreCase("I_GRADO"))
				{
					/* Mev 2020/22
					if(anbscMsgService.invioConfiscaIGrado(proced.getIdProcedimento().longValue(), idAtto, idUffOwn, codUtente) == false)
						super.setMessage(Constants.MESSAGE, "anbsc.invio.error", null, false);
					*/
					EsitoFromResponse esitoFromResponse = anbscMsgService.invioConfiscaIGrado(proced.getIdProcedimento().longValue(), idAtto, idUffOwn, codUtente);

					switch (esitoFromResponse.getEsito()) {
					case 'C':
						super.addMessageIntoList(customMessageListSuccess, Constants.SUCCESS_MESSAGE, esitoFromResponse.getMessaggio(), null);
						break;

					default:
						super.addMessageIntoList(customMessageListError, Constants.MESSAGE, esitoFromResponse.getMessaggio(), null);
						break;

					}
					// Mev 2020/22 Fine

					List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(Integer.valueOf(proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(), Constants.TIPOPROC_PATRIMONIALE);
					for(int i=0; i<uffDestinatariList.size(); i++)
					{
						if(poliziaMsgService.invioDecretoDecisorioIGradoPatrimonialiPolizia(proced.getIdProcedimento().longValue(), idAtto, idUffOwn, codUtente, uffDestinatariList.get(i).toString()) == false)
							// Mev 2020/22
							//super.setMessage(Constants.MESSAGE, "polizia.invio.error", null, false);
							super.addMessageIntoList(customMessageListError, Constants.MESSAGE, "polizia.invio.error", null);
					}
				}

				if(proced.getTipoFascicolo().getId().equals("1") && funzione.equalsIgnoreCase("II_GRADO"))
				{
					/* Mev 2020/22
					if(anbscMsgService.invioConfiscaIIGrado(proced.getIdProcedimento().longValue(), idAtto, idUffOwn, codUtente) == false)
						super.setMessage(Constants.MESSAGE, "anbsc.invio.error", null, false);
					*/
					EsitoFromResponse esitoFromResponse = anbscMsgService.invioConfiscaIIGrado(proced.getIdProcedimento().longValue(), idAtto, idUffOwn, codUtente);

					switch (esitoFromResponse.getEsito()) {
					case 'C':
						super.addMessageIntoList(customMessageListSuccess, Constants.SUCCESS_MESSAGE, esitoFromResponse.getMessaggio(), null);
						break;

					default:
						super.addMessageIntoList(customMessageListError, Constants.MESSAGE, esitoFromResponse.getMessaggio(), null);
						break;

					}
					// Mev 2020/22 Fine


					List<Integer> uffDestinatariList = poliziaService.getUffDestinatario(Integer.valueOf(proced.getProcedente().getId()), idUffOwn, proced.getIdProcedimento(), Constants.TIPOPROC_PATRIMONIALE);
					for(int i=0; i<uffDestinatariList.size(); i++)
					{
						if(poliziaMsgService.invioDecretoDecisorioIIGradoPatrimonialiPolizia(proced.getIdProcedimento().longValue(), idAtto, idUffOwn, codUtente, uffDestinatariList.get(i).toString()) == false)
						// Mev 2020/22
						//super.setMessage(Constants.MESSAGE, "polizia.invio.error", null, false);
						super.addMessageIntoList(customMessageListError, Constants.MESSAGE, "polizia.invio.error", null);
					}
				}
			}
			// super.addMessageIntoList(customMessageList,
			// Constants.SUCCESS_MESSAGE, "success.invioAtto", "");
			//super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
			super.addMessageIntoList(customMessageListSuccess, Constants.SUCCESS_MESSAGE, "success.invioAtto", null);
		} else
			//super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);
			super.addMessageIntoList(customMessageListSuccess, Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA");
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
		 logger.debug("--- fine aggiornaDecisorio -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		//super.setMessages(customMessageListError, true);
		super.setMessaggiErrori(customMessageListError, true);
		super.setMessagesSuccess(customMessageListSuccess, true);

		return copertinaAtto(attoForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/decisorioIGrado.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaDecisorioIGrado(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = recuperaProcedimento().getIdProcedimento();
		List<Message> customMessageListError = new ArrayList<Message>();

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return copertinaAtto(attoForm, result, request, modelMap);
		}

		beniDecretoUtilService.controlloSuiBeni(idProcedimento, attoForm.getCodAtto(), (int) idUfficio, request, result, true);

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			// F.C. 05/04/2022 - Modifica del msg
			customMessageListError = (List<Message>)getSession().getAttribute(Constants.MESSAGELIST);
			super.addMessageIntoList(customMessageListError, Constants.MESSAGE, "error.beni.no.definiti.categoria", null);
			super.setMessages(customMessageListError, true);
			super.setMessaggiErrori(customMessageListError, true);
			// F.C: Fine mod 05/04
			return copertinaAtto(attoForm, result, request, modelMap);
		}

		String idTipoProc=((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getTipoProcedimento().getId();
		if (idTipoProc != null && !idTipoProc.equals("" + Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM)) {
			attoValidation.validateSoggettiIntervenientiNonAssociati(idProcedimento, (int) idUfficio, result, request, modelMap);
			if (result.hasErrors()) {
				super.setMessage(Constants.MESSAGE, "atto.decreto.decisorioIGrado.intervenientiNonAssociati", null, false);
			}
		}
		return aggiornaDecisorio(attoForm, result, request, modelMap, "ConfermaInvia");
	}

	@RequestMapping(value = "/procedimento/atto/accertamento/aggiorna.htm", method = RequestMethod.POST, params = { "ConfermaModifica" })
	public String aggiornaAccertamento(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap)
			throws IOException, SQLException {

		ProcedimentoForm procedimento = recuperaProcedimento();

		attoValidation.validateAggiornaAccertamento(attoForm, result);
		if (result.hasErrors()) {
			attoForm.setDataInformativa(attoForm.getDataEmissione());
			List<SoggettoForm> soggettiDirettiInteressati = procedimentoService.soggettiDirettiInteressatiDelProcedimento(
					procedimento.getIdProcedimento(), Constants.RUOLO_DIRETTO, Constants.Flag.S);
			modelMap.addAttribute("soggettiInteressati", soggettiDirettiInteressati);
			return "/procedimento/atto/copertinaAccertamentoQuestura";
		}

		long idStatoProc = 0l;
		if (procedimento.getStatoProcedimento() != null && procedimento.getStatoProcedimento().getId() != null)
			idStatoProc = Long.parseLong(procedimento.getStatoProcedimento().getId());
		long idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = procedimento.getIdProcedimento();
		this.inizializzaDocumento(attoForm, request);
		this.attoService.aggiornaAccertamento(idUfficio, idProcedimento, attoForm, codiceUtente, idStatoProc);
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);
		super.updateProcedimentoIntoSession(procedimento.getIdProcedimento());
		return copertinaAtto(attoForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/anticipazioneRinvioUdienza.htm", method = RequestMethod.POST, params = { "Salva" })
	public String aggiornaDecretoAnticipazioneRinvioUdienza(@Valid UdienzaForm udienzaForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		String viewAnt = "/procedimento/atto/copertinaDecretoAnticipazioneUdienza";
		String viewRinv = "/procedimento/atto/copertinaDecretoRinvioUdienza";
		String viewReturn = "";

		attoValidation.validateDecretoAntRinvUdienzaCampiObbl(udienzaForm, result, request, modelMap);
		if (result.hasErrors()) {
			udienzaForm.setDataRegistrazione(null);
			procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
			if (attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA)
					|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA_II_GRADO))
				return viewAnt;
			else
				return viewRinv;
		}
		if (attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA)
				|| attoInSessione.getCategoriaAtto().getId().equals(Constants.DECRETO_ANTICIPAZIONE_UDIENZA_II_GRADO)) {
			attoValidation.validateDecretoAnticipazioneUdienza(udienzaForm, result, request, modelMap);
			viewReturn = viewAnt;
		} else {
			attoValidation.validateDecretoRinvioUdienza(udienzaForm, result, request, modelMap);
			viewReturn = viewRinv;
		}
		if (result.hasErrors()) {
			udienzaForm.setDataRegistrazione(null);
			procuraUdienzaUtilService.caricaProcuraInUdienzaInSessione(modelMap);
			super.setMessage(Constants.MESSAGE, "errors.campi.controllo", null, false);
			return viewReturn;
		}
		udienzaForm.setCodAtto(attoInSessione.getCodAtto());
		udienzaForm.setTipoAtto(attoInSessione.getTipoAtto());
		udienzaForm.setCategoriaAtto(attoInSessione.getCategoriaAtto());
		if (udienzaForm.getAllegato().getFileData() != null && udienzaForm.getAllegato().getFileData().getSize() > 0) {
			udienzaForm.getAllegato().setFileName(udienzaForm.getAllegato().getFileData().getOriginalFilename());
			udienzaForm.getAllegato().setContentType(udienzaForm.getAllegato().getFileData().getContentType());
			udienzaForm.setDataRicezione(Calendar.getInstance().getTime());
		}
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(proced.getIdProcedimento());

		long idProcUdi = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());

		attoService.aggiornaDecretoAnticipazioneRinvioUdienza(udienzaForm, udienzaForm.getUdienzaPrecedente().getCodUdienza(), idUffOwn, idProcUdi,
				proced.getIdProcedimento(), codUtente);
		super.updateProcedimentoIntoSession(proced.getIdProcedimento());
		super.setMessage(Constants.SUCCESS_MESSAGE, "success", null, true);
		return copertinaAtto(udienzaForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/anticipazioneRinvioUdienza.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaDecretoAnticipazioneRinvioUdienza(@Valid UdienzaForm udienzaForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		udienzaForm.setDataRegistrazione(new Date());
		return aggiornaDecretoAnticipazioneRinvioUdienza(udienzaForm, result, request, modelMap);
	}

	public String nuovoDecretoConvalidaSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {
		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String categoriaAttoSeq = null;

		if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_CONVALIDA_SEQUESTRO_ANTICIPATO))
			categoriaAttoSeq = Constants.DECRETO_SEQUESTRO_ANTICIPATO;
		else if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_CONVALIDA_SEQUESTRO_URGENTE))
			categoriaAttoSeq = Constants.DECRETO_SEQUESTRO_URGENTE;
		List<AttoForm> listaDecretiSequestri;
		if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO)
			listaDecretiSequestri = attoService.getAttiByProcedimento(procedimento.getIdProcedimento(),
					Long.parseLong(Constants.TIPO_ATTO_DECRETO_II_GRADO), categoriaAttoSeq);
		else
			listaDecretiSequestri = attoService.getAttiByProcedimento(procedimento.getIdProcedimento(), Long.parseLong(Constants.TIPO_ATTO_DECRETO),
					categoriaAttoSeq);

		List<ComboForm> listaSequestriCombo = new ArrayList<ComboForm>();
		Iterator<AttoForm> iterSeq = listaDecretiSequestri.iterator();
		while (iterSeq.hasNext()) {
			String descrizione = "";
			ComboForm combo = new ComboForm();
			AttoForm sequestro = iterSeq.next();
			String numAttoView = "";

			if (Utility.isTDecretoRecord(sequestro.getTipoAtto().getId())) {

				Criterion c1 = Restrictions.eq("id.codiKIdDecreto", sequestro.getCodAtto());
				Criterion c2 = Restrictions.eq("id.codiKIdUffOwner", idUffOwn);
				Object obj = attoService.getAttoByPrimaryKey(TDecreto.class, c1, c2);
				if (obj != null) {
					TDecreto ist = (TDecreto) obj;
					numAttoView = AttoServiceImpl.builNumeroAttoView(ist);
					// sequestro.setNumeroAtto(numAttoView);
				}
			}

			if (sequestro.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)
					&& !attoService.esisteDecretoConvalidaSequesto(sequestro.getCodAtto(), idUffOwn)) {
				descrizione = numAttoView + " depositato il " + Utility.convertDateToString(sequestro.getDataDeposito());
				combo.setId("" + sequestro.getCodAtto());
				combo.setDescrizione(descrizione);
				listaSequestriCombo.add(combo);
			}
		}

		if (!Utility.isDefinito(listaSequestriCombo)) {
			if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_CONVALIDA_SEQUESTRO_ANTICIPATO))
				super.setMessage(Constants.MESSAGE, "atto.decreto.convalidaSequestro.noDecretiSequestro", "anticipato", false);
			else if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_CONVALIDA_SEQUESTRO_URGENTE))
				super.setMessage(Constants.MESSAGE, "atto.decreto.convalidaSequestro.noDecretiSequestro", "urgente", false);
			return "/procedimento/atto/nuovoAtto";
		}

		modelMap.addAttribute("attoForm", attoForm);
		modelMap.addAttribute("listaDecretiSequestri", listaSequestriCombo);
		return "/procedimento/atto/copertinaDecretoConvalidaSequestro";
	}

	public String nuovoDecretoRevocaSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {
		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String categoriaAttoSeq = null;

		List<AttoForm> listaDecretiSequestri;
		if ((Integer) request.getSession().getAttribute("idTipoUfficio") == Constants.TIPO_UFFICIO_CORTE_D_APPELLO) {
			categoriaAttoSeq = Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO;
			listaDecretiSequestri = attoService.getAttiByProcedimento(procedimento.getIdProcedimento(),
					Long.parseLong(Constants.TIPO_ATTO_DECRETO_II_GRADO), categoriaAttoSeq);
		} else {
			categoriaAttoSeq = Constants.DECRETO_SEQUESTRO_ORDINARIO;
			listaDecretiSequestri = attoService.getAttiByProcedimento(procedimento.getIdProcedimento(), Long.parseLong(Constants.TIPO_ATTO_DECRETO),
					categoriaAttoSeq);
		}
		List<ComboForm> listaSequestriCombo = new ArrayList<ComboForm>();
		Iterator<AttoForm> iterSeq = listaDecretiSequestri.iterator();
		while (iterSeq.hasNext()) {
			String descrizione = "";
			ComboForm combo = new ComboForm();
			AttoForm sequestro = iterSeq.next();
			String numAttoView = "";

			if (Utility.isTDecretoRecord(sequestro.getTipoAtto().getId())) {

				Criterion c1 = Restrictions.eq("id.codiKIdDecreto", sequestro.getCodAtto());
				Criterion c2 = Restrictions.eq("id.codiKIdUffOwner", idUffOwn);
				Object obj = attoService.getAttoByPrimaryKey(TDecreto.class, c1, c2);
				if (obj != null) {
					TDecreto ist = (TDecreto) obj;
					numAttoView = AttoServiceImpl.builNumeroAttoView(ist);
					// sequestro.setNumeroAtto(numAttoView);
				}
			}

			if (sequestro.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)){ // alf
				//	&& !attoService.esisteDecretoConvalidaSequesto(sequestro.getCodAtto(), idUffOwn)) {
				descrizione = numAttoView + " depositato il " + Utility.convertDateToString(sequestro.getDataDeposito());
				combo.setId("" + sequestro.getCodAtto());
				combo.setDescrizione(descrizione);
				listaSequestriCombo.add(combo);
			}
		}
		// GINESTI modifica 4 segna plo
		if (!Utility.isDefinito(listaSequestriCombo)) {
		//	if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_REVOCA_SEQUESTRO)
		//			|| attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_REVOCA_SEQUESTRO_II_GRADO))
		//		super.setMessage(Constants.MESSAGE, "atto.decreto.revocaSequestro.noDecretiSequestro", "ordinario", false);
			return "/procedimento/atto/nuovoAtto";
		}

		modelMap.addAttribute("attoForm", attoForm);
		modelMap.addAttribute("listaDecretiSequestri", listaSequestriCombo);
		return "/procedimento/atto/copertinaDecretoRevocaSequestro";
	}

	@RequestMapping(value = "/procedimento/atto/decretoConvalidaSequestro.htm", method = RequestMethod.POST, params = { "SelezionaSequestro" })
	public String inserisciDecretoConvalidaSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return nuovoDecretoConvalidaSequestro(attoForm, result, request, modelMap);
		}

		long idAtto = attoService.inserisciAttoDecretoConvalidaSequestro(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());
		// attoForm.setCodAtto(idAtto);
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(
				procedimento.getIdProcedimento(), idAtto, idUffOwn);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);

		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoConvalidaSequestro";
	}

