	@RequestMapping(value = "/procedimento/atto/decretoRigettoSequestro.htm", method = RequestMethod.POST)
	public ModelAndView inserisciDecretoRigettoTotaleSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = recuperaProcedimento().getIdProcedimento();
		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;

//		KeyMessageDto ritornoDb = attoService.insDecretoRigettoTotaleSequestro(idUffOwn, idProcedimento, codiceUtente, attoForm,
//				Constants.STATOATTO_IN_LAVORAZIONE, super.printMethodName());
		KeyMessageDto ritornoDb = attoService.esisteDecretoSequestroProcedimento(idUffOwn, idProcedimento, codiceUtente, idStatoAtto, super.printMethodName());
		if (ritornoDb.isError()) {
			super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
			result.reject(Constants.MESSAGE);
			return new ModelAndView("/procedimento/atto/nuovoAtto", "atto", attoForm);
		} else {
//			super.setMessage(Constants.SUCCESS_MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
//			result.reject(Constants.MESSAGE);
		}
//		long idAtto = ritornoDb.getId();
		long idAtto = attoService.salvaDecretoRigettoTotaleSequestro(idUffOwn, idProcedimento, codiceUtente, attoForm, idStatoAtto);
		beniDecretoUtilService.beniDecretoRigettoSequestro(idAtto, modelMap);

		utilityService.gestioneMagistratiAssociati(idUffOwn, idAtto, idProcedimento, codiceUtente);

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, idProcedimento, request, attoForm);
		String url = copertinaAtto(attoForm, result, request, modelMap);
		ModelAndView mnv = new ModelAndView(url, "attoForm", attoForm);
		return mnv;
	}

