	@RequestMapping(value = "/procedimento/atto/decretoRevocaSequestro.htm", method = RequestMethod.POST, params = { "SelezionaSequestro" })
	public String inserisciDecretoRevocaSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return nuovoDecretoRevocaSequestro(attoForm, result, request, modelMap);
		}

		long idAtto = attoService.inserisciAttoDecretoRevocaSequestro(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());
		// attoForm.setCodAtto(idAtto);
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimentoPerRevoca(
				procedimento.getIdProcedimento(), idAtto, idUffOwn, codUtente, super.printMethodName());
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);
		List<BeneForm> beni = beneService.listaBeniPerProcedimentoNoAttoPerRevoca(idAtto, procedimento.getIdProcedimento(), codUtente, idUffOwn,
				super.printMethodName(), 0, 0, 0, 0, 0);
		modelMap.addAttribute("beni", beni);

		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoRevocaSequestro";
	}

	@RequestMapping(value = { "/procedimento/atto/decretoConvalidaSequestro.htm" }, method = RequestMethod.POST, params = { "Convalida" })
	public String convalidaSequestro(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap) {

		List<BeneForm> beniSelezionati = beneSoggettoForm.estrapolaListaBeniConIdSoggettiCheckati();
		attoValidation.validateSceltaListaStringBeneSoggettoFormData(null, beneSoggettoForm, beniSelezionati, null, result, request);
		if (result.hasErrors())
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		String descUtente = recuperaIdCodiceUtente();
		String nomeMetodo = super.printMethodName();
		Integer idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		AttoForm attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);

		attoService.convalidaNonConvalidaSequestro(beniSelezionati, idProcedimento, idUffOwn.intValue(), attoForm.getCodAtto(),
				Constants.TIPO_MISURA_SEQUESTRO, descUtente, Constants.TipiOperazioneConvalidaNonConvalida.CONVALIDA, nomeMetodo);
		return copertinaAtto(new AttoForm(), result, request, modelMap);
	}

