	@RequestMapping(value = "/procedimento/atto/nuovoCorrezioneErroreMateriale.htm", method = RequestMethod.POST)
	public ModelAndView nuovoAttoCorrezioneErroreMateriale(AttoForm attoForm, BindingResult result, ModelMap modelMap) {
		int idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = recuperaIdProcedimento();
		
		long idTipoAtto=Long.valueOf(Constants.TipoAtto.TIPO_ATTO_GENERICO);
		String catAtto = Constants.CategoriaAtto.CAT_CORREZIONE_ERRORE_MATERIALE_S;
		
		//F.C. SITMP-393 ticket 202209230111
		//può esistere un solo atto correzione in lavorazione (impedire la creazione quando c'è un atto di correzione in lavorazione )
		
		// verifica che esista un UNICO atto decisorio di II Grado
		List<AttoForm> attoCorrezioneErroreM = attoService.getAttiByProcedimento(idProcedimento, idTipoAtto,
				catAtto);
		if(attoCorrezioneErroreM.size()> 0){
			for (AttoForm atto : attoCorrezioneErroreM) {
				
				if (atto.getStatoAtto().getId().equals(String.valueOf(Constants.STATOATTO_IN_LAVORAZIONE))) {
					super.setMessage(Constants.MESSAGE, "error.atto.unico", "Correzione errore materiale", true);
					attoForm.getTipoAtto().setId(Constants.NO_ITEM_SELECTED);					
					//return new ModelAndView("/procedimento/atto/nuovoAtto");
					return new ModelAndView("/procedimento/atto/nuovoAtto", "atto", attoForm);
				}
			}
		}
		//F.C. fine modifica  SITMP-393
		long idAttoCorrezione = attoService.inserisciAttoGenerico(idUfficio, codiceUtente, idProcedimento, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, super.printMethodName());

		if (logger.isDebugEnabled()) {
			logger.debug("Id Ufficio : " + idUfficio);
			logger.debug("codiceUtente : " + codiceUtente);
			logger.debug("Id Ufficio : " + idUfficio);
			logger.debug("Id Procedimento : " + idProcedimento);
			logger.debug("Inserimento di Atto Generico di Correzione Errore Materiale identificativo : " + idAttoCorrezione);
		}

		AttoForm nuovoAtto = attoService.dettaglioAtto(idUfficio, idAttoCorrezione, idProcedimento, codiceUtente);

		if (logger.isDebugEnabled()) {
			logger.debug("Carimento dettaglio Atto con identificativo : " + idAttoCorrezione + ", AttoForm --> " + nuovoAtto);
			logger.debug("Imposto l'atto appena creato in sessione ...");
			logger.debug("Redirect alla vista della scelta dei beni del procedimento ...");
		}

		// Solo per test
		// attoForm.setNumeroAtto("9999999999999999999");
		// attoForm.getTipoAtto().setDescrizione("Atto Generico");
		// attoForm.getCategoriaAtto().setDescrizione("Correzione Errore Materiale");

		impostaAtto(nuovoAtto);



		ProcedimentoForm procedimentoForm = recuperaProcedimento();
		procedimentoForm.setCallbackUrl("redirect:/procedimento/atti/elencoAttiOrdineCronologico.htm");
		return new ModelAndView(new RedirectView("/procedimento/bene/beniCollegati.htm", true, true, false));
		// return new
		// ModelAndView("redirect:/procedimento/bene/beniCollegati.htm");
	}

	@RequestMapping(value = "/procedimento/atto/sentenzaRevocazioneConfisca.htm", method = RequestMethod.POST, params = { "SelezionaDecreto" })
	public String inserisciSentenzaRevocazioneConfisca(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		List<AttoForm> attoSentenza = attoService.getAttiByProcedimento(procedimento.getIdProcedimento(), 18l,
				Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA);
		if (attoSentenza.size() > 0) {
			super.setMessage(Constants.MESSAGE, "error.atto.unico", "Decreto su revocazione della confisca", true);
			attoForm.getTipoAtto().setId(Constants.NO_ITEM_SELECTED);
			return "procedimento/atto/nuovoAtto";
		}

		int idCatAtto = Integer.valueOf(Constants.REVOCAZIONE_DELLA_CONFISCA);
		long idAtto = attoService.inserisciAttoSentenzaRevocazioneConfisca(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idCatAtto, super.printMethodName());

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);

		return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/sentenzaRevocazioneConfisca.htm", method = RequestMethod.POST, params = { "Salva" })
	public String aggiornaSentenzaRevocazioneConfisca(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap,
			String tipo) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();

		attoValidation.validateSalvaSentenzaRevocazioneConfisca(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
		} else {
			// INIZIA GESTIONE DOCUMENTALE
			allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
			// FINE GESTIONE DOCUMENTALE
			if (tipo != null && tipo.equals("ConfermaInvia"))
				attoValidation.validateAttoDate(attoForm, result, request);
			if (result.hasErrors()) {
				super.setMessage(Constants.MESSAGE, "errors.campi.controllo", null, false);
				result.reject(Constants.MESSAGE);
				attoForm.setDataRegistrazione(null);
				return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
			} else {
				// INIZIO Spese processuali Marzo 2020 mev
				if (tipo != null && tipo.equals("ConfermaInvia")) {
					List<ComboForm> listaSpeseProcessuali = commonService.listaSpeseProcessuali();
					List<SoggettoForm> soggetti = attoService.getRicercaSoggettoAttoSpeseProc(proced.getIdProcedimento(),
							attoForm.getCodAtto(), idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S, listaSpeseProcessuali);
					if (soggetti != null && !soggetti.isEmpty()) {
						for (int i = 0; i < soggetti.size(); i++) {
							SoggettoForm sf = soggetti.get(i);
							if (sf.getSpeseProcessuali() != null && sf.getSpeseProcessuali().getId() != null) {
								int idSpesaP = Integer.parseInt(sf.getSpeseProcessuali().getId());
								TTpSpeseProcessuali ricercaSpesa = commonService.ricercaSpeseProcessuali(idSpesaP);
								if (ricercaSpesa != null && ricercaSpesa.getDataFineValidita() != null
										&& DateUtils.isBefore(ricercaSpesa.getDataFineValidita(), new Date())) {
									String params = DateUtils.formatDate(new Date(), DateUtils.FORMAT_STANDARD) + ";"
										+ DateUtils.formatDate(ricercaSpesa.getDataFineValidita(), DateUtils.FORMAT_STANDARD) + ";"
										+ Utility.getImporto(ricercaSpesa.getImportoSpese());
									super.setMessage(Constants.MESSAGE, "error.importi.non.validi", params, false);
									result.reject(Constants.MESSAGE);
									attoForm.setDataRegistrazione(null);
									return apriDecisiorioBeni(new BeneSoggettoForm(), result, request, modelMap);
								}
							}
						}
					}
				}
				// FINE Spese processuali Marzo 2020 mev
				attoForm.setCodAtto(attoInSessione.getCodAtto());
				if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
					attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
					attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
					attoForm.setDataRicezione(Calendar.getInstance().getTime());
				}

				// List<ComboForm> ufficiCompetenza = caricaUfficiSentenzaRevocazioneConfisca();
				long idUff1 = 0l;
				long idUff2 = 0l;
				long idUff3 = 0l;
				/*
				for (int i = 0; ufficiCompetenza != null && i < ufficiCompetenza.size(); i++) {
					ComboForm uff = ufficiCompetenza.get(i);
					if (i == 0)
						idUff1 = Long.parseLong(uff.getId());
					if (i == 1)
						idUff2 = Long.parseLong(uff.getId());
					if (i == 2)
						idUff3 = Long.parseLong(uff.getId());
				}
				*/
				if (tipo != null && tipo.equals("ConfermaInvia"))
					attoForm.setDataRegistrazione(new Date());

				attoService.aggiornaSentenzaRevocazioneConfisca(idUffOwn, idUff1, idUff2, idUff3, proced.getIdProcedimento(), attoForm,
						codUtente);
				super.updateProcedimentoIntoSession(proced.getIdProcedimento());
				// INIZIA GESTIONE DOCUMENTALE
				gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
				// FINE GESTIONE DOCUMENTALE
				if (tipo != null && tipo.equals("ConfermaInvia"))
					super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
				else
					super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);
				return copertinaAtto(attoForm, result, request, modelMap);
			}
		}
	}

	@RequestMapping(value = "/procedimento/atto/sentenzaRevocazioneConfisca.htm", method = RequestMethod.POST, params = { "Definitivita" })
	public String definitivitaRevocazione(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = 0l;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			idAtto = attoForm.getCodAtto();
		else
			idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, idProcedimento, request, attoForm);
		modelMap.addAttribute("attoForm", attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(idProcedimento, idAtto,
				idUffOwn);

		// controllo disabilitazione definitività
		boolean disableDefinitivita = true;
		if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento)
			for (int i = 0; i < risultatiRicerca.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
				if (beneSogg != null) {
					List<SoggettoForm> soggetti = beneSogg.getSoggetti();
					if (soggetti != null)
						for (int j = 0; j < soggetti.size(); j++) {
							SoggettoForm sogg = soggetti.get(j);
							if (!sogg.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}
		//
		modelMap.addAttribute("disableDefinitività", disableDefinitivita);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);
		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);
		MenuController.caricaMenu("15", request);
		return "/procedimento/atto/copertinaDefinitivita";
	}

