	private String gestioneDefinitivitaRevocazioneConfisca(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap, String tipoOpDefinitivita) {

		Integer idUfficioUtente = (Integer) request.getSession().getAttribute("idUffOwner");
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		List<BeneForm> misurePatrimoniali = beneSoggettoForm.estrapolaListaBeniConIdSoggettiCheckati();
		AttoForm attoForm = attoUtilService.caricaAttoInSessione(idUfficioUtente.intValue(), idAtto, codUtente, idProcedimento, request, new AttoForm());
		boolean errore = attoValidation.validateSceltaListaMisureDefinitivita(tipoOpDefinitivita, attoForm, beneSoggettoForm, misurePatrimoniali,
				null, result, request);
		if (errore)
			return definitivitaRevocazione(new AttoForm(), beneSoggettoForm, result, modelMap, request);
		else {
			// Non ho errori sulla Validazione
			Date dataDefinitivita = beneSoggettoForm.getDataDefinitivitaAtto();
			long tipoAtto = Long.valueOf(attoForm.getTipoAtto().getId()).longValue();
			if (dataDefinitivita != null)
				// Solo se è presente la Data Definitività vuol dire che ho
				// selezionato almeno una misura e devo passare prima per il
				// salva (anche nel caso del ConfInvia)
				attoService.definitivitaAttoRegistratoSalva(dataDefinitivita, misurePatrimoniali, null, idProcedimento, idUfficioUtente, idAtto,
						tipoAtto, codUtente, tipoOpDefinitivita);
			if (tipoOpDefinitivita.equals("salva"))
				return definitivitaRevocazione(new AttoForm(), beneSoggettoForm, result, modelMap, request);
			else { /* if(tipo.equals("confInvia")) */
				// Verificare che ci siano righe su T_DEF_PATR e T_DEF_PERS con
				// Data Invio NULL
				String tipoRicerca = "dataInvioNull";
				List<TDefPatr> misPatr = procedimentoService.definitivitaMisurePatrimoniali(idProcedimento, idAtto, idUfficioUtente, tipoRicerca);
				if (misPatr.size() == 0) {
					// Se non ci sta nemmeno una --> Errore :
					super.setMessage(Constants.MESSAGE, "error.atto.datadefinitivita.invio", null, false);
					result.reject(Constants.MESSAGE);
					return definitivitaRevocazione(new AttoForm(), beneSoggettoForm, result, modelMap, request);
				} else {// Invio tutte quelle presenti su T_DEF_PATR e
						// T_DEF_PERS con Data Invio NULL
					int aggiornaStatoProc = 0;
					tipoRicerca = "";
					// Prendo tutte le righe su T_DEF_PATR e T_DEF_PERS
					List<TDefPatr> misPatrPresenti = procedimentoService.definitivitaMisurePatrimoniali(idProcedimento, idAtto, idUfficioUtente,
							tipoRicerca);
					// Conto tutte le misurePersonali e misurePatrimoniali
					// dell'Atto
					List<BeneSoggettoForm> misPatrimoniali = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(idProcedimento,
							idAtto, idUfficioUtente);
					int countMisPatr = 0;
					for (BeneSoggettoForm beneSoggettoForm2 : misPatrimoniali)
						if (beneSoggettoForm2.getSoggetti().size() > 0) {
							int count = beneSoggettoForm2.getSoggetti().size();
							countMisPatr = countMisPatr + count;
						}
					// Controllo se tutte le misure dell'Atto sono presenti su
					// T_DEF_PATR e T_DEF_PERS
					if (misPatrPresenti.size() == countMisPatr)
						aggiornaStatoProc = 1;

					List<ComboForm> uffici = ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca();

					long idDest1 = 0;
					long idDest2 = 0;
					long idDest3 = 0;

					if (uffici != null && uffici.size() >= 1)
						idDest1 = Long.valueOf(uffici.get(0).getId());
					if (uffici != null && uffici.size() >= 2)
						idDest2 = Long.valueOf(uffici.get(1).getId());
					if (uffici != null && uffici.size() >= 3)
						idDest3 = Long.valueOf(uffici.get(2).getId());

					// Chiamo la SP di Conferma e Invia
					attoService.definitivitaRevocazioneConfiscaConfermaInvia(idProcedimento, idAtto, idUfficioUtente, idDest1, idDest2, idDest3,
							codUtente, aggiornaStatoProc);
					// Se cambia lo stato del procedimento, lo aggiorno in
					// Session
					if (aggiornaStatoProc == 1)
						updateProcedimentoIntoSession(idProcedimento);

					super.setMessage(SUCCESS_MESSAGE, "succes.invio.generic", null, false);
					return copertinaAtto(new AttoForm(), result, request, modelMap);
				}
			}
		}
	}

