							//attoForm.setIdProcedimentoCda(proc.getId().getCodiKIdProc2());

							istanze=attoService.getricercaIstanza(new Integer(idTribComp.getId()), proc.getId().getCodiKIdProc2(), Long.parseLong(Constants.TIPO_ATTO_ISTANZA_CAM),Long.parseLong(attoIstanza));
