	@RequestMapping(value = "/procedimento/atto/visualizzaDirettiInteressatiIIGrado.htm", method = RequestMethod.POST, params = { "Definitivita" })
	public String definitivitaDecisorioIIGrado(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm,
			BindingResult result, ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		String codiceUtente = recuperaIdCodiceUtente();
		long IdAtto = 0l;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			IdAtto = attoForm.getCodAtto();
		else
			IdAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, IdAtto, codiceUtente, idProcedimento, request, attoForm);
		modelMap.addAttribute("attoForm", attoForm);

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();

		String idTribComp = commonService.getTribunaleCompetente(idProcedimento).getId();

		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {
			List<AttoForm> idsAttoIstanza;
			if(idTribComp!=null) {
				idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 4l, Constants.RICORSO_IN_APPELLO);
			} else {
				idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 5l, Constants.ISTANZA_LIQUIDAZIONE_AMM);
			}
			if(idsAttoIstanza!=null && !idsAttoIstanza.isEmpty()) {
				AttoForm af = idsAttoIstanza.get(0);
				AmministratoreForm amministratore = null;
				if(idTribComp!=null) {
					amministratore = procedimentoService.getAmministratoreByImpugnazione(idProcedimento, af.getCodAtto(), idUffOwn);
				} else {
					amministratore = procedimentoService.getAmministratoreByIstanza(idProcedimento, af.getCodAtto(), idUffOwn);
				}
				List<BeneForm>beniInAmministrazione = beneService.listaBeniInAmministrazione(idUffOwn, idProcedimento, af.getCodAtto(), amministratore.getId());
				modelMap.addAttribute("beniInAmministrazione", beniInAmministrazione);
			}
			boolean disableDefinitivita = true;
			if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento)
				disableDefinitivita = false;
			modelMap.addAttribute("disableDefinitività", disableDefinitivita);

			TDefIstGenId id = new TDefIstGenId();
			id.setCodiKIdAtto(IdAtto);
			id.setCodiKIdProc(idProcedimento);
			id.setCodiKIdUffOwner(idUffOwn);
			TDefIstGen rec = attoService.caricaDefinitivitaIstGen(id);
			if(rec!=null)
				attoForm.setDataDefinitivita(rec.getDataDefinitivita());
		} else {
			soggettiUtilService.soggettiMisurePersonali(request, modelMap);
			beniDecretoUtilService.beniDecretoSequestro(attoForm, request, modelMap, result, false, super.printMethodName());
			modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

			List<BeneSoggettoForm> risultatiRicerca = (List<BeneSoggettoForm>) modelMap.get("risultatiRicerca");
			List<BeneSoggettoForm> risultatiRicercaSogg = (List<BeneSoggettoForm>) modelMap.get("risultatiRicercaSogg");

			// controllo disabilitazione definitività
			boolean disableDefinitivita = true;
			if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento) {
				for (int i = 0; risultatiRicerca != null && i < risultatiRicerca.size(); i++) {
					BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
					if (beneSogg != null) {
						List<SoggettoForm> soggetti = beneSogg.getSoggetti();
						if (soggetti != null)
							for (int j = 0; j < soggetti.size(); j++) {
								SoggettoForm sogg = soggetti.get(j);
								if (!sogg.isDisabledCheckDefinitivita())
									disableDefinitivita = false;
							}
					}
				}

				for (int i = 0; risultatiRicercaSogg != null && i < risultatiRicercaSogg.size(); i++) {
					BeneSoggettoForm beneSogg = risultatiRicercaSogg.get(i);
					if (beneSogg != null) {
						List<MisuraForm> misure = beneSogg.getMisure();
						if (misure != null)
							for (int j = 0; j < misure.size(); j++) {
								MisuraForm mis = misure.get(j);
								if (!mis.isDisabledCheckDefinitivita())
									disableDefinitivita = false;

								 if(idTipoProc.equals(""+Constants.TIPOPROC_CAUZIONI_CAM)) {
									   if (mis != null && mis.getTipoMisura()!= null && !"25".equalsIgnoreCase(mis.getTipoMisura().getId()))
									   {
										   misure.remove(j);
									   }
									  }
							}
					}
				}
			}

			modelMap.addAttribute("disableDefinitività", disableDefinitivita);
		}

		MenuController.caricaMenu("15", request);
		return "/procedimento/atto/copertinaDefinitivita";
	}

	@RequestMapping(value = { "/procedimento/atto/visualizzaDirettiInteressatiIIGrado.htm" }, method = RequestMethod.POST, params = { "DecisioneBeni" })
	public String apriDecisiorioBeniIIGrado(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap map) {

		ProfiloForm profilo = (ProfiloForm) request.getSession().getAttribute("profilo");
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		int idTipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();



		ComboForm idTribComp = commonService.getTribunaleCompetente(idProcedimento);


		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {

			//caricare la decisione su t_rel_atto_ist_gen
			TRelAttoIstGenId id = new TRelAttoIstGenId();
			id.setCodiKIdAtto(idCurrentAtto);
			id.setCodiKIdProc(idProcedimento);
			id.setCodiKIdUffOwner(idUffOwn);
			TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
			ComboForm esitoIGrado =null;
			//primo grado solo in visualizzazione
			if(relAttoIstGen!=null && relAttoIstGen.getTTpEsitoByCodiFkIdEsito1()!=null) {

				esitoIGrado = new ComboForm();
				esitoIGrado.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito1().getCodiKIdEsito());

			}
				//carico tutti gli esiti possibili di I Grado
				Long catAttoSearchIGrado = new Long(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE);

				String tipoEsito = "LA";
				List<ComboForm> esitiIGrado = procedimentoService.getEsiti(tipoEsito, catAttoSearchIGrado, 0);

				//imposto le descrizione per l'esito di I Grado
				if(esitiIGrado!=null && esitoIGrado!=null && esitoIGrado.getId()!=null)
					for(int i=0;esitiIGrado!=null && i<esitiIGrado.size();i++) {
						ComboForm esito = esitiIGrado.get(i);
						if(esito.getId().equals(esitoIGrado.getId()))
							esitoIGrado.setDescrizione(esito.getDescrizione());
					}

				map.addAttribute("esitoIGrado", esitoIGrado);

				//decisione II grado
				ComboForm decisioneIIGrado = new ComboForm();
				if(relAttoIstGen!=null && relAttoIstGen.getTTpEsitoByCodiFkIdEsito2()!=null) {
					decisioneIIGrado.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito2().getCodiKIdEsito());
					beneSoggettoForm.setDecisioneBeni(decisioneIIGrado);
					beneSoggettoForm.setMotivazione1(relAttoIstGen.getDescAltro1());
					beneSoggettoForm.setImporto1(relAttoIstGen.getImpo1());
				}

			List<AttoForm> idsAttoIstanza = null;
			if (idTipoUfficio == Constants.TIPO_UFFICIO_CORTE_D_APPELLO && idTribComp.getId()!=null){
				idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 4l, Constants.RICORSO_IN_APPELLO);
			}else{

				idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 5l, Constants.ISTANZA_LIQUIDAZIONE_AMM);
				  }
				if(idsAttoIstanza!=null && !idsAttoIstanza.isEmpty()) {
				AttoForm af = idsAttoIstanza.get(0);
				AmministratoreForm amministratore = null;
				if (idTipoUfficio == Constants.TIPO_UFFICIO_CORTE_D_APPELLO && idTribComp!=null && idTribComp.getId()!=null)
					amministratore = procedimentoService.getAmministratoreByImpugnazione(idProcedimento, af.getCodAtto(), idUffOwn);
				else
					amministratore = procedimentoService.getAmministratoreByIstanza(idProcedimento, af.getCodAtto(), idUffOwn);
				List<BeneForm>beniInAmministrazione = beneService.listaBeniInAmministrazione(idUffOwn, idProcedimento, af.getCodAtto(), amministratore.getId());
				map.addAttribute("beniInAmministrazione", beniInAmministrazione);
			}
		} else {
			List<BeneSoggettoForm> beni = procedimentoService.listaBeniAttoDecisorio(idProcedimento, idCurrentAtto, idUffOwn, 0, 0, 0, 0, 0);
			map.addAttribute("risultatoRicerca", beni);
		}


		 List<AttoForm> istanze=null;
		 String tipoAttoIstanza="";
		 if(procedimentoForm.getTipoFascicolo().getId().equals(String.valueOf(Constants.TIPO_FASCICOLO_CAMERA_DI_CONSIGLIO))){
			 if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) tipoAttoIstanza=Constants.ISTANZA_LIQUIDAZIONE_AMM;

				if (idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM))     tipoAttoIstanza=Constants.ISTANZA_TERZO_INTERVENIENTE;

				if (idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM)) tipoAttoIstanza =Constants.ISTANZA_MODIFICA_PATRIMONIALE;

				if (idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) tipoAttoIstanza =Constants.ISTANZA_CORREZIONE_ERRORI_MATERIALI;

		if (idTipoUfficio == Constants.TIPO_UFFICIO_CORTE_D_APPELLO && idTribComp.getId()!=null){
			//originato da procedimento tribunale

			List<TRelProcProc> listaProcedimenti = procedimentoService
					.getListaProcedimentiCdaTrib(idProcedimento,
							recuperaIdUfficioUtente());
			if (listaProcedimenti != null && !listaProcedimenti.isEmpty()) {


					Iterator<TRelProcProc> iter = listaProcedimenti.iterator();
					Map map1 = (Map) iter.next();
					TRelProcProc proc = (TRelProcProc) map1.get("rel");


					istanze=attoService.getricercaIstanza(new Integer(idTribComp.getId()), proc.getId().getCodiKIdProc2(), Long.parseLong(Constants.TIPO_ATTO_ISTANZA_CAM),Long.parseLong(tipoAttoIstanza));
				   if (listaProcedimenti.size() > 1 && (istanze== null || istanze.isEmpty())){
						map1 = (Map) iter.next();
						proc = (TRelProcProc) map1.get("rel");
						if (!tipoAttoIstanza.equals(""))  istanze=attoService.getricercaIstanza(new Integer(idTribComp.getId()), proc.getId().getCodiKIdProc2(), Long.parseLong(Constants.TIPO_ATTO_ISTANZA_CAM),Long.parseLong(tipoAttoIstanza));
				   }

				}
		}else{

			//originato da un procedimento di corte d'appello


			 if (!tipoAttoIstanza.equals(""))istanze= attoService.getricercaIstanza((Integer) request.getSession().getAttribute(Constants.ID_UFFICIO_UTENTE), ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento(), Long.parseLong(Constants.TIPO_ATTO_ISTANZA_CAM),Long.parseLong(tipoAttoIstanza));
		}
			AttoForm istanza = new AttoForm();

			 if(istanze != null && !istanze.isEmpty()){

				 istanza = istanze.get(0);
				 beneSoggettoForm.setDescRichiesta(istanza.getNote());
			 }
		 }



		map.addAttribute("beneSoggetto", beneSoggettoForm);
		String categoriaAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId();
		Long catAttoSearch = Long.parseLong(Constants.DECRETO_DECISORIO_II_GRADO);


		if (categoriaAtto != null && categoriaAtto.equals(Constants.SENTENZA_OPPOSIZIONE_AL_DISSEQUESTRO)) {
			catAttoSearch = Long.parseLong(Constants.SENTENZA_OPPOSIZIONE_AL_DISSEQUESTRO);
			AttoForm attoForm = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
			if (attoForm.getDataRegistrazione() != null) {
				List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
				map.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
			} else
				map.addAttribute("ufficiList", ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca());
		} else if (categoriaAtto != null && categoriaAtto.equals(Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA)) {
			catAttoSearch = Long.parseLong(Constants.SENTENZA_REVOCAZIONE_DELLA_CONFISCA);
			AttoForm attoForm = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO)));
			if (attoForm.getDataRegistrazione() != null) {
				List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
				map.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
			} else
				map.addAttribute("ufficiList", ufficioUtilService.caricaUfficiSentenzaRevocazioneConfisca());
		}
		long idUffRic = profilo.getIdTipoUfficio();
		String tipoEsito="T";

		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM) ||
				idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM) ||
					idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM) ||
					idTipoProc.equals(""+Constants.TIPOPROC_MODIFICA_PATRIMONIALE_CAM)) {
			tipoEsito="X";
			if (idTribComp.getId()==null)	{
				catAttoSearch=Long.parseLong(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE);
				tipoEsito="T";
				idUffRic=0L;
			}
			else  catAttoSearch=359L;

		}

		if(idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) tipoEsito = "LA";
		if(idTipoProc.equals(""+Constants.TIPOPROC_TERZO_INTERVENIENTE_CAM)) tipoEsito = "T";
		if(idTipoProc.equals(""+Constants.TIPOPROC_CORREZIONE_ERRORI_CAM)) tipoEsito = "EM";


		if(tipoEsito.equals("LA")) idUffRic = 0;

		List<ComboForm> esiti = procedimentoService.getEsiti(tipoEsito, catAttoSearch, idUffRic);
		map.addAttribute("esitiDecisioneBeni", esiti);
		AttoForm attoForm = (AttoForm) (request.getSession().getAttribute(Constants.ATTO));
		if ((attoForm.getNumeAnnoAtto() != null && attoForm.getNumeAnnoAtto().length() > 0)
				&& (attoForm.getNumeAtto() != null && attoForm.getNumeAtto().length() > 0)) {
			map.addAttribute("esitoReadOnly", "true");
		}

		if (map.get("attoForm") == null)
			map.addAttribute("attoForm", request.getSession().getAttribute(Constants.ATTO));
		// se è la corte d'appello quindi decisorio di II Grado
		return "procedimento/atto/decisorioBeniIIGrado";

	}

