	@RequestMapping(value = { "/procedimento/atto/visualizzaDirettiInteressatiIIGrado.htm","/procedimento/atto/decisorioBeniIIGrado.htm" }, method = RequestMethod.POST)
	public String postDecisiorioBeniIIGrado(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request, ModelMap map) {
		//System.out.println("---> PostDecisorioBeneIIGRADO"  );
		ProfiloForm profilo = (ProfiloForm) request.getSession().getAttribute("profilo");
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		int idTipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));
		String idTipoProc = procedimentoForm.getTipoProcedimento().getId();

		ComboForm idTribComp = commonService.getTribunaleCompetente(idProcedimento);

		boolean visualizzaFiltro = attoForm.isVisualizzaFiltro();

		if (!visualizzaFiltro) {
			attoForm.setSoggettiDiretti(null);
			attoForm.setSoggettiTitolari(null);
			attoForm.setTipologiaBene(null);
			attoForm.setCategoriaBene(null);
			attoForm.setSottoCategoriaBene(null);
		}

		long idSoggettoDiretto = attoForm.getIdSoggettoDiretto();
		long idSoggettoTitolare = attoForm.getIdSoggettoTitolare();
		long idTipologia = attoForm.getIdTipologia();
		long idCategoria = attoForm.getIdCategoria();
		long idSottocategoria = attoForm.getIdSottocategoria();

		if (visualizzaFiltro) {
			map.addAttribute("categorie", getCategorieBene(attoForm));
			map.addAttribute("sottocategorie", getSottoCategorieBene(attoForm));

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDiretti = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDiretti != null )
				map.addAttribute("soggettiDiretti", utility.creaComboSoggetti(soggettiDiretti));
			List<SoggettoForm> soggettiTitolari = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_TITOLARI, Constants.Flag.S);
			if (soggettiTitolari != null )
				map.addAttribute("soggettiTitolari", utility.creaComboSoggetti(soggettiTitolari));
		}

		if (idTipoProc.equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {
			//caricare la decisione su t_rel_atto_ist_gen
			TRelAttoIstGenId id = new TRelAttoIstGenId();
			id.setCodiKIdAtto(idCurrentAtto);
			id.setCodiKIdProc(idProcedimento);
			id.setCodiKIdUffOwner(idUffOwn);
			TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
			ComboForm esitoIGrado =null;
			//primo grado solo in visualizzazione
			if(relAttoIstGen!=null && relAttoIstGen.getTTpEsitoByCodiFkIdEsito1()!=null) {

				esitoIGrado = new ComboForm();
				esitoIGrado.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito1().getCodiKIdEsito());

			}
			// carico tutti gli esiti possibili di I Grado
			Long catAttoSearchIGrado = new Long(Constants.DECRETO_DECISORIO_I_GRADO_CAMERE);

			String tipoEsito = "LA";
			List<ComboForm> esitiIGrado = procedimentoService.getEsiti(tipoEsito, catAttoSearchIGrado, 0);

			// imposto le descrizione per l'esito di I Grado
			if(esitiIGrado!=null && esitoIGrado!=null && esitoIGrado.getId()!=null)
				for(int i=0;esitiIGrado!=null && i<esitiIGrado.size();i++) {
					ComboForm esito = esitiIGrado.get(i);
					if(esito.getId().equals(esitoIGrado.getId()))
						esitoIGrado.setDescrizione(esito.getDescrizione());
				}

			map.addAttribute("esitoIGrado", esitoIGrado);

			// decisione II grado
			ComboForm decisioneIIGrado = new ComboForm();
			if(relAttoIstGen.getTTpEsitoByCodiFkIdEsito2()!=null) {
				decisioneIIGrado.setId(""+relAttoIstGen.getTTpEsitoByCodiFkIdEsito2().getCodiKIdEsito());
				beneSoggettoForm.setDecisioneBeni(decisioneIIGrado);
			}

			List<AttoForm> idsAttoIstanza = null;
			if (idTipoUfficio == Constants.TIPO_UFFICIO_CORTE_D_APPELLO && idTribComp!=null && idTribComp.getId()!=null)
				idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 4l, Constants.RICORSO_IN_APPELLO);
			else
				idsAttoIstanza = attoService.getAttiByProcedimento(idProcedimento, 5l, Constants.ISTANZA_LIQUIDAZIONE_AMM);
			if (idsAttoIstanza!=null && !idsAttoIstanza.isEmpty()) {
				AttoForm af = idsAttoIstanza.get(0);
				AmministratoreForm amministratore = null;
				if (idTipoUfficio == Constants.TIPO_UFFICIO_CORTE_D_APPELLO && idTribComp!=null && idTribComp.getId()!=null)
					amministratore = procedimentoService.getAmministratoreByImpugnazione(idProcedimento, af.getCodAtto(), idUffOwn);
				else
					amministratore = procedimentoService.getAmministratoreByIstanza(idProcedimento, af.getCodAtto(), idUffOwn);
				List<BeneForm>beniInAmministrazione = beneService.listaBeniInAmministrazione(idUffOwn, idProcedimento, af.getCodAtto(), amministratore.getId());
				map.addAttribute("beniInAmministrazione", beniInAmministrazione);
			}
		} else {
			List<BeneSoggettoForm> beni = procedimentoService.listaBeniAttoDecisorio(idProcedimento, idCurrentAtto, idUffOwn,
				idSoggettoDiretto, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
			map.addAttribute("risultatoRicerca", beni);
		}

		map.addAttribute("beneSoggetto", beneSoggettoForm);
//		String categoriaAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId();
		Long catAttoSearch = Long.parseLong(Constants.DECRETO_DECISORIO_II_GRADO);

		long idUffRic = profilo.getIdTipoUfficio();
		String tipoEsito="T";
		((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getTipoProcedimento().getId();

		if(tipoEsito.equals("LA")) idUffRic = 0;

		List<ComboForm> esiti = procedimentoService.getEsiti(tipoEsito, catAttoSearch, idUffRic);
		map.addAttribute("esitiDecisioneBeni", esiti);
		//System.out.println("---> paginazione --> " + beneSoggettoForm.getPaginazione() + "<--" );
		if (beneSoggettoForm.getPaginazione().contains("N")){
			beneSoggettoForm.setPaginazione("N");
		}else{
			beneSoggettoForm.setPaginazione("Y");
		}
		//System.out.println("---> dopo paginazione --> " + beneSoggettoForm.getPaginazione() + "<--" );

		beneSoggettoForm.setSelected(null);
		if (map.get("attoForm") == null)
			map.addAttribute("attoForm", request.getSession().getAttribute(Constants.ATTO));
		// se è la corte d'appello quindi decisorio di II Grado
		return "procedimento/atto/decisorioBeniIIGrado";
	}

	@RequestMapping(value = {"/procedimento/atto/decisorioIIGrado.htm"}, method = RequestMethod.POST, params = { "Salva" })
	public String aggiornaDecisorioIIGrado(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap, String tipo) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		request.getAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE);
		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(Long.valueOf(attoInSessione.getCategoriaAtto().getId()));
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		//validaAllegatoEFirma(attoForm, result, request);

		boolean err = false;
		attoValidation.validateSalvaDecisorioPrevenzione(attoForm, result, request, modelMap);

		if(proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {
			//caricare la decisione su t_rel_atto_ist_gen
			TRelAttoIstGenId id = new TRelAttoIstGenId();
			id.setCodiKIdAtto(attoInSessione.getCodAtto());
			id.setCodiKIdProc(proced.getIdProcedimento());
			id.setCodiKIdUffOwner(idUffOwn);
			TRelAttoIstGen relAttoIstGen = beneService.getDecisorioBeniIstGen(id);
			if(relAttoIstGen==null || relAttoIstGen.getTTpEsitoByCodiFkIdEsito2()==null) {
				super.setMessage(Constants.MESSAGE, "atto.decreto.decisorioIGrado.beniSenzaDecisioni.error", null, false);
				err = true;
			}
		} else if (tipo != null && tipo.equals("ConfermaInvia")) attoValidation.validateConfermaInviaDecisorio("II_GRADO",proced.getIdProcedimento(),idUffOwn,attoForm, proced.getStatoProcedimento().getId(), result, request, modelMap);

		if (tipo != null && tipo.equals("ConfermaInvia"))
			attoValidation.validateConfermaInviaDecisorio("II_GRADO",proced.getIdProcedimento(),idUffOwn,attoForm, proced.getStatoProcedimento().getId(), result, request, modelMap);


		if (result.hasErrors() || err) {
			attoForm.setDataRegistrazione(null);
			if(proced.getTipoProcedimento().getId().equals(""+Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM)) {

				List<IntestatarioDto> listaIntestatari = procedimentoServiceCam.getIntestatari(idUffOwn, proced.getIdProcedimento());
				modelMap.addAttribute("listaIntestatari", listaIntestatari);
			} else {
				List<SoggettoForm> soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(proced.getIdProcedimento(),
						Constants.RUOLO_DIRETTO, Constants.Flag.S);
				modelMap.addAttribute("soggettoForm", new SoggettoForm());
				modelMap.addAttribute("soggetti", soggetti);
			}
			procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);

			return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
		}
// GESTIONE GIUDICE DELEGATO
   // Se NON C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO devo inserire il Giudice delegato
		List<MagistratoForm> magistratiAssociatiAtto = null;
		List<MagistratoForm> magistratiAssociatiProc = null;
		boolean esitoFinApplica = false;
		if (proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE_E_PATRIMONIALE) ||
			proced.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PATRIMONIALE)){
			int idUffOwnInt = recuperaIdUfficioUtente();
			// Controllo che ci sia almeno una decisione sui Beni con esito applica
			// in tal caso il giudice delegato è obbligatorio
			String Categoria = Constants.DECRETO_DECISORIO_II_GRADO;
				KeyMessageDto messaggioRitorno = attoService.controllaEsitoFinale(idUffOwnInt, proced.getIdProcedimento(), attoForm.getCodAtto(), Integer.parseInt(Categoria));
				if (!messaggioRitorno.isError())
					esitoFinApplica = true;
				if(esitoFinApplica){
					magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUffOwnInt , attoForm.getCodAtto(), Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
					magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUffOwnInt, proced.getIdProcedimento().longValue(), Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
					if(magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0)){
						modelMap.addAttribute("attoForm", attoForm);
						super.setMessage(Constants.MESSAGE,"magistrato.error.giudiceDelegato.registrazioneAtto",null,false);

						return "/procedimento/atto/copertinaDecretoDecisorioIIGrado";
					}
				}
		}

		attoForm.setCodAtto(attoInSessione.getCodAtto());
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
			attoForm.setDataRicezione(Calendar.getInstance().getTime());
		}

		if (tipo != null && tipo.equals("ConfermaInvia"))
			attoForm.setDataRegistrazione(new Date());

		// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		String giudiceDelegato = null;
		MagistratoForm magistratoForm = null;
		if(esitoFinApplica){
			if (tipo != null && tipo.equals("ConfermaInvia"))
				// se C'è nella REL_MAG_ATTO e NON C'è nella REL_MAG_PROC vuol dire che sto registrando il primo sequestro:
				// quindi devo inserire nella REL_MAG_PROC e associare il Giudice delegato al procedimento.
				if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
						&& (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() > 0)){
						magistratoForm = magistratiAssociatiAtto.get(0);
						giudiceDelegato = "PROC";
				}
		// se C'è nella REL_MAG_PROC e NON C'è nella REL_MAG_ATTO inserisco nella REL_MAG_ATTO)
			if((magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))
				&& (magistratiAssociatiProc != null && magistratiAssociatiProc.size() > 0)){
				magistratoForm = magistratiAssociatiProc.get(0);
				giudiceDelegato = "ATTO";
			}
		} else if(magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() > 0){
			magistratoForm = magistratiAssociatiAtto.get(0);
			giudiceDelegato = "CANC";
		}
		if(magistratoForm == null) {
			magistratoForm = new MagistratoForm();
			magistratoForm.setId(Long.valueOf(0));
		}
		else magistratoForm.setId(magistratoForm.getId());

		int tipoUfficio = (Integer) request.getSession().getAttribute("idTipoUfficio");
		attoService.aggiornaDecisorioPrevenzione(idUffOwn, 0l, 0l, 0l, proced.getIdProcedimento(), attoForm, codUtente, tipoUfficio, magistratoForm.getId(), giudiceDelegato);
		super.updateProcedimentoIntoSession(proced.getIdProcedimento());

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		if (tipo != null && tipo.equals("ConfermaInvia"))
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
		else if((attoForm.getAllegato().getFileData() == null || attoForm.getAllegato().getFileData().getSize() <= 0) && attoForm.getDataEmissione() == null && attoForm.getDataDeposito() == null)
			super.setMessage(Constants.MESSAGE, "atto.decreto.decisorioIIGrado.nessunaModifica", null, false);
		else
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		return copertinaAtto(attoForm, result, request, modelMap);
	}

	@RequestMapping(value = {"/procedimento/atto/decisorioIIGrado.htm"}, method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String inviaDecisorioIIGrado(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		request.getAttribute(HandlerMapping.BEST_MATCHING_PATTERN_ATTRIBUTE);
		long idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = recuperaProcedimento().getIdProcedimento();
		attoValidation.validateSoggettiIntervenientiNonAssociati(idProcedimento, (int) idUfficio, result, request, modelMap);
		if (result.hasErrors()) {
			super.setMessage(Constants.MESSAGE, "atto.decreto.decisorioIGrado.intervenientiNonAssociati", null, false);
		}
		return aggiornaDecisorio(attoForm, result, request, modelMap, "ConfermaInvia");
	}

