	public String nuovoParere(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		recuperaIdUfficioUtente();

		List<AttoForm> listaRichieste = attoService.getAttiParere(procedimento.getIdProcedimento());

		List<ComboForm> listaDecretiCombo = new ArrayList<ComboForm>();
		Iterator<AttoForm> iterSeq = listaRichieste.iterator();
		while (iterSeq.hasNext()) {
			String descrizione = "";
			ComboForm combo = new ComboForm();
			AttoForm attoGen = iterSeq.next();

			if (attoGen.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)) {
				descrizione = "Richiesta del " + Utility.convertDateToString(attoGen.getDataDeposito());
				combo.setId("" + attoGen.getCodAtto());
				combo.setDescrizione(descrizione);
				listaDecretiCombo.add(combo);
			}
		}

		if (!Utility.isDefinito(listaDecretiCombo)) {
			super.setMessage(Constants.MESSAGE, "atto.generico.parere.noRichieste", null, false);
			return "/procedimento/atto/nuovoAtto";
		}

		modelMap.addAttribute("attoForm", attoForm);
		modelMap.addAttribute("listaDecreti", listaDecretiCombo);
		return "/procedimento/atto/copertinaParere";
	}

