	public String aggiornaInviaParere(boolean isRichiesta, String operazione, AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());

		String idTipoFasc = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getTipoFascicolo().getId();
		long idDestinatario = 0;

		if(operazione.equals("InviaProcura")){
			attoService.aggiornaInviaParere(isRichiesta, idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
					idDestinatario, super.printMethodName());
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
			modelMap.addAttribute("attoInviato", Boolean.TRUE);
		}else{

			ComboForm ufficioDest = null;
			if (isRichiesta)
				ufficioDest = commonService.getProcuraInUdienzaAssociata(idProcedimento);
			else {
				//Fabio NGG: l'ufficio CDA deve essere dello stesso distretto del tribunale competente
				if(Integer.valueOf(idTipoFasc) == Constants.TIPO_FASCICOLO_REVOCAZIONE)
				   ufficioDest = commonService.getCDA(idUffOwn);
				else
				{
					long uffTrib;
					Integer idTipoUfficio = recuperaIdTipoUfficio();
					if(idTipoUfficio!=null && Constants.TIPO_UFFICIO_TRIBUNALE.equals(idTipoUfficio.toString())){
						uffTrib = idUfficio;
					   ufficioDest=new ComboForm();
					   ufficioDest.setId(""+uffTrib);
					}
					else
					if(idTipoUfficio!=null && Constants.TIPO_UFFICIO_PROCURA_GENERALE == idTipoUfficio.longValue()){
						   ufficioDest = commonService.getCDA(idUffOwn);
					}
					else
					{

						ComboForm combTrib = commonService.getTribunaleCompetente(idProcedimento);
						ufficioDest=new ComboForm();
						if(combTrib != null && combTrib.getId() != null){
							uffTrib = Long.valueOf(combTrib.getId());
							ufficioDest.setId(""+uffTrib);
						 }
					}


					//ufficioDest = commonService.getCDA(uffTrib);


				}
				//
			}

			idDestinatario = Long.valueOf(ufficioDest.getId());

			if (operazione.equals("Invia")) {

				if (categoriaAtto == 330 || categoriaAtto == 331) {

					allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
					attoValidation.validateAttoDate(attoForm, result, request);
					attoValidation.validateAttoDataEmissioneAfterDeposito(attoForm, result, request);

				} else {
					// INIZIA GESTIONE DOCUMENTALE
					// validaAllegatoEFirma(attoForm, result, request);
					allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
					// FINE GESTIONE DOCUMENTALE

					attoValidation.validateAttoDate(attoForm, result, request);
				}

				if (result.hasErrors()) {
					attoForm.setDataRegistrazione(null);
					List<ComboForm> ufficiList = new ArrayList<ComboForm>();
					if (isRichiesta) {
						ComboForm procuraInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
						ufficiList.add(procuraInUdienza);
					} else {


						//ComboForm cda = commonService.getCDA(idUffOwn);
						//Fabio NGG: l'ufficio CDA deve essere dello stesso distretto del tribunale competente

						long uffTrib;
						Integer idTipoUfficio = recuperaIdTipoUfficio();
						if(idTipoUfficio!=null && Constants.TIPO_UFFICIO_TRIBUNALE.equals(idTipoUfficio.toString()))
							uffTrib = idUfficio;
						else  {
							   ComboForm combTrib = commonService.getTribunaleCompetente(idProcedimento);
							   if(combTrib.getId() != null)
								  uffTrib = Long.valueOf(combTrib.getId());
							   else
								  uffTrib = 0;
						}
						ComboForm cda = commonService.getCDA(uffTrib);
						//
						ufficiList.add(cda);

					}
					modelMap.addAttribute("ufficiList", ufficiList);
					if (isRichiesta) {
						if(categoriaAtto == 330) {
							attoForm.setCodAtto(idAtto);
							attoForm.setCategoriaAtto(attoTmp.getCategoriaAtto());
						}
						return "/procedimento/atto/copertinaRichiestaParere";
					} else {
						if(categoriaAtto == 331) {
							attoForm.setCodAtto(idAtto);
							attoForm.setCategoriaAtto(attoTmp.getCategoriaAtto());
						}
						return "/procedimento/atto/copertinaParere";
					}
				}

				attoForm.setDataRegistrazione(new Date());
			}

			// isRichiesta serve per identificare se si tratta di una richiesta di
			// parere oppure di un parere
			attoService.aggiornaInviaParere(isRichiesta, idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
					idDestinatario, super.printMethodName());

			if (operazione.equals("Invia")) {
				// INIZIA GESTIONE DOCUMENTALE
				gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
				// FINE GESTIONE DOCUMENTALE
				super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
			} else
				super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);


		}

		return copertinaAtto(attoForm, result, request, modelMap);


	}

	@RequestMapping(value = "/procedimento/atto/richiestaParere.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String salvaInviaRichiestaParere(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

//		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;


		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		attoForm.setDataRegistrazione(null);

//---

		if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)){
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				AttoForm attoAppo = attoService.getAttoById(idAtto, idUfficio);
				attoForm.setCodAtto(idAtto);
				attoForm.setCategoriaAtto(attoAppo.getCategoriaAtto());

				return "/procedimento/atto/copertinaRichiestaParere";
			}

		// INIZIA GESTIONE DOCUMENTALE
		//validaAllegatoEFirma(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateAttoDataEmissioneAfterDeposito(attoForm, result, request);
		if (result.hasErrors()) {
			request.removeAttribute(Constants.SUCCESS_MESSAGE);

			AttoForm attoAppo = attoService.getAttoById(idAtto, idUfficio);
			attoForm.setCodAtto(idAtto);
			attoForm.setCategoriaAtto(attoAppo.getCategoriaAtto());

			return "/procedimento/atto/copertinaRichiestaParere";
		}


		attoForm.setCodAtto(idAtto);

		inizializzaDocumento(attoForm, request);

		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

//		String categoriaAttoString = attoTmp.getCategoriaAtto().getId();

		attoForm.setDataRegistrazione(null);

		attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		//return copertinaAtto(attoForm, result, request, modelMap);
		return "/procedimento/atto/copertinaRichiestaParere";
	}

