	@RequestMapping(value = {"/procedimento/atto/postDefinitivitaRevoca.htm" }, method = RequestMethod.POST)
	public String postRevocaDefinitivitaDecisorio(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		ComboForm sogDirettiPers = attoForm.getSoggettiDirettiPers();
		ComboForm sogDiretti = attoForm.getSoggettiDiretti();

		ComboForm sogTitolari = attoForm.getSoggettiTitolari();
		ComboForm tipBene = attoForm.getTipologiaBene();
		ComboForm catBene = attoForm.getCategoriaBene();
		ComboForm sotcatBene = attoForm.getSottoCategoriaBene();

		boolean visualizzaFiltro = attoForm.isVisualizzaFiltro();
		boolean visualizzaFiltroPers = attoForm.isVisualizzaFiltroPers();

		if (!visualizzaFiltroPers) {
			attoForm.setSoggettiDirettiPers(null);
		}

		if (!visualizzaFiltro) {
			attoForm.setSoggettiDiretti(null);
			attoForm.setSoggettiTitolari(null);
			attoForm.setTipologiaBene(null);
			attoForm.setCategoriaBene(null);
			attoForm.setSottoCategoriaBene(null);
		}

		long idSoggettoDirettoPers = attoForm.getIdSoggettoDirettoPers();
		long idSoggettoDiretto = attoForm.getIdSoggettoDiretto();
		long idSoggettoTitolare = attoForm.getIdSoggettoTitolare();
		long idTipologia = attoForm.getIdTipologia();
		long idCategoria = attoForm.getIdCategoria();
		long idSottocategoria = attoForm.getIdSottocategoria();


		attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		attoForm.setVisualizzaFiltro(visualizzaFiltro);
		attoForm.setVisualizzaFiltroPers(visualizzaFiltroPers);

		attoForm.setSoggettiDirettiPers(sogDirettiPers);
		attoForm.setSoggettiDiretti(sogDiretti);
		attoForm.setSoggettiTitolari(sogTitolari);
		attoForm.setTipologiaBene(tipBene);
		attoForm.setCategoriaBene(catBene);
		attoForm.setSottoCategoriaBene(sotcatBene);

		modelMap.addAttribute("attoForm", attoForm);


		if (visualizzaFiltroPers) {

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDirettiPers = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDirettiPers != null ) {
				soggettiDirettiPers = soggettiUtilService.filtraSoloSoggettiMisPers(soggettiDirettiPers, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDirettiPers", utility.creaComboSoggetti(soggettiDirettiPers));
			}
		}

		if (visualizzaFiltro) {
			modelMap.addAttribute("categorie", getCategorieBene(attoForm));
			modelMap.addAttribute("sottocategorie", getSottoCategorieBene(attoForm));

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDiretti = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDiretti != null )
				soggettiDiretti = soggettiUtilService.filtraSoloSoggettiMisPatr(soggettiDiretti, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDiretti", utility.creaComboSoggetti(soggettiDiretti));

			List<SoggettoForm> soggettiTitolari = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_TITOLARI, Constants.Flag.S);
			if (soggettiTitolari != null )
				modelMap.addAttribute("soggettiTitolari", utility.creaComboSoggetti(soggettiTitolari));
		}
//---

		if (idSoggettoDirettoPers > 0 )
			soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivitaFiltrati(request, modelMap, idSoggettoDiretto);
		else
			soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivita(request, modelMap);

		if (idSoggettoDiretto > 0 || idSoggettoTitolare > 0 || idTipologia > 0 || idCategoria > 0 || idSottocategoria > 0 )
			beniDefinitivitaUtilService.beniRevocaDefinitivaFiltrati(request, modelMap, result, super.printMethodName(), idSoggettoDiretto, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
		else
			beniDefinitivitaUtilService.beniRevocaDefinitiva(request, modelMap, result, super.printMethodName());

		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

		List<BeneSoggettoForm> risultatiRicerca = (List<BeneSoggettoForm>) modelMap.get("risultatiRicerca");
		List<BeneSoggettoForm> risultatiRicercaSogg = (List<BeneSoggettoForm>) modelMap.get("risultatiRicercaSogg");

		// controllo disabilitazione definitività
		boolean disableDefinitivita = true;
		if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento) {
			for (int i = 0; risultatiRicerca != null && i < risultatiRicerca.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
				if (beneSogg != null) {
					List<SoggettoForm> soggetti = beneSogg.getSoggetti();
					if (soggetti != null)
						for (int j = 0; j < soggetti.size(); j++) {
							SoggettoForm sogg = soggetti.get(j);
							if (!sogg.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}

			for (int i = 0; risultatiRicercaSogg != null && i < risultatiRicercaSogg.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicercaSogg.get(i);
				if (beneSogg != null) {
					List<MisuraForm> misure = beneSogg.getMisure();
					if (misure != null)
						for (int j = 0; j < misure.size(); j++) {
							MisuraForm mis = misure.get(j);
							if (!mis.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}
		}
		//

		modelMap.addAttribute("disableDefinitività", disableDefinitivita);

		return "/procedimento/atto/copertinaRevocaDefinitivita";
	}

	@RequestMapping(value = {"/procedimento/atto/postDefinitivitaDecisorio.htm" }, method = RequestMethod.POST)
	public String postDefinitivitaDecisorio(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		ComboForm sogDirettiPers = attoForm.getSoggettiDirettiPers();
		ComboForm sogDiretti = attoForm.getSoggettiDiretti();

		ComboForm sogTitolari = attoForm.getSoggettiTitolari();
		ComboForm tipBene = attoForm.getTipologiaBene();
		ComboForm catBene = attoForm.getCategoriaBene();
		ComboForm sotcatBene = attoForm.getSottoCategoriaBene();

		boolean visualizzaFiltro = attoForm.isVisualizzaFiltro();
		boolean visualizzaFiltroPers = attoForm.isVisualizzaFiltroPers();

		if (!visualizzaFiltroPers) {
			attoForm.setSoggettiDirettiPers(null);
		}

		if (!visualizzaFiltro) {
			attoForm.setSoggettiDiretti(null);
			attoForm.setSoggettiTitolari(null);
			attoForm.setTipologiaBene(null);
			attoForm.setCategoriaBene(null);
			attoForm.setSottoCategoriaBene(null);
		}

		long idSoggettoDirettoPers = attoForm.getIdSoggettoDirettoPers();
		long idSoggettoDiretto = attoForm.getIdSoggettoDiretto();
		long idSoggettoTitolare = attoForm.getIdSoggettoTitolare();
		long idTipologia = attoForm.getIdTipologia();
		long idCategoria = attoForm.getIdCategoria();
		long idSottocategoria = attoForm.getIdSottocategoria();


		attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		attoForm.setVisualizzaFiltro(visualizzaFiltro);
		attoForm.setVisualizzaFiltroPers(visualizzaFiltroPers);

		attoForm.setSoggettiDirettiPers(sogDirettiPers);
		attoForm.setSoggettiDiretti(sogDiretti);
		attoForm.setSoggettiTitolari(sogTitolari);
		attoForm.setTipologiaBene(tipBene);
		attoForm.setCategoriaBene(catBene);
		attoForm.setSottoCategoriaBene(sotcatBene);

		modelMap.addAttribute("attoForm", attoForm);



		if (visualizzaFiltroPers) {

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDirettiPers = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDirettiPers != null )
				soggettiDirettiPers = soggettiUtilService.filtraSoloSoggettiMisPers(soggettiDirettiPers, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDirettiPers", utility.creaComboSoggetti(soggettiDirettiPers));
		}

		if (visualizzaFiltro) {
			modelMap.addAttribute("categorie", getCategorieBene(attoForm));
			modelMap.addAttribute("sottocategorie", getSottoCategorieBene(attoForm));

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDiretti = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDiretti != null )
				soggettiDiretti = soggettiUtilService.filtraSoloSoggettiMisPatr(soggettiDiretti, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDiretti", utility.creaComboSoggetti(soggettiDiretti));

			List<SoggettoForm> soggettiTitolari = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_TITOLARI, Constants.Flag.S);
			if (soggettiTitolari != null )
				modelMap.addAttribute("soggettiTitolari", utility.creaComboSoggetti(soggettiTitolari));
		}

		if (idSoggettoDirettoPers > 0 ) {
			soggettiUtilService.soggettiMisurePersonaliFiltrati(request, modelMap, idSoggettoDirettoPers);
		}
		else {
			soggettiUtilService.soggettiMisurePersonali(request, modelMap);
		}

		if (idSoggettoDiretto > 0 || idSoggettoTitolare > 0 || idTipologia > 0 || idCategoria > 0 || idSottocategoria > 0 )
			beniDefinitivitaUtilService.beniDefinitivaFiltrati(request, modelMap, result, super.printMethodName(), idSoggettoDiretto, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
		else
			beniDefinitivitaUtilService.beniDefinitiva(request, modelMap, result, super.printMethodName());

		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

		List<BeneSoggettoForm> risultatiRicerca = (List<BeneSoggettoForm>) modelMap.get("risultatiRicerca");
		List<BeneSoggettoForm> risultatiRicercaSogg = (List<BeneSoggettoForm>) modelMap.get("risultatiRicercaSogg");

		// controllo disabilitazione definitività
		boolean disableDefinitivita = true;
		if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento) {
			for (int i = 0; risultatiRicerca != null && i < risultatiRicerca.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
				if (beneSogg != null) {
					List<SoggettoForm> soggetti = beneSogg.getSoggetti();
					if (soggetti != null)
						for (int j = 0; j < soggetti.size(); j++) {
							SoggettoForm sogg = soggetti.get(j);
							if (!sogg.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}

			for (int i = 0; risultatiRicercaSogg != null && i < risultatiRicercaSogg.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicercaSogg.get(i);
				if (beneSogg != null) {
					List<MisuraForm> misure = beneSogg.getMisure();
					if (misure != null)
						for (int j = 0; j < misure.size(); j++) {
							MisuraForm mis = misure.get(j);
							if (!mis.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}
		}
		//

		modelMap.addAttribute("disableDefinitività", disableDefinitivita);

		return "/procedimento/atto/copertinaDefinitivita";
	}

	@RequestMapping(value = {"/procedimento/atto/postDefinitivitaDecisorioIIGrado.htm" }, method = RequestMethod.POST)
	public String postDefinitivitaDecisorioIIGrado(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		ComboForm sogDirettiPers = attoForm.getSoggettiDirettiPers();
		ComboForm sogDiretti = attoForm.getSoggettiDiretti();

		ComboForm sogTitolari = attoForm.getSoggettiTitolari();
		ComboForm tipBene = attoForm.getTipologiaBene();
		ComboForm catBene = attoForm.getCategoriaBene();
		ComboForm sotcatBene = attoForm.getSottoCategoriaBene();

		boolean visualizzaFiltro = attoForm.isVisualizzaFiltro();
		boolean visualizzaFiltroPers = attoForm.isVisualizzaFiltroPers();

		if (!visualizzaFiltroPers) {
			attoForm.setSoggettiDirettiPers(null);
		}

		if (!visualizzaFiltro) {
			attoForm.setSoggettiDiretti(null);
			attoForm.setSoggettiTitolari(null);
			attoForm.setTipologiaBene(null);
			attoForm.setCategoriaBene(null);
			attoForm.setSottoCategoriaBene(null);
		}

		long idSoggettoDirettoPers = attoForm.getIdSoggettoDirettoPers();
		long idSoggettoDiretto = attoForm.getIdSoggettoDiretto();
		long idSoggettoTitolare = attoForm.getIdSoggettoTitolare();
		long idTipologia = attoForm.getIdTipologia();
		long idCategoria = attoForm.getIdCategoria();
		long idSottocategoria = attoForm.getIdSottocategoria();


		attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		attoForm.setVisualizzaFiltro(visualizzaFiltro);
		attoForm.setVisualizzaFiltroPers(visualizzaFiltroPers);

		attoForm.setSoggettiDirettiPers(sogDirettiPers);
		attoForm.setSoggettiDiretti(sogDiretti);
		attoForm.setSoggettiTitolari(sogTitolari);
		attoForm.setTipologiaBene(tipBene);
		attoForm.setCategoriaBene(catBene);
		attoForm.setSottoCategoriaBene(sotcatBene);

		modelMap.addAttribute("attoForm", attoForm);


		if (visualizzaFiltroPers) {

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDirettiPers = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDirettiPers != null )
				soggettiDirettiPers = soggettiUtilService.filtraSoloSoggettiMisPers(soggettiDirettiPers, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDirettiPers", utility.creaComboSoggetti(soggettiDirettiPers));
		}

		if (visualizzaFiltro) {
			modelMap.addAttribute("categorie", getCategorieBene(attoForm));
			modelMap.addAttribute("sottocategorie", getSottoCategorieBene(attoForm));

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDiretti = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDiretti != null )
				soggettiDiretti = soggettiUtilService.filtraSoloSoggettiMisPatr(soggettiDiretti, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDiretti", utility.creaComboSoggetti(soggettiDiretti));

			List<SoggettoForm> soggettiTitolari = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_TITOLARI, Constants.Flag.S);
			if (soggettiTitolari != null )
				modelMap.addAttribute("soggettiTitolari", utility.creaComboSoggetti(soggettiTitolari));
		}
//---

		if (idSoggettoDirettoPers > 0 ) {
			soggettiUtilService.soggettiMisurePersonaliFiltrati(request, modelMap, idSoggettoDirettoPers);
		}
		else {
			soggettiUtilService.soggettiMisurePersonali(request, modelMap);
		}

		if (idSoggettoDiretto > 0 || idSoggettoTitolare > 0 || idTipologia > 0 || idCategoria > 0 || idSottocategoria > 0 )
			beniDefinitivitaUtilService.beniDefinitivaIIGradoFiltrati(request, modelMap, result, super.printMethodName(), idSoggettoDiretto, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
		else
			beniDefinitivitaUtilService.beniDefinitivaIIGrado(request, modelMap, result, super.printMethodName());

		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

		List<BeneSoggettoForm> risultatiRicerca = (List<BeneSoggettoForm>) modelMap.get("risultatiRicerca");
		List<BeneSoggettoForm> risultatiRicercaSogg = (List<BeneSoggettoForm>) modelMap.get("risultatiRicercaSogg");

		// controllo disabilitazione definitività
		boolean disableDefinitivita = true;
		if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento) {
			for (int i = 0; risultatiRicerca != null && i < risultatiRicerca.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
				if (beneSogg != null) {
					List<SoggettoForm> soggetti = beneSogg.getSoggetti();
					if (soggetti != null)
						for (int j = 0; j < soggetti.size(); j++) {
							SoggettoForm sogg = soggetti.get(j);
							if (!sogg.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}

			for (int i = 0; risultatiRicercaSogg != null && i < risultatiRicercaSogg.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicercaSogg.get(i);
				if (beneSogg != null) {
					List<MisuraForm> misure = beneSogg.getMisure();
					if (misure != null)
						for (int j = 0; j < misure.size(); j++) {
							MisuraForm mis = misure.get(j);
							if (!mis.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}
		}

		modelMap.addAttribute("disableDefinitività", disableDefinitivita);

		return "/procedimento/atto/copertinaDefinitivita";
	}

	@RequestMapping(value = "/procedimento/atto/visualizzaDirettiInteressati.htm", method = RequestMethod.POST, params = { "RevocaDefinitivita" })
	public String revocaDefinitivitaDecisorio(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long IdAtto = 0l;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			IdAtto = attoForm.getCodAtto();
		else
			IdAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, IdAtto, codiceUtente, idProcedimento, request, attoForm);
		modelMap.addAttribute("attoForm", attoForm);

		soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivita(request, modelMap);

		beniDefinitivitaUtilService.beniRevocaDefinitiva(request, modelMap, result, super.printMethodName());

		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

		List<BeneSoggettoForm> risultatiRicerca = (List<BeneSoggettoForm>) modelMap.get("risultatiRicerca");
		List<BeneSoggettoForm> risultatiRicercaSogg = (List<BeneSoggettoForm>) modelMap.get("risultatiRicercaSogg");

		boolean noMisurePresenti = false;

		if (((risultatiRicerca == null) || risultatiRicerca.isEmpty()) && ((risultatiRicercaSogg == null) || (risultatiRicercaSogg.isEmpty())))
			noMisurePresenti = true;
		if (noMisurePresenti) {
			super.setMessage(Constants.MESSAGE, "error.atto.revocadefinitivita.select", null, false);
			result.reject(Constants.MESSAGE);
			//return copertinaAtto(new AttoForm(), result, request, modelMap);
			return copertinaAtto(attoForm, result, request, modelMap);//Segnalazione EMS-29
		}

		// controllo disabilitazione definitività
		boolean disableDefinitivita = true;
		if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento) {
			for (int i = 0; risultatiRicerca != null && i < risultatiRicerca.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
				if (beneSogg != null) {
					List<SoggettoForm> soggetti = beneSogg.getSoggetti();
					if (soggetti != null)
						for (int j = 0; j < soggetti.size(); j++) {
							SoggettoForm sogg = soggetti.get(j);
							if (!sogg.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}

			for (int i = 0; risultatiRicercaSogg != null && i < risultatiRicercaSogg.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicercaSogg.get(i);
				if (beneSogg != null) {
					List<MisuraForm> misure = beneSogg.getMisure();
					if (misure != null)
						for (int j = 0; j < misure.size(); j++) {
							MisuraForm mis = misure.get(j);
							if (!mis.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}
		}
		//

		modelMap.addAttribute("disableDefinitività", disableDefinitivita);
		MenuController.caricaMenu("15", request);
		return "/procedimento/atto/copertinaRevocaDefinitivita";
	}

	@RequestMapping(value = { "/procedimento/atto/definitivitaRevoca.htm" }, method = RequestMethod.POST, params = { "Salva" })
	public String salvaDefinitivitaRevocaDecisorio(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap) {

		return gestioneRevocaDefinitivita(beneSoggettoForm, result, request, response, modelMap, "salva");
	}

	@RequestMapping(value = { "/procedimento/atto/definitivitaRevoca.htm" }, method = RequestMethod.POST, params = { "ConfermaInviaDefinitivita" })
	public String confermaDefinitivitaRevocaDecisorio(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap) {

		return gestioneRevocaDefinitivita(beneSoggettoForm, result, request, response, modelMap, "cfInvia");
	}

	private String gestioneRevocaDefinitivita(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap, String tipoOpDefinitivita) {

		Integer idUfficioUtente = (Integer) request.getSession().getAttribute("idUffOwner");
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		List<BeneForm> misurePatrimoniali = beneSoggettoForm.estrapolaListaBeniConIdSoggettiCheckati();
		List<SoggettoForm> misurePersonali = beneSoggettoForm.estrapolaListaSoggettiMisPersConIdCheckati();
		AttoForm attoForm = attoUtilService.caricaAttoInSessione(idUfficioUtente.intValue(), idAtto, codUtente, idProcedimento, request, new AttoForm());

		// modifica perche' senza data di definitivita
		boolean errore = attoValidation.validateSceltaListaMisureRevocaDefinitivita(tipoOpDefinitivita, attoForm, beneSoggettoForm,
				misurePatrimoniali, misurePersonali, result, request);

		if (errore)
			return revocaDefinitivitaDecisorio(new AttoForm(), beneSoggettoForm, result, modelMap, request);
		// Non ho errori sulla Validazione
		// Solo se è presente la Data Definitività vuol dire che ho selezionato
		// almeno una misura e devo passare prima per il salva (anche nel caso
		// del ConfInvia)
		attoService.revocaDefinitivitaAttoRegistratoSalva(misurePatrimoniali, misurePersonali, idProcedimento, idUfficioUtente, idAtto, codUtente,
				tipoOpDefinitivita, "I_GRADO", super.printMethodName());
		String idTipoFasc = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getTipoFascicolo().getId();
//		String abilFascGest = configParameterSource.getMessage("ABIL_FASC_GEST", null, null);

		if(idTipoFasc.equals(""+Constants.TIPO_FASCICOLO_MERITO)) {
			//verifica fascicolo gestione -------
			HashMap fascGestione = commonService.getFascicoloGestione(idProcedimento, idUfficioUtente, codUtente);
			if(fascGestione!=null) {
				Long idProcGest = (Long) fascGestione.get("idProcGest");
				Long idUffRic = (Long) fascGestione.get("idUffRic");
				if(idProcGest!=null && idUffRic!=null && idProcGest>0 && idUffRic>0)
					attoService.revocaDefinitivitaFascGestAttoRegistratoSalva(misurePatrimoniali, idProcGest, Integer.valueOf(""+idUffRic), idAtto, codUtente,
							tipoOpDefinitivita, "I_GRADO", super.printMethodName());
			}
			//fine verifica fascicolo gestione -------
		}

		if (tipoOpDefinitivita.equals("salva"))
			return revocaDefinitivitaDecisorio(new AttoForm(), beneSoggettoForm, result, modelMap, request);
		else {
			attoService.revocaDefinitivitaInvio(idProcedimento, idUfficioUtente, idAtto, codUtente, "I_GRADO", super.printMethodName());
			super.setMessage(SUCCESS_MESSAGE, "succes.invio.generic", null, false);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}
	}



