	@RequestMapping(value = "/procedimento/atti/nuovo.htm", method = RequestMethod.POST, params = { "SelezionatoDecisorioIIGrado" })
	private String nuovoRicorsoInCassazione(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento().longValue();
		int idUffOwn = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		long tipoProc = Long.parseLong(procedimento.getTipoProcedimento().getId());

		long codAttoOrigine = Long.parseLong(attoForm.getDecisorioIIGrado().getId());
		long IdAtto = attoService.salvaAttoRicorso(idUffOwn, idProcedimento, codiceUtente, attoForm, Constants.STATOATTO_IN_LAVORAZIONE,
				codAttoOrigine);

		attoForm = this.attoUtilService.caricaAttoInSessione(idUffOwn, IdAtto, codiceUtente, idProcedimento, request, attoForm);

		attoForm.setCodAtto(IdAtto);
		attoForm.setIdProcedimento(idProcedimento);
		List<SoggettoStralcioForm> listaRicorso = null;

		int catAtto = 0;
		if (attoForm.getCategoriaAtto() != null && attoForm.getCategoriaAtto().getId() != null)
			catAtto = Integer.parseInt(attoForm.getCategoriaAtto().getId());
		else
			catAtto = Integer.parseInt(((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId());

		// controllo che ci sia il decisorio di 2° grado registrato PG
		/* SS13 come richiesto da Enrica Santacroce  viene tolto il controllo per l'inserimento del ricorso in cassazione

		KeyMessageDto ritornoDb = commonService.controllaInvioProcuraPG(idProcedimento, idUffOwn, codiceUtente, "RICORSO_CASSAZIONE", super.printMethodName());

		if (ritornoDb.isError()) {

			attoService.cancellaAtto(idUffOwn, IdAtto, codiceUtente, super.printMethodName());
			super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
			// svuoto il form
			if (request.getSession().getAttribute(Constants.ATTO) != null) {
				request.getSession().removeAttribute(Constants.ATTO);
				request.getSession().setAttribute(Constants.ATTO, new AttoForm());
			}

			modelMap.addAttribute("categoria", this.categoria);
			return "/procedimento/atto/nuovoAtto";
		}*/

		if (tipoProc != Constants.TIPOPROC_LIQUIDAZIONE_COMPENSI_AMM_CAM) {

			listaRicorso = attoService.getRicercaMisureAtto(idProcedimento, idUffOwn, attoForm, null, catAtto);

			if (listaRicorso == null || listaRicorso.isEmpty()) {
				attoService.cancellaAtto(idUffOwn, IdAtto, codiceUtente, super.printMethodName());
				super.setMessage(Constants.MESSAGE, "error.apri.ricorso", null, false);
				// svuoto il form
				if (request.getSession().getAttribute(Constants.ATTO) != null) {
					request.getSession().removeAttribute(Constants.ATTO);
					request.getSession().setAttribute(Constants.ATTO, new AttoForm());
				}

				modelMap.addAttribute("categoria", this.categoria);
				return "/procedimento/atto/nuovoAtto";
			}

			modelMap.addAttribute("listaRicorso", listaRicorso);
			return comboUtilComponent.impostaCombo(attoForm, result, request, modelMap,"CASSAZIONE");
		}
		return riepilogoRicorsoCassazione(attoForm, result, modelMap, request);
	}

	@RequestMapping(value = "/procedimento/atto/copertinaRicorsoInCassazione.htm", method = RequestMethod.POST)
	private String postRicorsoInCassazione(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento().longValue();
		attoForm.setIdProcedimento(idProcedimento);
		int idUffOwn = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();

		long idAtto = 0l;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			idAtto = attoForm.getCodAtto();
		else {
			idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		}

		// rimetto i dati dell'atto
		AttoForm attoFormDati = this.attoService.dettaglioAtto(idUffOwn, idAtto, idProcedimento, codiceUtente);
		attoFormDati.setVisualizzaFiltro(attoForm.isVisualizzaFiltro());
		attoFormDati.setIdSoggettoDiretto(attoForm.getIdSoggettoDiretto());
		attoFormDati.setIdSoggettoTitolare(attoForm.getIdSoggettoTitolare());
		attoFormDati.setIdTipologia(attoForm.getIdTipologia());
		attoFormDati.setIdCategoria(attoForm.getIdCategoria());
		attoFormDati.setIdSottocategoria(attoForm.getIdSottocategoria());
		attoFormDati.setTipoMisure(attoForm.getTipoMisure());
		attoFormDati.setSoggettiDirettiFiltro(attoForm.getSoggettiDirettiFiltro());
		attoFormDati.setSoggettiTitolariFiltro(attoForm.getSoggettiTitolariFiltro());
		attoFormDati.setTipologiaBene(attoForm.getTipologiaBene());
		attoFormDati.setCategoriaBene(attoForm.getCategoriaBene());
		attoFormDati.setSottoCategoriaBene(attoForm.getSottoCategoriaBene());
		attoForm = attoFormDati;

		ComboForm statoAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getStatoAtto();
		attoForm.setStatoAtto(statoAtto);

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);


		updateViewAndMenu(procedimento, request);
		// MenuController.caricaMenu("15", request);
		ricorsoUtilService.caricaRicorsoCassazione(idProcedimento, idUffOwn, idAtto, attoForm, modelMap, request);

		long conta = attoService.contaInvioMsgCassazione(idProcedimento, idAtto, idUffOwn);
		attoForm.setPulsanteInviaRicorsoInCassazione("S");
		if (conta >0l){
			attoForm.setPulsanteInviaRicorsoInCassazione("N");
		}


		modelMap.addAttribute("attoForm", attoForm);


		return "/procedimento/atto/copertinaRicorsoInCassazione";

	}

