	@RequestMapping(value = "/procedimento/atto/decretoProrogaSequestro.htm", method = RequestMethod.POST, params = { "SelezionaDecreto" })
	public String inserisciDecretoProrogaSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return nuovoDecretoProrogaSequestro(attoForm, result, request, modelMap);
		}

		long idAtto = attoService.inserisciAttoDecretoProrogaSequestro(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());
		// attoForm.setCodAtto(idAtto);
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(
				procedimento.getIdProcedimento(), idAtto, idUffOwn);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);
		//List<BeneForm> beni = beneService.listaBeniPerProcedimentoNoAttoPerProrogaSequestro(idAtto, procedimento.getIdProcedimento(), codUtente, idUffOwn, super.printMethodName());
		//modelMap.addAttribute("beni", beni);

		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoProrogaSequestro";
	}

	@RequestMapping(value = "/procedimento/atto/decretoProrogaSequestro.htm", method = RequestMethod.POST, params = { "Invia" })
	public String inviaDecretoProrogaSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

		beniDecretoUtilService.beniDecretoProrogaSequestro(attoForm,request, modelMap, result, super.printMethodName());

		// INIZIA GESTIONE DOCUMENTALE
		//validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE
		attoValidation.validateAttoDate(attoForm, result, request);

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/copertinaDecretoProrogaSequestro";
		}
		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		attoForm.setDataRegistrazione(new Date());
		attoService.inviaAttoDecretoProrogaSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
				super.printMethodName());

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE
		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/copertinaDecretoProrogaSequestro";
	}

	@RequestMapping(value = "/procedimento/atto/decretoProrogaSequestro.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String salvaDecretoProrogaSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

		beniDecretoUtilService.beniDecretoProrogaSequestro(attoForm,request, modelMap, result, super.printMethodName());

		// INIZIA GESTIONE DOCUMENTALE
		if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)){
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return "/procedimento/atto/copertinaDecretoProrogaSequestro";
			}
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateAttoDateSalva(attoForm, result, request);

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/copertinaDecretoProrogaSequestro";
		}

		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		attoForm.setDataRegistrazione(null);

		attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);
		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		return "/procedimento/atto/copertinaDecretoProrogaSequestro";
	}

