	@RequestMapping(value = "/procedimento/atto/decretoSospensioneTemporanea.htm", method = RequestMethod.POST, params = { "Invia" })
	public String inviaDecretoSospensioneTemporanea(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

//---
//--- recupero il flag AllegatoObbligatorio
//---
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);

		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());
//---

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE
		attoValidation.validateAttoDate(attoForm, result, request);
		beniDecretoUtilService.beniDecretoSospensioneTemporanea(attoForm,request, modelMap, result, super.printMethodName());

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/copertinaDecretoSospensioneTemporanea";
		}

		// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		List<MagistratoForm> magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUffOwn, idAtto, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
		List<MagistratoForm> magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUffOwn, idProcedimento, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
		// se non C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO vuol dire che sto registrando il primo sequestro, mando il messaggio Giudice Delegato obbligatorio.
		if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
			&& (magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))){
			modelMap.addAttribute("attoForm", attoForm);
			super.setMessage(Constants.MESSAGE,"magistrato.error.giudiceDelegato.registrazioneAtto",null,false);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}
		//
		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		attoForm.setDataRegistrazione(new Date());
		attoService.inviaAttoDecretoSospensioneTemporanea(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
				super.printMethodName());

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/copertinaDecretoSospensioneTemporanea";
	}

	@RequestMapping(value = "/procedimento/atto/decretoSospensioneTemporanea.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String salvaDecretoSospensioneTemporanea(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

//		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

//---
//--- recupero il flag AllegatoObbligatorio
//---
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);

		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());
//---

		// INIZIA GESTIONE DOCUMENTALE
		if (allegatoFirmaUtilService.validaAllegatoEDateIncompleti(attoForm, result, request)){
				attoForm.setDataRegistrazione(null);
				request.removeAttribute(Constants.SUCCESS_MESSAGE);
				return "/procedimento/atto/copertinaDecretoSospensioneTemporanea";
			}
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateAttoDateSalva(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return "/procedimento/atto/copertinaDecretoSospensioneTemporanea";
		}

		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		attoForm.setDataRegistrazione(null);

		attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		return "/procedimento/atto/copertinaDecretoSospensioneTemporanea";
	}

	public String nuovoDecretoProrogaSospensioneTemporanea(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		//String categoriaAttoSeq = null;

		//categoriaAttoSeq = Constants.DECRETO_SOSPENSIONE_TEMP_TRIB;

		List<AttoForm> listaSequestri = attoService.getAttiSospensioneTemporanea(procedimento.getIdProcedimento(), idUffOwn);

		List<ComboForm> listaDecretiCombo = new ArrayList<ComboForm>();
		Iterator<AttoForm> iterSeq = listaSequestri.iterator();
		while (iterSeq.hasNext()) {
			String descrizione = "";
			ComboForm combo = new ComboForm();
			AttoForm decreto = iterSeq.next();
			String numAttoView = "";

			if (Utility.isTDecretoRecord(decreto.getTipoAtto().getId())) {
				Criterion c1 = Restrictions.eq("id.codiKIdDecreto", decreto.getCodAtto());
				Criterion c2 = Restrictions.eq("id.codiKIdUffOwner", idUffOwn);
				Object obj = attoService.getAttoByPrimaryKey(TDecreto.class, c1, c2);
				if (obj != null) {
					TDecreto ist = (TDecreto) obj;
					numAttoView = AttoServiceImpl.builNumeroAttoView(ist);
					decreto.setNumeroAtto(numAttoView);
				}
			}

			if (decreto.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)) {
				descrizione = numAttoView + " depositato il " + Utility.convertDateToString(decreto.getDataDeposito());
				combo.setId("" + decreto.getCodAtto());
				combo.setDescrizione(descrizione);
				listaDecretiCombo.add(combo);
			}
		}

		if (!Utility.isDefinito(listaDecretiCombo)) {
			super.setMessage(Constants.MESSAGE, "atto.decreto.prorogaSospensioneTemporanea.noDecretiSospensione", null, false);
			return "/procedimento/atto/nuovoAtto";
		}

		modelMap.addAttribute("attoForm", attoForm);
		modelMap.addAttribute("listaDecreti", listaDecretiCombo);
		return "/procedimento/atto/copertinaDecretoProrogaSospensioneTemporanea";
	}

	@RequestMapping(value = "/procedimento/atto/decretoProrogaSospensioneTemporanea.htm", method = RequestMethod.POST, params = { "SelezionaDecreto" })
	public String inserisciDecretoProrogaSospensioneTemporanea(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return nuovoDecretoProrogaSequestro(attoForm, result, request, modelMap);
		}

		long idAtto = attoService.inserisciAttoDecretoProrogaSospensioneTemporanea(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());
		// attoForm.setCodAtto(idAtto);
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(
				procedimento.getIdProcedimento(), idAtto, idUffOwn);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);
		//List<BeneForm> beni = beneService.listaBeniPerProcedimentoNoAttoPerProrogaSequestro(idAtto, procedimento.getIdProcedimento(), codUtente, idUffOwn, super.printMethodName());
		//modelMap.addAttribute("beni", beni);

		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoProrogaSospensioneTemporanea";
	}

