	public String nuovoDecretoRevocaApplicazioneProvvisoria(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();

		List<AttoForm> listaDecreti = attoService.getAttiDecretoApplicazioneProvvisoria(procedimento.getIdProcedimento(), idUffOwn);

		List<ComboForm> listaDecretiCombo = new ArrayList<ComboForm>();
		Iterator<AttoForm> iterSeq = listaDecreti.iterator();
		while (iterSeq.hasNext()) {
			String descrizione = "";
			ComboForm combo = new ComboForm();
			AttoForm decreto = iterSeq.next();
			String numAttoView = "";

			if (Utility.isTDecretoRecord(decreto.getTipoAtto().getId())) {

				Criterion c1 = Restrictions.eq("id.codiKIdDecreto", decreto.getCodAtto());
				Criterion c2 = Restrictions.eq("id.codiKIdUffOwner", idUffOwn);
				Object obj = attoService.getAttoByPrimaryKey(TDecreto.class, c1, c2);
				if (obj != null) {
					TDecreto ist = (TDecreto) obj;
					numAttoView = AttoServiceImpl.builNumeroAttoView(ist);
					decreto.setNumeroAtto(numAttoView);
				}
			}

			if (decreto.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)) {
				descrizione = numAttoView + " depositato il " + Utility.convertDateToString(decreto.getDataDeposito());
				combo.setId("" + decreto.getCodAtto());
				combo.setDescrizione(descrizione);
				listaDecretiCombo.add(combo);
			}
		}

		if (!Utility.isDefinito(listaDecretiCombo)) {
			super.setMessage(Constants.MESSAGE, "atto.decreto.revocaApplicazioneProvvisoria.noDecreti", null, false);
			return "/procedimento/atto/nuovoAtto";
		}

		modelMap.addAttribute("attoForm", attoForm);
		modelMap.addAttribute("listaDecreti", listaDecretiCombo);
		return "/procedimento/atto/copertinaDecretoRevocaApplicazioneProvvisoria";
	}

	@RequestMapping(value = "/procedimento/atto/decretoRevocaApplicazioneProvvisoria.htm", method = RequestMethod.POST, params = { "SelezionaDecreto" })
	public String inserisciDecretoRevocaApplicazioneProvvisoria(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();

		long idAttoOrigine = attoForm.getCodAtto();

		attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
		if (result.hasErrors()) {
			attoForm.setCodAtto(0);
			return nuovoDecretoRevocaApplicazioneProvvisoria(attoForm, result, request, modelMap);
		}

		long idAtto = attoService.inserisciAttoDecretoRevocaApplicazioneProvvisoria(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);


		return misuraDecretoRevocaApplicazioneProvvisoria(attoForm, result, modelMap, request);
	}

	@SuppressWarnings("unused")
	@RequestMapping(value = "/procedimento/atto/misuraDecretoRevocaApplicazioneProvvisoria.htm", method = RequestMethod.POST, params = { "MisuraApplicazioneProvvisoria" })
	public String misuraDecretoRevocaApplicazioneProvvisoria(AttoForm attoForm, BindingResult result, ModelMap modelMap,
			HttpServletRequest request) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		Integer idUfficio = recuperaIdUfficioUtente();
		String codiceUtente = recuperaIdCodiceUtente();
		Long idProcedimento = recuperaIdProcedimento();
		long idAtto = 0l;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			idAtto = attoForm.getCodAtto();
		else
			idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();

		Long idProcedimentoCda = attoForm.getIdProcedimentoCda();

		// vado a controllare se c'e' nell'atto
		if (idProcedimentoCda == null || idProcedimentoCda == 0) {

			attoForm.setIdProcedimentoCda(((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getIdProcedimentoCda());
			idProcedimentoCda = attoForm.getIdProcedimentoCda();

			AttoForm atto = recuperaAtto();
			if (atto != null) {
				atto.setIdProcedimentoCda(null);
				request.getSession().setAttribute("atto", atto);
			}
		}

		if (attoForm.getIdProcedimentoCda() != null && attoForm.getIdProcedimentoCda() > 0) {
			idUffOwn = Integer.parseInt(commonService.getUfficiCompetenza(idProcedimento, 19L).get(0).getId());
			idProcedimento = attoForm.getIdProcedimentoCda();
		}

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, idProcedimento, request, attoForm);

		if (idProcedimentoCda != null && idProcedimentoCda > 0)
			attoForm.setIdProcedimentoCda(idProcedimentoCda);

		List attiOrigine = attoService.getRelAtti(0, 0, attoForm.getCodAtto(), idUffOwn, recuperaIdCodiceUtente().toString(), super.printMethodName());
		Map mapAttoOrigine = (Map)attiOrigine.get(0);
		TRelAtti relAtto = (TRelAtti)mapAttoOrigine.get("relAtti");
		long idAttoOrigine = relAtto.getId().getCodiKIdAttoOr();
		SoggettoForm soggettoForm = new SoggettoForm();
		List<Long> risultatiRicercaSogg;
		if (idProcedimentoCda != null && idProcedimentoCda > 0) {
			risultatiRicercaSogg = procedimentoService.listaSoggettiMisurePersAtto(idProcedimentoCda, idAttoOrigine, idUffOwn);
		} else {
			risultatiRicercaSogg = procedimentoService.listaSoggettiMisurePersAtto(procedimento.getIdProcedimento(),
				idAttoOrigine, idUffOwn);
		}

		Long idSoggetto = risultatiRicercaSogg.get(0);

		List<SoggettoForm> soggetti;
		if (idProcedimentoCda != null && idProcedimentoCda > 0) {
			soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(idProcedimentoCda);
		} else {
			soggetti = procedimentoService.soggettiDirettiInteressatiDelProcedimento(procedimento.getIdProcedimento());
		}

		for(int i=0;i<soggetti.size();i++) {
			SoggettoForm soggTemp = soggetti.get(i);
			if(soggTemp.getIdSoggetto().longValue() == idSoggetto.longValue()) soggettoForm = soggTemp;
		}

		soggettoForm.setSchermataDiProvenienza("copertinaDecretoRevocaApplicazioneProvvisoria");

		soggettoForm.setMisura(new MisuraForm());
		if (idProcedimentoCda != null && idProcedimentoCda > 0) {
			soggettoForm.setIdUfficio(idUffOwn);
			soggettoForm.setIdProcedimento(idProcedimentoCda);
			soggettoForm.setIdAtto(0L);
		} else {
			soggettoForm.setIdUfficio(idUfficio);
			soggettoForm.setIdProcedimento(procedimento.getIdProcedimento());
			soggettoForm.setIdAtto(0L);
		}

		soggettoForm = misuraService.caricaMisuraPersonale(soggettoForm);

		//
		SoggettoForm soggettoOrigine = new SoggettoForm();
		soggettoOrigine.setMisura(new MisuraForm());

		if (idProcedimentoCda != null && idProcedimentoCda > 0) {
			soggettoOrigine.setIdUfficio(idUffOwn);
			soggettoOrigine.setIdProcedimento(idProcedimentoCda);
			soggettoOrigine.setIdAtto(new Long(idAttoOrigine));
		} else {
			soggettoOrigine.setIdUfficio(idUfficio);
			soggettoOrigine.setIdProcedimento(procedimento.getIdProcedimento());
			soggettoOrigine.setIdAtto(new Long(idAttoOrigine));
		}

		soggettoOrigine.setIdSoggetto(soggettoForm.getIdSoggetto());
		soggettoOrigine = misuraService.caricaMisuraPersonale(soggettoOrigine);
		modelMap.addAttribute("soggettoOrigine", soggettoOrigine);
		//
		soggettoForm = procedimentoService.caricaValoriDettaglioSoggettoFisicoProcedimento(soggettoForm);
		soggettoForm.setTipoSoggetto(Constants.SOGGETTO_FISICO);

		soggettoForm.setTipologiaPrevenzioneDb(soggettoForm.getTipologiaPrevenzione());


		attoForm.setSoggetto(soggettoForm);

		//Carico nel ModelAndView le Normative
		soggettoController.caricaNormative(soggettoForm, null, modelMap);
		List<ComboForm> list = commonService.listaPrescrizioniMisuraPersonale();
		modelMap.addAttribute("listaPrescrizioni", list);
		modelMap.addAttribute("attoForm", attoForm);

		if(soggettoOrigine!=null)
			if(soggettoForm.getMisura().getTipoMisura()!=null && commonService.localitaObbligatoriaNelTipoMisuraSelezionato(Long.parseLong(soggettoForm.getMisura().getTipoMisura().getId()),"AP"))
				soggettoForm.getMisura().setLocalita(soggettoOrigine.getMisura().getLocalita());
			else
				soggettoForm.getMisura().setLocalita(null);
		// variabile booleana per la gestione della funzionalità di 'Indietro'

		if (idProcedimentoCda != null && idProcedimentoCda > 0) {
			addBreadcrumbs("GET", "/procedimento/atti/elencoAttiTribunale.htm", null);
			addBreadcrumbs("POST", "procedimento/atto/copertinaAtto.htm", null);
		} else {
			addBreadcrumbs("POST", "/procedimento/atti/elencoAttiOrdineCronologico.htm", null);
			addBreadcrumbs("POST", "procedimento/atto/copertinaAtto.htm", null);
		}

		MenuController.caricaMenu("124", request);

		return "procedimento/atto/copertinaDecretoRevocaApplicazioneProvvisoria";
	}

