	@RequestMapping(value = "/procedimento/atto/dettaglioAtto.htm", method = RequestMethod.POST, params = { "Invia" })
	public String aggiornaCorrezioneErroreMateriale(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, ModelMap modelMap,
			HttpServletRequest request) {

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirma(attoForm, result, request);
		allegatoFirmaUtilService.validaAllegatoEFirmaAttoCorrezioneErroreMateriale(attoForm, result, request);
		if (result.hasErrors()) {
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return beniDecretoUtilService.beneCorrezioneErroreMateriale(request,modelMap,result, "");
		}
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateSalvaCorrezioneErroreMateriale(attoForm, result, request);
		if (result.hasErrors()) {

			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return beniDecretoUtilService.beneCorrezioneErroreMateriale(request,modelMap,result, "");
		}

		long idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();
		this.inizializzaDocumento(attoForm, request);
		attoForm.setDataRegistrazione(attoForm.getDataEmissione());

		long idAtto = attoService.registraAttoGenerico(idUffOwn, idProcedimento, attoForm, codUtente,
				Constants.STATOATTO_REGISTRATO, super.printMethodName());

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		attoForm = attoUtilService.caricaAttoInSessione(Integer.parseInt(""+idUffOwn), idAtto, codUtente, idProcedimento, request, attoForm);
		if (attoForm.getDataEmissione() != null)
			super.updateProcedimentoIntoSession(idProcedimento);

		// INIZIA GESTIONE DOCUMENTALE

		// FINE GESTIONE DOCUMENTALE
		// siccome questo metodo è richiamato anche da invia proposta, per non
		// sovrascrivere il messaggio di INVIO, effettuo il controllo
		// seguente...
		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "INVIO", false);

		return copertinaAtto(attoForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/dettaglioAtto.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String salvaCorrezioneErroreMateriale(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, ModelMap modelMap,
			HttpServletRequest request) {

		int idUfficio = recuperaIdUfficioUtente();
		long idProcedimento = recuperaIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = recuperaAtto().getCodAtto();

		if (allegatoFirmaUtilService.validaAllegatoEDateIncompletiCorrezioneErroreMateriale(attoForm, result, request)){
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return beniDecretoUtilService.beneCorrezioneErroreMateriale(request,modelMap,result, "");
		}

		attoValidation.validateAttoDateSalvaCorrezioneErroreMateriale(attoForm, result, request);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return beniDecretoUtilService.beneCorrezioneErroreMateriale(request,modelMap,result, "");
		}

//		attoValidation.validateSalvaCorrezioneErroreMateriale(attoForm, result, request);
//		if (result.hasErrors()) {
//			request.removeAttribute(Constants.SUCCESS_MESSAGE);
//			return beneCorrezioneErroreMateriale(request,modelMap,result, "");
//		}

		attoForm.setCodAtto(idAtto);

		inizializzaDocumento(attoForm, request);

		long idStatoAtto = Constants.STATOATTO_IN_LAVORAZIONE;

		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		attoForm.setDataRegistrazione(null);

		attoService.aggiornaAttoDecretoSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto, idProcUdi, idProcProp);

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		modelMap.addAttribute("attoForm", attoForm);

		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null)
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);

		return beniDecretoUtilService.beneCorrezioneErroreMateriale(request,modelMap,result, "");
	}

	@RequestMapping(value = "/procedimento/atto/postdefinitivitaRevocaIIGrado.htm", method = RequestMethod.POST)
	public String postrevocaDefinitivitaDecisorioIIGrado(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idCurrentAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		ComboForm sogDirettiPers = attoForm.getSoggettiDirettiPers();
		ComboForm sogDiretti = attoForm.getSoggettiDiretti();

		ComboForm sogTitolari = attoForm.getSoggettiTitolari();
		ComboForm tipBene = attoForm.getTipologiaBene();
		ComboForm catBene = attoForm.getCategoriaBene();
		ComboForm sotcatBene = attoForm.getSottoCategoriaBene();

		boolean visualizzaFiltro = attoForm.isVisualizzaFiltro();
		boolean visualizzaFiltroPers = attoForm.isVisualizzaFiltroPers();

		if (!visualizzaFiltroPers) {
			attoForm.setSoggettiDirettiPers(null);
		}

		if (!visualizzaFiltro) {
			attoForm.setSoggettiDiretti(null);
			attoForm.setSoggettiTitolari(null);
			attoForm.setTipologiaBene(null);
			attoForm.setCategoriaBene(null);
			attoForm.setSottoCategoriaBene(null);
		}

		long idSoggettoDirettoPers = attoForm.getIdSoggettoDirettoPers();
		long idSoggettoDiretto = attoForm.getIdSoggettoDiretto();
		long idSoggettoTitolare = attoForm.getIdSoggettoTitolare();
		long idTipologia = attoForm.getIdTipologia();
		long idCategoria = attoForm.getIdCategoria();
		long idSottocategoria = attoForm.getIdSottocategoria();


		attoForm = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		attoForm.setVisualizzaFiltro(visualizzaFiltro);
		attoForm.setVisualizzaFiltroPers(visualizzaFiltroPers);

		attoForm.setSoggettiDirettiPers(sogDirettiPers);
		attoForm.setSoggettiDiretti(sogDiretti);
		attoForm.setSoggettiTitolari(sogTitolari);
		attoForm.setTipologiaBene(tipBene);
		attoForm.setCategoriaBene(catBene);
		attoForm.setSottoCategoriaBene(sotcatBene);

		modelMap.addAttribute("attoForm", attoForm);


		if (visualizzaFiltroPers) {

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDirettiPers = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDirettiPers != null )
				soggettiDirettiPers = soggettiUtilService.filtraSoloSoggettiMisPers(soggettiDirettiPers, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDirettiPers", utility.creaComboSoggetti(soggettiDirettiPers));
		}

		if (visualizzaFiltro) {
			modelMap.addAttribute("categorie", getCategorieBene(attoForm));
			modelMap.addAttribute("sottocategorie", getSottoCategorieBene(attoForm));

			// carica combo soggetti diretti e titolari se filtro = true
			List<SoggettoForm> soggettiDiretti = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_DIRETTO, Constants.Flag.S);
			if (soggettiDiretti != null )
				soggettiDiretti = soggettiUtilService.filtraSoloSoggettiMisPatr(soggettiDiretti, idProcedimento, idCurrentAtto, idUffOwn);
				modelMap.addAttribute("soggettiDiretti", utility.creaComboSoggetti(soggettiDiretti));

			List<SoggettoForm> soggettiTitolari = attoService.getRicercaSoggettoAtto(idProcedimento, idCurrentAtto, idUffOwn, Constants.ID_RUOLO_TITOLARI, Constants.Flag.S);
			if (soggettiTitolari != null )
				modelMap.addAttribute("soggettiTitolari", utility.creaComboSoggetti(soggettiTitolari));
		}
//---
		if (idSoggettoDiretto > 0
				||
			idSoggettoTitolare > 0
				||
			idTipologia > 0
				||
			idCategoria > 0
				||
			idSottocategoria > 0
				)
		{
			soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivitaIIGradoFiltrati(request, modelMap, idSoggettoDiretto);
			beniDefinitivitaUtilService.beniRevocaDefinitivaIIGradoFiltrati(request, modelMap, result, super.printMethodName(), idSoggettoDiretto, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
		}
		else {
			if (idSoggettoDirettoPers > 0
					||
				idSoggettoTitolare > 0
					||
				idTipologia > 0
					||
				idCategoria > 0
					||
				idSottocategoria > 0
					)
			{
				soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivitaIIGradoFiltrati(request, modelMap, idSoggettoDirettoPers);
				beniDefinitivitaUtilService.beniRevocaDefinitivaIIGradoFiltrati(request, modelMap, result, super.printMethodName(), idSoggettoDirettoPers, idSoggettoTitolare, idTipologia, idCategoria, idSottocategoria);
			}
			else {
				soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivitaIIGrado(request, modelMap);
				beniDefinitivitaUtilService.beniRevocaDefinitivaIIGrado(request, modelMap, result, super.printMethodName());
			}
		}

		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

		modelMap.get("risultatiRicerca");
		modelMap.get("risultatiRicercaSogg");

		return "/procedimento/atto/copertinaRevocaDefinitivitaIIGrado";
	}

	//revoca definitivita di II grado
	@RequestMapping(value = "/procedimento/atto/visualizzaDirettiInteressatiIIGrado.htm", method = RequestMethod.POST, params = { "RevocaDefinitivita" })
	public String revocaDefinitivitaDecisorioIIGrado(@ModelAttribute("attoForm") AttoForm attoForm, BeneSoggettoForm beneSoggettoForm, BindingResult result,
			ModelMap modelMap, HttpServletRequest request) {

		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long IdAtto = 0l;
		if (attoForm != null && attoForm.getCodAtto() > 0)
			IdAtto = attoForm.getCodAtto();
		else
			IdAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, IdAtto, codiceUtente, idProcedimento, request, attoForm);
		modelMap.addAttribute("attoForm", attoForm);
		soggettiUtilService.soggettiMisurePersonaliRevocaDefinitivitaIIGrado(request, modelMap);

		beniDefinitivitaUtilService.beniRevocaDefinitivaIIGrado(request, modelMap, result, super.printMethodName());

		modelMap.addAttribute("beneSoggettoForm", beneSoggettoForm);

		List<BeneSoggettoForm> risultatiRicerca = (List<BeneSoggettoForm>) modelMap.get("risultatiRicerca");
		List<BeneSoggettoForm> risultatiRicercaSogg = (List<BeneSoggettoForm>) modelMap.get("risultatiRicercaSogg");

		boolean noMisurePresenti = false;

		if (((risultatiRicerca == null) || risultatiRicerca.isEmpty()) && ((risultatiRicercaSogg == null) || (risultatiRicercaSogg.isEmpty())))
			noMisurePresenti = true;
		if (noMisurePresenti) {
			super.setMessage(Constants.MESSAGE, "error.atto.revocadefinitivita.select", null, false);
			result.reject(Constants.MESSAGE);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}

		// controllo disabilitazione definitività
		boolean disableDefinitivita = true;
		if (attoForm.getIdProcEmiss() > 0 && attoForm.getIdProcEmiss() == idProcedimento) {
			for (int i = 0; risultatiRicerca != null && i < risultatiRicerca.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicerca.get(i);
				if (beneSogg != null) {
					List<SoggettoForm> soggetti = beneSogg.getSoggetti();
					if (soggetti != null)
						for (int j = 0; j < soggetti.size(); j++) {
							SoggettoForm sogg = soggetti.get(j);
							if (!sogg.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}

			for (int i = 0; risultatiRicercaSogg != null && i < risultatiRicercaSogg.size(); i++) {
				BeneSoggettoForm beneSogg = risultatiRicercaSogg.get(i);
				if (beneSogg != null) {
					List<MisuraForm> misure = beneSogg.getMisure();
					if (misure != null)
						for (int j = 0; j < misure.size(); j++) {
							MisuraForm mis = misure.get(j);
							if (!mis.isDisabledCheckDefinitivita())
								disableDefinitivita = false;
						}
				}
			}
		}
		//

		modelMap.addAttribute("disableDefinitività", disableDefinitivita);
		MenuController.caricaMenu("15", request);
		return "/procedimento/atto/copertinaRevocaDefinitivitaIIGrado";
	}

	@RequestMapping(value = { "/procedimento/atto/definitivitaRevocaIIGrado.htm" }, method = RequestMethod.POST, params = { "Salva" })
	public String salvaDefinitivitaRevocaDecisorioIIGrado(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap) {

		return gestioneRevocaDefinitivitaIIGrado(beneSoggettoForm, result, request, response, modelMap, "salva");
	}

	@RequestMapping(value = { "/procedimento/atto/definitivitaRevocaIIGrado.htm" }, method = RequestMethod.POST, params = { "ConfermaInviaDefinitivita" })
	public String confermaDefinitivitaRevocaDecisorioIIGrado(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap) {

		return gestioneRevocaDefinitivitaIIGrado(beneSoggettoForm, result, request, response, modelMap, "cfInvia");
	}

	private String gestioneRevocaDefinitivitaIIGrado(BeneSoggettoForm beneSoggettoForm, BindingResult result, HttpServletRequest request,
			HttpServletResponse response, ModelMap modelMap, String tipoOpDefinitivita) {

		Integer idUfficioUtente = (Integer) request.getSession().getAttribute("idUffOwner");
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		List<BeneForm> misurePatrimoniali = beneSoggettoForm.estrapolaListaBeniConIdSoggettiCheckati();
		List<SoggettoForm> misurePersonali = beneSoggettoForm.estrapolaListaSoggettiMisPersConIdCheckati();
		AttoForm attoForm = attoUtilService.caricaAttoInSessione(idUfficioUtente.intValue(), idAtto, codUtente, idProcedimento, request, new AttoForm());

		// modifica perche' senza data di definitivita
		boolean errore = attoValidation.validateSceltaListaMisureRevocaDefinitivita(tipoOpDefinitivita, attoForm, beneSoggettoForm,
				misurePatrimoniali, misurePersonali, result, request);

		if (errore)
			return revocaDefinitivitaDecisorioIIGrado(new AttoForm(), beneSoggettoForm, result, modelMap, request);
		// Non ho errori sulla Validazione
		// Solo se è presente la Data Definitività vuol dire che ho selezionato
		// almeno una misura e devo passare prima per il salva (anche nel caso
		// del ConfInvia)
		attoService.revocaDefinitivitaAttoRegistratoSalva(misurePatrimoniali, misurePersonali, idProcedimento, idUfficioUtente, idAtto, codUtente,
				tipoOpDefinitivita, "I_GRADO", super.printMethodName());

		if (tipoOpDefinitivita.equals("salva"))
			return revocaDefinitivitaDecisorioIIGrado(new AttoForm(), beneSoggettoForm, result, modelMap, request);

		attoService.revocaDefinitivitaInvio(idProcedimento, idUfficioUtente, idAtto, codUtente, "I_GRADO", super.printMethodName());
		super.setMessage(SUCCESS_MESSAGE, "succes.invio.generic", null, false);
		return copertinaAtto(new AttoForm(), result, request, modelMap);
	}


