	@RequestMapping(value = "/procedimento/atto/istanzaModificaPersonali.htm", method = RequestMethod.POST, params = { "Conferma" })
	public ModelAndView aggiornaIstanzaModificaPersonali(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, ModelMap modelMap,
			HttpServletRequest request) {
		ProcedimentoForm procedimento = recuperaProcedimento();
		int idUffOwn = recuperaIdUfficioUtente();
		Long codiKIdAmministratore = null;
		String codUtente = recuperaIdCodiceUtente();

		if(attoForm.getCategoriaAtto()!=null
				&& attoForm.getCategoriaAtto().getId()!=null
					  && attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_LIQUIDAZIONE_AMM)){

			if(attoForm.getListaIdCheckbox_associati()==null || attoForm.getListaIdCheckbox_associati().isEmpty()) {
				super.setMessage(Constants.MESSAGE, "cameralini.error.selezionareBene", null, false);
				return istanzaModificaPersonaliRefresh(attoForm, result, modelMap, request);
			}

			beneService.eliminaRelProcBene(procedimento.getIdProcedimento(), 0, idUffOwn);

			AmministratoreForm amministratore = procedimentoService.getAmministratoreByIstanza(procedimento.getIdProcedimento(), attoForm.getCodAtto(), idUffOwn);
			if(amministratore != null && amministratore.getId() != null){
			  codiKIdAmministratore = amministratore.getId();
			  beneService.eliminaRelAmministratoreBeneAtto(idUffOwn, amministratore.getId(), attoForm);
			}

			if(attoForm.getListaIdCheckbox_associati()!=null && !attoForm.getListaIdCheckbox_associati().isEmpty())
				
				//F.C.
				//Ticket#202403070119 — SITMP - Errore registrazione istanza liquidazione
				//faccio il controllo se la lista dei beni associati selezionati siano duplicati
				//in modo da evitare che i due metodi beneService.associaBeneAlProcedimento e 
				//beneService.inserisciRelAmministratoreBeneAtto non restituiscano l'errore di chiave duplicata.
				attoForm.setListaIdCheckbox_associati(Utility.removeDuplicates(attoForm.getListaIdCheckbox_associati()));
			
				for(int i=0; i<attoForm.getListaIdCheckbox_associati().size();i++) {
					Long idBeneSel = attoForm.getListaIdCheckbox_associati().get(i);
					BeneForm beneForm = new BeneForm();
					beneForm.setIdBene(idBeneSel);
					beneService.associaBeneAlProcedimento(idUffOwn, codUtente, procedimento.getIdProcedimento(), beneForm);
					beneService.inserisciRelAmministratoreBeneAtto(idUffOwn, amministratore.getId(), attoForm, idBeneSel, (String) request.getSession().getAttribute(Constants.ID_CODICE_UTENTE), super.printMethodName());
				}
		}

		 int catAtto = 0;
			if (attoForm.getCategoriaAtto() != null && attoForm.getCategoriaAtto().getId() != null)
				catAtto = Integer.parseInt(attoForm.getCategoriaAtto().getId());
			else
				catAtto = Integer.parseInt(((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCategoriaAtto().getId());

			if(attoForm.getCategoriaAtto()!=null
				&& attoForm.getCategoriaAtto().getId()!=null
					  && (attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_TERZO_INTERVENIENTE)
						  || attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_MODIFICA_PATRIMONIALE))){


		List<SoggettoStralcioForm> listaRicorso1 = attoService.getRicercaMisureIstanza(procedimento.getIdProcedimento(), idUffOwn, attoForm, "R", catAtto);
		if (listaRicorso1==null || listaRicorso1.size()==0){

			super.setMessage(Constants.MESSAGE, "error.atto.datadefinitivita.select", null, false);
			return istanzaModificaPersonaliRefresh(attoForm, result, modelMap, request);
		}
	}

		if (procedimento.getTipoProcedimento() != null)
			Long.valueOf(procedimento.getTipoProcedimento().getId());

		// INIZIA GESTIONE DOCUMENTALE
		allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE*/
		 List<SoggettoStralcioForm> listaRicorso = null;


		if(!(attoForm.getCategoriaAtto()!=null && attoForm.getCategoriaAtto().getId()!=null &&
				( attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_LIQUIDAZIONE_AMM)  ||
				  attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_CORREZIONE_ERRORI_MATERIALI)
				)
		)) {
			if(attoForm.getCategoriaAtto()!=null && attoForm.getCategoriaAtto().getId()!=null && !attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_LIQUIDAZIONE_AMM))
				listaRicorso = attoService.getRicercaMisureIstanza(procedimento.getIdProcedimento(), idUffOwn, attoForm, null, catAtto);
			if (listaRicorso==null || listaRicorso.size()==0){
				super.setMessage(Constants.MESSAGE, "error.atto.datadefinitivita.select", null, false);
				return istanzaModificaPersonaliRefresh(attoForm, result, modelMap, request);
			}
		}

		if(attoForm.getCategoriaAtto()!=null && attoForm.getCategoriaAtto().getId()!=null && attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_TERZO_INTERVENIENTE))
		{
			boolean validateSelezioneBeneRegistrazioneIstanzaTerzoInterveniente = attoValidation.validateSelezioneBeneRegistrazioneIstanzaTerzoInterveniente(listaRicorso, result);
			if (validateSelezioneBeneRegistrazioneIstanzaTerzoInterveniente)
			{
				super.setMessage(Constants.MESSAGE, "atto.interveniente.sceltabeni", null, false);
				return istanzaModificaPersonaliRefresh(attoForm, result, modelMap, request);
			}
		}

		  if (attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_CAUZIONE)){
				if ( recuperaIdTipoUfficio() == Constants.TIPO_UFFICIO_PROCURA_L.intValue()) {
					modelMap.addAttribute("altroNomeTastoRegistra", "Conferma e Invia");
				}
				//controllo sulla data apertura fascicolo
				Date dataApeFasc = Utility.removeTime(procedimento.getDataApertura());
				if ((attoForm.getDataDeposito() != null) && attoForm.getDataDeposito().before(dataApeFasc)) {

					super.setMessage(Constants.MESSAGE, "error.dataApeFasc", null, false);
					return istanzaModificaPersonaliRefresh(attoForm, result, modelMap, request);
				}
			}

		String tipoUfficio = recuperaIdTipoUfficio().toString();
		if (!tipoUfficio.equals(Constants.TIPO_UFFICIO_PROCURA))
		{
			attoValidation.validateSalvaIstanzaModificaPersonale(attoForm, result, request);
		}
		else {
			attoValidation.validateSalvaIstanzaProcura(attoForm, result, request);
			ProfiloForm profilo = recuperaProfilo();
			 attoForm.getImpugnazione().setDescTipoProp(profilo.getDescrizioneUfficio() + " di " + profilo.getCitta());
		}
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return istanzaModificaPersonaliRefresh(attoForm, result, modelMap, request);
		}
		long idUffOwn2 = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
		}


		// modifiche CS (da spostare DAO)
		istanzaUtilService.correzioneErroriModIstanza(attoForm, procedimento.getIdProcedimento());


		attoForm.setCodAtto(procedimentoService.aggiornaIstanzaMP(idUffOwn2, idProcedimento, attoForm, codiKIdAmministratore, codUtente));
		if (attoForm.getDataRegistrazione() != null)
			super.updateProcedimentoIntoSession(idProcedimento);


		if (request.getAttribute(Constants.SUCCESS_MESSAGE) == null) {
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation", "MODIFICA", false);
			request.setAttribute("modifica", "modifica");
		}
		attoForm = attoUtilService.caricaAttoInSessione(Integer.parseInt(""+idUffOwn), attoForm.getCodAtto(), codUtente, idProcedimento, request, attoForm);
		return istanzaUtilService.istanzaModificaPersonali(attoForm, result,request, modelMap);
	}

