	@RequestMapping(value = "/procedimento/atto/attiIstanzaFascicoloGestione.htm", method = RequestMethod.POST)
	public String istanzaFascicoloGestione(AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		int idUffOwn = recuperaIdUfficioUtente();
		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento();
		recuperaProfilo();
		recuperaIdCodiceUtente();

		List<ComboForm> tipiProponenti = new ArrayList<ComboForm>();
		if(attoForm.getCategoriaAtto()!=null &&
				(attoForm.getCategoriaAtto().getId().equals(Constants.ISTANZA_CONTO_GESTIONE) ||
					attoForm.getCategoriaAtto().getId().equals(Constants.RICHIESTA_RINUNCIA_AMMINISTRATORI) ||
						attoForm.getCategoriaAtto().getId().equals(Constants.RELAZIONE_AMMINISTRATORE))) {
			tipiProponenti.add(new ComboForm("AMMINISTRATORE", "AMMINISTRATORE"));
			attoForm.setTipoProponente(new ComboForm("AMMINISTRATORE", "AMMINISTRATORE"));
		} else {
			tipiProponenti.add(new ComboForm("AMMINISTRATORE", "AMMINISTRATORE"));
			tipiProponenti.add(new ComboForm("ENTE", "ENTE"));
			tipiProponenti.add(new ComboForm("ALTRO", "ALTRO"));
		}

		modelMap.addAttribute("tipiProponenti", tipiProponenti);

		List<AmministratoreForm> amministratoriAssociati = beneService.getAmministratori(idUffOwn, idProcedimento, null, null, true);

		if(attoForm.getCategoriaAtto().getId().equals(Constants.RICHIESTA_RINUNCIA_AMMINISTRATORI)) {
			List<AmministratoreForm> amministratoriRinuncia = beneService.getAmministratori(idUffOwn, idProcedimento, attoForm.getCodAtto(), null, true);
			if(amministratoriRinuncia!=null && amministratoriRinuncia.size()>0) {
				AmministratoreForm amministratoreRinuncia = amministratoriRinuncia.get(0);
				attoForm.setAmministratore(new ComboForm(amministratoreRinuncia.getId().toString(), amministratoreRinuncia.getCognome() + " " + amministratoreRinuncia.getNome()));
			}
		}

		if(amministratoriAssociati!=null && amministratoriAssociati.size()>0) {
			List<ComboForm> amministratori = new ArrayList<ComboForm>();
			for(int i=0;i<amministratoriAssociati.size();i++) {
				AmministratoreForm amministratore = amministratoriAssociati.get(i);
				//amministratori.add(new ComboForm(amministratore.getId().toString(), amministratore.getCognome() + " " + amministratore.getNome()));
				if(attoForm.getCategoriaAtto().getId().equals(Constants.RICHIESTA_RINUNCIA_AMMINISTRATORI))
					amministratori.add(new ComboForm(amministratore.getId().toString(), amministratore.getCognome() + " " + amministratore.getNome()));
				else
					amministratori.add(new ComboForm(amministratore.getCognome() + "#" + amministratore.getNome(), amministratore.getCognome() + " " + amministratore.getNome()));
			}
			modelMap.addAttribute("amministratori", amministratori);
		}

		if(!attoForm.getCategoriaAtto().getId().equals(Constants.RICHIESTA_RINUNCIA_AMMINISTRATORI))
			if(attoForm.getTipoProponente()!=null && attoForm.getTipoProponente().getId().equals("AMMINISTRATORE")) {
				attoForm.setAmministratore(new ComboForm(attoForm.getCognProponente() + "#" + attoForm.getNomeProponente(), null));
				attoForm.setCognProponente(null);
				attoForm.setNomeProponente(null);;
			}

		inizializzaDocumento(attoForm, request);

		if(attoForm.getCategoriaAtto().getId().equals(Constants.RELAZIONE_AMMINISTRATORE)) {
			long idDepositoAmm = 0;
			long codAtto = attoForm.getCodAtto();
			TDepositiAmm depositoAmm = flussiService.getDepositoAmmByIdAtto(codAtto,idUffOwn);
			if(depositoAmm != null) {
			   idDepositoAmm = depositoAmm.getCodiKIdDepositoAmm();
			   FlussiToolAmministratoriForm flussoForm = new FlussiToolAmministratoriForm();

			   modelMap.addAttribute("listaBeni", flussiService.getListaBeniDeposito(flussoForm,idDepositoAmm));
			}
		}

		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/attiIstanzaFascicoloGestione";
	}

