	public String salvaIstanzaFascicoloGestione(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		return insAggIstanzaFascicoloGestione(attoForm, Constants.STATOATTO_IN_LAVORAZIONE, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/attiIstanzaFascicoloGestione.htm", method = RequestMethod.POST, params = { "Conferma" })
	public String confermaIstanzaFascicoloGestione(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		return insAggIstanzaFascicoloGestione(attoForm, Constants.STATOATTO_REGISTRATO, result, request, modelMap);
	}

	public String insAggIstanzaFascicoloGestione(AttoForm attoForm, long statoAtto, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		String categoriaAtto = attoForm.getCategoriaAtto().getId();

		// INIZIA GESTIONE DOCUMENTALE
		allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE*/

		attoValidation.validateSalvaIstanzaFascicoloGestione(attoForm, result);
		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			if(attoForm.getAllegato()!=null) {
				attoForm.getAllegato().setFileData(null);
				attoForm.getAllegato().setFileName(null);
				attoForm.getAllegato().setContentType(null);
				attoForm.getAllegato().setDocumento(null);
			}
			request.removeAttribute(Constants.SUCCESS_MESSAGE);
			return istanzaFascicoloGestione(attoForm, result, request, modelMap);
		}

		if(attoForm.getAllegato()!=null && !attoForm.getAllegato().isAllegatoRimosso())
			inizializzaDocumento(attoForm, request);
		attoForm.setDataRegistrazione(Calendar.getInstance().getTime());
		int idUffOwn = recuperaIdUfficioUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		String codUtente = recuperaIdCodiceUtente();

		if(categoriaAtto.equals(Constants.RICHIESTA_RINUNCIA_AMMINISTRATORI)) {
			long idAmministratore = new Long(attoForm.getAmministratore().getId());
			attoForm.setCodAtto(attoService.salvaIstanzaRinunciaAmministratore(idUffOwn, idProcedimento, idAmministratore, codUtente, statoAtto, Long.valueOf(attoForm.getTipoAtto().getId()), Long.valueOf(attoForm.getCategoriaAtto().getId()), attoForm, super.printMethodName()));
		} else {
			if(attoForm.getAmministratore()!=null && attoForm.getAmministratore().getId()!=null && !attoForm.getAmministratore().getId().equalsIgnoreCase(Constants.NO_ITEM_SELECTED)) {
				attoForm.setCognProponente(attoForm.getAmministratore().getId().substring(0, attoForm.getAmministratore().getId().indexOf("#")));
				attoForm.setNomeProponente(attoForm.getAmministratore().getId().substring(attoForm.getAmministratore().getId().indexOf("#")+1));
			}
			attoForm.setCodAtto(attoService.salvaIstanzaFascicoloGestione(idUffOwn, idProcedimento, codUtente, statoAtto, Long.valueOf(attoForm.getTipoAtto().getId()), Long.valueOf(attoForm.getCategoriaAtto().getId()), attoForm, super.printMethodName()));
		}

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, attoForm.getCodAtto(), codUtente, idProcedimento, request, attoForm);

		if(statoAtto == Constants.STATOATTO_REGISTRATO)
			// INIZIA GESTIONE DOCUMENTALE
			gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
			// FINE GESTIONE DOCUMENTALE

		super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);
		return copertinaAtto(attoForm, result, request, modelMap);
		//modelMap.addAttribute("attoForm", attoForm);
		//return "/procedimento/atto/attiIstanzaFascicoloGestione";

	}
	@RequestMapping(value = { "/procedimento/atti/impostaIstanza" }, method = RequestMethod.POST)
	public String impostaIstanza(@Valid AttoForm attoForm, BindingResult result,
			@RequestParam(value = "tipoRicorso", required = true) String tipoStralcio,
			@RequestParam(value = "idProcedimento", required = true) long idProcedimento,
			@RequestParam(value = "idUfficio", required = true) long idUfficio,
			@RequestParam(value = "checked", required = true) boolean checked,
			@RequestParam(value = "idSoggInt", required = true) long idSoggInt,
			@RequestParam(value = "idBene", required = false) long idBene,
			@RequestParam(value = "idSoggTit", required = false) String idSoggTit,
			@RequestParam(value = "codAtto", required = false) long idAtto,
			@RequestParam(value = "carattereMisura", required = false) String carattereMisura, ModelMap modelMap, HttpServletRequest request) {

		if (Constants.TipoMisura.PATRIMONIALE_DESCR.equalsIgnoreCase(tipoStralcio))
			attoService.impostaIstanzaMisPatr(idProcedimento, idAtto, idUfficio, checked,idSoggInt,idBene,idSoggTit,
						recuperaIdCodiceUtente(), Integer.parseInt(attoForm.getCategoriaAtto().getId()),"APPELLO");
		else if (Constants.TipoMisura.PERSONALE_DESCR.equalsIgnoreCase(tipoStralcio))
			// in questo caso l'id bene è l'id della misura personale
			attoService.impostaIstanzaMisPers(idProcedimento, idAtto, idUfficio, checked, idBene, idSoggInt, recuperaIdCodiceUtente(),
					Integer.parseInt(attoForm.getCategoriaAtto().getId()),"APPELLO");
		else
			// per soggetto
			attoService.impostaIstanzaSoggetto(idProcedimento, idAtto, idUfficio, checked, idSoggInt,
					recuperaIdCodiceUtente(), Integer.parseInt(attoForm.getCategoriaAtto().getId()),"APPELLO");

		return istanzaModificaPersonaliRefresh(attoForm, result,modelMap, request).getViewName();
	}

	@RequestMapping(value = "/procedimento/atto/provvedimentoFascicoloGestione.htm", method = RequestMethod.POST)
	public String provvedimentoFascicoloGestione(AttoForm attoForm, String params, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		//MenuController.caricaMenu("15", request);

		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento();

		int idUffOwn = recuperaIdUfficioUtente();
		long idUfficio = recuperaIdUfficioUtente();

		String codiceUtente = recuperaIdCodiceUtente();
		String nomeMetodo = super.printMethodName();

		inizializzaDocumento(attoForm, request);

		String catAtto = attoForm.getCategoriaAtto().getId();

		//atto già inserito
		if(attoForm!=null && attoForm.getCodAtto()>0) {
			//visualizzazione atto
			if (params!=null) {
				//modifica atto

				// INIZIA GESTIONE DOCUMENTALE
				allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
				// FINE GESTIONE DOCUMENTALE

				attoForm.setIdProcedimento(idProcedimento);

				attoValidation.validateProvvedimentoFascicoloGestione(attoForm, result, request, modelMap, catAtto, params);

				if (!result.hasErrors()) {

					long idStatoAtto = 0;
					if(params.equals("Conferma")) {
						attoForm.setDataRegistrazione(Calendar.getInstance().getTime());
						idStatoAtto = Constants.STATOATTO_REGISTRATO;
					}

					long idAtto = attoService.salvaProvvedimentoFascicoloGestione(idUffOwn, idProcedimento, attoForm.getCodAtto(), codiceUtente, attoForm, idStatoAtto, nomeMetodo);
					attoForm.setCodAtto(idAtto);

					if(params.equals("Conferma")) {
						super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);

						// INIZIA GESTIONE DOCUMENTALE
						gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);
						// FINE GESTIONE DOCUMENTALE

						return copertinaAtto(attoForm, result, request, modelMap);
					}

				} else if(attoForm.getAllegato()!=null) {
					attoForm.getAllegato().setFileData(null);
					attoForm.getAllegato().setFileName(null);
					attoForm.getAllegato().setContentType(null);
					attoForm.getAllegato().setDocumento(null);
				}

			}
		//atto da inserire
		} else {
			//inserimento atto

			long catTipoAttoIstanze = 25;
			String listaCatAttoIstanze  = null;
			if(catAtto.equals(Constants.PROVVEDIMENTO_SU_ISTANZA_DELLE_PARTI_E_AMMINISTRATORE))
				listaCatAttoIstanze = "344, 345, 346, 347";
			else if(attoForm.getCategoriaAtto().getId().equals(Constants.PROVVEDIMENTO_CONTO_GESTIONE))
				listaCatAttoIstanze = "356";

			List<AttoForm> listaIstanze = attoService.getAttiByProcedimento(idProcedimento, catTipoAttoIstanze, listaCatAttoIstanze);

			List<ComboForm> listaIstanzeCombo = new ArrayList<ComboForm>();
			Iterator<AttoForm> iterSeq = listaIstanze.iterator();
			while (iterSeq.hasNext()) {
				String descrizione = "";
				ComboForm combo = new ComboForm();
				AttoForm decreto = iterSeq.next();
				if (Utility.isTIstanzaRecord(decreto.getTipoAtto().getId())) {

					Criterion c1 = Restrictions.eq("id.codiKIdIstanza", decreto.getCodAtto());
					Criterion c2 = Restrictions.eq("id.codiKIdUffOwner", idUffOwn);
					attoService.getAttoByPrimaryKey(TIstanza.class, c1, c2);
				}

				if (decreto.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)) {
					boolean isAttoOrigine = attoService.isAttoOrigine(decreto.getCodAtto(), idUffOwn);
					if(!isAttoOrigine) {
						descrizione = decreto.getFonte().getDescrizione() + " ricevuto il " + Utility.convertDateToString(decreto.getDataRicezione());
						combo.setId("" + decreto.getCodAtto());
						combo.setDescrizione(descrizione);
						listaIstanzeCombo.add(combo);
					}
				}
			}

			if (!Utility.isDefinito(listaIstanzeCombo)) {
				super.setMessage(Constants.MESSAGE, "atto.istanzaDellePartieAmministratore.noIstanze", null, false);
				return "/procedimento/atto/nuovoAtto";
			}

			modelMap.addAttribute("listaIstanze", listaIstanzeCombo);
		}


		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/provvedimentoFascicoloGestione";
	}

