	@RequestMapping(value = "/procedimento/atti/nuovo.htm", method = RequestMethod.POST, params = {"SelezionatoSoggettoOrdinanza"})
	private ModelAndView nuovoOrdinanzaAntimafia(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {


		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
		long idProcedimento = recuperaProcedimento().getIdProcedimento();


		long idSoggetto = Long.parseLong(attoForm.getSoggettiAntimafia().getId());
		long idAtto = attoService.inserisciOrdinanzaAntimafia(idUffOwn, codUtente, idProcedimento, attoForm,Constants.STATOATTO_IN_LAVORAZIONE, super.printMethodName(),idSoggetto);

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, idProcedimento, request, attoForm);

		ComboForm combo = new ComboForm();
		SoggettoForm soggetto = attoService.getSogAntimafia(idUffOwn, idProcedimento, idAtto);

		combo.setDescrizione(soggetto.getDescrizioneSoggettoConVersione());
		combo.setId("" + soggetto.getIdSoggetto());
		attoForm.setSoggettiAntimafia(combo);


		attoForm.setCodAtto(idAtto);
		attoForm.setIdProcedimento(idProcedimento);

		addBreadcrumbs();
		String lPagina = null;

		if(attoForm.getCategoriaAtto() != null && Constants.ORDINANZA_ART15_CODICE_ANTIMAFIA.equals(attoForm.getCategoriaAtto().getId())){

			attoForm.setFonteAttoGenerico(null);
			lPagina=caricaOrdinanza15CodiceAntimafia(attoForm,result,request,modelMap);

		} else
			lPagina=utilityService.caricaOrdinanza14CodiceAntimafia(attoForm,result,request,modelMap);
		 ModelAndView mnv = new ModelAndView(lPagina, "attoForm", attoForm);
		return mnv;
	}


