	/**
	 * nuovoDecretoPerditaEfficaciaSequestro
	 *
	 * @param attoForm
	 * @param result
	 * @param request
	 * @param modelMap
	 * @return String
	 */

	@RequestMapping(value = "/procedimento/atti/nuovo.htm", method = RequestMethod.POST, params = { "SelezionatoSequestroPerditaEfficacia" })
	private String nuovoDecretoPerditaEfficaciaSequestro(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento().longValue();
		int idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();

		long idAttoOrigine = Long.parseLong(attoForm.getSeqPerditaEfficacia().getId());

		 KeyMessageDto ritornoDb = attoService
					.controllaCollegioAtto(idProcedimento, Constants.PERDITA_EFFICACIA_SEQUESTRO, codUtente, idUffOwn, super.printMethodName());
			if (ritornoDb.isError()) {
				super.setMessage(Constants.MESSAGE, "messaggio.gestito.db", ritornoDb.getMessage(), false);
				result.reject(Constants.MESSAGE);
				return "/procedimento/atto/nuovoAtto";
			}

		long idAtto = attoService.inserisciDecretoPerditaEfficacia(idUffOwn, procedimento.getIdProcedimento(), codUtente, attoForm,
				Constants.STATOATTO_IN_LAVORAZIONE, idAttoOrigine, super.printMethodName());


		if(idAtto == 0){
				super.setMessage(Constants.MESSAGE, "antimafia.no.beni.perdita.efficacia", null, false);
				result.reject(Constants.MESSAGE);
				modelMap.addAttribute("categoria", this.categoria);
				modelMap.addAttribute("atto", new AttoForm());
				return "/procedimento/atto/nuovoAtto";

		}

		attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codUtente, procedimento.getIdProcedimento(), request, attoForm);
		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(idProcedimento, idAtto, idUffOwn);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);

		modelMap.addAttribute("beneForm", new BeneForm());
		modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());

		MenuController.caricaMenu("15", request);

		return "/procedimento/atto/copertinaDecretoPerditaEfficaciaSequestro";
	}

	@RequestMapping(value = "/procedimento/atto/decretoPerditaEfficaciaSequestro.htm", method = RequestMethod.POST, params = { "ConfermaInvia" })
	public String confermaInviaDecretoPerditaEfficaciaSequestro(AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		/*
		 * ISSUE MEV : Specifiche Intervento-006-SpeseProces-NumAtto
		 * Numero MEV : 006
		 * Autore    : Gioggi
		 * Data      : 20 apr 2020
		 * Branch    : MEV_006
		 */
		attoUtilService.caricaDatiDaAttoInSessione(attoForm, modelMap);
		//***** FINE INTERVENTO MEV_006 *****//

		int idUfficio = recuperaIdUfficioUtente();
		long idAtto = ((AttoForm) (request.getSession().getAttribute(Constants.ATTO))).getCodAtto();
		String codiceUtente = recuperaIdCodiceUtente();
		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();

		// INIZIA GESTIONE DOCUMENTALE
		allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE
		attoValidation.validateAttoDate(attoForm, result, request);

		List<BeneSoggettoForm> risultatiRicerca = procedimentoService.listaBeniConSoggettiAssociatiAdAttoEProcedimento(idProcedimento, idAtto,idUfficio);
		modelMap.addAttribute("risultatiRicerca", risultatiRicerca);

		if (result.hasErrors()) {
			attoForm.setDataRegistrazione(null);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/copertinaDecretoPerditaEfficaciaSequestro";
		}

		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore) {
			modelMap.addAttribute("beneForm", new BeneForm());
			modelMap.addAttribute("beneSoggettoForm", new BeneSoggettoForm());
			return "/procedimento/atto/copertinaDecretoPerditaEfficaciaSequestro";
		}

		// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		List<MagistratoForm> magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUfficio, idAtto, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
		List<MagistratoForm> magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUfficio, idProcedimento, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
	// se non C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO,  mando il messaggio Giudice Delegato obbligatorio.
		if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
			&& (magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))){
			modelMap.addAttribute("attoForm", attoForm);
			super.setMessage(Constants.MESSAGE,"magistrato.error.giudiceDelegato.registrazioneAtto",null,false);
			return copertinaAtto(new AttoForm(), result, request, modelMap);
		}

		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());


		// *** INIZIO GESTIONE UDIENZA DEL DECRETO ***
		GestioneUdienzaDto gestUdienza = udienzaUtilService.gestioneUdienzaPerInvioDecreto(attoForm, modelMap, idUfficio, idUfficio, idProcedimento, attoTmp);
		if (gestUdienza != null && gestUdienza.getUrlRitorno() != null && gestUdienza.getUrlRitorno().trim().length() > 0)
		 return gestUdienza.getUrlRitorno();

		attoForm.setDataRegistrazione(new Date());

		attoService.inviaDecretoPerditaEfficaciaSequestro(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto, idStatoAtto,
				  attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(), gestUdienza.getCodUdienzaInFaseDiRip(),
					gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(), super.printMethodName());


		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUfficio);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);
		// FINE GESTIONE DOCUMENTALE

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.invioAtto", null, false);
		ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/copertinaDecretoPerditaEfficaciaSequestro";
	}
