	private boolean invioSequestro(long idProcedimento, long idAtto, Integer idUfficioUtente, String codUtente)
	{
		boolean result = true;
		SequestroRequest sequestroRequest = anbscService.createSequestroRequest(idProcedimento, idAtto, idUfficioUtente, Constants.DECRETO_SEQUESTRO_ORDINARIO);
		long idMsg = anbscService.insertMsgDatabase(sequestroRequest, idProcedimento, idAtto, Constants.ANBSC_SEQUESTRO, codUtente);
		if(idMsg > 0)
		{
			SequestroResponse responseAnbsc = anbscService.inviaSequestro(sequestroRequest);
			if(responseAnbsc != null)
				anbscService.updateRispostaMsgDatabase(idMsg, responseAnbsc.getEsito());
			else
				result = false;
		}
		return result;
	}

