	private boolean invioDecretoConvalidaSequestro(long idProcedimento, long idAttoFi, Integer idUfficioUtente, String codUtente, String tipoSequestro)
	{
		boolean result = true;
		long idAttoOr = anbscService.recuperaAttoOrig(idAttoFi, idUfficioUtente);

		if(idAttoOr != 0)
		{
			String tipoMsg = null;
			if(tipoSequestro.equals(Constants.DECRETO_CONVALIDA_SEQUESTRO_URGENTE))
				tipoMsg = Constants.ANBSC_SEQUESTRO_URGENTE;
			else if(tipoSequestro.equals(Constants.DECRETO_CONVALIDA_SEQUESTRO_ANTICIPATO))
				tipoMsg = Constants.ANBSC_SEQUESTRO_ANTICIPATO;
			SequestroRequest sequestroRequest = anbscService.createDecretoConvalidaRequest(idProcedimento, idAttoOr, idAttoFi, idUfficioUtente, tipoSequestro);
			long idMsg = anbscService.insertMsgDatabase(sequestroRequest, idProcedimento, idAttoFi, tipoMsg, codUtente);
			if(idMsg > 0)
			{
				SequestroResponse responseAnbsc = anbscService.inviaSequestro(sequestroRequest);
				if(responseAnbsc != null)
					anbscService.updateRispostaMsgDatabase(idMsg, responseAnbsc.getEsito());
				else
					result = false;
			}
			return result;
		}
		else
			return false;
	}
