	@RequestMapping(value = "/procedimento/atto/provvedimentoRevocaAmministratori.htm", method = RequestMethod.POST)
	public String provvedimentoRevocaAmministratori(AttoForm attoForm, String params, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		MenuController.caricaMenu("15", request);

		ProcedimentoForm procedimento = recuperaProcedimento();
		long idProcedimento = procedimento.getIdProcedimento();

		int idUffOwn = recuperaIdUfficioUtente();
		long idUfficio = recuperaIdUfficioUtente();

		String codiceUtente = recuperaIdCodiceUtente();
		String nomeMetodo = super.printMethodName();

		inizializzaDocumento(attoForm, request);

		String catAtto = attoForm.getCategoriaAtto().getId();

		//atto già inserito
		if(attoForm!=null && attoForm.getCodAtto()>0 && !"InserimentoRinuncia".equals(params)) {
			//visualizzazione atto
			long idAtto = attoForm.getCodAtto();

			if (params!=null) {

				//modifica atto

				// INIZIA GESTIONE DOCUMENTALE
				allegatoFirmaUtilService.validaAllegatoEFirma(attoForm, result, request);
				// FINE GESTIONE DOCUMENTALE

				attoForm.setIdProcedimento(idProcedimento);

				attoValidation.validateProvvedimentoRevocaAmministratori(attoForm, result, request, modelMap, catAtto, params);

				if (!result.hasErrors()) {

					long idStatoAtto = 0;
					if(params.equals("Conferma")) {
						attoForm.setDataRegistrazione(Calendar.getInstance().getTime());
						idStatoAtto = Constants.STATOATTO_REGISTRATO;
					}

					idAtto = attoService.salvaProvvedimentoRevocaAmministratori(idUffOwn, idProcedimento, attoForm.getCodAtto(), codiceUtente, attoForm, idStatoAtto, attoForm.getIdAmministratoriRevocati(), nomeMetodo);
					attoForm.setCodAtto(idAtto);

					if(params.equals("Conferma")) {
						super.setMessage(Constants.SUCCESS_MESSAGE, "success.operation.generic", null, false);

						// INIZIA GESTIONE DOCUMENTALE
						gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);
						// FINE GESTIONE DOCUMENTALE

						return copertinaAtto(attoForm, result, request, modelMap);
					}

				} else if(attoForm.getAllegato()!=null) {
					attoForm.getAllegato().setFileData(null);
					attoForm.getAllegato().setFileName(null);
					attoForm.getAllegato().setContentType(null);
					attoForm.getAllegato().setDocumento(null);
				}

			}

			List<AmministratoreForm> amministratoriRevocati = attoService.getAmministratoriRevocati(idUffOwn, idProcedimento, idAtto);
			modelMap.addAttribute("amministratoriRevocati", amministratoriRevocati);
			List<Long> idsAmmRev = new ArrayList();
			for(int i=0;amministratoriRevocati!=null && i<amministratoriRevocati.size();i++)
				idsAmmRev.add(amministratoriRevocati.get(i).getId());
			attoForm.setIdAmministratoriRevocati(idsAmmRev);

			List<AmministratoreForm> amministratoriRevocabili = attoService.getAmministratoriRevocabili(idUffOwn, idProcedimento);
			modelMap.addAttribute("amministratoriRevocabili", amministratoriRevocabili);


		//atto da inserire
		} else if(params!=null && params.equals("SelezionaDecreto")) {
			long catTipoAttoIstanze = 25;
			String listaCatAttoIstanze  = null;
			listaCatAttoIstanze = Constants.RICHIESTA_RINUNCIA_AMMINISTRATORI;

			List<AttoForm> listaIstanze = attoService.getAttiByProcedimento(idProcedimento, catTipoAttoIstanze, listaCatAttoIstanze);

			List<ComboForm> listaIstanzeCombo = new ArrayList<ComboForm>();
			Iterator<AttoForm> iterSeq = listaIstanze.iterator();
			while (iterSeq.hasNext()) {
				String descrizione = "";
				ComboForm combo = new ComboForm();
				AttoForm decreto = iterSeq.next();
				if (Utility.isTIstanzaRecord(decreto.getTipoAtto().getId())) {

					Criterion c1 = Restrictions.eq("id.codiKIdIstanza", decreto.getCodAtto());
					Criterion c2 = Restrictions.eq("id.codiKIdUffOwner", idUffOwn);
					attoService.getAttoByPrimaryKey(TIstanza.class, c1, c2);
				}

				if (decreto.getStatoAtto().getId().equals("" + Constants.STATOATTO_REGISTRATO)) {
					descrizione = decreto.getFonte().getDescrizione() + " ricevuto il " + Utility.convertDateToString(decreto.getDataRicezione());
					combo.setId("" + decreto.getCodAtto());
					combo.setDescrizione(descrizione);
					listaIstanzeCombo.add(combo);
				}
			}

			if (!Utility.isDefinito(listaIstanzeCombo)) {
				super.setMessage(Constants.MESSAGE, "atto.error.provvedimentoRinunciaAmministratori", null, false);
				return "/procedimento/atto/nuovoAtto";
			}

			modelMap.addAttribute("listaIstanze", listaIstanzeCombo);

		} else {
			//inserimento atto
			attoValidation.validateSelezionaDecreto(attoForm, result, request, modelMap);
			if (result.hasErrors()) {
				attoForm.setCodAtto(0);
				return provvedimentoRevocaAmministratori(attoForm, null, result, request, modelMap);
			} else {

				Long idAttoOrigine = null;
				if(params!=null && params.equals("InserimentoRinuncia"))
					idAttoOrigine = attoForm.getCodAtto();

				long idAtto = attoService.inserisciProvvedimentoRevocaAmministratori(idUffOwn, procedimento.getIdProcedimento(), codiceUtente, attoForm,
						Constants.STATOATTO_IN_LAVORAZIONE, super.printMethodName(), idAttoOrigine);

				attoForm = attoUtilService.caricaAttoInSessione(idUffOwn, idAtto, codiceUtente, procedimento.getIdProcedimento(), request, attoForm);

				MenuController.caricaMenu("15", request);
			}

			return provvedimentoRevocaAmministratori(attoForm, null, result, request, modelMap);
		}

		modelMap.addAttribute("attoForm", attoForm);
		return "/procedimento/atto/provvedimentoRevocaAmministratori";
	}

