	@RequestMapping(value = { "/procedimento/atto/nuovoDecretoIncompetenza.htm",
			"/procedimento/atto/nuovoDecretoIncompetenzaProcura.htm" }, method = RequestMethod.POST, params = { "GeneraNumAtto" })
	public String generaNumeroAttoDI(@Valid @ModelAttribute("attoForm") AttoForm attoForm, BindingResult result, HttpServletRequest request,
			ModelMap modelMap) {

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		List<Message> msgs = new ArrayList<Message>();

		long idProcedimento = ((ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO))).getIdProcedimento();
		attoForm.setIdProcedimento(idProcedimento);

//		attoValidation.validateFormDecretoIncompetenza(attoForm, result, request, modelMap, true);
		if (result.hasErrors()) {
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			return decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
		}

		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore) {
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			return decretoUtilService.apriDecretoIncompetenza(attoForm.getCategoriaAtto().getId(), attoForm, request, result, modelMap);
		}

		long idUfficio = recuperaIdUfficioUtente();

		String codiceUtente = recuperaIdCodiceUtente();
		long categoriaAtto = Long.parseLong(attoForm.getCategoriaAtto().getId());

//		attoForm.setDataRegistrazione(Calendar.getInstance().getTime());
//		long idAtto = salvaModificaDecretoIncompetenza(attoForm, idUfficio, codiceUtente, idProcedimento, request);

		if (attoForm.getAllegato() != null && attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
		}

		if (attoForm.getCodAtto() == 0) {
			// inserimento
			if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_PROCURA)) {
				ProcedimentoForm procedimento = recuperaProcedimento();
				procedimento.setAntimafia(true);
				this.procedimentoService.aggiornaProcedimento(idUfficio, codiceUtente, procedimento);
			}
			attoForm.setCodAtto(attoService.inserisciDecretoIncompetenza((int) idUfficio, idProcedimento, codiceUtente, attoForm,
					Constants.STATOATTO_IN_LAVORAZIONE, super.printMethodName()));
		} else {
			// modifica
			inizializzaDocumento(attoForm, request);
			attoForm.setCodAtto(attoService.modificaAtto((int) idUfficio, attoForm, Constants.STATOATTO_IN_LAVORAZIONE, true));
		}
		long idAtto = attoForm.getCodAtto();

		long idDestinatario1 = 0;
		long idDestinatario2 = 0;
		long idDestinatario3 = 0;
		long idDestinatarioProposta = 0;

		if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_RESTITUZIONE_ATTI_PROCURA)
				|| attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_TRASF_ALTRO_TRIBUNALE)) {
			procuraUdienzaUtilService.caricaProcuraInUdienzaProcuraGeneraleProcuraProponente(modelMap);
			List<ComboForm> uffDestinatari = (List<ComboForm>) modelMap.get("ufficiList");

			if (uffDestinatari.size() >= 1)
				idDestinatario1 = Long.valueOf(uffDestinatari.get(0).getId());
			if (uffDestinatari.size() >= 2)
				idDestinatario2 = Long.valueOf(uffDestinatari.get(1).getId());
			if (uffDestinatari.size() >= 3)
				idDestinatario3 = Long.valueOf(uffDestinatari.get(2).getId());

			numeroAttoService.generaNumeroAttoDI(idProcedimento, idAtto, idUfficio, idDestinatario1, idDestinatario2,
					idDestinatario3, codiceUtente, idUfficio, categoriaAtto, super.printMethodName());
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.genera.num.atto", null, false);
		} else if (attoForm.getCategoriaAtto().getId().equals(Constants.DECRETO_INCOMPETENZA_PROCURA)) {
			List<ComboForm> uffDestinatari = ufficioUtilService.getUfficiDestinatariIncompetenzaProcura(request);

			if (uffDestinatari.size() >= 1)
				idDestinatarioProposta = Long.valueOf(uffDestinatari.get(0).getId());
			if (uffDestinatari.size() >= 2)
				idDestinatario2 = Long.valueOf(uffDestinatari.get(1).getId());
			if (uffDestinatari.size() >= 3)
				idDestinatario3 = Long.valueOf(uffDestinatari.get(2).getId());

			numeroAttoService.generaNumeroAttoDIP(idProcedimento, idAtto, idUfficio, idDestinatarioProposta, idDestinatario2, idDestinatario3,
					codiceUtente, idUfficio, categoriaAtto, super.printMethodName());
			super.setMessage(Constants.SUCCESS_MESSAGE, "success.genera.num.atto", null, false);
		}

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUfficio, result);
		// FINE GESTIONE DOCUMENTALE

		super.updateProcedimentoIntoSession(idProcedimento);
		// invoca metodo per l'esecuzione dell'invio
		return copertinaAtto(attoForm, result, request, modelMap);
	}

	@RequestMapping(value = "/procedimento/atto/confermaInviaAtto.htm", method = RequestMethod.POST, params = { "GeneraNumAtto" })
	public String generaNumeroAttoID(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		List<Message> msgs = new ArrayList<Message>();

		int idUffOwn = recuperaIdUfficioUtente();
		int idUfficio = recuperaIdUfficioUtente();
		String nomeMetodo = super.printMethodName();
		long idProcedimento = recuperaIdProcedimento();
		String codiceUtente = recuperaIdCodiceUtente();
		long idAtto = recuperaAtto().getCodAtto();
		long idCatAtto = RequestUtil.recuperaIdCategoriaAtto(request);
		if (idCatAtto <= 0)
			idCatAtto = attoForm.getCategoriaAtto() != null ? Long.valueOf(attoForm.getCategoriaAtto().getId()).longValue() : 0;
		TTpCatAtto tTpCatAtto = commonService.getCategoriaAtto(idCatAtto);
		modelMap.addAttribute("AllegatoObbligatorio", tTpCatAtto.getFlgAllegObbl());

		if (logger.isDebugEnabled())
		 logger.debug("--- inizio generaNumeroAttoID -> modelMap get ->AllegatoObbligatorio :[" + modelMap.get("AllegatoObbligatorio") + "]");

		if (result.hasErrors()) {
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/confermaInviaAtti";
		}

		utilityService.validateNumeroAttoDate(attoForm, result, request);

		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE

		if (result.hasErrors()) {
			attoForm = recuperaAtto();
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			attoForm.setDataRegistrazione(null);
			ufficioUtilService.caricaUfficiCompetenzaEProcuraInUdienza(modelMap);
			modelMap.addAttribute("attoForm", attoForm);
			return "/procedimento/atto/confermaInviaAtti";
		}

		// CONTROLLO SULL'INVIO DELL'ATTO --> COLLEGIALE O PRESIDENZIALE
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore) {
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			return "/procedimento/atto/confermaInviaAtti";
		}

		attoForm.setCodAtto(idAtto);
		inizializzaDocumento(attoForm, request);
		long idStatoAtto = Constants.STATOATTO_REGISTRATO;
		AttoForm attoTmp = attoService.getAttoById(idAtto, idUfficio);
		long tipoAtto = Long.parseLong(attoTmp.getTipoAtto().getId());
		long categoriaAtto = Long.parseLong(attoTmp.getCategoriaAtto().getId());
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(idProcedimento);
		ComboForm procProponente = commonService.getProcuraProponente(idProcedimento);
		// id procura in udienza
		long idProcUdi = 0l;
		// id procura proponente
		long idProcProp = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		if (procProponente != null)
			idProcProp = Long.parseLong(procProponente.getId());

		String categoriaAttoString = attoTmp.getCategoriaAtto().getId();
		GestioneUdienzaDto gestUdienza = new GestioneUdienzaDto();
		if (ComparatorUtil.containsValue(categoriaAttoString,
				Constants.DECRETO_SEQUESTRO_URGENTE,
				Constants.DECRETO_SEQUESTRO_ANTICIPATO,
				Constants.DECRETO_SEQUESTRO_ORDINARIO,
				Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO,
				Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO,
				Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO)) {
			// *** INIZIO GESTIONE UDIENZA DEL DECRETO ***
			gestUdienza = udienzaUtilService.gestioneUdienzaPerInvioDecreto(attoForm, modelMap, idUffOwn, idUfficio, idProcedimento, attoTmp);
			if (gestUdienza != null && gestUdienza.getUrlRitorno() != null && gestUdienza.getUrlRitorno().trim().length() > 0)
			 return gestUdienza.getUrlRitorno();
		}
		// *** INIZIO GESTIONE GIUDICE DELEGATO ***
		String giudiceDelegato = null;
		MagistratoForm magistratoForm = null;
		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE) || categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_BENI)) {
			List<MagistratoForm> magistratiAssociatiAtto = attoService.listaMagistratiPerAtto(idUffOwn, idAtto, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL));
			List<MagistratoForm> magistratiAssociatiProc = procedimentoService.listaMagistratiPerProcedimento(idUffOwn, idProcedimento, Integer.parseInt(Constants.ID_TIPO_RUOLO_GIU_DEL), true);
			// se NON C'è nè nella REL_MAG_PROC nè nella REL_MAG_ATTO mando il messaggio Giudice Delegato obbligatorio.
			if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
				&& (magistratiAssociatiAtto == null || (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() == 0))){
				modelMap.addAttribute("attoForm", attoForm);
				super.addMessageIntoList(msgs, Constants.MESSAGE, "magistrato.error.giudiceDelegato.registrazioneAtto", null);
				super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
				super.setMessages(msgs, true);
				return copertinaAtto(new AttoForm(), result, request, modelMap);
			}
			// se C'è nella REL_MAG_ATTO e NON C'è nella REL_MAG_PROC vuol dire che sto registrando il primo sequestro:
			// quindi devo inserire nella REL_MAG_PROC e associare il Giudice delegato al procedimento.
			if((magistratiAssociatiProc == null || (magistratiAssociatiProc != null && magistratiAssociatiProc.size() == 0))
				&& (magistratiAssociatiAtto != null && magistratiAssociatiAtto.size() > 0)){
				magistratoForm = magistratiAssociatiAtto.get(0);
				giudiceDelegato = "PROC";
			}
			if(magistratoForm == null) {
				magistratoForm = new MagistratoForm();
				magistratoForm.setId(Long.valueOf(0));
			} else
				magistratoForm.setId(magistratoForm.getId());
		}
		// *** FINE GESTIONE GIUDICE DELEGATO ***

//		attoForm.setDataRegistrazione(new Date());

		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO)
				|| categoriaAttoString.equals(Constants.DECRETO_SOSPENSIONE_TEMP_CDA))
			numeroAttoService.generaNumeroAttoDS(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto,
					idStatoAtto, idProcUdi, idProcProp, attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(),
					gestUdienza.getCodUdienzaInFaseDiRip(), gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(),
					magistratoForm.getId(), giudiceDelegato);
		else if (ComparatorUtil.containsValue(categoriaAttoString,
					Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO,
					Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO))
			numeroAttoService.generaNumeroAttoDRTS(idUfficio, idProcedimento, attoForm, codiceUtente, tipoAtto, categoriaAtto,
					idStatoAtto, idProcUdi, idProcProp, attoTmp.getFkUdienzaDecreto(), gestUdienza.getCodUdienzaFiss(),
					gestUdienza.getCodUdienzaInFaseDiRip(), gestUdienza.getCodUdienzaInFaseDiRim(), gestUdienza.getStatoUdienzaPrec(),
					nomeMetodo);

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoForm.getCodAtto(), idUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);
		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, idUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		attoForm = attoUtilService.caricaAttoInSessione(idUfficio, idAtto, codiceUtente, idProcedimento, request, attoForm);

		super.setMessage(SUCCESS_MESSAGE, "success.genera.num.atto", null, false);

		if (categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_URGENTE)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ANTICIPATO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO)
				|| categoriaAttoString.equals(Constants.DECRETO_SEQUESTRO_ORDINARIO_II_GRADO))
			return confermaInviaUtilService.includeConfermaInviaDecretoSequestro(attoForm, result, request, modelMap);
		else if (ComparatorUtil.containsValue(categoriaAttoString,
				Constants.DECRETO_RIGETTO_TOTALE_SEQUESTRO,
				Constants.DECRETO_RIGETTO_STATO_RICHIESTA_SEQUESTRO))
			return confermaInviaUtilService.includeConfermaInviaDecretoRigettoTotaleSequestro(attoForm, result, request, modelMap);

		return "/procedimento/atto/confermaInviaAtti";
	}

	@RequestMapping(value = "/procedimento/atto/associaDecretoApplicazioneProvvisoria.htm", method = RequestMethod.POST, params = { "GeneraNumAtto" })
	public ModelAndView generaNumeroAttoDAP(AttoForm attoForm, BindingResult result, ModelMap modelMap,HttpServletRequest request) {

		List<Message> msgs = new ArrayList<Message>();
		// INIZIA GESTIONE DOCUMENTALE
//		validaAllegatoEFirmaAtto(attoForm, result, request);
		// FINE GESTIONE DOCUMENTALE
		utilityService.validateNumeroAttoDate(attoForm, result, request);
		if (result.hasErrors()) {
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			attoForm.setDataRegistrazione(null);
			return new ModelAndView("procedimento/atto/decretoApplicazioneProvvisoria");
		}
		boolean errore = attoUtilService.controllaCollegioInvioAtto(super.printMethodName(), result);
		if (errore) {
			 attoForm.setDataRegistrazione(null);
			 super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			 super.setMessages(msgs, true);
			 return decretoUtilService.misuraDecretoApplicazioneProvvisoriaRefresh(attoForm, result, modelMap, request);
		}

		inizializzaDocumento(attoForm, request);

//		attoForm.setDataRegistrazione(Calendar.getInstance().getTime());

		SoggettoForm soggettoForm = attoForm.getSoggetto();

		ProcedimentoForm procedimento = recuperaProcedimento();

//		attoValidation.validateDecretoApplicazioneProvvisoria(procedimento, soggettoForm, attoForm, result, request);
		boolean containErrors = false;
		if (soggettoForm.getMisura() != null && soggettoForm.getMisura().getNormativaDiRiferimento() != null
				&& soggettoForm.getMisura().getNormativaDiRiferimento().getId() != null) {
			boolean localitaObbligatoria = commonService.localitaObbligatoriaNelTipoMisuraSelezionato(Long.parseLong(
					soggettoForm.getMisura().getTipoMisura().getId()), "AP");
			if ((soggettoForm.getMisura().getLocalita() == null) && localitaObbligatoria) {
				super.addMessageIntoList(msgs, Constants.MESSAGE, "error.soggetto.misurapersonale", null);
				super.setMessages(msgs, true);
				containErrors = true;
			}
		}
		if (soggettoForm.getMisura() != null && soggettoForm.getMisura().getTipoMisura() != null
				&& !soggettoForm.getMisura().getTipoMisura().getId().equals(Constants.NO_ITEM_SELECTED)
				&& soggettoForm.getMisura().getNormativaDiRiferimento() != null
				&& soggettoForm.getMisura().getNormativaDiRiferimento().getId() != null
				&& soggettoForm.getMisura().getNormativaDiRiferimento().getId().equals(Constants.NO_ITEM_SELECTED)) {
			super.addMessageIntoList(msgs, Constants.MESSAGE, "error.soggetto.normativa.obbligatoria", null);
			super.setMessages(msgs, true);
			containErrors = true;
		}
		Date now = Calendar.getInstance().getTime();
		Date dataIscrizioneProc = Utility.removeTime(procedimento.getDataApertura());
		Date dataEmissioneAtto = attoForm.getDataEmissione();
		Date dataDepositoAtto = attoForm.getDataDeposito();
		if (dataEmissioneAtto != null) {
			if (dataIscrizioneProc.after(dataEmissioneAtto)) {
				super.addMessageIntoList(msgs, Constants.MESSAGE, "error.data.emissione.iscrizione", null);
				super.setMessages(msgs, true);
				containErrors = true;
			}
			if (dataEmissioneAtto.after(now)) {
				super.addMessageIntoList(msgs, Constants.MESSAGE, "error.data.emissione.now", null);
				super.setMessages(msgs, true);
				containErrors = true;
			}
		}
		if (dataDepositoAtto != null && dataEmissioneAtto != null) {
			if (dataDepositoAtto.before(dataEmissioneAtto)) {
				super.addMessageIntoList(msgs, Constants.MESSAGE, "error.data.emissione.deposito", null);
				super.setMessages(msgs, true);
				containErrors = true;
			}
		}
		if (dataDepositoAtto != null) {
			if (dataIscrizioneProc.after(dataDepositoAtto)) {
				super.addMessageIntoList(msgs, Constants.MESSAGE, "error.data.deposito.iscrizione", null);
				super.setMessages(msgs, true);
				containErrors = true;
			}
			if (dataDepositoAtto.after(now)) {
				super.addMessageIntoList(msgs, Constants.MESSAGE, "error.data.deposito.now", null);
				super.setMessages(msgs, true);
				containErrors = true;
			}
		}
		if (result.hasErrors() || containErrors) {
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			return decretoUtilService.misuraDecretoApplicazioneProvvisoriaRefresh(attoForm,result,modelMap,request);
		}

		Integer vidUffOwn = recuperaIdUfficioUtente();
		String vcodUtente = (String) request.getSession().getAttribute(Constants.ID_CODICE_UTENTE);
		long idSoggInt = soggettoForm.getIdSoggetto();

		ProcedimentoForm procedimentoForm = (ProcedimentoForm) (request.getSession().getAttribute(Constants.ID_PROCEDIMENTO));

		AttoForm attoFormTmp = (AttoForm)request.getSession().getAttribute(Constants.ATTO);
		soggettoForm.setIdAtto(attoFormTmp.getCodAtto());

		// attoDecretoApplicazioneProvvisoria
		numeroAttoService.generaNumeroAttoDAP(procedimento.getIdProcedimento(), vidUffOwn, idSoggInt, vcodUtente,
				soggettoForm, attoForm);

		super.setMessage(Constants.SUCCESS_MESSAGE, "success.genera.num.atto", null, false);

		// INIZIA GESTIONE DOCUMENTALE
		gestionePiattaformaDocumentale(attoForm, request, vidUffOwn, result);
		// FINE GESTIONE DOCUMENTALE

		// INIZIO INVIO DATI MPS - 8.8
//		if (procedimento.getTipoProcedimento() != null && procedimento.getTipoProcedimento().getId() != null
//				&& procedimento.getTipoProcedimento().getId().equals(Constants.TIPOPROC_PERSONALE)) {
//			inviaDecretiProvvApplicazioneRevoca(procedimento, attoFormTmp.getCodAtto(),
//					Constants.POLIZIA_DECRETI_PROVVISORI_APPLICAZIONE);
//		}
		// FINE INVIO DATI MPS - 8.8

		attoForm = attoUtilService.caricaAttoInSessione(vidUffOwn, attoFormTmp.getCodAtto(), vcodUtente, procedimentoForm.getIdProcedimento(),
				request, attoForm);

		List<ComboForm> ListaUfficiDestinatari = commonService.getUfficiDestinatari(attoFormTmp.getCodAtto(), vidUffOwn);
		modelMap.addAttribute("ufficiListFromFlussiOut", ListaUfficiDestinatari);

		if (Long.toString(Constants.STATOATTO_REGISTRATO).equalsIgnoreCase(attoForm.getStatoAtto().getId()))
			modelMap.addAttribute("disabledObject", "true");

		String lPagina = decretoUtilService.getMisuraDecretoApplicazioneProvvisoria(soggettoForm, attoForm , modelMap, false, request);
		attoForm.setSoggetto(soggettoForm);

		ModelAndView mnv = new ModelAndView(lPagina, "attoForm", attoForm);

		return  mnv;
	}

