	@RequestMapping(value = "/procedimento/atto/decisioneRiesame.htm", method = RequestMethod.POST, params = { "GeneraNumAtto" })
	public String generaNumeroAttoDO(@Valid AttoForm attoForm, BindingResult result, HttpServletRequest request, ModelMap modelMap) {

		List<Message> msgs = new ArrayList<Message>();
		AttoForm attoInSessione = (AttoForm) request.getSession().getAttribute(Constants.ATTO);
		ProcedimentoForm proced = recuperaProcedimento();
		long idUffOwn = recuperaIdUfficioUtente();
		String codUtente = recuperaIdCodiceUtente();
//		attoForm.setDataRegistrazione(new Date());

		Date dataApeFasc = Utility.removeTime(proced.getDataApertura());
		Date now = Calendar.getInstance().getTime();
		if (attoForm.getEsitoOpposizione().getId() != null
				&& Long.parseLong(attoForm.getEsitoOpposizione().getId()) < 0) {
			result.rejectValue("esitoOpposizione.id", "NotNull");
		}
//			if (attoForm.getDataEmissione() == null) {
//				result.rejectValue("dataEmissione", "NotNull");
//			}
		if (attoForm.getDataDeposito() == null) {
			result.rejectValue("dataDeposito", "NotNull");
		}
		if ((attoForm.getDataEmissione() != null) && attoForm.getDataEmissione().after(now)) {
			result.rejectValue("dataEmissione", "error.dataCorrente");
		}
		if ((attoForm.getDataDeposito() != null) && attoForm.getDataDeposito().after(now)) {
			result.rejectValue("dataDeposito", "error.dataCorrente");
		}
		if ((attoForm.getDataEmissione() != null) && attoForm.getDataEmissione().before(dataApeFasc)) {
			result.rejectValue("dataEmissione", "error.dataApeFasc");
		}
		if ((attoForm.getDataDeposito() != null) && attoForm.getDataDeposito().before(dataApeFasc)) {
			result.rejectValue("dataDeposito", "error.dataApeFasc");
		}
		if (result.hasErrors()) {
			attoForm = recuperaAtto();
			super.addMessageIntoList(msgs, Constants.MESSAGE, "warning.genera.num.atto", Constants.STRINGAVUOTA);
			super.setMessages(msgs, true);
			attoForm.setDataRegistrazione(null);
			return decretoUtilService.dettaglioDecisorioIGradoRiesame(attoForm, modelMap, result, request);
		}
		attoForm.setCodAtto(attoInSessione.getCodAtto());
		if (attoForm.getAllegato().getFileData() != null && attoForm.getAllegato().getFileData().getSize() > 0) {
			attoForm.getAllegato().setFileName(attoForm.getAllegato().getFileData().getOriginalFilename());
			attoForm.getAllegato().setContentType(attoForm.getAllegato().getFileData().getContentType());
			attoForm.setDataRicezione(Calendar.getInstance().getTime());
		}
		ComboForm procInUdienza = commonService.getProcuraInUdienzaAssociata(proced.getIdProcedimento());
		long idProcUdi = 0l;
		if (procInUdienza != null)
			idProcUdi = Long.parseLong(procInUdienza.getId());
		numeroAttoService.generaNumeroAttoDO(idUffOwn, idProcUdi, 0, proced.getIdProcedimento(), attoForm, codUtente);
		super.updateProcedimentoIntoSession(proced.getIdProcedimento());
		super.setMessage(Constants.SUCCESS_MESSAGE, "success.genera.num.atto", null, false);
		return copertinaAtto(attoForm, result, request, modelMap);
	}
